      isEditable: !!el && (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA' || !!el.isContentEditable),
      role: el ? el.getAttribute('role') : null,
      text: String((el && el.textContent) || '').trim().slice(0, 24),
