      window.__gf.calls.push(gid);
      if (window.__gf.fail) throw new Error('ipc down');
      return [{
        transfer_id: gid + '-1',
        name: gid + '.bin',
        size: 1024,
        sender_id: 'peer-1',
        created_at: 0,
        local_state: 'local',
        local_path: '/tmp/' + gid + '.bin',
        delivered: 1,
        total: 1,
      }];
