        lastCellMark = `段 ${name} 首抛（已回滚到段前）`;
        console.log(`  · 段 ${name} 第一次抛错（工具竞态候选）：${m1} —— 回滚本段半程结果，重载页面整段重试一次`);
        if (process.env.GOSSLAN_PROBE_DEBUG_STACK) console.log(String(e1 && e1.stack || "").slice(0, 2000));
