/**
 * 默认头像选择器（--only=avatar）：真组件、真浏览器、390 宽。
 *
 * 这段量的是**只有运行时才看得见**的四件事：
 *   ① 选项数必须与 `avatarSeed.ts` 派生清单相等（不是模板里手抄的另一份）；
 *   ② 点表情 / 点颜色 / 随机之后，选中态与预览同步翻面（同一次 eval 读不到 Vue 翻面后的
 *      aria-pressed，必须拆两次 eval —— 这是本文件踩过的坑）；
 *   ③ 390 宽下弹窗与两组网格都不横向溢出，确认键仍在视口内；
 *   ④ 生成的头像 SVG **真的画出了 emoji**（不是只有一块背景色）：Chromium 里把 data URL
 *      画进 canvas，数"与背景不同的像素"。这条是整个方案最大的技术前提。
 *
 * ⚠️ 这条只证明 Chromium 内核；macOS 的 WKWebView 仍是人工验收（见文件头那条边界）。
 */
async function runAvatar(cdp, url) {
  const INITIAL = { emoji: "🦊", bg: "#4284b3" };
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  // 导航会把 device metrics 复位：页面起来后再钉一次，并 reload 让 store 的 resize 监听翻到窄档。
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  await cdp.send("Page.reload");
  await sleep(2_000);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  await sleep(600);
  await cdp.eval(PAGE_FIXTURE);

  const mounted = await cdp.eval(
    `window.__probe.install('/src/components/settings/AvatarPresetDialog.vue', '', ${
      JSON.stringify(JSON.stringify({ open: true, initial: INITIAL }))
    })`,
  );
  await sleep(500);

  const read = () => cdp.eval(`(async () => {
    const A = await import('/src/utils/avatarSeed.ts');
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { ok: false };
    const emojiBtns = [...dlg.querySelectorAll('[data-avatar-emoji]')];
    const bgBtns = [...dlg.querySelectorAll('[data-avatar-bg]')];
    const pressed = (sel) => [...dlg.querySelectorAll(sel + '[aria-pressed="true"]')];
    const pe = pressed('[data-avatar-emoji]');
    const pb = pressed('[data-avatar-bg]');
    const preview = dlg.querySelector('.gosslan-avatar-box');
    const rect = dlg.getBoundingClientRect();
    const apply = dlg.querySelector('[data-avatar-apply]');
    const ar = apply ? apply.getBoundingClientRect() : null;
    const opts = dlg.querySelector('[data-avatar-options]');
    const flexes = opts ? [...opts.querySelectorAll('.flex.flex-wrap')] : [];
    return {
      ok: true,
      emojis: emojiBtns.length,
      bgs: bgBtns.length,
      emojiSetLen: A.AVATAR_EMOJIS.length,
      bgSetLen: A.AVATAR_BACKGROUNDS.length,
      emojiAllFromSet: emojiBtns.every((b) => A.AVATAR_EMOJIS.includes(b.getAttribute('data-avatar-emoji'))),
      bgAllFromSet: bgBtns.every((b) => A.AVATAR_BACKGROUNDS.includes(b.getAttribute('data-avatar-bg'))),
      pressedEmoji: pe.length === 1 ? pe[0].getAttribute('data-avatar-emoji') : null,
      pressedBg: pb.length === 1 ? pb[0].getAttribute('data-avatar-bg') : null,
      pressedEmojiCount: pe.length,
      pressedBgCount: pb.length,
      previewEmoji: (preview && preview.innerText || '').trim(),
      previewBg: preview ? getComputedStyle(preview).backgroundColor : null,
      vw: innerWidth,
      sw: document.documentElement.scrollWidth,
      dlg: { l: +rect.left.toFixed(1), r: +rect.right.toFixed(1), w: +rect.width.toFixed(1), h: +rect.height.toFixed(1) },
      options: opts ? { scrollW: opts.scrollWidth, clientW: opts.clientWidth } : null,
      flexes: flexes.map((g) => ({ justify: getComputedStyle(g).justifyContent, display: getComputedStyle(g).display })),
      selectedEmojiInset: pe.length === 1 ? getComputedStyle(pe[0]).boxShadow.includes('inset') : false,
      selectedBgHasCheck: pb.length === 1 ? !!pb[0].querySelector('svg') : false,
      apply: ar ? { l: +ar.left.toFixed(1), r: +ar.right.toFixed(1), h: +ar.height.toFixed(1) } : null,
      inputs: dlg.querySelectorAll('input').length,
      colorInputs: dlg.querySelectorAll('input[type="color"]').length,
      textInputs: dlg.querySelectorAll('input:not([type="color"])').length,
      hasRandom: !!dlg.querySelector('[data-avatar-random]'),
    };
  })()`);

  const s0 = await read();
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-avatar.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 默认头像选择器取证帧 → " + SHOT_PATH.replace(/\.png$/, "-avatar.png"));
  }
  check("默认头像：弹窗在 390 宽下打开，选项数与随机算法的清单一致（不是手抄的第二份）",
    mounted && mounted.ok === true && s0.ok === true
      && s0.emojis === s0.emojiSetLen && s0.bgs === s0.bgSetLen
      && s0.emojiAllFromSet === true && s0.bgAllFromSet === true,
    "emoji 数=AVATAR_EMOJIS、颜色数=AVATAR_BACKGROUNDS，且每个值都在清单内",
    JSON.stringify({ mounted, emojis: s0.emojis, emojiSet: s0.emojiSetLen, bgs: s0.bgs, bgSet: s0.bgSetLen }));

  check("默认头像：打开时选中态就是传入的当前组合，预览同源",
    s0.ok === true && s0.pressedEmoji === INITIAL.emoji && s0.pressedBg === INITIAL.bg
      && s0.pressedEmojiCount === 1 && s0.pressedBgCount === 1
      && s0.previewEmoji === INITIAL.emoji
      && s0.previewBg === "rgb(66, 132, 179)",
    "恰有一个表情/一个颜色选中，预览 emoji 与背景都等于传入组合",
    JSON.stringify({ pe: s0.pressedEmoji, pb: s0.pressedBg, preview: s0.previewEmoji, bg: s0.previewBg }));

  // 点一个不同的表情：选中态与预览都要跟着翻（拆两次 eval 才读得到 Vue 翻面后的属性）。
  const nextEmoji = await cdp.eval(
    `import('/src/utils/avatarSeed.ts').then((A) => A.AVATAR_EMOJIS.find((e) => e !== ${JSON.stringify(INITIAL.emoji)}))`,
  );
  await cdp.eval(
    `document.querySelector(${JSON.stringify(`[data-avatar-emoji="${nextEmoji}"]`)}).click()`,
  );
  await sleep(200);
  const s1 = await read();
  check("默认头像：点表情后选中态唯一、预览立即跟着换（拖动/点击都不串味）",
    s1.ok === true && s1.pressedEmoji === nextEmoji && s1.pressedEmojiCount === 1
      && s1.previewEmoji === nextEmoji,
    "pressedEmoji=被点的那个且只有一个，预览 emoji 同步",
    JSON.stringify({ want: nextEmoji, got: s1.pressedEmoji, count: s1.pressedEmojiCount, preview: s1.previewEmoji }));

  // 随机：必须换一张，而且换到的仍是组合表里的行（与手动选项同一个数据集）。
  await cdp.eval("document.querySelector('[data-avatar-random]').click()");
  await sleep(200);
  const s2 = await read();
  const pairOk = await cdp.eval(
    `import('/src/utils/avatarSeed.ts').then((A) => A.AVATAR_PAIRS.some((p) => p.emoji === ${
      JSON.stringify(s2.pressedEmoji)
    } && p.bg === ${JSON.stringify(s2.pressedBg)}))`,
  );
  check("默认头像：随机一定换一张，且结果落在 AVATAR_PAIRS 里（不是另一套随机源）",
    s2.ok === true && pairOk === true
      && !(s2.pressedEmoji === s1.pressedEmoji && s2.pressedBg === s1.pressedBg)
      && s2.previewEmoji === s2.pressedEmoji,
    "组合变化 + 属于 AVATAR_PAIRS + 预览同步",
    JSON.stringify({ before: [s1.pressedEmoji, s1.pressedBg], after: [s2.pressedEmoji, s2.pressedBg], pairOk }));

  // 点一个不同的背景色：预览背景必须等于那颗色块的实测颜色。
  const nextBg = await cdp.eval(
    `import('/src/utils/avatarSeed.ts').then((A) => A.AVATAR_BACKGROUNDS.find((c) => c !== ${JSON.stringify(s2.pressedBg)}))`,
  );
  const swatchSel = `[data-avatar-bg="${nextBg}"]`;
  const swatchBg = await cdp.eval(
    `getComputedStyle(document.querySelector(${JSON.stringify(swatchSel)})).backgroundColor`,
  );
  await cdp.eval(`document.querySelector(${JSON.stringify(swatchSel)}).click()`);
  await sleep(200);
  const s3 = await read();
  check("默认头像：点背景色后预览真的换成那一格（读的是计算样式，不是自己记的值）",
    s3.ok === true && s3.pressedBg === nextBg && s3.pressedBgCount === 1
      && s3.previewBg === swatchBg,
    "pressedBg=被点的那个，预览背景=色块计算样式",
    JSON.stringify({ want: nextBg, got: s3.pressedBg, previewBg: s3.previewBg, swatchBg }));

  check("默认头像：390 宽下弹窗/选项不横向溢出，两组选项居中换行，确认键留在视口内",
    s3.ok === true && s3.sw <= s3.vw + 1
      && s3.dlg.l >= -1 && s3.dlg.r <= s3.vw + 1
      && s3.options !== null && s3.options.scrollW <= s3.options.clientW + 1
      && s3.flexes.length === 2 && s3.flexes.every((f) => f.display === "flex" && f.justify === "center")
      && s3.apply !== null && s3.apply.l >= -1 && s3.apply.r <= s3.vw + 1 && s3.apply.h >= 24,
    "scrollWidth<=vw、dialog 左右不越界、选项无横向滚动、两个 flex 都是 justifyContent=center、apply 可见且高度>=24",
    JSON.stringify({ vw: s3.vw, sw: s3.sw, dlg: s3.dlg, options: s3.options, flexes: s3.flexes, apply: s3.apply }));

  check("默认头像：选中环画在按钮内部、色块选中带勾（左右边缘不会被滚动区裁掉）",
    s3.ok === true && s3.selectedEmojiInset === true && s3.selectedBgHasCheck === true,
    "选中表情的 box-shadow 含 inset、选中色块内有勾",
    JSON.stringify({ inset: s3.selectedEmojiInset, check: s3.selectedBgHasCheck }));

  check("默认头像：没有自由文本输入，唯一的 input 是自定义取色器；随机键是按钮",
    s3.ok === true && s3.colorInputs === 1 && s3.textInputs === 0 && s3.hasRandom === true,
    "colorInputs=1、textInputs=0、random 按钮存在",
    JSON.stringify({ inputs: s3.inputs, colorInputs: s3.colorInputs, textInputs: s3.textInputs, hasRandom: s3.hasRandom }));

  // 预览固定：矮窗口里只允许选项区滚；滚动前后预览的 top 不许动。
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 600, deviceScaleFactor: 2, mobile: true,
  });
  await sleep(400);
  const fixed = await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { ok: false };
    const preview = dlg.querySelector('.gosslan-avatar-box');
    const opts = dlg.querySelector('[data-avatar-options]');
    if (!preview || !opts) return { ok: false };
    const scrollers = [...dlg.querySelectorAll('*')].filter((el) => {
      const st = getComputedStyle(el);
      return /auto|scroll/.test(st.overflowY) && el.scrollHeight > el.clientHeight + 1;
    });
    let sc = opts;
    while (sc && !scrollers.includes(sc)) sc = sc.parentElement;
    if (!sc) return { ok: false, scrollers: scrollers.length };
    const before = preview.getBoundingClientRect().top;
    sc.scrollTop = 240;
    const after = preview.getBoundingClientRect().top;
    // 再滚到真正的最大值：最后一颗色块（含自定义色）与确认键都必须完整落在可视区。
    sc.scrollTop = sc.scrollHeight;
    const lastOption = [...dlg.querySelectorAll('[data-avatar-bg], [data-avatar-custom-color]')].pop();
    const apply = dlg.querySelector('[data-avatar-apply]');
    const scRect = sc.getBoundingClientRect();
    const lastRect = lastOption ? lastOption.getBoundingClientRect() : null;
    const applyRect = apply ? apply.getBoundingClientRect() : null;
    return {
      ok: true,
      scrollers: scrollers.length,
      scrollTop: Math.round(sc.scrollTop),
      moved: +(before - after).toFixed(1),
      previewTop: +before.toFixed(1),
      optionsScrollH: sc.scrollHeight,
      optionsClientH: sc.clientHeight,
      maxScroll: Math.round(sc.scrollTop + sc.clientHeight) >= Math.round(sc.scrollHeight) - 1,
      lastBottom: lastRect ? +lastRect.bottom.toFixed(1) : null,
      scrollerBottom: +scRect.bottom.toFixed(1),
      applyTop: applyRect ? +applyRect.top.toFixed(1) : null,
      applyBottom: applyRect ? +applyRect.bottom.toFixed(1) : null,
      vh: innerHeight,
    };
  })()`);
  check("默认头像：矮窗口里预览固定不动，只有选项区在滚（且全弹窗只有一个滚动区）",
    fixed.ok === true && fixed.scrollers === 1 && fixed.scrollTop > 0
      && Math.abs(fixed.moved) <= 1 && fixed.optionsScrollH > fixed.optionsClientH,
    "唯一滚动区 scrollTop>0、预览 top 位移<=1px",
    JSON.stringify(fixed));
  check("默认头像：滚到最底部后，最后一颗色块与确认键都完整可见",
    fixed.ok === true && fixed.maxScroll === true && fixed.lastBottom !== null
      && fixed.lastBottom <= fixed.scrollerBottom + 1
      && fixed.applyTop !== null && fixed.applyTop >= 0
      && fixed.applyBottom !== null && fixed.applyBottom <= fixed.vh + 1,
    "maxScroll + 最后一颗色块底边≤滚动区底边 + 确认键完整在视口内",
    JSON.stringify({ maxScroll: fixed.maxScroll, lastBottom: fixed.lastBottom, scrollerBottom: fixed.scrollerBottom, apply: [fixed.applyTop, fixed.applyBottom], vh: fixed.vh }));
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  await sleep(300);

  // 确认：emit 的组合必须等于屏幕上选中的那一组。
  await cdp.eval("document.querySelector('[data-avatar-apply]').click()");
  await sleep(200);
  const applied = await cdp.eval(
    `window.__probe.events.filter((e) => e[0] === 'apply').pop() || null`,
  );
  check("默认头像：点「使用这个头像」emit 的组合就是屏幕上选中的那一组",
    Array.isArray(applied) && applied[1] === s3.pressedEmoji && applied[2] === s3.pressedBg,
    "apply 事件载荷 = 选中组合",
    JSON.stringify({ event: applied, selected: [s3.pressedEmoji, s3.pressedBg] }));

  // 自定义色：取色器写入后预览必须立即变，且选中环落到自定义那颗上。
  const customSet = await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { ok: false };
    const input = dlg.querySelector('input[type="color"]');
    const btn = dlg.querySelector('[data-avatar-custom-color]');
    if (!input || !btn) return { ok: false };
    input.value = '#123456';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    return { ok: true };
  })()`);
  await sleep(200);
  const customRead = await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { ok: false };
    const btn = dlg.querySelector('[data-avatar-custom-color]');
    const preview = dlg.querySelector('.gosslan-avatar-box');
    return {
      ok: true,
      pressed: btn ? btn.getAttribute('aria-pressed') : null,
      previewBg: preview ? getComputedStyle(preview).backgroundColor : null,
      palettePressed: dlg.querySelectorAll('[data-avatar-bg][aria-pressed="true"]').length,
    };
  })()`);
  check("默认头像：自定义颜色写入后预览生效，选中态落在自定义色块上",
    customSet.ok === true && customRead.ok === true
      && customRead.pressed === "true" && customRead.palettePressed === 0
      && customRead.previewBg === "rgb(18, 52, 86)",
    "aria-pressed=true、调色板无选中、预览=#123456",
    JSON.stringify({ set: customSet, read: customRead }));

  // SVG 真的画出了 emoji：画进 canvas 数非背景像素。只画背景色 ⇒ 图标位置是一整块纯色，
  // 对端看到的就是"没有脸的色块"，而界面这边所有字符串判据仍然全绿。
  const art = await cdp.eval(`(async () => {
    const A = await import('/src/utils/avatarSeed.ts');
    const url = A.avatarPresetDataUrl(${JSON.stringify(INITIAL)});
    const img = new Image();
    const loaded = await new Promise((resolve) => {
      img.onload = () => resolve(true);
      img.onerror = () => resolve(false);
      img.src = url;
    });
    if (!loaded) return { loaded: false, urlLen: url.length };
    const size = 64;
    const c = document.createElement('canvas');
    c.width = size; c.height = size;
    const ctx = c.getContext('2d');
    ctx.drawImage(img, 0, 0, size, size);
    const px = ctx.getImageData(0, 0, size, size).data;
    const bg = ${JSON.stringify(INITIAL.bg)};
    const br = parseInt(bg.slice(1, 3), 16), bgc = parseInt(bg.slice(3, 5), 16), bb = parseInt(bg.slice(5, 7), 16);
    let other = 0;
    for (let i = 0; i < px.length; i += 4) {
      if (Math.abs(px[i] - br) > 12 || Math.abs(px[i + 1] - bgc) > 12 || Math.abs(px[i + 2] - bb) > 12) other++;
    }
    return { loaded: true, w: img.naturalWidth, h: img.naturalHeight, other, urlLen: url.length };
  })()`);
  check("默认头像：生成的头像 SVG 真的渲染出 emoji（不是一块纯背景色）",
    art.loaded === true && art.w === 512 && art.h === 512 && art.other > 100,
    "naturalSize=512、非背景像素>100",
    JSON.stringify(art));

  // ── 资料页布局（桌面 1200 宽）：头像框与右侧字段顶/底对齐；入口文案按用户口径。 ──
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1200, height: 800, deviceScaleFactor: 1, mobile: false,
  });
  await cdp.send("Page.reload");
  await sleep(2_000);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1200, height: 800, deviceScaleFactor: 1, mobile: false,
  });
  await sleep(500);
  await cdp.eval(PAGE_FIXTURE);
  const mountedProfileDesktop = await cdp.eval(
    `window.__probe.install('/src/components/settings/ProfileSection.vue', '', ${JSON.stringify(JSON.stringify({ active: true }))})`,
  );
  await cdp.eval("window.__probe.seedDevice('probe-me')");
  await sleep(400);
  const align = await cdp.eval(`(() => {
    const av = document.querySelector('[data-profile-avatar]');
    const fields = document.querySelector('[data-profile-fields]');
    if (!av || !fields) return { ok: false };
    const a = av.getBoundingClientRect();
    const f = fields.getBoundingClientRect();
    const labels = [...document.querySelectorAll('button')].map((b) => String(b.innerText || '').trim());
    return {
      ok: true,
      avatar: { t: +a.top.toFixed(1), b: +a.bottom.toFixed(1), h: +a.height.toFixed(1) },
      fields: { t: +f.top.toFixed(1), b: +f.bottom.toFixed(1), h: +f.height.toFixed(1) },
      hasUpload: labels.includes('上传头像'),
      hasEmoji: labels.includes('自定义 emoji 头像'),
      vw: innerWidth,
      sw: document.documentElement.scrollWidth,
    };
  })()`);
  // ⚠️ 3.5 的来历（是换参照物，不是放宽门槛）：右侧字段 = 输入行 h-9(36) + mt-1(4) +
  //    按钮行 30 = 70px，头像固定 64px；items-center 居中后上下各差 (70−64)/2 = 3px。
  //    旧阈值 2.5 是按 ProfileSection 里"输入行 34 / 字段 68 ⇒ 各差 2px"写的；
  //    2fb3cc8e（2026-11-05，输入框三档更正为 36/40）把这一行抬到 36 之后，2px 那个
  //    设计假设已经不存在，旧阈值在**任何**环境下都必然红。仍能咬住真实错位：
  //    头像放大到 80 时每边差 8px，远超 3.5。
  check("资料页：头像框与右侧字段上下对齐，两个入口按用户口径命名",
    mountedProfileDesktop && mountedProfileDesktop.ok === true && align.ok === true
      && Math.abs(align.avatar.t - align.fields.t) <= 3.5
      && Math.abs(align.avatar.b - align.fields.b) <= 3.5
      && align.avatar.h >= 62 && align.avatar.h <= 66
      && align.hasUpload === true && align.hasEmoji === true
      && align.sw <= align.vw + 1,
    "头像 top/bottom 与右侧字段差 <=3.5px（36+4+30=70 对 64，各差 3px）、头像高 62~66、按钮文案=上传头像/自定义 emoji 头像、无横向溢出",
    JSON.stringify(align));
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-profile.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 资料页布局取证帧 → " + SHOT_PATH.replace(/\.png$/, "-profile.png"));
  }

  // ── 资料页入口 → 选择器 → 既有 updateProfile 的整条链（组件级，不是只看弹窗） ──
  // 重新导航一次：上一段留着开着的弹窗，别在同一个页面里叠第二个浮层。
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  await cdp.send("Page.reload");
  await sleep(2_000);
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  await sleep(600);
  await cdp.eval(PAGE_FIXTURE);
  const mountedProfile = await cdp.eval(
    `window.__probe.install('/src/components/settings/ProfileSection.vue', '', ${JSON.stringify(JSON.stringify({ active: true }))})`,
  );
  await cdp.eval("window.__probe.seedDevice('probe-me')");
  await sleep(400);
  // 记录 updateProfile 的真实入参；getFriends 给空数组，避免保存成功后的资料刷新抛错回滚。
  await cdp.eval(`(async () => {
    const m = await import('/src/api/index.ts');
    window.__profileCalls = [];
    m.api.updateProfile = async (nickname, avatar) => {
      window.__profileCalls.push({ nickname: nickname, avatar: avatar });
      return { device_id: 'probe-me', nickname: nickname, avatar: avatar, device_type: 'desktop', tcp_port: 12345, online: true };
    };
    m.api.getFriends = async () => [];
    return true;
  })()`);
  const entry = await cdp.eval("!!document.querySelector('[data-default-avatar-entry]')");
  await cdp.eval("document.querySelector('[data-default-avatar-entry]').click()");
  await sleep(400);
  const opened = await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    return { ok: !!d, emojis: d ? d.querySelectorAll('[data-avatar-emoji]').length : 0 };
  })()`);
  check("默认头像：资料页的入口真的打开选择器（不是只摆了一个按钮）",
    mountedProfile && mountedProfile.ok === true && entry === true && opened.ok === true && opened.emojis > 0,
    "入口存在、点击后有 dialog 且表情网格已渲染",
    JSON.stringify({ mountedProfile, entry, opened }));

  const pick = await cdp.eval(
    `import('/src/utils/avatarSeed.ts').then((A) => ({ emoji: A.AVATAR_EMOJIS[2], bg: A.AVATAR_BACKGROUNDS[0] }))`,
  );
  await cdp.eval(
    `document.querySelector(${JSON.stringify(`[data-avatar-emoji="${pick.emoji}"]`)}).click()`,
  );
  await cdp.eval(
    `document.querySelector(${JSON.stringify(`[data-avatar-bg="${pick.bg}"]`)}).click()`,
  );
  await sleep(150);
  await cdp.eval("document.querySelector('[data-avatar-apply]').click()");
  await sleep(700);
  const saved = await cdp.eval(`(async () => {
    const A = await import('/src/utils/avatarSeed.ts');
    const calls = window.__profileCalls || [];
    const last = calls[calls.length - 1] || null;
    const img = document.querySelector('.gosslan-avatar-box img');
    return {
      calls: calls.length,
      nickname: last ? last.nickname : null,
      isSvg: !!last && String(last.avatar).startsWith('data:image/svg+xml;base64,'),
      pair: last ? A.parseAvatarPreset(last.avatar) : null,
      imgSrc: img ? String(img.getAttribute('src')).slice(0, 26) : null,
      dialogGone: !document.querySelector('[role="dialog"]'),
    };
  })()`);
  check("默认头像：确认后走的是既有 updateProfile，落库值就是选中的组合（SVG data URL）",
    saved.calls === 1 && saved.nickname === "探针我" && saved.isSvg === true
      && saved.pair && saved.pair.emoji === pick.emoji && saved.pair.bg === pick.bg
      && saved.imgSrc === "data:image/svg+xml;base64,"
      && saved.dialogGone === true,
    "updateProfile 1 次、入参可解析回选中组合、资料头像立即变成同一张、弹窗关闭",
    JSON.stringify({ want: pick, saved }));

  await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
}


/**
 * 应用更新面板（--only=updater）：纯展示组件 + 四态夹具，不碰 Tauri。
 * 量的是“发现更新/下载中/下载完成/移动端不支持”在真浏览器里的可见性与用户确认门槛。
 */
async function runUpdater(cdp, url) {
  const base = {
    phase: "available",
    info: { currentVersion: "5.4.1", version: "5.5.0", notes: "修复若干问题", publishedAt: 1_700_000_000 },
    currentVersion: "5.4.1",
    downloaded: 0,
    total: null,
    error: null,
    checkedAt: null,
    dismissedVersion: null,
  };
  const mount = async (state, supported = true) => {
    const ok = await cdp.eval(
      `window.__probe.install('/src/components/settings/UpdatePanel.vue', '', ${
        JSON.stringify(JSON.stringify({ state, supported }))
      })`,
    );
    await sleep(350);
    return ok;
  };
  const text = () => cdp.eval("document.body.innerText");
  const hasDialog = () => cdp.eval("!!document.querySelector('[role=\"dialog\"]')");

  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  await mount(base);
  const t1 = await text();
  check("应用更新：发现更新时显示版本/说明/下载与稍后，且没有启动弹窗",
    t1.includes("5.5.0") && t1.includes("下载更新") && t1.includes("稍后") && (await hasDialog()) === false,
    "含 5.5.0/下载更新/稍后；无 role=dialog",
    JSON.stringify({ head: String(t1).slice(0, 180), dialog: await hasDialog() }));

  await mount({ ...base, phase: "downloading", downloaded: 40, total: 100 });
  const t2 = await text();
  const bar = await cdp.eval(`(() => {
    const el = document.querySelector('[role="progressbar"]');
    return el ? { now: el.getAttribute('aria-valuenow'), max: el.getAttribute('aria-valuemax') } : null;
  })()`);
  check("应用更新：下载中显示真实进度条与取消入口",
    t2.includes("取消下载") && bar && bar.now === "40" && bar.max === "100",
    "含取消下载，progressbar 40/100",
    JSON.stringify({ bar, hasCancel: t2.includes("取消下载") }));

  await mount({ ...base, phase: "ready" });
  const readyText = await text();
  check("ready 状态不再显示会丢弃已下载字节的「稍后」",
    !readyText.includes("稍后"), "无 稍后 按钮", JSON.stringify({ tail: String(readyText).slice(-120) }));
  const installRect = await cdp.eval(`(() => {
    const b = [...document.querySelectorAll('button')].find((x) => (x.innerText || '').includes('安装并重启'));
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return { top: Math.round(r.top), left: Math.round(r.left) };
  })()`);
  await cdp.eval(`(() => {
    const b = [...document.querySelectorAll('button')].find((x) => (x.innerText || '').includes('安装并重启'));
    if (b) b.click();
    return !!b;
  })()`);
  await sleep(200);
  const t3 = await text();
  check("应用更新：安装必须先出现二次确认（不点确认不安装）",
    t3.includes("安装会退出应用并重启") && t3.includes("确认安装"),
    "出现确认文案与确认键",
    JSON.stringify({ head: String(t3).slice(0, 200) }));

  // 用户 2026-10-25：二次确认不该在安装按钮**下面**另起一块，也不该同时留着两个安装入口。
  const confirmGeom = await cdp.eval(`(() => {
    const buttons = [...document.querySelectorAll('button')];
    const install = buttons.filter((b) => (b.innerText || '').includes('安装并重启'));
    const confirm = buttons.find((b) => (b.innerText || '').trim() === '确认安装');
    const hint = [...document.querySelectorAll('p')].find((p) => (p.innerText || '').includes('安装会退出应用并重启'));
    const box = hint ? hint.parentElement.getBoundingClientRect() : null;
    return {
      installCount: install.length,
      confirm: !!confirm,
      boxTop: box ? Math.round(box.top) : null,
      confirmTop: confirm ? Math.round(confirm.getBoundingClientRect().top) : null,
    };
  })()`);
  // 2026-10-29 产品决定：确认改成**弹窗**（原先是内联块，两格判据随这次决定改写）。
  const dlg = await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    if (!d) return { open: false };
    const txt = d.innerText || '';
    return { open: true, txt, hasConfirm: /确认安装/.test(txt), hasCancel: /取消/.test(txt) };
  })()`);
  check("应用更新：点安装弹出确认框（有确认/取消两键，不点确认不安装）",
    dlg.open === true && dlg.hasConfirm === true && dlg.hasCancel === true,
    "dialog + 确认安装 + 取消", JSON.stringify(dlg));
  await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    const b = d ? [...d.querySelectorAll('button')].find((x) => (x.innerText || '').trim() === '取消') : null;
    if (b) b.click();
    return !!b;
  })()`);
  await sleep(500);
  const dlgAfter = await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    return { open: !!d, txt: d ? (d.innerText || '').replace(/\\s+/g, ' ').slice(0, 120) : '' };
  })()`);
  check("应用更新：取消确认后框关闭（什么都没装）", dlgAfter.open === false, "dialog 已关闭", JSON.stringify(dlgAfter));

  // 2026-11-08 用户直报：点「确认安装」后弹窗不应立刻消失 —— 应切 loading 并留到重启前一刻。
  await cdp.eval(`(() => {
    const b = [...document.querySelectorAll('button')].find((x) => (x.innerText || '').includes('安装并重启'));
    if (b) b.click();
    return !!b;
  })()`);
  await sleep(200);
  await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    const b = d ? [...d.querySelectorAll('button')].find((x) => (x.innerText || '').trim() === '确认安装') : null;
    if (b) b.click();
    return !!b;
  })()`);
  await sleep(300);
  const dlgBusy = await cdp.eval(`(() => {
    const d = document.querySelector('[role="dialog"]');
    if (!d) return { open: false };
    // 只看页脚两个键：标题栏的 ✕ 由 onCancel 的 busy 守卫吞掉（不改它的 disabled 属性）。
    const footer = [...d.querySelectorAll('button')].filter((b) => {
      const s = (b.innerText || '').trim();
      return s === '取消' || s.includes('正在安装');
    });
    return {
      open: true,
      footer: footer.map((b) => ({ txt: (b.innerText || '').trim().slice(0, 24), disabled: b.disabled })),
      txt: (d.innerText || '').slice(0, 160),
    };
  })()`);
  check("应用更新：点确认后弹窗不消失，切 loading 且两键禁用",
    dlgBusy.open === true && Array.isArray(dlgBusy.footer) && dlgBusy.footer.length === 2
      && dlgBusy.footer.every((b) => b.disabled === true) && /正在安装/.test(dlgBusy.txt),
    "dialog 仍在 / 取消与主键 disabled / 主键显示安装中",
    JSON.stringify(dlgBusy));

  // 下载一半失败：要说清楚已下多少、重试从头
  await mount({ ...base, phase: "error", error: "network", downloaded: 40, total: 100 });
  const tHalf = await text();
  check("应用更新：下载中途失败时说明已下载量与重试代价",
    tHalf.includes("上次已下载") && tHalf.includes("重试会从头开始"),
    "含「上次已下载 … 重试会从头开始」", JSON.stringify({ tail: String(tHalf).slice(-160) }));

  // 说明是 Markdown：标题/粗体渲染出来，脚本必须被消毒掉
  await mount({ ...base, info: { ...base.info, notes: "### 修了什么\n\n- **重要**：修复 A\n- 修复 B\n<script>window.__xss = 1</script>" } });
  const md = await cdp.eval(`(() => ({
    h3: (document.querySelector('h3') || {}).textContent || '',
    strong: (document.querySelector('strong') || {}).textContent || '',
    li: document.querySelectorAll('li').length,
    script: document.querySelectorAll('#probe-host script').length,
    xss: !!window.__xss,
  }))()`);
  check("应用更新：更新说明按 Markdown 渲染（标题/粗体/列表），且脚本被消毒",
    md.h3.includes("修了什么") && md.strong.includes("重要") && md.li >= 2 && md.script === 0 && md.xss === false,
    "h3/strong/li 都在，script=0", JSON.stringify(md));

  await mount({ ...base, info: null, phase: "idle" }, false);
  const t4 = await text();
  const checkBtn = await cdp.eval(`(() => [...document.querySelectorAll('button')]
    .some((b) => (b.innerText || '').trim() === '检查更新'))()`);
  check("应用更新：移动端不支持时只给手动渠道说明，不给检查按钮",
    t4.includes("移动端不支持应用内更新") && checkBtn === false,
    "含移动端说明且没有文案为「检查更新」的按钮",
    JSON.stringify({ head: String(t4).slice(0, 180), checkBtn }));

  const geom = await cdp.eval(`(() => ({
    vw: innerWidth,
    sw: document.documentElement.scrollWidth,
    host: (() => { const h = document.getElementById('probe-host'); return h ? Math.round(h.getBoundingClientRect().width) : 0; })(),
  }))()`);
  check("应用更新：390 宽下不横向溢出",
    geom.sw <= geom.vw + 1,
    "scrollWidth<=vw",
    JSON.stringify(geom));
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
}

/**
 * 移动端「聊天列穿透左侧列表」（--only=bleed，2026-11-06 用户截图 524×1024）。
 *
 * 定性：`aside` 与 `main` 在移动布局里**都绝对定位、都铺满整屏**，`main` 在上层（z-20），
 * 而它自己只是一层 `--ambient-canvas-base` 的 16% 薄纱（html[data-ambient] 下与 fog 合成）。
 * 22ee3301 把 ChatWindow 根改成 `ambient-canvas-child`（自身背景清空）之后，那 16% 的薄纱
 * 下面直接就是平移 -30% 的 `aside`（列表），于是列表文字/底纹从薄纱里透出来。
 * 桌面布局里 `aside` 是 in-flow（与 `main` 水平并排），没有"下层"可透，所以只在 ≤767 出现。
 *
 * 量法：六档宽度 × 亮/暗 × frost 开/关，读四层 computed `background-color`，再用
 * 「把 aside 设为 visibility:hidden 前后、同一批采样点的像素差」作为**穿透量**。
 * 修复后 aside 在聊天列下面是 `visibility:hidden`（过渡结束后才切，保留视差），
 * 所以同点色差必须为 0；桌面档用矩形不相交做结构判据（隐藏 aside 会改布局，不能做差分）。
 *
 * 闸：`fog 开` 时 `main` 的 alpha 必须仍然很低（≤0.35）——不许用"把聊天列改成不透明"糊过去。
 */
async function runBleed(cdp, url) {
  const WIDTHS = [1280, 900, 768, 640, 430, 390];
  const HEIGHT = 800;
  const MOBILE_MAX = 767;
  const outFile = path.join(ROOT, "test-results", "bleed-readings.json");
  const shotDir = path.join(ROOT, "test-results", "bleed-shots");
  fs.mkdirSync(shotDir, { recursive: true });

  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});

  // ⚠️ 必须**在挂载前**把视口设成目标宽度：`isMobile` 的初值在 store 创建时
  // 由 `resolveMobileLayout`（平台优先、宽度兜底）算一次，挂载后再改 ref 只会改
  // 我们 import 到的 store，不会触发已挂载布局的重渲染（探针里没有 init 的 resize 监听）。
  const boot = async (width) => {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width, height: HEIGHT, deviceScaleFactor: 1, mobile: false,
    }).catch(() => {});
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_200);
    await cdp.eval(PAGE_FIXTURE);

    await cdp.eval(`(async () => {
      window.__TAURI_INTERNALS__ = window.__TAURI_INTERNALS__ || {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      window.__TAURI_EVENT_PLUGIN_INTERNALS__ = window.__TAURI_EVENT_PLUGIN_INTERNALS__ || { unregisterListener: () => {} };
      await window.__probe.install('/src/layouts/ResponsiveLayout.vue', '', ${
        JSON.stringify(JSON.stringify({ router: true, hostHeight: `${HEIGHT}px` }))
      });
      const host = document.getElementById('probe-host');
      host.className = (host.className + ' ambient-canvas').trim();
      host.style.setProperty('--ambient-canvas-base', 'var(--gosslan-chat)');
      host.style.background = '';
      // ambient 层必须在 install **之后**补装：install 会把 body.innerHTML 清掉。
      if (!document.querySelector('.ambient')) {
        const A = await import('/src/utils/ambient.ts');
        A.installAmbient();
      }
    })()`);

    // 种子：列表要有真实行（穿透的像素差来自行文字），聊天列要有真实消息。
    await cdp.eval(`(async () => {
      const { useChatStore } = await import('/src/stores/useChatStore.ts');
      const chat = useChatStore();
      const conv = 'peer-demo';
      chat.conversations = [
        { id: conv, kind: 'single', name: '林岸', avatar: null, last_msg: '晚点把图发你', last_ts: 1700000000100, unread: 0, pinned: true },
        { id: 'peer-2', kind: 'single', name: '安德烈 P4N', avatar: null, last_msg: '徽章做好了', last_ts: 1700000000090, unread: 2, pinned: false },
        { id: 'peer-3', kind: 'group', name: '设计评审组', avatar: null, last_msg: '就按这个方向走', last_ts: 1700000000080, unread: 9, pinned: false },
        { id: 'peer-4', kind: 'single', name: 'Kong', avatar: null, last_msg: '收到', last_ts: 1700000000070, unread: 0, pinned: false },
        { id: 'peer-5', kind: 'group', name: '发版线', avatar: null, last_msg: '5.18.35 过闸', last_ts: 1700000000060, unread: 0, pinned: false },
      ];
      chat.messages[conv] = Array.from({ length: 18 }, (_, i) => ({
        id: 'm' + i, conv_id: conv, sender_id: i % 2 ? conv : 'self', kind: 'text',
        text: '第 ' + (i + 1) + ' 条：窗口缩窄后这里不应该露出列表文字。',
        ts: 1700000000000 + i * 1000, status: 'sent', media: null,
      }));
      chat.activeConv = conv;
      const R = await import('/src/router/main.ts');
      await R.mainRouter.push({ name: 'conversation', params: { convId: conv } });
      await new Promise((r) => setTimeout(r, 900));
    })()`);
    await sleep(700);
  };

  const LAYERS = `(() => {
    const host = document.getElementById('probe-host');
    const st = (el) => (el ? getComputedStyle(el) : null);
    const bg = (el) => { const s = st(el); return s ? String(s.backgroundColor) : 'none'; };
    const bf = (el) => { const s = st(el); return s ? String(s.backdropFilter || s.webkitBackdropFilter || 'none') : 'none'; };
    const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height }; };
    const main = host ? host.querySelector('main') : null;
    const aside = host ? host.querySelector('aside.ambient-canvas') : null;
    const chatRoot = main ? main.querySelector('[data-lang-menu-boundary]') : null;
    const body = chatRoot || main;
    const listArea = body ? body.querySelector('.vlist') : null;
    const kids = body ? [...body.querySelectorAll('.ambient-canvas-child')].filter((el) => el.className.includes('shrink-0')) : [];
    const composer = kids.length ? kids[kids.length - 1] : null;
    return {
      isMobile: document.documentElement.classList.contains('is-mobile'),
      vw: innerWidth,
      host: { bg: bg(host), rect: rect(host) },
      aside: {
        exists: !!aside, vis: aside ? st(aside).visibility : 'none', pos: aside ? st(aside).position : 'none',
        bg: bg(aside), rect: rect(aside), text: aside ? (aside.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 48) : '',
      },
      main: { exists: !!main, bg: bg(main), bf: bf(main), rect: rect(main) },
      chatRoot: { exists: !!chatRoot, bg: chatRoot ? bg(chatRoot) : 'none', rect: rect(chatRoot) },
      listArea: { bg: listArea ? bg(listArea) : 'none' },
      composer: { bg: composer ? bg(composer) : 'none' },
    };
  })()`;

  const alphaOf = (s) => {
    const slash = /\/\s*([\d.]+)\s*\)/.exec(s || "");
    if (slash) return parseFloat(slash[1]);
    const rgba = /rgba\(\s*[\d.]+\s*,\s*[\d.]+\s*,\s*[\d.]+\s*,\s*([\d.]+)\s*\)/.exec(s || "");
    return rgba ? parseFloat(rgba[1]) : 1;
  };
  const hexRgb = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];

  const sample = async (points) => {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    const hexes = await cdp.eval(`(async () => {
      const im = new Image();
      im.src = 'data:image/png;base64,' + ${JSON.stringify(shot.data)};
      await new Promise((res, rej) => { im.onload = () => res(true); im.onerror = () => rej(new Error('img')); });
      const cv = document.createElement('canvas');
      cv.width = im.width; cv.height = im.height;
      const ctx = cv.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(im, 0, 0);
      const sx = im.width / innerWidth, sy = im.height / innerHeight;
      const hex = (d) => '#' + [d[0], d[1], d[2]].map((v) => v.toString(16).padStart(2, '0')).join('');
      return ${JSON.stringify(points)}.map((p) => {
        const x = Math.min(im.width - 1, Math.max(0, Math.round(p.x * sx)));
        const y = Math.min(im.height - 1, Math.max(0, Math.round(p.y * sy)));
        const d = ctx.getImageData(x, y, 1, 1).data;
        return hex(d);
      });
    })()`);
    return { data: shot.data, hexes };
  };

  /** 采样点：聊天列左缘竖条（用户截图里露字的那一带）+ 底部横条。 */
  const gridPoints = (r) => {
    const pts = [];
    for (let y = Math.round(r.y + 40); y <= r.y + r.h - 30; y += 10) {
      for (const dx of [6, 18, 34, 54]) pts.push({ x: Math.round(r.x + dx), y });
    }
    for (let x = Math.round(r.x + 20); x <= r.x + r.w - 20; x += 24) {
      pts.push({ x, y: Math.round(r.y + r.h - 16) });
    }
    return pts;
  };

  const rows = [];
  // `isMobile` 在 store 创建时按**当时视口**算一次，探针没跑 `app.init()` 的 resize 监听，
  // 所以每跨过 `≤767` 这条线都必须重新 boot（navigate → install）；同一布局组内只改视口。
  const BOOT_AT = new Map([[1280, 1280], [900, 1280], [768, 1280], [640, 640], [430, 640], [390, 640]]);
  let bootedAt = null;
  for (const width of WIDTHS) {
    const anchor = BOOT_AT.get(width);
    if (bootedAt !== anchor) {
      await boot(anchor);
      bootedAt = anchor;
    } else if (width !== anchor) {
      await cdp.send("Emulation.setDeviceMetricsOverride", {
        width, height: HEIGHT, deviceScaleFactor: 1, mobile: false,
      }).catch(() => {});
      await sleep(800);
    }
    const isMobile = width <= MOBILE_MAX;
    // `applyIsMobile()` 是 `html.is-mobile` 的唯一写入方，探针没跑 init，这里按同一宽度兜底补上
    // （只影响 `.conv-footer-safe` 这类布局补偿，不参与穿透定性）。
    await cdp.eval(`(() => {
      document.documentElement.classList.toggle('is-mobile', ${isMobile});
      return true;
    })()`);
    await sleep(500);

    const combos = [];
    for (const dark of [false, true]) {
      for (const frostOn of [true, false]) {
        combos.push({ tag: `${dark ? "暗" : "亮"}-fog-frost${frostOn ? "on" : "off"}`, dark, fog: true, frostOn });
      }
    }
    combos.push({ tag: "亮-fogoff-froston", dark: false, fog: false, frostOn: true });

    for (const c of combos) {
      await cdp.eval(`(() => {
        const h = document.documentElement;
        h.classList.toggle('dark', ${c.dark});
        h.dataset.ambient = ${JSON.stringify(c.fog ? "static" : "off")};
        if (${!c.frostOn}) h.dataset.frost = 'off'; else delete h.dataset.frost;
        return true;
      })()`);
      await sleep(260);
      const layer = await cdp.eval(LAYERS);
      const rec = { width, tag: c.tag, isMobile, layer };

      if (isMobile) {
        const pts = gridPoints(layer.main.rect);
        const a = await sample(pts);
        await cdp.eval(`(() => { const a = document.querySelector('#probe-host aside.ambient-canvas'); if (a) a.style.visibility = 'hidden'; return true; })()`);
        await sleep(160);
        const b = await sample(pts);
        await cdp.eval(`(() => { const a = document.querySelector('#probe-host aside.ambient-canvas'); if (a) a.style.visibility = ''; return true; })()`);
        let maxD = 0, hit = 0, worst = null;
        for (let i = 0; i < pts.length; i++) {
          const x = hexRgb(a.hexes[i]), y = hexRgb(b.hexes[i]);
          const d = Math.max(Math.abs(x[0] - y[0]), Math.abs(x[1] - y[1]), Math.abs(x[2] - y[2]));
          if (d > maxD) { maxD = d; worst = { ...pts[i], withList: a.hexes[i], listHidden: b.hexes[i] }; }
          if (d > 2) hit += 1;
        }
        rec.maxD = maxD;
        rec.hit = hit;
        rec.points = pts.length;
        rec.worst = worst;
        if ((width === 390 || width === 1280) && c.fog && c.frostOn) {
          const name = `bleed-${width}-${c.dark ? "dark" : "light"}.png`;
          fs.writeFileSync(path.join(shotDir, name), Buffer.from(a.data, "base64"));
          rec.shot = name;
        }
      } else {
        const ar = layer.aside.rect, mr = layer.main.rect;
        rec.overlap = Math.max(0, Math.round(ar.x + ar.w - mr.x));
        if (width === 1280 && c.fog && c.frostOn) {
          const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
          const name = `bleed-${width}-${c.dark ? "dark" : "light"}.png`;
          fs.writeFileSync(path.join(shotDir, name), Buffer.from(shot.data, "base64"));
          rec.shot = name;
        }
      }
      rows.push(rec);

      const tail = isMobile
        ? `main=${layer.main.bg} α=${alphaOf(layer.main.bg)} | aside.vis=${layer.aside.vis} pos=${layer.aside.pos} bg=${layer.aside.bg} | chat=${layer.chatRoot.bg} | 输入区=${layer.composer.bg} | Δ=${rec.maxD}(超2色阶 ${rec.hit}/${rec.points})`
        : `aside=${layer.aside.rect ? Math.round(layer.aside.rect.x) + ".." + Math.round(layer.aside.rect.x + layer.aside.rect.w) : "-"} main.x=${Math.round(layer.main.rect.x)} 重叠=${rec.overlap}px`;
      console.log(`  · ${width}px ${c.tag}: ${tail}`);
    }

    const light = rows.filter((r) => r.width === width && r.tag === "亮-fog-froston").pop();
    if (isMobile) {
      // 反向（聊天 → 列表）：`pane-under-chat` 被摘掉、`visibility` 立刻回到可见 ——
      // 证明修复只隐藏「被盖住」的列表，没有把 push/pop 里滑出的列表一起藏掉。
      await cdp.eval(`(async () => {
        const R = await import('/src/router/main.ts');
        await R.mainRouter.push({ name: 'chats' });
        await new Promise((r) => setTimeout(r, 500));
      })()`);
      await sleep(400);
      const back = await cdp.eval(LAYERS);
      check(`穿透 ${width}px：回到列表态时列表立刻恢复可见（视差方向未被修坏）`,
        back.aside.vis === "visible" && Math.round(back.main.rect.x) >= width,
        "aside.visibility=visible 且 main 已滑出屏幕右缘",
        `aside.vis=${back.aside.vis} main.x=${Math.round(back.main.rect.x)} vw=${back.vw}`);
      await cdp.eval(`(async () => {
        const R = await import('/src/router/main.ts');
        await R.mainRouter.push({ name: 'conversation', params: { convId: 'peer-demo' } });
        await new Promise((r) => setTimeout(r, 500));
      })()`);
      await sleep(400);
      check(`穿透 ${width}px：列表在聊天列下面时已退出合成（aside visibility）`,
        light.layer.aside.vis === "hidden",
        "aside.visibility=hidden（平移结束后再切，保留视差）",
        `aside.visibility=${light.layer.aside.vis} / position=${light.layer.aside.pos} / main=${light.layer.main.bg}`);
      check(`穿透 ${width}px：聊天列自身画布仍允许雾穿透（未改成不透明）`,
        alphaOf(light.layer.main.bg) <= 0.35,
        "main 的 background alpha ≤0.35（薄纱保留）",
        `${light.layer.main.bg} α=${alphaOf(light.layer.main.bg)}`);
      for (const r of rows.filter((x) => x.width === width)) {
        check(`穿透 ${width}px ${r.tag}：聊天列与左侧列表之间无可见穿透`,
          r.maxD <= 1,
          "隐藏列表前后同点像素差 ≤1 色阶（≈ 不存在可辨穿透）",
          `Δ=${r.maxD} 超2色阶=${r.hit}/${r.points}${r.worst ? " 最差点=" + JSON.stringify(r.worst) : ""}`);
      }
    } else {
      check(`穿透 ${width}px：桌面布局里列表与聊天列水平不交叠（不存在下层可透）`,
        light.overlap === 0 && light.layer.aside.vis === "visible",
        "aside.right <= main.left 且 aside.visibility=visible",
        `重叠=${light.overlap}px aside.vis=${light.layer.aside.vis} aside=${JSON.stringify(light.layer.aside.rect)} main.x=${Math.round(light.layer.main.rect.x)}`);
    }
  }

  // 桌面标题栏 LAN 徽标（2026-11-10 用户）：桌面没有「我的」列表那一栏，
  // 点标题栏这枚 LAN · N 必须能打开网络拓扑整页。量两件事：
  // 徽标是带 aria-label 的按钮、点击后 force-graph 的 canvas 真的挂出来。
  await boot(1280);
  const lanEntry = await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const host = document.getElementById('probe-host');
    const pill = [...host.querySelectorAll('button')]
      .find((b) => (b.getAttribute('aria-label') || '').startsWith(I.t('topology.title')));
    if (!pill) return { found: false };
    const r = pill.getBoundingClientRect();
    // @click 听的是 click 事件：直接派发一颗带坐标的 MouseEvent（pointerdown/up 不会合成 click）。
    pill.dispatchEvent(new MouseEvent('click', {
      bubbles: true, cancelable: true, button: 0,
      clientX: Math.round(r.left + r.width / 2), clientY: Math.round(r.top + r.height / 2),
    }));
    // topology 是 defineAsyncComponent + 独立 chunk：给 dev 现编译留有界等待。
    let opened = false;
    for (let i = 0; i < 20 && !opened; i += 1) {
      await new Promise((res) => setTimeout(res, 200));
      opened = !!document.querySelector('#probe-host .force-graph-container canvas');
    }
    const stats = document.querySelector('[data-topo-stats]');
    return { found: true, x: Math.round(r.left), y: Math.round(r.top), opened, hasStats: !!stats };
  })()`);
  check("桌面标题栏 LAN 徽标可点：点开网络拓扑整页（force-graph 真的挂出来）",
    lanEntry.found === true && lanEntry.opened === true && lanEntry.hasStats === true,
    "aria=网络拓扑 + 点后 canvas 与统计行出现",
    JSON.stringify(lanEntry));

  fs.writeFileSync(outFile, JSON.stringify({ widths: WIDTHS, mobileMax: MOBILE_MAX, rows }, null, 2));
}

/**
 * 移动端图片预览的左右滑动切图（`--only=imgswipe`，用户 2026-11-09：
 * 「多图片预览模式，左右滑动图片没法上一张下一张」）。
 *
 * 这一段先把"完全不响应"与"偶尔不响应"分开：同一张相册（3 张真尺寸 SVG）、同一组阈值，
 * 只用 CDP `Input.dispatchTouchEvent` 改变**手指落点**——
 *   ① 图片上；② 图片左侧黑边；③ 图片上/下方的留白。
 * 判据是 `update:index` 真的变了（不是"事件到了"）。反例自证：短滑（<60px）与竖滑
 * 必须**不**切图 —— 否则上面几条只是"任何手势都切图"的空转。
 */
async function runImgSwipe(cdp, url) {
  const W = 390;
  const H = 844;
  const UA = "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36";
  const outFile = path.join(ROOT, "test-results", "imgswipe-readings.json");

  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: W, height: H, deviceScaleFactor: 2, mobile: true,
  }).catch(() => {});
  await cdp.send("Emulation.setUserAgentOverride", { userAgent: UA }).catch(() => {});
  // 触摸模拟必须显式开：`Input.dispatchTouchEvent` 在没开时不会产生 pointer 事件
  // （上一版就是这样：8 条判据里 4 条"手势没到"伪红，改的是量具不是产品）。
  await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 1 }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(2_200);
  await cdp.eval(PAGE_FIXTURE);
  const mounted = await cdp.eval(`window.__probe.zoomMount()`);
  check("预览手势：灯箱挂载成功（3 张真尺寸图）", !!mounted && mounted.ok === true,
    "ok:true", JSON.stringify(mounted));
  if (!mounted || mounted.ok !== true) {
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
    return;
  }
  await sleep(1_000);

  const geo = await cdp.eval(`(() => {
    const rect = (el) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { l: +b.left.toFixed(1), t: +b.top.toFixed(1), r: +b.right.toFixed(1), b: +b.bottom.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) };
    };
    return {
      img: rect(document.querySelector('[data-lightbox-img]')),
      stage: rect(document.querySelector('[data-lightbox-stage]')),
      shade: rect(document.querySelector('[role="dialog"]')),
      vw: innerWidth, vh: innerHeight,
    };
  })()`);
  console.log(`  · 几何：图 ${JSON.stringify(geo.img)} 舞台 ${JSON.stringify(geo.stage)} 视口 ${geo.vw}×${geo.vh}`);
  if (!geo.img || geo.img.w <= 0) {
    check("预览手势：图片已落定（量得到真矩形）", false, "img.w > 0", JSON.stringify(geo.img));
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
    return;
  }

  const setIndex = (i) => cdp.eval(`(async () => {
    window.__lbState.index = ${i};
    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
    return window.__lbState.index;
  })()`);
  const getIndex = () => cdp.eval(`window.__lbState.index`);
  const getPropIndex = () => cdp.eval(`(() => {
    const el = document.querySelector('[data-lightbox-img]');
    let inst = el && el.__vueParentComponent;
    let hops = 0;
    while (inst && !(inst.props && Array.isArray(inst.props.images)) && hops < 8) { inst = inst.parent; hops += 1; }
    return inst ? inst.props.index : null;
  })()`);

  const swipe = async (from, dx, dy = 0) => {
    const steps = 6;
    await cdp.send("Input.dispatchTouchEvent", {
      type: "touchStart", touchPoints: [{ x: Math.round(from.x), y: Math.round(from.y) }],
    });
    for (let i = 1; i <= steps; i++) {
      await cdp.send("Input.dispatchTouchEvent", {
        type: "touchMove",
        touchPoints: [{ x: Math.round(from.x + (dx * i) / steps), y: Math.round(from.y + (dy * i) / steps) }],
      });
      await sleep(16);
    }
    await cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
    await sleep(260);
  };

  const imgMid = { x: geo.img.l + geo.img.w / 2, y: geo.img.t + geo.img.h / 2 };
  const leftBar = { x: Math.max(6, geo.img.l - 18), y: imgMid.y };
  const topGap = { x: imgMid.x, y: Math.max(geo.shade.t + 72, geo.img.t - 30) };
  const rows = [];

  const caseSwipe = async (tag, from, dx, dy, expectFrom, expectTo) => {
    await setIndex(expectFrom);
    const before = await getPropIndex();
    await swipe(from, dx, dy);
    const to = await getIndex();
    const after = await getPropIndex();
    rows.push({ tag, from, dx, dy, expectFrom, expectTo, to, propBefore: before, propAfter: after });
    console.log(`  · ${tag}：起点 (${Math.round(from.x)},${Math.round(from.y)}) d=(${dx},${dy}) ⇒ state ${expectFrom} → ${to}｜prop ${before} → ${after}`);
    return to;
  };

  // ① 图片上左滑 = 下一张；② 图片上右滑 = 上一张（方向不能反）
  const imgNext = await caseSwipe("图片上左滑", imgMid, -120, 0, 1, 2);
  check("预览手势：图片上左滑 = 下一张", imgNext === 2, "index 1 → 2", String(imgNext));
  const imgPrev = await caseSwipe("图片上右滑", imgMid, 120, 0, 1, 0);
  check("预览手势：图片上右滑 = 上一张", imgPrev === 0, "index 1 → 0", String(imgPrev));

  // ③ 黑边（图片左侧留白）右滑 = 上一张 —— 用户报的正是这一档
  const barPrev = await caseSwipe("左侧黑边右滑", leftBar, 120, 0, 1, 0);
  check("预览手势：图片左侧黑边上横滑也能切图", barPrev === 0, "index 1 → 0", String(barPrev));
  const barOpen = await cdp.eval(`window.__lbState.open`);
  check("预览手势：黑边上横滑不会顺手关窗", barOpen === true, "open 仍为 true", String(barOpen));

  // ④ 图片上下留白横滑 = 切图
  const gapNext = await caseSwipe("上方留白左滑", topGap, -120, 0, 1, 2);
  check("预览手势：图片上/下留白横滑也能切图", gapNext === 2, "index 1 → 2", String(gapNext));

  // 反例自证：短滑与竖滑都不许切图（阈值那三条判据还活着）
  const short = await caseSwipe("短滑 30px", imgMid, 30, 0, 1, 1);
  check("预览手势反例：短滑（<60px）不切图", short === 1, "index 保持 1", String(short));
  const vertical = await caseSwipe("竖滑 120px", imgMid, 20, 120, 1, 1);
  check("预览手势反例：竖滑（|dy|>|dx|）不切图", vertical === 1, "index 保持 1", String(vertical));
  // 到头不回绕：第一张继续右滑
  const edge = await caseSwipe("第一张继续右滑", imgMid, 120, 0, 0, 0);
  check("预览手势：第一张继续右滑不回绕", edge === 0, "index 保持 0", String(edge));

  await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
  fs.writeFileSync(outFile, JSON.stringify({ viewport: { w: W, h: H }, geo, rows }, null, 2));
}

/**
 * 一行里「控件底边」与「气泡底边」的对齐（`--only=rowalign`，用户 2026-11-09：
 * 「感叹号和表情回复按钮和图片没有对齐，应该是视觉上底部对齐，和其他消息一样」）。
 *
 * 逐种消息类型量四个底边：气泡本体 / 气泡外壳 / 表情回应入口 / 回执。
 * 判据：无回应时入口与回执的**底边**都必须≈气泡底边（±1px）；有回应时入口≈外壳底边（减去回应条）。
 * 原因：入口是 absolute 锚在本列、回执在 `items-end` 的行里 —— 两者锚的不是同一个盒时，
 * 图片（高度由内容撑）就先露出来。
 */
async function runRowAlign(cdp, url) {
  const BASE = 1_700_000_000_000;
  const KINDS = ["text", "code", "file", "merge", "todo", "image"];
  const bodyByKind = {
    text: "这一条只用来量底边对齐：一行短文本。",
    code: "SELECT id FROM messages WHERE conv_id = 'c' ORDER BY seq;",
    file: JSON.stringify({ name: "季度报告.pdf", path: "/tmp/report.pdf", size: 123456 }),
    merge: JSON.stringify({ title: "群聊的聊天记录", items: [{ sender: "甲", text: "第一条" }] }),
    todo: JSON.stringify({
      todo_id: "t-align", title: "季度报告复核", status: "pending", creator: "peer-a",
      assignees: ["peer-a"], priority: "normal", category: "normal", number: 1,
    }),
    // 图片必须真能解码：旧格式兼容分支认 `content` 直接是 data URL（见 imageDataUrl）；
    // 写 JSON 元数据要走 IPC 取字节，夹具里拿不到 ⇒ 量到的永远是骨架。
    image: "data:image/svg+xml," + encodeURIComponent("<svg xmlns='http://www.w3.org/2000/svg' width='200' height='150'><rect width='200' height='150' fill='#3b82f6'/></svg>"),
  };

  const mount = async (kind, { mine = false, status = "sent", isGroup = true, reactions = null } = {}) => {
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    const props = {
      message: {
        msg_id: "m-align", sender_id: mine ? "self-align" : "peer-a", kind,
        content: bodyByKind[kind], ts: BASE, conv_id: "c-align", seq: 2, status,
      },
      reactions,
      canReact: true, isGroup, senderName: "对方", readerIds: isGroup ? ["peer-b"] : undefined,
    };
    const r = await cdp.eval("window.__probe.install('/src/components/MessageItem.vue', '', "
      + JSON.stringify(JSON.stringify(props)) + ")");
    if (mine) {
      await cdp.eval("window.__probe.seedDevice('self-align')");
      await sleep(250);
    }
    await sleep(450);
    return !!r && r.ok === true;
  };

  const measure = () => cdp.eval(`(() => {
    const host = document.getElementById('probe-host');
    const rect = (el) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { t: +b.top.toFixed(1), b: +b.bottom.toFixed(1), h: +b.height.toFixed(1) };
    };
    const shell = host.querySelector('[data-msg-bubble-shell]');
    const bubble = shell ? (shell.querySelector('[data-msg-bubble] > :first-child') || shell.firstElementChild) : null;
    const entry = host.querySelector('[data-reaction-entry]');
    const strip = host.querySelector('[data-reaction-strip]');
    // 回执没有 data 锚点：它在消息行里、与外壳同级（外壳前的那个兄弟）。
    const row = shell ? shell.parentElement : null;
    const receipt = row ? [...row.children].find((el) => el !== shell) : null;
    const failIcon = receipt ? receipt.querySelector('[role="img"], button') : null;
    const img = host.querySelector('[data-msg-bubble] img');
    const kids = bubble
      ? [...bubble.querySelectorAll('*')].filter((el) => el.getClientRects().length).slice(0, 6)
        .map((el) => ({ tag: el.tagName, cls: String(el.className).slice(0, 48), ...rect(el) }))
      : [];
    return {
      bubble: rect(bubble), shell: rect(shell), entry: rect(entry), strip: rect(strip),
      receipt: rect(receipt), fail: rect(failIcon), img: rect(img), kids,
      entryBottomStyle: entry ? entry.style.bottom : null,
    };
  })()`);

  // 回执根节点没有 data-receipt？用组件 class 兜底（见 MessageReceipt 的根元素）。
  await cdp.send("Page.enable").catch(() => {});
  const rows = [];
  const cases = [
    ...KINDS.map((k) => ({ kind: k, mine: false, tag: k + "·对方" })),
    ...KINDS.map((k) => ({ kind: k, mine: true, tag: k + "·自己·已发" })),
    { kind: "image", mine: true, status: "failed", tag: "image·自己·失败" },
    { kind: "text", mine: true, status: "failed", tag: "text·自己·失败" },
  ];
  for (const c of cases) {
    const ok = await mount(c.kind, { mine: c.mine, status: c.status ?? "sent" });
    const g = ok ? await measure() : null;
    rows.push({ tag: c.tag, ok, ...(g ?? {}) });
    console.log("  · " + c.tag + "：" + JSON.stringify(g));
  }
  fs.writeFileSync(path.join(ROOT, "test-results", "rowalign-readings.json"), JSON.stringify(rows, null, 2));

  // ── 判据 ──────────────────────────────────────────────────────────────
  // ① 非空转：图片这条必须真的"图比外框矮"（旧消息无尺寸 ⇒ 外框 288、图 150），
  //    否则"入口贴图底"在已知尺寸的图上恒等于"贴框底"，判不出任何东西。
  const imgRow = rows.find((r) => r.tag === "image·对方");
  const letterboxed = !!imgRow && !!imgRow.img && !!imgRow.bubble && imgRow.img.h > 0
    && imgRow.bubble.b - imgRow.img.b > 4;
  check("行对齐：图片夹具真的出现了「图比外框矮」（否则这一组是空转）", letterboxed,
    "bubble.bottom − img.bottom > 4", JSON.stringify(imgRow && { bubble: imgRow.bubble, img: imgRow.img }));

  // ② 每种消息：表情入口底边贴**内容**底边（无回应条时 = 气泡底边；图片 = 图底）。
  for (const r of rows.filter((x) => x.ok && !r2strip(x))) {
    const ref = r.img && r.img.h > 0 ? r.img.b : r.bubble && r.bubble.b;
    if (ref == null || !r.entry) continue;
    check(`行对齐 ${r.tag}：表情入口底边贴内容底边（≤1px）`, Math.abs(r.entry.b - ref) <= 1,
      "|entry.bottom − ref.bottom| ≤ 1", `entry=${r.entry.b} ref=${ref}`);
  }

  // ③ 自己的消息：回执容器底边也贴内容底边（图片按图底，其它按气泡底）。
  for (const r of rows.filter((x) => x.ok && x.receipt && !r2strip(x))) {
    const ref = r.img && r.img.h > 0 ? r.img.b : r.bubble && r.bubble.b;
    if (ref == null) continue;
    check(`行对齐 ${r.tag}：回执底边贴内容底边（≤1px）`, Math.abs(r.receipt.b - ref) <= 1,
      "|receipt.bottom − ref.bottom| ≤ 1", `receipt=${r.receipt.b} ref=${ref}`);
  }
}

/** 有回应条时入口锚的是回应条底边，另一条判据管，不在这组里重复判。 */
function r2strip(row) {
  return !!row.strip;
}

/**
 * 列表→聊天**转场中**的穿透（`--only=panefade`，2026-11-09 安卓端「列表在底部残余一下」）。
 *
 * 与 `--only=bleed` 的分工：bleed 量的是**静止终态**（列表已 `visibility: hidden`），
 * 这一段量的是 0–280ms 的**过程**：列表整屏宽、只平移 −30%，右侧 70% 一直压在聊天列
 * （薄纱 α 0.16/0.14）下面 ⇒ 旧列表整段透出。修法是随进度把列表裁到聊天列左缘之外
 * （`pane-parallax` 的 `inset(0 0 0 0)` + `.pane-under-chat` 的 `inset(0 70% 0 0)`，
 * 与 −30% 平移互补）。
 *
 * 取证方法（确定性，不靠抓帧时机）：
 *   1) 把文档时间轴放慢（`Animation.setPlaybackRate` 0.05×）再触发真实路由 push；
 *   2) 用 `Animation.animationStarted` 收 CSSTransition 的 id，`setPaused` + `seekAnimations`；
 *   3) 缓动曲线前段很快 ⇒ 按 aside 的**实际位移**二分到目标进度 e（0.4/0.7/0.95）；
 *   4) 截图 A（列表可见）→ 隐藏列表 → 截图 B，只在「被聊天列盖住」的区域逐点比色。
 *
 * 闸：每个姿态盖住区最大色差 ≤2。反例自证：同一姿态把裁剪内联改回 `inset(0 0 0 0)`
 * 必须重新出现可辨穿透（实测 e=0.95 处 171 色阶 / 30+ 点，不是空转）。
 * 另外核一条结构判据：裁剪比例 / 70% 必须等于平移进度 / 30% 的进度（两根时钟锁死）。
 */
async function runPaneFade(cdp, url) {
  const W = 390;
  const H = 844;
  const DUR = 280;
  const POSES = [0.4, 0.7, 0.95];
  const UA = "Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Mobile Safari/537.36";
  const outFile = path.join(ROOT, "test-results", "panefade-readings.json");
  const shotDir = path.join(ROOT, "test-results", "panefade-shots");
  fs.mkdirSync(shotDir, { recursive: true });

  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});
  // 视口必须在**挂载前**设好：`isMobile` 的初值在 store 创建时算一次（同 runBleed）。
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: W, height: H, deviceScaleFactor: 2, mobile: true,
  }).catch(() => {});
  await cdp.send("Emulation.setUserAgentOverride", { userAgent: UA }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(2_200);
  await cdp.eval(PAGE_FIXTURE);
  await cdp.eval(`(async () => {
    window.__TAURI_INTERNALS__ = window.__TAURI_INTERNALS__ || {
      metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
      invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
    };
    window.__TAURI_EVENT_PLUGIN_INTERNALS__ = window.__TAURI_EVENT_PLUGIN_INTERNALS__ || { unregisterListener: () => {} };
    await window.__probe.install('/src/layouts/ResponsiveLayout.vue', '', ${
      JSON.stringify(JSON.stringify({ router: true, hostHeight: `${H}px` }))
    });
    return true;
  })()`);
  // 种子：列表要有真实行文字（穿透的色差来自行文字），聊天列要有真实消息。
  await cdp.eval(`(async () => {
    const { useChatStore } = await import('/src/stores/useChatStore.ts');
    const chat = useChatStore();
    const conv = 'peer-demo';
    chat.conversations = [
      { id: conv, kind: 'single', name: '林岸', avatar: null, last_msg: '晚点把图发你', last_ts: 1700000000100, unread: 0, pinned: true },
      { id: 'peer-2', kind: 'single', name: '安德烈 P4N', avatar: null, last_msg: '徽章做好了', last_ts: 1700000000090, unread: 2, pinned: false },
      { id: 'peer-3', kind: 'group', name: '设计评审组', avatar: null, last_msg: '就按这个方向走', last_ts: 1700000000080, unread: 9, pinned: false },
      { id: 'peer-4', kind: 'single', name: 'Kong', avatar: null, last_msg: '收到', last_ts: 1700000000070, unread: 0, pinned: false },
      { id: 'peer-5', kind: 'group', name: '发版线', avatar: null, last_msg: '5.20.4 过闸', last_ts: 1700000000060, unread: 0, pinned: false },
    ];
    chat.messages[conv] = Array.from({ length: 12 }, (_, i) => ({
      id: 'm' + i, conv_id: conv, sender_id: i % 2 ? conv : 'self', kind: 'text',
      text: '第 ' + (i + 1) + ' 条：列表到聊天的转场中途，这里不该露出旧列表。',
      ts: 1700000000000 + i * 1000, status: 'sent', media: null,
    }));
    chat.activeConv = conv;
    const R = await import('/src/router/main.ts');
    await R.mainRouter.push({ name: 'chats' });
    await new Promise((r) => setTimeout(r, 900));
    const A = await import('/src/utils/ambient.ts');
    A.installAmbient();
    document.documentElement.dataset.ambient = 'static';
    await new Promise((r) => setTimeout(r, 500));
    return true;
  })()`);
  await sleep(700);

  const isMobile = await cdp.eval(`document.documentElement.classList.contains('is-mobile')`);
  check("转场：探针落在移动档（否则这一段测的是桌面布局）", isMobile === true,
    "html.is-mobile", String(isMobile));
  if (!isMobile) return;

  const animIds = [];
  cdp.on("Animation.animationStarted", (p) => {
    const a = p && p.animation;
    if (a && a.type === "CSSTransition") animIds.push(a.id);
  });
  await cdp.send("Animation.enable").catch(() => {});

  const pushConv = `(async () => {
    const R = await import('/src/router/main.ts');
    void R.mainRouter.push({ name: 'conversation', params: { convId: 'peer-demo' } });
    return true;
  })()`;
  const backToChats = `(async () => {
    const host = document.getElementById('probe-host');
    const aside = host.querySelector('aside.ambient-canvas'), main = host.querySelector('main');
    aside.style.cssText = ''; main.style.cssText = '';
    for (const an of document.getAnimations()) { try { an.cancel(); } catch {} }
    const R = await import('/src/router/main.ts');
    await R.mainRouter.push({ name: 'chats' });
    await new Promise((r) => setTimeout(r, 800));
    return true;
  })()`;

  /** 起一次真实转场，把过渡按**平移进度** e 冻住（缓动前段很快，按时间来会偏到 0.95）。 */
  const freezeAt = async (e) => {
    let ids = [];
    for (let attempt = 0; attempt < 2 && ids.length === 0; attempt++) {
      animIds.length = 0;
      await cdp.send("Animation.setPlaybackRate", { playbackRate: 0.05 }).catch(() => {});
      await cdp.eval(pushConv);
      for (let i = 0; i < 40 && animIds.length === 0; i++) await sleep(50);
      await sleep(600);
      ids = [...new Set(animIds)];
      if (ids.length === 0) {
        await cdp.send("Animation.setPlaybackRate", { playbackRate: 1 }).catch(() => {});
        await cdp.eval(backToChats);
      }
    }
    if (ids.length === 0) return null;
    await cdp.send("Animation.setPaused", { animations: ids, paused: true }).catch(() => {});
    let lo = 0;
    let hi = DUR;
    for (let i = 0; i < 9; i++) {
      const mid = (lo + hi) / 2;
      await cdp.send("Animation.seekAnimations", { animations: ids, currentTime: mid }).catch(() => {});
      await cdp.eval(`new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)))`);
      const p = await cdp.eval(`(() => {
        const aside = document.getElementById('probe-host').querySelector('aside.ambient-canvas');
        const tx = new DOMMatrixReadOnly(getComputedStyle(aside).transform).m41;
        return -tx / (innerWidth * 0.3);
      })()`);
      if (Math.abs(p - e) < 0.008) break;
      if (p < e) lo = mid; else hi = mid;
    }
    await cdp.eval(`new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)))`);
    const pose = await cdp.eval(`(() => {
      const host = document.getElementById('probe-host');
      const aside = host.querySelector('aside.ambient-canvas');
      const main = host.querySelector('main');
      const as = getComputedStyle(aside);
      const ar = aside.getBoundingClientRect(), mr = main.getBoundingClientRect();
      const mainLeft = Math.round(mr.x);
      const pts = [];
      for (let y = 0; y < innerHeight; y += 10) for (let x = mainLeft + 4; x < innerWidth; x += 10) pts.push({ x, y });
      const tx = new DOMMatrixReadOnly(as.transform).m41;
      const clip = /inset\\(([^)]*)\\)/.exec(as.clipPath);
      const clipRight = clip ? parseFloat((clip[1].split(/\\s+/)[1] || '0')) : 0;
      return {
        pan: +(-tx / (innerWidth * 0.3)).toFixed(4),
        clipRight: +clipRight.toFixed(4),
        vis: as.visibility,
        asideRight: Math.round(ar.right),
        mainLeft,
        pts,
      };
    })()`);
    return { pose, ids };
  };

  const sample = async (points) => {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    const hexes = await cdp.eval(`(async () => {
      const im = new Image();
      im.src = 'data:image/png;base64,' + ${JSON.stringify(shot.data)};
      await new Promise((res, rej) => { im.onload = () => res(true); im.onerror = () => rej(new Error('img')); });
      const cv = document.createElement('canvas');
      cv.width = im.width; cv.height = im.height;
      const ctx = cv.getContext('2d', { willReadFrequently: true });
      ctx.drawImage(im, 0, 0);
      const sx = im.width / innerWidth, sy = im.height / innerHeight;
      const hex = (d) => '#' + [d[0], d[1], d[2]].map((v) => v.toString(16).padStart(2, '0')).join('');
      return ${JSON.stringify(points)}.map((p) => {
        const x = Math.min(im.width - 1, Math.max(0, Math.round(p.x * sx)));
        const y = Math.min(im.height - 1, Math.max(0, Math.round(p.y * sy)));
        const d = ctx.getImageData(x, y, 1, 1).data;
        return hex(d);
      });
    })()`);
    return { data: shot.data, hexes };
  };
  const diffOf = (pa, pb) => {
    const hexRgb = (h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)];
    let max = 0;
    let hit = 0;
    let worst = null;
    for (let i = 0; i < pa.length; i++) {
      const x = hexRgb(pa[i]);
      const y = hexRgb(pb[i]);
      const d = Math.max(Math.abs(x[0] - y[0]), Math.abs(x[1] - y[1]), Math.abs(x[2] - y[2]));
      if (d > max) { max = d; worst = { i, a: pa[i], b: pb[i] }; }
      if (d > 2) hit += 1;
    }
    return { max, hit, n: pa.length, worst };
  };

  const measure = async (e, { unclip = false } = {}) => {
    const fr = await freezeAt(e);
    if (!fr) return null;
    if (unclip) {
      await cdp.eval(`(() => {
        const a = document.getElementById('probe-host').querySelector('aside.ambient-canvas');
        a.style.setProperty('clip-path', 'inset(0 0 0 0)', 'important');
        return true;
      })()`);
      await sleep(80);
    }
    const a = await sample(fr.pose.pts);
    const shotName = `${unclip ? "unclip" : "clip"}-e${String(e).replace(".", "_")}-A.png`;
    fs.writeFileSync(path.join(shotDir, shotName), Buffer.from(a.data, "base64"));
    await cdp.eval(`(() => {
      const a = document.getElementById('probe-host').querySelector('aside.ambient-canvas');
      a.style.setProperty('visibility', 'hidden', 'important');
      return true;
    })()`);
    await sleep(120);
    const b = await sample(fr.pose.pts);
    const d = diffOf(a.hexes, b.hexes);
    await cdp.send("Animation.setPlaybackRate", { playbackRate: 1 }).catch(() => {});
    await cdp.send("Animation.releaseAnimations", { animations: fr.ids }).catch(() => {});
    await cdp.eval(backToChats);
    return { ...fr.pose, ...d, shot: shotName };
  };

  const rows = [];
  for (const e of POSES) {
    const r = await measure(e);
    if (!r) {
      check(`转场 e=${e}：抓到 aside/main 的 CSSTransition`, false,
        "至少一条 transform transition", "0 条（动画没起，这一格无读数）");
      continue;
    }
    rows.push({ e, kind: "clip", ...r });
    console.log(`  · 转场 e=${e}：main.x=${r.mainLeft} pan=${r.pan} clip=${r.clipRight}% vis=${r.vis} | 盖住区 Δ=${r.max}（超2色阶 ${r.hit}/${r.n}）${r.shot ? " " + r.shot : ""}`);
    check(`转场 e=${e}：列表被裁到聊天列左缘之外（薄纱下无可辨旧列表）`,
      r.max <= 2,
      "隐藏列表前后同点色差 ≤2（≈ 不存在可辨穿透）",
      `Δ=${r.max} 超2色阶=${r.hit}/${r.n} clipRight=${r.clipRight}% pan=${r.pan}`);
    // 两根时钟锁死：裁剪比例 / 70% 必须等于平移进度（e=0.4 实测 0.4034 对 28.2346/70）。
    check(`转场 e=${e}：裁剪与平移同进度（不会在中间错开）`,
      Math.abs(r.clipRight / 70 - r.pan) <= 0.02,
      "|clipRight/70 − pan| ≤ 0.02",
      `clipRight/70=${(r.clipRight / 70).toFixed(4)} pan=${r.pan}`);
  }

  // 反例自证：同一姿态摘掉裁剪，必须重新看见旧列表（否则上面几条是空转）。
  const neg = await measure(0.95, { unclip: true });
  if (neg) {
    rows.push({ e: 0.95, kind: "unclip", ...neg });
    console.log(`  · 反例 e=0.95 摘掉裁剪：Δ=${neg.max}（超2色阶 ${neg.hit}/${neg.n}）`);
    check("转场反例自证：同一姿态摘掉裁剪必须重新透出旧列表",
      neg.max > 2,
      "Δ>2 色阶（量具没有空转）",
      `Δ=${neg.max} 超2色阶=${neg.hit}/${neg.n}`);
  } else {
    check("转场反例自证：摘掉裁剪那一趟要能抓到动画", false, "抓到 CSSTransition", "0 条");
  }

  fs.writeFileSync(outFile, JSON.stringify({ poses: POSES, rows }, null, 2));
}

/**
 * 分栏把手命中区 vs 列表滚动条带 + 两个列表面板的内容竖线（2026-11-08）。
 *
 * 用户实测缺陷：左列与会话区之间的拖拽把手把左列滚动条盖住 ⇒ 想点滚动条只会触发左右拖拽。
 * 这一节把"这一下点击该归谁"变成可重跑的读数：把手矩形 ∩ 滚动条带矩形必须为 0，
 * 且滚动条带中点的 elementFromPoint 必须落在滚动容器里（不是把手）。
 * 反例自证：把把手内联改回旧值（左 -4px / 右 +4px，等价 `-mx-1`），同一测点立刻变成把手 ⇒ 判据红。
 *
 * 同时量外部链接 / 收藏两个左列面板：头部内容线、工具栏按钮左缘、行 hover 矩形左右缘。
 * 口径是"一页只有一条内容竖线，hover 通宽且左右对称内距"（用户 2026-11-08）。
 */
async function runListMetrics(cdp, url) {
  const outFile = path.join(ROOT, "test-results", "list-metrics.json");
  fs.mkdirSync(path.dirname(outFile), { recursive: true });
  const out = {};
  const page = (fnBody) => cdp.eval("(() => {" + fnBody + "})()");

  const MEASURE_SPLIT = `
    const host = document.getElementById('probe-host');
    const rect = (el) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { l: +b.left.toFixed(1), r: +b.right.toFixed(1), t: +b.top.toFixed(1), b: +b.bottom.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) };
    };
    // 页面上有两个 <aside>：NavRail(64) 与左列列表。取宽的那一个（宽度 > 100）。
    const asides = host ? [...host.querySelectorAll('aside')] : [];
    const aside = asides.filter((a) => a.getBoundingClientRect().width > 100)[0] || asides[0] || null;
    const sc = aside ? aside.querySelector('.scrollbar-both, .gosslan-scroll') : null;
    const handles = host ? [...host.querySelectorAll('div')].filter((d) => {
      const s = getComputedStyle(d);
      return s.cursor === 'col-resize' && d.getBoundingClientRect().width > 0 && d.offsetParent !== null;
    }) : [];
    const hd = handles[0] || null;
    const scR = rect(sc);
    const sbw = sc ? sc.offsetWidth - sc.clientWidth : 0;
    const band = scR ? { l: +(scR.r - sbw).toFixed(1), r: scR.r, t: scR.t, b: scR.b } : null;
    const hR = rect(hd);
    const ov = (a, b2) => (a && b2) ? Math.max(0, +(Math.min(a.r, b2.r) - Math.max(a.l, b2.l)).toFixed(1)) : 0;
    const ovY = (a, b2) => (a && b2) ? Math.max(0, +(Math.min(a.b, b2.b) - Math.max(a.t, b2.t)).toFixed(1)) : 0;
    const at = (x, y) => {
      const e = document.elementFromPoint(x, y);
      if (!e) return null;
      return {
        tag: e.tagName,
        isHandle: !!hd && (e === hd || hd.contains(e)),
        inScroller: !!sc && (e === sc || sc.contains(e)),
        cls: String(e.className || '').slice(0, 60),
      };
    };
    const midY = scR ? (scR.t + scR.b) / 2 : 0;
    return {
      aside: rect(aside), scroller: scR, sbw,
      band, handle: hR,
      overlapX: ov(hR, band), overlapY: ovY(hR, band),
      hitBandCenter: band ? at(band.l + sbw / 2, midY) : null,
      hitBandEdge: band ? at(band.r - 1, midY) : null,
      listW: aside ? Math.round(aside.getBoundingClientRect().width) : 0,
      scrollTop: sc ? Math.round(sc.scrollTop) : 0,
    };`;

  const MEASURE_PANEL = `
    const host = document.getElementById('probe-host');
    const rect = (el) => {
      if (!el) return null;
      const b = el.getBoundingClientRect();
      return { l: +b.left.toFixed(1), r: +b.right.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1) };
    };
    const num = (v) => parseFloat(v) || 0;
    const header = host ? host.querySelector('header') : null;
    const hPadL = header ? num(getComputedStyle(header).paddingLeft) : 0;
    const hPadR = header ? num(getComputedStyle(header).paddingRight) : 0;
    // hover 面的定位口径：类名里写了 hover:bg 的那一层 = 底色真正铺开的矩形（不靠猜 DOM 层级）。
    // 取**最宽**的那一层：行 hover 通宽，行内 32×32 的图标按钮也带 hover:bg（不是行）。
    const hoverEls = host ? [...host.querySelectorAll('[class*="hover:bg"]')]
      .filter((el) => el.getBoundingClientRect().height >= 28 && el.getBoundingClientRect().width > 0) : [];
    const row = hoverEls.slice().sort((a, b) => b.getBoundingClientRect().width - a.getBoundingClientRect().width)[0] || null;
    // 注意：CSS 选择器列表按**文档顺序**匹配，不是按列表顺序。探针宿主自己也挂了
    // .scrollbar-both，所以必须显式先取 .gosslan-list-scroll（列表列的唯一口径）。
    // ★ 这段是模板字符串正文：注释里**不能出现反引号**，否则会把字符串提前闭合并让整段变成 node 代码
    //   （2026-11-08 踩过：报错 "both is not defined"，指向的却是注释行）。
    const sc = host
      ? (host.querySelector('.gosslan-list-scroll') || host.querySelector('.scrollbar-both, .gosslan-scroll'))
      : null;
    const scR = rect(sc);
    const sbw = sc ? sc.offsetWidth - sc.clientWidth : 0;
    const scPadL = sc ? num(getComputedStyle(sc).paddingLeft) : 0;
    const scCls = sc ? String(sc.className) : '';
    const hostR = host ? host.getBoundingClientRect() : null;
    const back = host ? host.querySelector('button[aria-label="返回"]') : null;
    const search = host ? host.querySelector('input[type="search"], input[placeholder]') : null;
    return {
      host: host ? { l: +hostR.left.toFixed(1), r: +hostR.right.toFixed(1), w: +hostR.width.toFixed(1) } : null,
      header: rect(header), headerPadL: hPadL, headerPadR: hPadR,
      headerContentL: header ? +(header.getBoundingClientRect().left + hPadL).toFixed(1) : null,
      headerContentR: header ? +(header.getBoundingClientRect().right - hPadR).toFixed(1) : null,
      back: rect(back), search: rect(search),
      scroller: scR, sbw,
      scPadL, scCls,
      row: rect(row),
      rowPadL: row ? num(getComputedStyle(row).paddingLeft) : 0,
      rowPadR: row ? num(getComputedStyle(row).paddingRight) : 0,
      rowText: row ? (row.innerText || '').replace(/\\s+/g, ' ').trim().slice(0, 24) : '',
      rowBg: row ? getComputedStyle(row).backgroundColor : 'none',
      hovers: hoverEls.length,
    };`;

  const bootLayout = async () => {
    await cdp.send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false }).catch(() => {});
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_200);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(async () => {
      window.__TAURI_INTERNALS__ = window.__TAURI_INTERNALS__ || {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      window.__TAURI_EVENT_PLUGIN_INTERNALS__ = window.__TAURI_EVENT_PLUGIN_INTERNALS__ || { unregisterListener: () => {} };
      await window.__probe.install('/src/layouts/ResponsiveLayout.vue', '', ${JSON.stringify(JSON.stringify({ router: true, hostHeight: "800px" }))});
      const { useChatStore } = await import('/src/stores/useChatStore.ts');
      const chat = useChatStore();
      chat.conversations = Array.from({ length: 40 }, (_, i) => ({
        id: 'c' + i, kind: i % 3 ? 'single' : 'group', name: '联系人 ' + (i + 1), avatar: null,
        last_msg: '第 ' + (i + 1) + ' 条预览', last_ts: 1700000000000 - i * 1000, unread: 0, pinned: false,
      }));
      chat.messages['c0'] = Array.from({ length: 12 }, (_, i) => ({
        id: 'm' + i, conv_id: 'c0', sender_id: i % 2 ? 'c0' : 'self', kind: 'text',
        text: '第 ' + (i + 1) + ' 条消息', ts: 1700000000000 + i * 1000, status: 'sent', media: null,
      }));
      chat.activeConv = 'c0';
      const R = await import('/src/router/main.ts');
      await R.mainRouter.push({ name: 'conversation', params: { convId: 'c0' } });
      await new Promise((r) => setTimeout(r, 600));
    })()`);
    await sleep(700);
  };

  const bootPanel = async (cmp, stubExpr, width, height) => {
    await cdp.send("Emulation.setDeviceMetricsOverride", { width: width + 60, height: height + 60, deviceScaleFactor: 1, mobile: false }).catch(() => {});
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(stubExpr);
    const mounted = await cdp.eval(`window.__probe.install('${cmp}', '', '')`);
    await cdp.eval(`(() => {
      const h = document.getElementById('probe-host');
      h.style.width = '${width}px';
      h.style.maxWidth = '${width}px';
      h.style.height = '${height}px';
      h.style.display = 'block';
      h.style.overflow = 'hidden';
      return true;
    })()`);
    await sleep(500);
    return mounted;
  };

  const shot = async (name) => {
    const r = await cdp.send("Page.captureScreenshot", { format: "png" });
    const f = path.join(ROOT, "test-results", "list-metrics", name + ".png");
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, Buffer.from(r.data, "base64"));
    return f;
  };
  /** 把当前面板**内联**改回改前几何（旧类名 + 旧 px），用来拍"改前"对照图与读数。 */
  const injectOld = () => page(`
    const host = document.getElementById('probe-host');
    const sc = host.querySelector('.gosslan-list-scroll');
    if (sc) sc.className = sc.className.replace('gosslan-list-scroll', 'gosslan-scroll');
    const rows = [...host.querySelectorAll('[class*="hover:bg"]')].sort((a, b) => b.offsetWidth - a.offsetWidth);
    if (rows[0]) { rows[0].style.paddingLeft = '8px'; rows[0].style.paddingRight = '8px'; }
    const h = host.querySelector('header');
    if (h) { h.style.paddingLeft = '8px'; h.style.paddingRight = '8px'; }
    const seq = [...host.querySelectorAll('div')].filter((d) => d.className.includes('flex shrink-0 flex-col gap-2'));
    if (seq[0]) { seq[0].style.paddingLeft = '8px'; }
    return true;`);

  try {
    // ── ① 分栏把手 vs 左列滚动条（会话列表 ↔ 会话区）────────────────────────
    await bootLayout();
    out.before = await page(MEASURE_SPLIT);
    const b = out.before;
    check("分栏把手命中矩形不覆盖左列滚动条带（重叠宽度必须为 0）",
      b.sbw > 0 && b.overlapX === 0,
      "sbw>0 且 overlapX=0（纵向重叠是设计使然，不算）",
      `sbw=${b.sbw} overlapX=${b.overlapX} handle=${JSON.stringify(b.handle)} band=${JSON.stringify(b.band)}`);
    check("滚动条最右一列像素归滚动容器（把手不许盖住它）",
      !!b.hitBandEdge && b.hitBandEdge.inScroller === true && b.hitBandEdge.isHandle === false,
      "elementFromPoint(带最右缘) 落在滚动容器内且不是把手",
      JSON.stringify(b.hitBandEdge));

    // 滚动条上按下：原生翻页必须生效（scrollTop 变化）
    const bandCx = b.band ? b.band.l + b.sbw / 2 : 0;
    const bandCy = b.band ? (b.band.t + b.band.b) / 2 : 0;
    const top0 = b.scrollTop;
    await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: bandCx, y: bandCy, button: "left", clickCount: 1 });
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: bandCx, y: bandCy, button: "left", clickCount: 1 });
    await sleep(400);
    const top1 = await cdp.eval(`(() => {
      const sc = document.querySelector('#probe-host aside .scrollbar-both, #probe-host aside .gosslan-scroll');
      return sc ? Math.round(sc.scrollTop) : 0;
    })()`);
    out.scrollbarClick = { before: top0, after: top1 };
    check("在滚动条上按下能滚动左列（这一下没有被把手抢走）",
      top1 > top0,
      "点击滚动条轨道后 scrollTop 增大",
      JSON.stringify(out.scrollbarClick));

    // 把手上按下 + 拖动：listW 必须跟着变，且拖动期间 body 光标是 col-resize
    const hx = b.handle ? (b.handle.l + b.handle.r) / 2 : 0;
    const hy = b.handle ? b.handle.t + 240 : 0;
    await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: hx, y: hy, button: "left", clickCount: 1 });
    const bodyCursor = await cdp.eval("document.body.style.cursor");
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: hx + 40, y: hy, button: "left", buttons: 1 });
    await sleep(120);
    const during = await page(MEASURE_SPLIT);
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: hx + 40, y: hy, button: "left", clickCount: 1 });
    await sleep(200);
    out.drag = { from: b.listW, during: during.listW, cursor: bodyCursor };
    check("在把手上按下能拖动（listW 变化 + 拖动中光标 col-resize）",
      during.listW >= b.listW + 30 && bodyCursor === "col-resize",
      "listW 至少 +30 且 body.style.cursor=col-resize",
      JSON.stringify(out.drag));

    // 反例自证：把把手内联改回旧 `-mx-1`（左 -4 / 右 +4）⇒ 同一点位命中把手
    await page(`
      const hd = [...document.querySelectorAll('#probe-host div')].find((d) => getComputedStyle(d).cursor === 'col-resize' && d.offsetParent !== null);
      if (hd) { hd.style.marginLeft = '-4px'; hd.style.marginRight = '4px'; }
      return !!hd;`);
    await sleep(120);
    out.counter = await page(MEASURE_SPLIT);
    const c = out.counter;
    check("反例自证：把手改回旧覆盖值（-mx-1）时，滚动条带最右缘立刻归把手 ⇒ 上面那条会红",
      c.overlapX > 0 && !!c.hitBandEdge && c.hitBandEdge.isHandle === true,
      "overlapX>0 且 elementFromPoint(带最右缘).isHandle=true",
      `overlapX=${c.overlapX} hitEdge=${JSON.stringify(c.hitBandEdge)}`);

    // ── ② 外部链接面板：头部 / 工具栏 / 行 hover 内容竖线 ─────────────────
    const links = [
      { id: "l1", name: "公司内网", url: "https://intra.example.com", source: "user", remoteUrl: "" },
      { id: "l2", name: "产品文档", url: "https://docs.example.com", source: "url:https://backup.example.com/links.json", remoteUrl: "https://docs.example.com" },
      { id: "l3", name: "设计规范", url: "https://design.example.com", source: "user", remoteUrl: "" },
    ];
    const mountedLinks = await bootPanel("/src/components/LinksList.vue", `window.__probe.linksStore(${JSON.stringify(links)})`, 360, 700);
    out.links = await page(MEASURE_PANEL);
    fs.writeFileSync(outFile, JSON.stringify(out, null, 2));
    const L = out.links;
    const lBandOk = !!mountedLinks && mountedLinks.ok === true && !!L.row && !!L.scroller
      && Math.abs(L.row.l - L.scroller.l) <= 1
      && Math.abs(L.row.r - (L.scroller.r - L.sbw)) <= 1;
    const lPadOk = !!L.row && L.rowPadL === L.rowPadR && L.rowPadL > 0;
    const lLineOk = L.headerContentL !== null && !!L.row && Math.abs(L.headerContentL - (L.row.l + L.rowPadL)) <= 1;
    check("外部链接面板：行 hover 面通宽（左缘=容器左缘，右缘=滚动条左缘）", lBandOk,
      "row.l == scroller.l 且 row.r == scroller.r - sbw",
      `row=${JSON.stringify(L.row)} scroller=${JSON.stringify(L.scroller)} sbw=${L.sbw}`);
    check("外部链接面板：行内距左右对称且非零", lPadOk,
      "rowPadL == rowPadR > 0",
      `padL=${L.rowPadL} padR=${L.rowPadR}`);
    check("外部链接面板：头部内容线 = 行内容线（同一条竖线）", lLineOk,
      "|headerContentL - (row.l + rowPadL)| ≤ 1px",
      `headerContentL=${L.headerContentL} row.l=${L.row && L.row.l} rowPadL=${L.rowPadL} headerPadL=${L.headerPadL}`);
    await shot("links-after");
    await injectOld();
    out.linksOld = await page(MEASURE_PANEL);
    await shot("links-before");
    fs.writeFileSync(outFile, JSON.stringify(out, null, 2));

    // ── ③ 收藏面板 ───────────────────────────────────────────────────────
    const now = Date.now();
    const favs = [
      { id: "f1", msg_id: "m1", conv_id: "c0", sender_id: "peer-1", kind: "text", content: "收藏的文本：核对列表排版。", ts: now - 90_000, favorited_at: now - 60_000, media_path: null, media_size: 0, available: true },
      { id: "f2", msg_id: "m2", conv_id: "c0", sender_id: "peer-1", kind: "file", content: JSON.stringify({ name: "季度报告.pdf", path: "/tmp/a.pdf", size: 2048, subtype: "file" }), ts: now - 120_000, favorited_at: now - 120_000, media_path: "/tmp/a.pdf", media_size: 2048, available: true },
    ];
    const mountedFav = await bootPanel("/src/components/FavoritePanel.vue", `window.__probe.stubApi('listFavorites', ${JSON.stringify(favs)})`, 420, 700);
    out.favorites = await page(MEASURE_PANEL);
    fs.writeFileSync(outFile, JSON.stringify(out, null, 2));
    const F = out.favorites;
    const fBandOk = !!mountedFav && mountedFav.ok === true && !!F.row && !!F.scroller
      && Math.abs(F.row.l - F.scroller.l) <= 1
      && Math.abs(F.row.r - (F.scroller.r - F.sbw)) <= 1;
    const fPadOk = !!F.row && F.rowPadL === F.rowPadR && F.rowPadL > 0;
    check("收藏面板：行 hover 面通宽（左缘=容器左缘，右缘=滚动条左缘）", fBandOk,
      "row.l == scroller.l 且 row.r == scroller.r - sbw",
      `row=${JSON.stringify(F.row)} scroller=${JSON.stringify(F.scroller)} sbw=${F.sbw}`);
    check("收藏面板：行内距左右对称且非零", fPadOk,
      "rowPadL == rowPadR > 0",
      `padL=${F.rowPadL} padR=${F.rowPadR}`);
    // 收藏面板没有 <header>（头部是自绘的返回键 + 标题行）：内容竖线用搜索框左缘代表。
    const favLine = F.search ? F.search.l : (F.back ? F.back.l : null);
    check("收藏面板：行内容线与搜索框左缘同为一条竖线",
      favLine !== null && !!F.row && Math.abs(favLine - (F.row.l + F.rowPadL)) <= 1,
      "|搜索框左缘 - (row.l + rowPadL)| ≤ 1px",
      `search.l=${favLine} back=${JSON.stringify(F.back)} row.l=${F.row && F.row.l} rowPadL=${F.rowPadL}`);
    await shot("favorites-after");
    await injectOld();
    out.favoritesOld = await page(MEASURE_PANEL);
    await shot("favorites-before");
    fs.writeFileSync(outFile, JSON.stringify(out, null, 2));
  } finally {
    fs.writeFileSync(outFile, JSON.stringify(out, null, 2));
  }
}

async function runFavorites(cdp, url) {
  const now = Date.now();
  const favs = [
    { id: "f1", msg_id: "m1", conv_id: "conv-1", sender_id: "peer-1", kind: "text",
      content: "收藏的文本：这是一条用来核对收藏列表与详情排版的消息。", ts: now - 90_000, favorited_at: now - 60_000,
      media_path: null, media_size: 0, available: true },
    { id: "f2", msg_id: "m2", conv_id: "conv-1", sender_id: "peer-1", kind: "file",
      // 刻意超长（仍保留可搜索的“季度报告.pdf”前缀）：移动端必须省略而不是把「⋯」挤出屏幕。
      content: JSON.stringify({ name: "季度报告.pdf" + "超长文件名".repeat(20), path: "/tmp/季度报告.pdf", size: 20480, subtype: "file" }),
      ts: now - 120_000, favorited_at: now - 120_000,
      media_path: "/tmp/季度报告.pdf", media_size: 20480, available: true },
    { id: "f3", msg_id: "m3", conv_id: "conv-1", sender_id: "self", kind: "code",
      content: "const answer = 42;", ts: now - 180_000, favorited_at: now - 180_000,
      media_path: null, media_size: 0, available: true },
  ];
  const mount = async (width, height) => {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    // 同一次进程里先桌后窄：导航会把 device metrics 复位，必须在页面起来后再钉一次，
    // 让 store 的 resize 监听把 isMobile 真正翻到窄档。
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width, height, deviceScaleFactor: width < 768 ? 2 : 1, mobile: width < 768,
    });
    if (width < 768) {
      // 同一 target 从宽档再导航到窄档时，导航会把 metrics 复位成窗口默认宽；
      // reload 后 store 会按默认宽初始化，再钉一次让 resize 监听把它翻到窄档。
      await cdp.send("Page.reload");
      await sleep(2_000);
      await cdp.send("Emulation.setDeviceMetricsOverride", {
        width, height, deviceScaleFactor: 2, mobile: true,
      });
      await sleep(600);
    }
    await sleep(500);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`window.__probe.stubApi('listFavorites', ${JSON.stringify(favs)})`);
    const mounted = await cdp.eval("window.__probe.install('/src/components/FavoritePanel.vue', '', '')");
    await cdp.eval(`(() => {
      const h = document.getElementById('probe-host');
      h.style.width = '${width}px';
      h.style.maxWidth = '${width}px';
      h.style.minWidth = '0';
      h.style.height = '${height}px';
      h.style.display = 'block';
      h.style.overflow = 'hidden';
      return true;
    })()`);
    await sleep(400);
    return mounted;
  };
  const info = () => cdp.eval(`(() => {
    const txt = document.body.innerText;
    const rowTexts = [...document.querySelectorAll('button')]
      .map((b) => (b.innerText || '').trim())
      .filter((x) => x.includes('收藏的文本') || x.includes('季度报告.pdf') || x.includes('const answer'));
    const actions = [...document.querySelectorAll('button')]
      .map((b) => (b.innerText || '').trim())
      .filter((x) => ['复制', '转发', '跳回原消息', '删除收藏', '查看图片', '另存为', '打开'].includes(x));
    const detail = [...document.querySelectorAll('div')].find((d) => {
      const st = getComputedStyle(d);
      return st.position === 'fixed' && (d.innerText || '').includes('收藏的文本');
    });
    return {
      txt, rows: rowTexts.length, rowTexts, actions,
      vw: innerWidth,
      hostW: (() => { const h = document.getElementById('probe-host'); return h ? Math.round(h.getBoundingClientRect().width) : 0; })(),
      headerText: (document.querySelector('header') || {}).innerText || '',
      search: !!document.querySelector('input[placeholder*="搜索收藏"]'),
      // 绑到常量上的 maxlength 必须真的产出属性与 DOM 值 —— 绑错名字时 Vue 只会安静地不写属性，
      // 界面看不出区别，但上限已经消失（用户能把整段日志粘进搜索框）。
      searchMaxlen: (() => {
        const i = document.querySelector('input[placeholder*="搜索收藏"]');
        return i ? { attr: i.getAttribute('maxlength'), dom: i.maxLength } : null;
      })(),
      chips: [...document.querySelectorAll('button[aria-pressed]')].map((b) => b.innerText.trim()),
      chipsPressed: [...document.querySelectorAll('button[aria-pressed="true"]')].map((b) => b.innerText.trim()),
      picked: txt.includes('从左侧选一条收藏查看详情'),
      noMatch: txt.includes('没有匹配的收藏'),
      detailFixed: detail ? { fixed: true, width: Math.round(detail.getBoundingClientRect().width) } : null,
      back: !!document.querySelector('button[aria-label="返回"]'),
    };
  })()`);
  const rectOf = (needle, sel) => cdp.eval(`(() => {
    const el = [...document.querySelectorAll(${JSON.stringify(sel || "button")})]
      .find((b) => ((b.innerText || '') + ' ' + (b.getAttribute('aria-label') || '')).includes(${JSON.stringify(needle)}));
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  })()`);
  const clickText = async (needle, sel) => {
    const pt = await rectOf(needle, sel);
    if (!pt) return false;
    await cdp.click(pt.x, pt.y);
    await sleep(300);
    return true;
  };

  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1400, height: 900, deviceScaleFactor: 1, mobile: false,
  });
  try {
    const mounted = await mount(1200, 820);
    let s = await info();
    check("收藏面板：真实 store 拉取并渲染三条，搜索 / 五个筛选 / 空详情提示齐全",
      mounted && mounted.ok === true && s.rows === 3
        && s.search && s.chips.length === 5 && s.picked,
      "3 行 / 5 chips / 空详情提示",
      JSON.stringify({ rows: s.rows, chips: s.chips, search: s.search, picked: s.picked }));

    check("收藏搜索框的 maxlength 由常量绑定产出真数（绑错名字时 Vue 只安静地不写属性）",
      s.searchMaxlen && s.searchMaxlen.attr === "50" && s.searchMaxlen.dom === 50,
      'attr="50" 且 input.maxLength === 50',
      JSON.stringify(s.searchMaxlen));

    const searchPt = await cdp.eval(`(() => {
      const i = document.querySelector('input[placeholder*="搜索收藏"]');
      if (!i) return null;
      const r = i.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    })()`);
    if (searchPt) await cdp.click(searchPt.x, searchPt.y);
    await cdp.send("Input.insertText", { text: "季度" });
    await sleep(300);
    s = await info();
    check("搜索『季度』只剩文件行（标题与正文都参与匹配）",
      s.rows === 1 && s.rowTexts.join("|").includes("季度报告.pdf"),
      "1 行且是季度报告.pdf", JSON.stringify(s.rowTexts));

    await clickText("图片");
    s = await info();
    check("筛选『图片』在没有图片收藏时给出空结果提示（不是一片空白）",
      s.rows === 0 && s.noMatch && s.chipsPressed.includes("图片"),
      "0 行 + 没有匹配的收藏 + 图片激活",
      JSON.stringify({ rows: s.rows, noMatch: s.noMatch, pressed: s.chipsPressed }));

    await cdp.eval(`(() => {
      const i = document.querySelector('input[placeholder*="搜索收藏"]');
      if (i) { i.focus(); i.setSelectionRange(i.value.length, i.value.length); }
      return true;
    })()`);
    for (let i = 0; i < 2; i += 1) {
      await cdp.send("Input.dispatchKeyEvent", {
        type: "keyDown", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8,
      });
      await cdp.send("Input.dispatchKeyEvent", {
        type: "keyUp", key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8,
      });
    }
    await sleep(200);
    await clickText("全部");
    s = await info();
    check("清空搜索 + 回到『全部』：三条恢复（筛选是真状态，不是一次性渲染）",
      s.rows === 3 && s.chipsPressed.includes("全部") && !s.noMatch,
      "3 行 + 全部激活", JSON.stringify({ rows: s.rows, pressed: s.chipsPressed }));

    const clicked = await clickText("收藏的文本");
    s = await info();
    check("点文本收藏：右栏显示全文与底部操作条，空详情提示消失",
      clicked && s.txt.includes("这是一条用来核对收藏列表与详情排版的消息")
        && ["复制", "转发", "跳回原消息", "删除收藏"].every((x) => s.actions.includes(x)) && !s.picked,
      "全文 + 复制/转发/跳回/删除 + 空提示消失",
      JSON.stringify({ actions: s.actions, picked: s.picked }));
    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-favorites.png"), Buffer.from(shot.data, "base64"));
      console.log("  📷 收藏面板取证帧 → " + SHOT_PATH.replace(/\.png$/, "-favorites.png"));
    }

    // ── 移动端两级（列表 ↔ 详情覆盖层）：视口必须在 store 创建**之前**变窄 ──
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
    });
    const mMounted = await mount(390, 844);
    s = await info();
    check("移动端收藏：列表一列渲染（桌面空详情提示不出现），列表态没有返回键",
      mMounted && mMounted.ok === true && s.rows === 3 && s.hostW <= 390 && !s.picked && !s.back,
      "3 行 / 390 宿主宽 / 无桌面空详情提示 / 列表态无返回键",
      JSON.stringify({ rows: s.rows, hostW: s.hostW, picked: s.picked, back: s.back }));

    const longName = await cdp.eval(`(() => {
      const title = [...document.querySelectorAll('span')].find((s) =>
        (s.textContent || '').includes('季度报告.pdf')
        && getComputedStyle(s).textOverflow === 'ellipsis');
      if (!title) return { ok: false };
      const row = title.closest('div.relative');
      const more = row ? row.querySelector('button[aria-label="更多操作"]') : null;
      const r = more ? more.getBoundingClientRect() : null;
      const hit = r ? document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2) : null;
      return {
        ok: true,
        truncated: title.scrollWidth > title.clientWidth,
        more: !!more,
        right: r ? +r.right.toFixed(1) : null,
        hostRight: (() => { const h = document.getElementById('probe-host'); return h ? h.getBoundingClientRect().right : null; })(),
        hitMore: !!(hit && more && hit.closest('button') === more),
      };
    })()`);
    check("移动端收藏：超长文件名省略而不是撑破行，右侧「⋯」仍在视口内且可命中",
      longName.ok === true && longName.truncated === true && longName.more === true
        && longName.right !== null && longName.hostRight !== null
        && longName.right <= longName.hostRight + 1 && longName.hitMore === true,
      "ellipsis + 真正截断 + ⋯ 在面板内且命中", JSON.stringify(longName));

    await clickText("收藏的文本");
    s = await info();
    check("移动端点收藏：全屏 fixed 覆盖层（宽度=视口）、标题取正文而不是一律「文件」、带返回键",
      s.detailFixed && s.detailFixed.fixed && Math.abs(s.detailFixed.width - s.vw) <= 2 && s.back
        && s.headerText.includes("收藏的文本") && !s.headerText.includes("文件"),
      "fixed / width=vw / 标题含正文 / 返回键在",
      JSON.stringify({ detail: s.detailFixed, vw: s.vw, back: s.back, header: s.headerText }));
    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-favorites-mobile.png"), Buffer.from(shot.data, "base64"));
      console.log("  📷 收藏移动端取证帧 → " + SHOT_PATH.replace(/\.png$/, "-favorites-mobile.png"));
    }

    await clickText("返回");
    s = await info();
    check("移动端返回：覆盖层收起回到列表，三条都还在",
      !s.detailFixed && s.rows === 3,
      "覆盖层消失 + 3 行", JSON.stringify({ detail: s.detailFixed, rows: s.rows }));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 网络诊断面板（--only=diag）：§6.90 那格"只能由用户复看"的三态，在真浏览器里量一次。
 *
 * ① 命令在飞 ⇒ 屏幕上是「加载中...」（不是空白、也不是先报错）；
 * ② 读数到达 ⇒ 模式 / 绑定 IP / TCP 监听 / 版本行都在屏上；
 * ③ 刷新失败 ⇒ 旧读数仍在、整屏**没有**被「诊断数据读取失败」替换（`error && !diag` 那道闸）；
 * ④ 反控 ⇒ 没有旧快照时同一套失败**必须**把「诊断数据读取失败」说出来，
 *    否则③只是"永远不会报错"的别名；
 * ⑤ 一页只有一层滚动条（用户 2026-11-08）⇒ 弹窗壳在滚，而它内部**没有任何**子容器自己可滚。
 *    夹具把三份列表都塞满 16 条，先证壳真的溢出，否则"内层没滚"只是量空气。
 */
async function runDiag(cdp, url) {
  // 与本文件其它段同一口径：先把页面拉到前台，避免被遮挡时过渡停在中途。
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  // 三份列表都塞满：这一段要量「一页只有一层滚动条」，空列表会让那一格变成量空气。
  const many = (n, f) => Array.from({ length: n }, (_, i) => f(i));
  const DIAG = {
    mode: "lan",
    bound_ip: "192.168.1.9",
    selected_interface: "en0",
    selected_ip: "192.168.1.9",
    tcp_listen: "0.0.0.0:60012",
    udp_port: 60013,
    broadcast_target: "255.255.255.255:60013",
    multicast_group: "239.255.66.12:60013",
    multicast_join_result: "ok",
    multicast_if_result: "ok",
    last_broadcast_send: 0,
    last_multicast_send: 0,
    last_announce_recv: 0,
    candidates: [],
    bluetooth: {
      feature_compiled: true, enabled: true, available: true, running: true, peers: 3,
      activity: "active", scan_window_ms: 1000, scan_interval_ms: 500, last_scan_ts: 0,
      last_scan_total: 3, last_scan_matched: 3,
      backoff: many(16, (i) => ({ id: `dev-${i}-backoff`, failures: i + 1, remaining_ms: 30_000 })),
      no_dial: 2,
    },
    protocol_version: 1,
    // 探针自己造的一串，**故意不写真实版本号**：免得产品一升版本这条判据就漂。
    app_version: "probe-9.9",
    peer_versions: many(16, (i) => ({
      device_id: `peer-${i}`, nickname: `对端 ${i}`, protocol_version: 1, app_version: "probe-peer",
    })),
    conn_health: many(16, (i) => ({
      device_id: `dev-${i}`, conn_id: `c-${i}`, endpoint: `192.168.1.9:6001${i}`,
      path_kind: "tcp", last_write_seen_ms: 0, last_read_seen_ms: 0,
      write_age_ms: 1000, read_age_ms: 2000, healthy: i % 2 === 0, consecutive_failures: 0,
    })),
  };
  const boot = async () => {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.diagDeferred()");
  };
  const mount = () => cdp.eval(`window.__probe.install('/src/components/DevDiagPanel.vue', '', '{"open":true}')`);
  const txt = () => cdp.eval("document.body.innerText");
  const stats = () => cdp.eval("window.__probe.diagStats()");
  // 点刷新按钮用 DOM click（这一格量的是三态切换，不是命中区；命中区由 overlay/links 两段负责）。
  const clickRefresh = () => cdp.eval(`(() => {
    const b = [...document.querySelectorAll('button')]
      .find((x) => String(x.innerText || '').includes('刷新'));
    if (!b) return false;
    b.click();
    return true;
  })()`);

  await boot();
  const m1 = await mount();
  await sleep(350);
  const t1 = await txt();
  const s1 = await stats();
  check("诊断面板：命令在飞时屏幕上是「加载中...」（不是空白、也不是先报错）",
    m1 && m1.ok === true && s1.calls === 1 && t1.includes("加载中") && !t1.includes("诊断数据读取失败"),
    "calls=1 且含「加载中」且无错误块",
    JSON.stringify({ calls: s1 && s1.calls, head: String(t1).slice(0, 120) }));

  await cdp.eval(`window.__probe.diagResolve(${JSON.stringify(DIAG)})`);
  await sleep(450);
  const t2 = await txt();
  check("诊断面板：读数到达后三块事实都在屏上（模式 / 绑定 IP / TCP 监听 / 本机版本行），加载态退场",
    t2.includes("局域网") && t2.includes("192.168.1.9") && t2.includes("60012")
      && t2.includes("probe-9.9") && !t2.includes("加载中"),
    "含 局域网/192.168.1.9/60012/probe-9.9 且无「加载中」",
    JSON.stringify({ head: String(t2).slice(0, 200) }));

  // ⑤ 一页只有一层滚动条：内容里除弹窗壳外，不许再有第二个能滚的容器。
  //    先确认壳自己确实在滚 —— 否则内容没溢出时"内层也没滚"是量空气。
  const scroll = await cdp.eval(`(() => {
    const shell = document.querySelector('.gosslan-scroll');
    if (!shell) return { shell: false };
    const inner = [...shell.querySelectorAll('*')].filter((el) => {
      const s = getComputedStyle(el);
      return /(auto|scroll)/.test(s.overflowY) && el.scrollHeight > el.clientHeight + 1;
    });
    return {
      shell: true,
      shellScrolls: shell.scrollHeight > shell.clientHeight + 1,
      shellH: shell.clientHeight, shellSH: shell.scrollHeight,
      inner: inner.map((el) => ({
        cls: String(el.className || '').slice(0, 60),
        sh: el.scrollHeight, ch: el.clientHeight,
      })),
    };
  })()`);
  check("诊断面板：一页只有一层滚动条（内容区在滚，子列表一个都不许自己滚）",
    scroll.shell === true && scroll.shellScrolls === true && scroll.inner.length === 0,
    "弹窗壳可滚 且 内层可滚容器 0 个",
    JSON.stringify(scroll));

  await cdp.eval("window.__probe.diagFailWith('ipc down')");
  const clicked = await clickRefresh();
  await sleep(800);
  const t3 = await txt();
  const s3 = await stats();
  check("诊断面板·刷新失败但保留旧数据：旧读数仍在、整屏没有被错误页换掉（`error && !diag` 那道闸）",
    clicked === true && s3.calls >= s1.calls + 2
      && t3.includes("192.168.1.9") && !t3.includes("诊断数据读取失败"),
    "calls 至少 +2（retry 1）、旧读数仍在、无「诊断数据读取失败」",
    JSON.stringify({ before: s1 && s1.calls, after: s3 && s3.calls, head: String(t3).slice(0, 160) }));

  // 反控：干净的 Query 缓存 + 一开始就失败的命令 ⇒ 必须把「诊断数据读取失败」说出来
  await boot();
  await cdp.eval("window.__probe.diagFailWith('ipc down')");
  await mount();
  await sleep(900);
  const t4 = await txt();
  check("反控：没有旧快照时同一套失败必须说「诊断数据读取失败」（否则上一条只是永不报错）",
    t4.includes("诊断数据读取失败") && !t4.includes("192.168.1.9"),
    "含「诊断数据读取失败」且无旧读数",
    JSON.stringify({ head: String(t4).slice(0, 160) }));
}

/**
 * 外部链接左栏（--only=links）：真实组件 + 一份读写命令都在的内存表。
 * 重点照入口的可见文案、新增/编辑与导入的**弹窗职责分离**、表单回车提交、编辑预填、
 * 行点击真的把链接交给父级，以及**写路径**（§6.98：增/改/删共用一枚 mutation，
 * 成功时把返回的整份数组写回读缓存）。
 */
async function runLinks(cdp, url) {
  const links = [
    {
      id: "l1", name: "公司内网", url: "https://intra.example.com",
      source: "user", remoteUrl: "",
    },
    {
      id: "l2", name: "产品文档", url: "https://docs.example.com",
      source: "url:https://backup.example.com/links.json", remoteUrl: "https://docs.example.com",
    },
  ];
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1400, height: 900, deviceScaleFactor: 1, mobile: false,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    // 语言：显式 --locale 时强制对应偏好（否则宿主机是中文，英文一次会假绿）；
    // 未指定则沿用页面既有偏好。下面的期望文案全部从词典现取，判据不手抄两套句子。
    if (LOCALE_OVERRIDE === "en-US" || LOCALE_OVERRIDE === "zh-CN") {
      await cdp.eval(`(async () => { const m = await import('/src/i18n/index.ts');`
        + ` m.applyPreference('${LOCALE_OVERRIDE}'); return m.currentLocale(); })()`);
    }
    const L = await cdp.eval(`(async () => {
      const { t } = await import('/src/i18n/index.ts');
      return {
        title: t('links.title'),
        add: t('links.add'), importBtn: t('links.import'), backup: t('links.export'),
        backupHint: t('links.exportHint'), importTitle: t('links.importTitle'),
        fileSection: t('links.importFile'), fileAction: t('links.importFileAction'),
        urlSection: t('links.importUrl'), urlAction: t('links.importUrlAction'),
        importUrlPh: t('links.importUrlPlaceholder'),
        namePh: t('links.namePlaceholder'), urlPh: t('links.urlPlaceholder'),
        edit: t('links.edit'), remove: t('links.remove'),
        cancel: t('common.cancel'), save: t('common.save'),
        addFail: t('links.addFail'),
        sourceLabel: t('links.sourceLabel'), refresh: t('links.refresh'),
        refreshing: t('links.refreshing'), sourceCopy: t('links.sourceCopy'),
        sourceUser: t('links.source.user'), sourceUrlWith: t('links.source.urlWith'),
        failTitle: t('links.refreshFail'),
        failHttp: t('links.refreshFail.http'), failNetwork: t('links.refreshFail.network'),
      };
    })()`);
    await cdp.eval(`window.__probe.linksStore(${JSON.stringify(links)})`);
    const mounted = await cdp.eval("window.__probe.install('/src/components/LinksList.vue', '', '')");
    await cdp.eval(`(() => {
      const h = document.getElementById('probe-host');
      h.style.width = '360px';
      h.style.height = '640px';
      h.style.display = 'block';
      return true;
    })()`);
    await sleep(400);
    const sourceRows = await cdp.eval(`[...document.querySelectorAll('[data-probe="links-row-source"]')]
      .map((e) => (e.innerText || '').trim())`);
    check("来源标识：每行都可见「用户添加」或「远程来源 + 来源地址」",
      mounted && mounted.ok === true && sourceRows.length === 2
        && sourceRows.includes(L.sourceUser)
        && sourceRows.includes(L.sourceUrlWith.replace("{url}", "https://backup.example.com/links.json")),
      "2 行来源标识：用户添加 + 远程来源含完整地址",
      JSON.stringify(sourceRows));

    const info = () => cdp.eval(`(() => {
      const txt = document.body.innerText;
      const inputs = [...document.querySelectorAll('input')].map((i) => ({
        ph: i.placeholder, value: i.value,
      }));
      const btn = (label) => [...document.querySelectorAll('button')]
        .find((b) => ((b.innerText || '').trim() === label));
      const addBtn = btn(${JSON.stringify(L.add)});
      const importBtn = btn(${JSON.stringify(L.importBtn)});
      const backupBtn = btn(${JSON.stringify(L.backup)});
      const src = document.querySelector('[data-probe="links-source"]');
      const refreshBtn = document.querySelector('[data-probe="links-refresh"]');
      const hostTop = document.getElementById('probe-host').getBoundingClientRect().top;
      const srcRect = src ? src.getBoundingClientRect() : null;
      const rRect = refreshBtn ? refreshBtn.getBoundingClientRect() : null;
      return {
        txt, inputs,
        add: !!addBtn,
        importBtn: !!importBtn,
        backup: !!backupBtn,
        backupTitle: backupBtn ? backupBtn.getAttribute('title') : null,
        filePick: !!btn(${JSON.stringify(L.fileAction)}),
        urlAction: !!btn(${JSON.stringify(L.urlAction)}),
        edits: [...document.querySelectorAll('button[aria-label=${JSON.stringify(L.edit)}]')].length,
        removes: [...document.querySelectorAll('button[aria-label=${JSON.stringify(L.remove)}]')].length,
        rowTitles: [...document.querySelectorAll('button[title]')]
          .map((b) => b.getAttribute('title'))
          .filter((t) => t === 'https://intra.example.com' || t === 'https://docs.example.com'),
        rows: [...document.querySelectorAll('button[title]')]
          .map((b) => b.getAttribute('title'))
          .filter((t) => t && t.startsWith('https://')),
        source: !!src ? {
          text: (src.innerText || '').trim(),
          title: src.getAttribute('title'),
          top: srcRect ? Math.round(srcRect.top - hostTop) : null,
          copy: !!src.querySelector('[data-probe="links-copy"]'),
        } : null,
        refreshBtn: !!refreshBtn,
        refreshText: refreshBtn ? (refreshBtn.innerText || '').trim() : null,
        refreshBusy: refreshBtn ? refreshBtn.getAttribute('aria-busy') === 'true' : null,
        refreshDisabled: refreshBtn ? refreshBtn.disabled : null,
        refreshTop: rRect ? Math.round(rRect.top - hostTop) : null,
        refreshError: (() => {
          const el = document.querySelector('[data-probe="links-refresh-error"]');
          return el ? (el.innerText || '').trim() : null;
        })(),
        events: window.__probe.events.slice(),
      };
    })()`);
    const rectOf = (needle) => cdp.eval(`(() => {
      const el = [...document.querySelectorAll('button')]
        .find((b) => ((b.innerText || '') + ' ' + (b.getAttribute('aria-label') || '') + ' ' + (b.getAttribute('title') || '')).includes(${JSON.stringify(needle)}));
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    })()`);
    /**
     * 等那层弹窗遮罩真的从 DOM 里撤掉。
     * Reka 的 Presence 要等 **animationend** 才撤 DOM（`data-state="closed"` 那几条是
     * `gosslan-dialog-fade-out 150ms`），而 headless 的合成器可以**不回这个事件**
     * （2026-10-23 实测：单独跑这一段遮罩 300ms 内就没了；接在 --only=toast 后面跑，
     * 同一层遮罩 1.3s 后还停在 opacity 0.032 且永远不撤）。那层看不见的遮罩带命中，
     * 会把后面每一次鼠标事件全吃掉，读数就长成"弹窗根本没打开"。
     * 所以：先等，等过 600ms 还没撤就替它把动画放完（补发 animationend —— 只推时钟，
     * 不改产品状态），再等；到预算仍不撤就带着读数继续，让那一格自己说看到了什么。
     */
    /**
     * 等弹窗那层遮罩真的从 DOM 里撤掉再点下一处。
     * Reka 的 Presence 要等 **animationend** 才撤 DOM（`data-state="closed"` 那几条是 150ms 淡出），
     * 而 headless 的合成器在长跑里可以不回这个事件 —— 那层透明的遮罩会一直吃掉鼠标事件，
     * 读数就长成"弹窗根本没打开"。所以每次点之前等状态，不靠固定毫秒。
     *
     * ⚠️ 超预算后按 `data-state` 分家（2026-11-03 links 段常红取证）：
     * - 残留的是 **open** 遮罩 ⇒ 产品真没关弹窗，原样继续 ⇒ 让后面的判据红它（不掩盖）；
     * - 残留的全是 **closed** 遮罩 ⇒ 产品已经关了（data-state 就是证据），缺的只是
     *   headless 没投递的那个 animationend ⇒ 补发一次把 Presence 的 DOM 撤掉。
     *   只推时钟、不改产品状态；不这么做的话，一层看不见的遮罩会把之后每一次
     *   鼠标事件全吃掉（实测形状：回车导入那一格 importUrl 永远是 0、inputs 永远空）。
     *
     * ⚠️ 同一次取证的第二层：就算 portal 撤干净了，Reka 模态期加的**身体锁**
     *（`body` 的 `pointer-events:none` + 根容器 `aria-hidden`，见 reka-ui 的
     * useBodyScrollLock / useHideOthers）在 headless 里也可能不随组件卸载释放。
     * 锁住的 body 让 `elementFromPoint` 只能返回 `<html>`，之后的每次点击都落空。
     * 清锁的前提是**没有任何 open 遮罩**（产品侧确实一个弹窗都没开）—— 有 open
     * 遮罩时锁是模态的正当状态，绝不碰。
     */
    // 残留 portal 口径 = 遮罩 + 卡片/页/抽屉**一起数**：卡片与遮罩是两条独立 Presence，
    // 撤除不同步（实测遮罩先撤、卡片残留）。只数遮罩会提前放行，残留卡片继续干扰下一轮。
    const finishClosedOverlays = () => cdp.eval(`(() => {
      let n = 0;
      // 卡片与遮罩**各自是独立的 Presence**：动画类挂在卡片（DialogContent）上，
      // 遮罩（DialogOverlay）也有自己那条 150ms 淡出。headless 里两个 animationend
      // 都可能不投递 ⇒ 两者都补发一遍，谁在等谁就撤谁的 DOM。
      const sel = '.gosslan-dialog-card[data-state="closed"], .gosslan-dialog-page[data-state="closed"], .gosslan-dialog-sheet[data-state="closed"], .gosslan-dialog-overlay[data-state="closed"]';
      for (const el of document.querySelectorAll(sel)) {
        el.dispatchEvent(new AnimationEvent('animationend', { bubbles: true }));
        n += 1;
      }
      return n;
    })()`);
    const clearStaleBodyLocks = () => cdp.eval(`(() => {
      if (document.querySelector('.gosslan-dialog-overlay[data-state="open"]')) return;
      if (document.body.style.pointerEvents) document.body.style.pointerEvents = '';
      if (document.body.style.overflow === 'hidden') document.body.style.overflow = '';
      for (const el of document.querySelectorAll('body > [aria-hidden="true"]')) el.removeAttribute('aria-hidden');
    })()`);
    const closedPortalCount = () =>
      cdp.eval(`document.querySelectorAll('.gosslan-dialog-overlay[data-state="closed"], .gosslan-dialog-card[data-state="closed"], .gosslan-dialog-page[data-state="closed"], .gosslan-dialog-sheet[data-state="closed"]').length`);
    const waitDialogGone = async () => {
      // 只等 **closed 残留**撤走：那是"刚关掉的弹窗还没退场"，会挡点击、脏化下一轮。
      // **open** 门户是调用方正在交互的弹窗，立即放行（否则弹窗内每次点击白等 3 秒预算）。
      const t0 = Date.now();
      for (;;) {
        const n = await closedPortalCount();
        if (!n) { await clearStaleBodyLocks(); return 0; }
        if (Date.now() - t0 > 3_000) {
          await finishClosedOverlays();
          const t1 = Date.now();
          for (;;) {
            const n2 = await closedPortalCount();
            if (!n2 || Date.now() - t1 > 800) { await clearStaleBodyLocks(); return n2; }
            await sleep(80);
          }
        }
        await sleep(120);
      }
    };
    const clickText = async (needle) => {
      await waitDialogGone();
      const pt = await rectOf(needle);
      if (!pt) return false;
      await cdp.click(pt.x, pt.y);
      await sleep(300);
      return true;
    };

    let s = await info();
    // 首屏读数是异步 Query：等它真的落到 2 行再判（英文档/冷启动时 400ms 可能还不够）。
    for (let i = 0; i < 15 && s.rowTitles.length !== 2; i++) {
      await sleep(200);
      s = await info();
    }
    check("链接左栏：标题 / 两条链接 / 常显编辑与删除 / 添加·导入·备份入口齐全且都有可见文案",
      mounted && mounted.ok === true && s.txt.includes(L.title) && s.rowTitles.length === 2
        && s.edits === 2 && s.removes === 2 && s.add && s.importBtn && s.backup
        && s.backupTitle === L.backupHint,
      "2 行 + 2 编辑 + 2 删除 + 「添加 / 导入 / 备份」三个入口同一行同样式、文案可见 + 备份 title 说明 JSON",
      JSON.stringify({ rows: s.rowTitles, edits: s.edits, removes: s.removes, add: s.add,
        importBtn: s.importBtn, backup: s.backup, backupTitle: s.backupTitle }));

    const importOpened = await clickText(L.importBtn);
    s = await info();
    check("导入：入口打开独立弹窗，文件与网址两种来源都在这一处，且不出现新增/编辑字段",
      importOpened === true && s.txt.includes(L.importTitle) && s.txt.includes(L.fileSection)
        && s.txt.includes(L.urlSection) && s.filePick && s.urlAction
        && s.inputs.some((i) => i.ph === L.importUrlPh)
        && !s.inputs.some((i) => i.ph === L.namePh),
      "导入弹窗含「从文件导入 / 从网址导入」，无「显示名称」",
      JSON.stringify({ inputs: s.inputs, filePick: s.filePick, urlAction: s.urlAction }));
    await clickText(L.cancel);
    s = await info();
    check("导入取消：弹窗收起，列表不受影响",
      !s.txt.includes(L.importTitle) && !s.inputs.some((i) => i.ph === L.importUrlPh)
        && s.rowTitles.length === 2,
      "导入弹窗消失 + 2 行", JSON.stringify({ inputs: s.inputs, rows: s.rowTitles }));

    const opened = await clickText("https://intra.example.com");
    s = await info();
    check("点链接行：把该条交给父级开独立窗口（open 事件真的发出）",
      opened && s.events.some((e) => e[0] === "open-id"), "事件表出现 open-id",
      JSON.stringify(s.events));

    await clickText(L.add);
    s = await info();
    check("点添加：弹窗只有名称/网址两个空输入，不再混入 JSON 导入",
      s.inputs.length === 2 && s.inputs.some((i) => i.ph === L.namePh && i.value === "")
        && s.inputs.some((i) => i.ph === L.urlPh && i.value === "")
        && !s.txt.includes(L.fileSection) && !s.txt.includes(L.urlSection),
      "两个空输入，且无导入入口", JSON.stringify(s.inputs));
    // 新增/编辑现在是同一个 BaseModal：先关掉新增弹窗，才能点到列表行上的编辑。
    await clickText(L.cancel);

    await clickText(L.edit);
    s = await info();
    check("点编辑：同一份表单预填该条名称与网址（不是空表单）",
      s.inputs.some((i) => i.value === "公司内网") && s.inputs.some((i) => i.value === "https://intra.example.com"),
      "公司内网 / https://intra.example.com", JSON.stringify(s.inputs));

    // 读数件在这一格是**与输入框同排**的（360 宽的主栏是最挤的那一档）。
    // 静态判据只管"绑了同一个常量"，管不了把输入框挤到没法用 ⇒ 这一格只能在真浏览器里量。
    const cap = await cdp.eval(`(() => {
      const name = document.querySelector('input[maxlength]');
      if (!name) return { found: false };
      const row = name.parentElement;
      const span = row ? row.querySelector('span.tabular-nums') : null;
      // 表单已搬进 BaseModal（Portal 到 body），量的是弹窗卡片右沿，不是原列表宿主。
      const card = name.closest('.glass-3') || name.closest('[role="dialog"]');
      const ni = name.getBoundingClientRect();
      const cr = card ? card.getBoundingClientRect() : null;
      const r = span ? span.getBoundingClientRect() : null;
      return {
        found: true,
        cardFound: !!card,
        text: span ? span.textContent.trim() : null,
        spanLeft: r ? Math.round(r.left) : null,
        spanRight: r ? Math.round(r.right) : null,
        inputRight: Math.round(ni.right),
        inputWidth: Math.round(ni.width),
        cardRight: cr ? Math.round(cr.right) : null,
        attr: name.getAttribute('maxlength'),
      };
    })()`);
    check("链接名读数在弹窗里与输入框同排共存：两者都可见、互不重叠、不越出卡片",
      cap.found && cap.cardFound && cap.attr === "32" && /^\d+\/32$/.test(String(cap.text || ""))
        && cap.inputWidth >= 120 && cap.spanLeft >= cap.inputRight - 1
        && cap.spanRight <= cap.cardRight + 1,
      "输入框宽度 >=120、读数右沿 <= 卡片右沿、且读数在输入框右侧",
      JSON.stringify(cap));

    await clickText(L.cancel);
    s = await info();
    check("取消：表单收起，两行链接不受影响",
      s.inputs.length === 0 && s.rowTitles.length === 2,
      "0 输入 + 2 行", JSON.stringify({ inputs: s.inputs.length, rows: s.rowTitles.length }));

    // ---- 写路径（§6.98）：三条命令共用一个 mutation，成功时把后端返回的整份数组写回读缓存 ----
    // 判据要的三件事：① 真的发的是对应那条命令；② 列表**立刻**变成返回值的形状（不是等下次重开）；
    // ③ list 的调用次数全程不变（`setQueryData` 写回，不是 `invalidateQueries` 再拉一次）。
    /** 填某个 placeholder 的输入框（等它真出现，最多 2s —— 弹窗刚开那一下在长跑里会慢）。 */
    const fill = async (ph, value) => {
      const t0 = Date.now();
      for (;;) {
        const ok = await cdp.eval(`(() => {
          const i = [...document.querySelectorAll('input')].find((x) => x.placeholder === ${JSON.stringify(ph)});
          if (!i) return false;
          i.value = ${JSON.stringify(value)};
          i.dispatchEvent(new Event('input', { bubbles: true }));
          return true;
        })()`);
        if (ok || Date.now() - t0 > 2_000) return ok;
        await sleep(120);
      }
    };
    /**
     * 在指定 placeholder 的输入框上按一次**真**回车：聚焦后走 CDP 的 `Input.dispatchKeyEvent`，
     * 与用户按键同一条管线（不用 `new KeyboardEvent` 伪造）。聚焦不上就返回 false（同样等 2s）。
     */
    const pressEnter = async (ph) => {
      const t0 = Date.now();
      let focused = false;
      for (;;) {
        focused = await cdp.eval(`(() => {
          const i = [...document.querySelectorAll('input')].find((x) => x.placeholder === ${JSON.stringify(ph)});
          if (!i) return false;
          i.focus();
          return document.activeElement === i;
        })()`);
        if (focused || Date.now() - t0 > 2_000) break;
        await sleep(120);
      }
      if (!focused) return false;
      await cdp.key("Enter", "Enter", "\r", 13);
      return true;
    };
    /** 按行定位那颗按钮（同一页里每行都有一枚「编辑/删除」，不能按文字取第一枚）。 */
    const clickRowBtn = async (rowUrl, aria) => {
      await waitDialogGone();
      const pt = await cdp.eval(`(() => {
        const link = [...document.querySelectorAll('button[title]')]
          .find((b) => b.getAttribute('title') === ${JSON.stringify(rowUrl)});
        if (!link) return null;
        const row = link.parentElement;
        const btn = row ? [...row.querySelectorAll('button')]
          .find((b) => b.getAttribute('aria-label') === ${JSON.stringify(aria)}) : null;
        if (!btn) return null;
        const r = btn.getBoundingClientRect();
        return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
      })()`);
      if (!pt) return false;
      await cdp.click(pt.x, pt.y);
      await sleep(300);
      return true;
    };

    const stats0 = await cdp.eval("window.__probe.linksStats()");
    // 这一格按「保存」按钮走；**真按键**那两格排在段尾（见文件末尾那两格）。
    // 为什么排序要紧：这台引擎的 CSS 动画时钟在长跑里会停摆，Reka 的离场要等 animationend
    // ⇒ 遮罩撤不掉、后面的点击全被吃掉。实测同一段单独跑 13/13，接在 --only=toast 之后
    // 就会红 —— 那是量具的时序，不是产品行为。把真按键那两格放到最后，红也只红它们自己。
    await clickText(L.add);
    await fill(L.namePh, "周报");
    await fill(L.urlPh, "https://weekly.example.com");
    await clickText(L.save);
    await sleep(300);
    s = await info();
    const st1 = await cdp.eval("window.__probe.linksStats()");
    const last1 = await cdp.eval("window.__probe.linksLast()");
    check("新增：保存把 add 发出去，返回的整份数组立刻回填列表（3 行），且没有再拉一次 list",
      st1.add === 1 && st1.list === stats0.list && last1 && last1.kind === "add"
        && s.rows.length === 3 && s.txt.includes("周报") && s.inputs.length === 0,
      "add=1、list 不变、3 行含「周报」、草稿收起",
      JSON.stringify({ st1, last1, rows: s.rows, inputs: s.inputs.length }));

    const edited = await clickRowBtn("https://weekly.example.com", L.edit);
    const filled = await fill(L.namePh, "周报（改）");
    await clickText(L.save);
    await sleep(300);
    s = await info();
    const st2 = await cdp.eval("window.__probe.linksStats()");
    const last2 = await cdp.eval("window.__probe.linksLast()");
    check("修改：编辑该行的保存发 update(id)，列表就地换成新名字（仍是 3 行）",
      edited && filled && st2.update === 1 && st2.add === 1 && st2.list === stats0.list
        && last2 && last2.kind === "update" && last2.id === "n1"
        && s.rows.length === 3 && s.txt.includes("周报（改）"),
      "update=1、id=n1、3 行、显示新名",
      JSON.stringify({ st2, last2, rows: s.rows }));

    const removed = await clickRowBtn("https://weekly.example.com", L.remove);
    await sleep(300);
    s = await info();
    const st3 = await cdp.eval("window.__probe.linksStats()");
    check("删除：该行的删除发 remove(id)，行从列表消失、回到 2 行，list 全程只发过 1 次",
      removed && st3.remove === 1 && st3.list === stats0.list
        && s.rows.length === 2 && !s.txt.includes("周报（改）"),
      "remove=1、2 行、不再有该条",
      JSON.stringify({ st3, rows: s.rows }));

    // ---- 写失败：真实 Toast（§6.99）----
    // 三件事一起断：① 写命令真的发出且真的失败；② 屏幕上出现 **error toast**、文案是
    // `links.addFail` 拼出来的那句；③ 草稿还开着、列表没变（失败不许显示成成功态）。
    const hud = await cdp.eval("window.__probe.mountToastHud()");
    await cdp.eval("window.__probe.linksFailNext('add')");
    await clickText(L.add);
    await fill(L.namePh, "会失败");
    await fill(L.urlPh, "https://boom.example.com");
    await clickText(L.save);
    await sleep(500);
    s = await info();
    const st4 = await cdp.eval("window.__probe.linksStats()");
    const toast = await cdp.eval("window.__probe.toastRead()");
    check("写失败：onError 真的把 error toast 送进 HUD（不是静默失败），且列表与草稿都没被当成成功",
      hud && hud.ok === true && st4.add === 2 && st4.list === stats0.list
        && toast.visible >= 1 && toast.statuses.includes("error")
        && toast.texts.some((x) => x.includes(L.addFail))
        && s.rows.length === 2 && !s.rows.includes("https://boom.example.com")
        && s.inputs.some((i) => i.value === "会失败"),
      "add=2、1 条 error toast 含「添加链接失败」、2 行、草稿仍开着",
      JSON.stringify({ hud, toast, st4, rows: s.rows, inputs: s.inputs }));
    await clickText(L.cancel);

    // ==== 段尾两格：真按键（CDP Input.dispatchKeyEvent）提交 ====
    // 用户 2026-10-23 那句"不用每次自己手点"要的就是这两格：静态判据只能证明模板里写了
    // ime.enter(fn, $event)，证不了按下回车真的把动作发出去（2026-10-23 之前那 16 处
    // 全都写成 ime.enter(fn)，静态看着对、运行时一次都没执行）。
    // ① 新增：网址框按回车 = 保存（此时列表 2 行：删掉周报之后）
    await clickText(L.add);
    await fill(L.namePh, "周报二");
    await fill(L.urlPh, "https://weekly2.example.com");
    const addEnter = await pressEnter(L.urlPh);
    await sleep(400);
    s = await info();
    const st5 = await cdp.eval("window.__probe.linksStats()");
    const last5 = await cdp.eval("window.__probe.linksLast()");
    check("新增：在网址框按回车就保存（add=3）、列表立刻回填 3 行含「周报二」、弹窗自己收起",
      addEnter === true && st5.add === 3 && st5.list === stats0.list
        && last5 && last5.kind === "add" && last5.name === "周报二"
        && s.rows.length === 3 && s.txt.includes("周报二") && s.inputs.length === 0,
      "回车提交：add=3、list 不变、3 行含「周报二」、弹窗收起",
      JSON.stringify({ addEnter, st5, last5, rows: s.rows, inputs: s.inputs.length }));

    // ② 线上导入：网址框按回车 = 拉取并导入
    // 整页重载隔离（工具层，判据一字不动）：到这一格之前本段已密集开关六七个弹窗，
    // headless 里 Reka 的关闭动画（animationend）不一定投递，残留 portal 握着 body 的
    // 模态锁（pointer-events:none + aria-hidden），后续点击全落空、新弹窗打不开
    //（2026-11-03 取证：补发 animationend / 清锁 / 硬摘 DOM 都不能稳定复原，卡片 Presence
    // 卡死在 unmountSuspended）。探针页是无状态的，重载重建一份带 3 行（含上一格加进的
    // 「周报二」）的干净夹具，等价于把本格挪到段首执行 —— 量到的还是同一件事。
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`window.__probe.linksStore(${JSON.stringify([
      ...links,
      { id: "n1", name: "周报二", url: "https://weekly2.example.com" },
    ])})`);
    await cdp.eval("window.__probe.install('/src/components/LinksList.vue', '', '')");
    await cdp.eval(`(() => {
      const h = document.getElementById('probe-host');
      h.style.width = '360px';
      h.style.height = '640px';
      h.style.display = 'block';
      return true;
    })()`);
    await sleep(400);
    const importAgain = await clickText(L.importBtn);
    await fill(L.importUrlPh, "https://backup.example.com/links.json");
    const importEnter = await pressEnter(L.importUrlPh);
    await sleep(500);
    s = await info();
    const st6 = await cdp.eval("window.__probe.linksStats()");
    const last6 = await cdp.eval("window.__probe.linksLast()");
    check("线上导入：在网址框按回车就导入（importUrl=1），返回的整份数组立刻回填、弹窗收起",
      importAgain && importEnter && st6.importUrl === 1 && st6.list === stats0.list
        && last6 && last6.kind === "importUrl" && last6.url === "https://backup.example.com/links.json"
        && s.rows.length === 4 && s.txt.includes("导入的链接")
        && !s.inputs.some((i) => i.ph === L.importUrlPh),
      "回车提交：importUrl=1、list 不变、4 行含「导入的链接」、弹窗收起",
      JSON.stringify({ st6, last6, rows: s.rows, inputs: s.inputs }));

    // ---- 固定来源 + 刷新（用户 2026-11-04）----
    s = await info();
    const st7 = await cdp.eval("window.__probe.linksStats()");
    check("导入后：来源条固定显示完整链接（含复制键），标题栏刷新键有可见文案且位于正文上方",
      s.source && s.source.title === "https://backup.example.com/links.json"
        && s.source.text.includes(L.sourceLabel)
        && s.source.copy && s.refreshBtn && s.refreshText === L.refresh
        && s.refreshBusy === false && s.refreshDisabled === false
        && s.refreshTop !== null && s.source.top !== null && s.refreshTop < s.source.top,
      "来源条 = label + 完整 URL + 复制键；刷新键在标题栏（top 小于来源条）并显示「刷新」",
      JSON.stringify({ source: s.source, refreshText: s.refreshText, refreshTop: s.refreshTop }));

    // HUD 可能被中途的模态关合带走（探针夹具现象）；刷新这几格要读 toast，先重挂一份干净的。
    await cdp.eval("window.__probe.remountToastHud()");
    const toastBefore = await cdp.eval("window.__probe.toastRead()");
    await cdp.eval("window.__probe.linksHold()");
    // 同一轮同步派发两次 click（Vue 还没来得及把按钮置 disabled）⇒ 只有 single-flight 能挡住第二次。
    const dbl = await cdp.eval(`(() => {
      const b = document.querySelector('[data-probe="links-refresh"]');
      if (!b) return false;
      b.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      b.dispatchEvent(new MouseEvent('click', { bubbles: true }));
      return true;
    })()`);
    await sleep(300);
    s = await info();
    const st8 = await cdp.eval("window.__probe.linksStats()");
    check("刷新进行中：按钮文案变「刷新中…」且 aria-busy，旧数据仍在；连点两次只发一次请求",
      dbl && st8.importUrl === st7.importUrl + 1 && s.refreshBusy === true
        && s.refreshText === L.refreshing && s.refreshDisabled === true
        && s.rows.length === 4,
      "importUrl 只 +1、按钮「刷新中…」+ disabled、4 行旧数据仍在",
      JSON.stringify({ st7, st8, refreshText: s.refreshText, rows: s.rows.length }));
    await cdp.eval("window.__probe.linksRelease()");
    await sleep(600);
    s = await info();
    const toastAfter = await cdp.eval("window.__probe.toastRead()");
    check("刷新成功：静默（不新增 toast），列表换成本次返回的 5 行",
      s.refreshBusy === false && s.rows.length === 5 && toastAfter.total <= toastBefore.total,
      "无新 toast、5 行",
      JSON.stringify({ before: toastBefore.total, after: toastAfter.total, rows: s.rows.length }));

    await cdp.eval("window.__probe.remountToastHud()");
    await cdp.eval("window.__probe.linksFailNext('refreshHttp')");
    await cdp.eval(`document.querySelector('[data-probe="links-refresh"]').dispatchEvent(new MouseEvent('click', { bubbles: true }))`);
    await sleep(600);
    s = await info();
    const toastHttp = await cdp.eval("window.__probe.toastRead()");
    const st9 = await cdp.eval("window.__probe.linksStats()");

    // A1 修正：完整原因（HTTP 状态 + 建议）搬到来源条下方的页面内错误行；toast 只留结论。
    check("刷新失败（链接失效）：来源行下方给出 HTTP 状态 + 检查/重新导入建议，toast 只报结论，旧数据不清空，按钮可重试",
      toastHttp.visible >= 1 && toastHttp.statuses.includes("error")
        && toastHttp.texts.some((x) => x.includes(L.failTitle))
        && !!s.refreshError && s.refreshError.includes(L.failHttp.replace("{status}", "410"))
        && s.rows.length === 5 && s.refreshBusy === false && s.refreshDisabled === false,
      "toast=刷新失败、页面内错误行含 HTTP 410、5 行旧数据仍在、按钮恢复",
      JSON.stringify({ toast: toastHttp.texts, inline: s.refreshError, rows: s.rows.length, st9 }));

    await cdp.eval("window.__probe.remountToastHud()");
    await cdp.eval("window.__probe.linksFailNext('refreshNetwork')");
    await cdp.eval(`document.querySelector('[data-probe="links-refresh"]').dispatchEvent(new MouseEvent('click', { bubbles: true }))`);
    await sleep(600);
    s = await info();
    const toastNet = await cdp.eval("window.__probe.toastRead()");
    check("刷新失败（网络不可达）：页面内错误行给网络话术而不是兜底「操作失败」，toast 只报结论，旧数据仍在",
      toastNet.texts.some((x) => x.includes(L.failTitle))
        && !!s.refreshError && s.refreshError.includes(L.failNetwork)
        && !(s.refreshError || "").includes("操作失败")
        && s.rows.length === 5,
      "toast=刷新失败、页面内含网络不可达话术、无「操作失败」、5 行仍在",
      JSON.stringify({ toast: toastNet.texts, inline: s.refreshError, rows: s.rows.length }));
    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-links.png"), Buffer.from(shot.data, "base64"));
      console.log("  📷 链接左栏取证帧 → " + SHOT_PATH.replace(/\.png$/, "-links.png"));
    }
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 设置页字体下拉（--only=fontsel）：Reka Select 不渲染空串 option。
 * 判据是"默认档到底存不存在"：触发器文案、菜单四项、选中第二档后的落库值、再切回默认。
 */
async function runFontSelect(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  await cdp.eval("window.__probe.stubApi('saveSettings', null)");
  const mounted = await cdp.eval("window.__probe.install('/src/components/settings/AppearanceSection.vue', '', "
    + JSON.stringify(JSON.stringify({ isolated: true })) + ")");
  await cdp.eval(`(() => {
    const h = document.getElementById('probe-host');
    h.style.width = '760px';
    h.style.display = 'block';
    return true;
  })()`);
  await sleep(400);

  const info = () => cdp.eval(`(() => {
    const trigger = document.querySelector('button[aria-label="界面字体"]');
    return {
      trigger: trigger ? (trigger.innerText || '').trim() : null,
      items: [...document.querySelectorAll('.gosslan-menu-item')].map((b) => (b.innerText || '').trim()),
      stored: localStorage.getItem('gosslan.fontFamily'),
    };
  })()`);
  const openMenu = async () => {
    const pt = await cdp.eval(`(() => {
      const b = document.querySelector('button[aria-label="界面字体"]');
      if (!b) return null;
      const r = b.getBoundingClientRect();
      return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    })()`);
    if (!pt) return false;
    await cdp.click(pt.x, pt.y);
    await sleep(300);
    return true;
  };

  let s = await info();
  check("字体下拉默认档：触发器显示「系统默认」（不是空白）",
    mounted && mounted.ok === true && s.trigger === "系统默认",
    "触发器=系统默认", JSON.stringify({ trigger: s.trigger }));

  await openMenu();
  s = await info();
  check("菜单包含四个字体档，且「系统默认」没有被 Reka 的空串值吞掉",
    s.items.length === 4 && s.items.includes("系统默认") && s.items.includes("思源黑体"),
    "4 项且含系统默认", JSON.stringify(s.items));
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-font.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 字体下拉取证帧 → " + SHOT_PATH.replace(/\.png$/, "-font.png"));
  }

  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  await cdp.key("Enter", "Enter", "\r", 13);
  await sleep(300);
  s = await info();
  check("↓+Enter 选中第二档：触发器显示苹方 / 微软雅黑，落库值是字体栈（不是哨兵）",
    s.trigger === "苹方 / 微软雅黑" && String(s.stored || "").includes("PingFang SC"),
    "触发器=苹方 / 微软雅黑 + 落库字体栈",
    JSON.stringify({ trigger: s.trigger, stored: s.stored }));

  await openMenu();
  await cdp.key("ArrowUp", "ArrowUp", "", 38);
  await cdp.key("Enter", "Enter", "\r", 13);
  await sleep(300);
  s = await info();
  check("再切回系统默认：触发器恢复、落库值为空串（哨兵没有泄漏到设置里）",
    s.trigger === "系统默认" && s.stored === "",
    "触发器=系统默认 + stored=''", JSON.stringify({ trigger: s.trigger, stored: s.stored }));
}

/**
 * 网络拓扑（--only=topology，2026-11-10）：挂**真组件 + 真 force-graph**，四条读数。
 *
 * 为什么要有这一段：拓扑是纯 Canvas 渲染，设计护栏只能盯源码形状（圆角/断点/安全区），
 * 盯不到"图到底画出来了没有、点节点到底开不开面板"。这里用一针 `arc` 记录器拿到
 * force-graph 真正落笔的节点圆心（含 zoom/DPR 变换），再用 CDP 真点一下，
 * 避免用网格瞎扫（半径 11 的圆在 30px 网格下会漏）。
 */
async function runTopology(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  await cdp.eval(`(() => {
    window.__pageErrors = [];
    window.addEventListener('error', (e) => window.__pageErrors.push(String(e.message || e)));
    window.addEventListener('unhandledrejection', (e) => window.__pageErrors.push('rej:' + String(e.reason && e.reason.message || e.reason)));
    return true;
  })()`);

  // 1) 三条 IPC 换成替身：4 个在线节点（2 好友 / 1 陌生 / 1 走 Mesh）+ 每条会话的链路读数。
  await cdp.eval(`(async () => {
    const m = await import('/src/api/index.ts');
    const peer = (id, nickname, link) => ({
      device_id: id, nickname, avatar: null, device_type: 'desktop', ip: '10.0.0.2',
      tcp_port: 1420, last_seen: Date.now(), rtt_ms: 12, x25519_pubkey: null,
      ed25519_pubkey: null, first_seen: null, link,
    });
    const peers = [
      peer('f-lan', '直连好友', 'lan'),
      peer('f-relay', '中转好友', 'relay'),
      peer('p-routed', '陌生节点', 'routed'),
      peer('f-mesh', 'Mesh 好友', null),
    ];
    const friends = [
      { device_id: 'f-lan', nickname: '直连好友', avatar: null, device_type: 'desktop', online: true, peer_app_version: '5.20.11' },
      { device_id: 'f-relay', nickname: '中转好友', avatar: null, device_type: 'desktop', online: true, peer_app_version: '5.20.11' },
      { device_id: 'f-mesh', nickname: 'Mesh 好友', avatar: null, device_type: 'desktop', online: true, peer_app_version: '5.20.11' },
    ];
    m.api.getPeers = async () => peers;
    m.api.getFriends = async () => friends;
    m.api.getConvLink = async (id) => (id === 'f-lan'
      ? { path: 'lan', hop: 0 }
      : id === 'f-relay' ? { path: 'relay', hop: 1 } : { path: 'routed', hop: 2 });
    window.__probeTopo = { peers, friends };
    return true;
  })()`);

  // 2) `arc` 记录器：只记节点本体半径（11/12/18），把 canvas 变换一并算成 CSS 像素。
  await cdp.eval(`(() => {
    window.__topoArcs = [];
    const proto = CanvasRenderingContext2D.prototype;
    const orig = proto.arc;
    proto.arc = function (x, y, r) {
      try {
        if (this.canvas && this.canvas.closest('#probe-host') && r > 0.5) {
          const t = this.getTransform();
          // 组件现在按 **graph 坐标 / globalScale** 画节点（屏幕尺寸恒定），
          // 所以这里换算回**屏幕半径**再套 10..19 的节点半径窗口。
          const sr = (r * t.a) / devicePixelRatio;
          if (sr >= 10 && sr <= 19) {
            window.__topoArcs.push({
              x: (t.a * x + t.c * y + t.e) / devicePixelRatio,
              y: (t.b * x + t.d * y + t.f) / devicePixelRatio,
              r: sr,
            });
          }
        }
      } catch {}
      return orig.apply(this, arguments);
    };
    window.__topoCands = () => {
      const seen = new Set();
      const out = [];
      for (const a of (window.__topoArcs || []).slice().reverse()) {
        if (Math.round(a.r) !== 11) continue;
        const key = Math.round(a.x) + '|' + Math.round(a.y);
        if (seen.has(key)) continue;
        seen.add(key);
        out.push({ x: Math.round(a.x), y: Math.round(a.y) });
        if (out.length >= 14) break;
      }
      return out;
    };
    return true;
  })()`);

  const mounted = await cdp.eval("window.__probe.install('/src/components/NetworkTopology.vue', '', "
    + JSON.stringify(JSON.stringify({ isolated: true })) + ")");
  // 2b) 首帧位置（2026-11-11 用户：「自己的节点一开始在最左上角，过了一下才到中间」）：
  //     挂载后立刻（种名单**之前**，此时图里只有 self）读**最早**那几笔落笔坐标 ——
  //     首帧就该落在图区中心；先画在 (0,0)=左上角再被 zoomToFit 拉回来就是这条 bug。
  await sleep(600);
  const firstFrame = await cdp.eval(`(() => {
    const canvas = document.querySelector('#probe-host .force-graph-container canvas');
    if (!canvas) return { ok: false };
    const cr = canvas.getBoundingClientRect();
    const a = (window.__topoArcs || [])[0];
    if (!a) return { ok: false, hasArc: false };
    const cx = cr.left + cr.width / 2;
    const cy = cr.top + cr.height / 2;
    return {
      ok: true,
      dist: Math.round(Math.hypot(a.x - cx, a.y - cy)),
      at: { x: Math.round(a.x), y: Math.round(a.y) },
      center: { x: Math.round(cx), y: Math.round(cy) },
    };
  })()`);
  check("拓扑首帧：self 节点一开始就画在图区中心（不许先挂左上角再弹回中间）",
    firstFrame.ok === true && firstFrame.dist <= 150,
    "最早落笔距图区中心 ≤ 150px",
    JSON.stringify(firstFrame));
  // 3) 名单必须写进**组件正在用的那份 store**（install 之后才有同一个 pinia）。
  const seeded = await cdp.eval(`(async () => {
    const A = await import('/src/stores/useAppStore.ts');
    const C = await import('/src/stores/useChatStore.ts');
    const app = A.useAppStore();
    const chat = C.useChatStore();
    app.device = { device_id: 'me', nickname: '本机', avatar: null, device_type: 'desktop',
      tcp_port: 1, online: true, x25519_pubkey: '', ed25519_pubkey: '' };
    chat.peers = window.__probeTopo.peers;
    chat.friends = window.__probeTopo.friends;
    await new Promise((r) => setTimeout(r, 0));
    return { ok: true, peers: chat.peers.length, friends: chat.friends.length };
  })()`);
  // 等力导向**真的**停笔：软件渲染下 90 tick 可能慢过 2.5s，拿半途坐标去点会点空。
  // 判据是 `arc` 记录器不再增长（force-graph 收尾后不再重绘），不是固定等几秒。
  let lastDraws = -1;
  let stableRounds = 0;
  for (let i = 0; i < 24 && stableRounds < 2; i += 1) {
    await sleep(300);
    const draws = await cdp.eval("(window.__topoArcs || []).length");
    if (draws === lastDraws) stableRounds += 1;
    else { stableRounds = 0; lastDraws = draws; }
  }

  const m = await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const canvas = document.querySelector('#probe-host .force-graph-container canvas');
    const legend = document.querySelector('[data-topo-legend]');
    const stats = document.querySelector('[data-topo-stats]');
    if (!canvas || !legend || !stats) {
      return { ok: false, hasCanvas: !!canvas, hasLegend: !!legend, hasStats: !!stats };
    }
    const rect = canvas.getBoundingClientRect();
    const ctx = canvas.getContext('2d');
    const data = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
    let ink = 0; // 背景是透明的：采样到 alpha>0 就是真画了东西
    for (let i = 3; i < data.length; i += 4 * 16) if (data[i] > 0) ink += 1;
    const statsText = (stats.textContent || '').replace(/\\s+/g, ' ').trim();
    const expect = [
      I.t('topology.online', { n: 4 }),
      I.t('topology.friends', { n: 3 }),
      I.t('topology.relayed', { n: 1 }),
      I.t('topology.mesh', { n: 1 }),
    ];
    const arcs = (window.__topoArcs || []).filter((a) => a.x > 0 && a.y > 0);
    return {
      ok: true,
      vw: innerWidth,
      vh: innerHeight,
      canvasW: Math.round(rect.width),
      canvasH: Math.round(rect.height),
      canvasLeft: Math.round(rect.left),
      canvasTop: Math.round(rect.top),
      ink,
      statsText,
      statsHas: expect.map((s) => statsText.includes(s)),
      legendRows: legend.children.length,
      arcs: arcs.slice(-40).map((a) => ({ x: Math.round(a.x), y: Math.round(a.y), r: Math.round(a.r) })),
      drawCalls: arcs.length,
      // 候选点去重、保留最近一次落笔（同一节点在每帧都会重画）
      candidates: (() => {
        const seen = new Set();
        const out = [];
        for (const a of arcs.slice().reverse()) {
          if (Math.round(a.r) !== 11) continue;
          const k = Math.round(a.x) + '|' + Math.round(a.y);
          if (seen.has(k)) continue;
          seen.add(k);
          out.push({ x: Math.round(a.x), y: Math.round(a.y) });
          if (out.length >= 14) break;
        }
        return out;
      })(),
    };
  })()`);
  check("网络拓扑：Canvas 铺满图区并真的画出了东西（透明背景上采样到墨迹）",
    mounted && mounted.ok === true && m.ok === true && m.canvasW > 200 && m.canvasH > 200 && m.ink >= 50,
    "canvas > 200×200 + ink ≥ 50",
    JSON.stringify({ mounted, ok: m.ok, w: m.canvasW, h: m.canvasH, ink: m.ink }));
  check("网络拓扑：画布高度钉在真图区里（不许按整窗高度画到视口外，底部节点会被裁）",
    m.ok === true && Math.abs(m.canvasTop + m.canvasH - m.vh) <= 1 && m.canvasH < m.vh,
    "canvasTop + canvasH = 视口底",
    JSON.stringify({ top: m.canvasTop, h: m.canvasH, vh: m.vh }));
  check("网络拓扑：顶栏总数与四种计数（在线/好友/中转/Mesh）都渲染出来",
    m.ok === true && m.statsHas.length === 4 && m.statsHas.every(Boolean),
    "四项都在 stats 文本里",
    JSON.stringify({ text: m.statsText, has: m.statsHas }));
  check("网络拓扑：图例五行（好友/节点/中枢/直连/中转）齐备",
    m.ok === true && m.legendRows === 5,
    "legend children = 5",
    JSON.stringify({ rows: m.legendRows }));
  // 取证帧必须拍在点开详情卡**之前**：窄视口下底部卡会盖住大半张图。
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-topology.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 网络拓扑取证帧 → " + SHOT_PATH.replace(/\.png$/, "-topology.png"));
  }

  // 4) 真点普通节点（r=11）：面板必须开，且动作键对得上节点身份。
  //    点击走组件自己的 `screen2GraphCoords` 命中测试（见 §2.15），不依赖 force-graph
  //    那块 800ms 节流的 hover 影子画布 —— 后者在数据刷新后可能拿着上一代颜色索引。
  const candidates = m.candidates || [];
  check("网络拓扑：力导向真的落了节点本体（arc 记录器认到 r=11 的节点）",
    m.ok === true && candidates.length >= 3 && m.drawCalls >= 20,
    "至少 3 个 r=11 节点 + 多次重绘",
    JSON.stringify({ candidates, drawCalls: m.drawCalls }));
  let panel = { ok: false, hasPanel: false };
  const tried = [];
  for (const c of candidates) {
    const x = m.canvasLeft + c.x;
    const y = m.canvasTop + c.y;
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x, y, button: "none" });
    await sleep(80);
    await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x, y, button: "left", clickCount: 1 });
    await sleep(60);
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x, y, button: "left", clickCount: 1 });
    await sleep(320);
    panel = await cdp.eval(`(async () => {
      const I = await import('/src/i18n/index.ts');
      const aside = document.querySelector('#probe-host aside');
      if (!aside || !aside.getClientRects().length) return { ok: false, hasPanel: false };
      const buttons = [...aside.querySelectorAll('button')].map((b) => (b.textContent || '').trim()).filter(Boolean);
      const roleText = (aside.querySelector('[data-topo-role]')?.textContent || '').trim();
      return {
        ok: true, hasPanel: true, buttons, roleText,
        hasChat: buttons.includes(I.t('topology.action.chat')),
        hasAdd: buttons.includes(I.t('topology.action.add')),
        role: roleText === I.t('topology.role.friend') ? 'friend'
          : roleText === I.t('topology.role.peer') ? 'peer' : 'other',
      };
    })()`);
    tried.push({ x, y, hasPanel: panel.hasPanel });
    if (panel.hasPanel) break;
  }
  check("网络拓扑：点节点弹出详情卡（好友给「发消息」、陌生节点给「加好友」）",
    panel.ok === true && panel.hasPanel === true
      && ((panel.role === "friend" && panel.hasChat) || (panel.role === "peer" && panel.hasAdd)),
    "panel 开 + 动作键与身份一致",
    JSON.stringify({ panel, candidates, tried, canvasTop: m.canvasTop, canvasLeft: m.canvasLeft, canvasH: m.canvasH }));

  // 相机归属 + 增量更新（2026-11-11 用户）：
  // ① 用户滚轮放大后，数据刷新（新增节点）不得把缩放重置回 1；
  // ② 老节点不得大幅移动（新节点在自己的槽位就地出现）。
  // 选一个离所有节点最远的角落做**平移**（拖拽 = 用户动了相机）。
  const cand0 = await cdp.eval("window.__topoCands()");
  const corner = (() => {
    const spots = [
      { x: m.canvasLeft + 30, y: m.canvasTop + 30 },
      { x: m.canvasLeft + m.canvasW - 30, y: m.canvasTop + 30 },
      { x: m.canvasLeft + 30, y: m.canvasTop + m.canvasH - 30 },
      { x: m.canvasLeft + m.canvasW - 30, y: m.canvasTop + m.canvasH - 30 },
    ];
    return spots
      .map((sp) => ({ ...sp, d: Math.min(...(cand0 || [{ x: -9999, y: -9999 }]).map((c) => Math.hypot(c.x + m.canvasLeft - sp.x, c.y + m.canvasTop - sp.y))) }))
      .sort((a, b) => b.d - a.d)[0];
  })();
  const camPre = await cdp.eval("(() => { const c = document.querySelector('#probe-host .force-graph-container canvas'); return c && c.__zoom ? { k: c.__zoom.k, x: c.__zoom.x, y: c.__zoom.y } : null; })()");
  await cdp.drag(corner.x, corner.y, corner.x + 80, corner.y + 60);
  await sleep(350);
  const cam0 = await cdp.eval("(() => { const c = document.querySelector('#probe-host .force-graph-container canvas'); return c && c.__zoom ? { k: c.__zoom.k, x: c.__zoom.x, y: c.__zoom.y } : null; })()");
  // 清一次 arc 历史：候选数要等于**当前**节点数（历史位置会把计数撑爆）。
  await cdp.eval("window.__topoArcs = []");
  await sleep(350);
  const candBefore = await cdp.eval("window.__topoCands()");
  await cdp.eval("window.__topoArcs = []");
  await cdp.eval(`(async () => {
    const C = await import('/src/stores/useChatStore.ts');
    const chat = C.useChatStore();
    chat.peers = [...chat.peers, { device_id: 'p-new', nickname: '新节点', avatar: null,
      device_type: 'desktop', ip: '10.0.0.9', tcp_port: 1420, last_seen: Date.now(), rtt_ms: 9,
      x25519_pubkey: null, ed25519_pubkey: null, first_seen: null, link: 'lan' }];
    await new Promise((r) => setTimeout(r, 0));
    return true;
  })()`);
  await sleep(1_000);
  const cam2 = await cdp.eval("(() => { const c = document.querySelector('#probe-host .force-graph-container canvas'); return c && c.__zoom ? { k: c.__zoom.k, x: c.__zoom.x, y: c.__zoom.y } : null; })()");
  const candAfter = await cdp.eval("window.__topoCands()");
  const kept = (candBefore || []).filter((b) => (candAfter || [])
    .some((a) => Math.hypot(a.x - b.x, a.y - b.y) <= 20)).length;
  check("拓扑相机：用户平移后数据刷新不重置相机（平移量/缩放都保持）",
    !!camPre && !!cam0 && !!cam2
      && Math.abs(cam0.k - camPre.k) <= 0.001  // 拖拽是平移，不改 k
      && Math.abs(cam0.x - camPre.x) >= 20 && Math.abs(cam0.y - camPre.y) >= 20
      && Math.abs(cam2.x - cam0.x) <= 2 && Math.abs(cam2.y - cam0.y) <= 2
      && Math.abs(cam2.k - cam0.k) <= 0.001,
    "拖出平移量，刷新后 x/y/k 原样",
    JSON.stringify({ camPre, cam0, cam2 }));
  check("拓扑增量：新增节点后老节点不动（≤20px）、新节点就地出现",
    (candBefore || []).length >= 3 && kept >= Math.min(3, (candBefore || []).length)
      && (candAfter || []).length >= (candBefore || []).length + 1,
    `老节点 kept=${kept} / 候选 ${candBefore && candBefore.length} → ${candAfter && candAfter.length}`,
    JSON.stringify({ kept, before: candBefore && candBefore.length, after: candAfter && candAfter.length }));

  // 空态与顶栏（2026-11-11 用户）：
  // ① 只剩自己时，提示文字不许盖住居中的 self 节点（提示在 center+64px 起）；
  // ② 桌面顶栏只让刘海（--gosslan-inset-top），返回键上方不许再有 caption 第二遍的死间距。
  await cdp.eval(`(async () => {
    const C = await import('/src/stores/useChatStore.ts');
    const chat = C.useChatStore();
    chat.peers = [];
    chat.friends = [];
    await new Promise((r) => setTimeout(r, 0));
    return true;
  })()`);
  await sleep(1_200); // 力导向把唯一的 self 节点收回中心
  const emptyRead = await cdp.eval(`(() => {
    // 顶栏那条判据量的是**桌面 token 环境**（inset-top 回落 0）：探针窗口 <768 时
    // applyIsMobile 给 html 挂了 is-mobile（回落 24px）。这里只摘类、不改视口 ——
    // 变视口会干扰 force-graph 的 zoom 读数（2026-11-11 实测）。
    document.documentElement.classList.remove('is-mobile');
    const canvas = document.querySelector('#probe-host .force-graph-container canvas');
    const hint = document.querySelector('#probe-host [class*="50%+64px"]');
    const header = document.querySelector('#probe-host header');
    const back = header ? header.querySelector('button') : null;
    const cr = canvas ? canvas.getBoundingClientRect() : null;
    const hr = hint ? hint.getBoundingClientRect() : null;
    return {
      hasCanvas: !!canvas,
      hasHint: !!hint,
      canvasMidY: cr ? Math.round(cr.top + cr.height / 2) : -1,
      hintTop: hr ? Math.round(hr.top) : -1,
      headerTop: header ? Math.round(header.getBoundingClientRect().top) : -1,
      headerH: header ? Math.round(header.getBoundingClientRect().height) : -1,
      backTop: back ? Math.round(back.getBoundingClientRect().top) : -1,
      backH: back ? Math.round(back.getBoundingClientRect().height) : -1,
      headerPadTop: header ? getComputedStyle(header).paddingTop : '',
      insetTop: getComputedStyle(document.documentElement).getPropertyValue('--gosslan-inset-top').trim(),
    };
  })()`);
  check("网络拓扑：只有自己时空态提示落在节点下方（不盖住 self 节点）",
    emptyRead.hasCanvas === true && emptyRead.hasHint === true
      && emptyRead.hintTop >= emptyRead.canvasMidY + 40,
    `hintTop ≥ canvasMidY + 40`,
    JSON.stringify(emptyRead));
  // 桌面上 inset-top=0 ⇒ header 的 padding-top 必须是 0（caption 已由外壳让过，
  // 再读 --gosslan-safe-top 就是把 caption 高度算第二遍 = 用户报的那条死间距）；
  // 返回键在 52px 页头里垂直居中，上方余量 = (headerH − backH) / 2，不许更多。
  check("网络拓扑：桌面顶栏不再读 safe-top（padding-top=0，返回键上方只剩居中余量）",
    emptyRead.headerTop >= 0 && emptyRead.headerPadTop === '0px'
      && Math.abs((emptyRead.backTop - emptyRead.headerTop) - (emptyRead.headerH - emptyRead.backH) / 2) <= 1,
    "headerPadTop=0px + backTop−headerTop=(headerH−backH)/2",
    JSON.stringify(emptyRead));
  // 兜底态（INV-P36 同族）：名单**读不到**时必须给错误横幅 + 重试，
  // 不许把 IO 失败画成"还没有发现其他节点"。让 getPeers/getFriends 抛错，
  // 点空态提示里的「刷新」按钮（它调 refreshAll），横幅要带出真实原因。
  await cdp.eval(`(async () => {
    const m = await import('/src/api/index.ts');
    const C = await import('/src/stores/useChatStore.ts');
    C.useChatStore().peers = []; // 相机阶段加过 p-new：兜底量的是**空名单 + 读失败**
    m.api.getPeers = async () => { throw new Error('probe-net-down'); };
    m.api.getFriends = async () => { throw new Error('probe-net-down'); };
    return true;
  })()`);
  await sleep(300);
  await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const btn = [...document.querySelectorAll('#probe-host button')]
      .find((b) => (b.textContent || '').trim() === I.t('topology.refresh'));
    if (btn) btn.click();
    return true;
  })()`);
  await sleep(700);
  const failRead = await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const zone = document.querySelector('#probe-host [class*="50%+64px"]');
    const text = (zone && zone.textContent || '').replace(/\s+/g, ' ').trim();
    return {
      showsError: text.includes('probe-net-down'),
      showsHint: text.includes(I.t('topology.loadFailedHint')),
      emptyGone: !text.includes(I.t('topology.empty')),
    };
  })()`);
  failRead.hasRetry = await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const zone = document.querySelector('#probe-host [class*="50%+64px"]');
    return !!zone && [...zone.querySelectorAll('button')]
      .some((b) => (b.textContent || '').trim() === I.t('common.retry'));
  })()`);
  check("拓扑兜底：名单读不到时给错误横幅（原因行 + 重试键），不说成空场",
    failRead.showsHint === true && failRead.emptyGone === true && failRead.hasRetry === true,
    "横幅含 loadFailedHint + 重试键，空态文案消失",
    JSON.stringify(failRead));

  // 渲染循环死掉（如 createRadialGradient(NaN) 那次）在这里现形：本段页面零未捕获错误。
  const pageErrors = await cdp.eval("(window.__pageErrors || [])");
  check("拓扑段：页面零未捕获错误（error / unhandledrejection）",
    Array.isArray(pageErrors) && pageErrors.length === 0,
    "0 条", JSON.stringify(pageErrors));
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-topology-empty.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 拓扑空态取证帧 → " + SHOT_PATH.replace(/\.png$/, "-topology-empty.png"));
  }
}

/**
 * 移动端输入框（--only=composermobile）：390 宽下工具栏与发送键的布局。
 * 发送/表情的行为由 --only=inputpanel 覆盖，这里只量移动端视口。
 */
async function runComposerMobile(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.stubApi('saveSettings', null)");
    const mounted = await cdp.eval("window.__probe.install('/src/components/chat/MessageComposer.vue', '', "
      + JSON.stringify(JSON.stringify({
        convId: "group:composer-mobile",
        mentionMembers: [{ id: "p1", name: "小布" }],
      })) + ")");
    await sleep(600);
    const m = await cdp.eval(`(() => {
      const card = document.querySelector('.gosslan-composer');
      const editor = card ? card.querySelector('[role="textbox"]') : null;
      if (!card || !editor) return { ok: false, hasCard: !!card, hasEditor: !!editor };
      const buttons = [...card.querySelectorAll('button')].filter((b) => b.getClientRects().length > 0);
      const outside = buttons.filter((b) => {
        const r = b.getBoundingClientRect();
        return r.right > innerWidth + 1 || r.left < -1;
      });
      const send = buttons.find((b) => (b.textContent || '').trim() === '发送');
      const er = editor.getBoundingClientRect();
      return {
        ok: true,
        vw: innerWidth,
        scrollW: document.documentElement.scrollWidth,
        buttons: buttons.length,
        outside: outside.map((b) => String(b.getAttribute('aria-label') || b.textContent || '').trim().slice(0, 20)),
        editorW: +er.width.toFixed(1),
        // 2026-11-10 用户：输入框没内容不该有滚动条（移动端双滚动条）。
        editorBarW: editor.offsetWidth - editor.clientWidth,
        editorOverflow: editor.scrollHeight > editor.clientHeight + 1,
        editorGutter: getComputedStyle(editor).scrollbarGutter || "",
        hasSend: !!send,
        hasEmoji: buttons.some((b) => (b.getAttribute('aria-label') || '').includes('表情')),
        // 2026-11-09 用户：输入框上下边距要匀 + 与外框同心。两条都从真矩形现算。
        rowPadTop: +(er.top - editor.parentElement.getBoundingClientRect().top).toFixed(1),
        rowPadBottom: +(editor.parentElement.getBoundingClientRect().bottom - er.bottom).toFixed(1),
        cardRadius: parseFloat(getComputedStyle(card).borderTopLeftRadius) || 0,
        // 每个工具条按钮：圆角 vs「外框圆角 − 它到底边的内距」（同心弧度的定义）。
        buttonRings: buttons.map((b) => {
          const br = b.getBoundingClientRect();
          return {
            r: parseFloat(getComputedStyle(b).borderTopLeftRadius) || 0,
            inset: +(card.getBoundingClientRect().bottom - br.bottom).toFixed(1),
          };
        }),
      };
    })()`);
    check("移动端输入框：工具栏与发送键都在视口内，编辑器没有被挤没",
      mounted && mounted.ok === true && m.ok === true && m.scrollW <= m.vw + 1
        && m.outside.length === 0 && m.editorW >= 100 && m.hasSend === true && m.hasEmoji === true,
      "无横向溢出 + outside=0 + editorW>=100 + 发送/表情在", JSON.stringify({ mounted, ...m }));
    check("移动端输入框：发送键与表情入口都可见（不是被 390 宽挤掉）",
      m.ok === true && m.hasSend === true && m.hasEmoji === true,
      "send + emoji", JSON.stringify({ hasSend: m.hasSend, hasEmoji: m.hasEmoji }));
    check("移动端输入框：单行文字在 44px 行里垂直居中（上下留白差 ≤1px）",
      m.ok === true && Math.abs(m.rowPadTop - m.rowPadBottom) <= 1,
      "|上留白 − 下留白| ≤1", `上=${m.rowPadTop} 下=${m.rowPadBottom}`);
    check("移动端输入框：空内容时编辑器没有滚动条/滚动槽（scrollbar-gutter=auto）",
      m.ok === true && m.editorOverflow === false && m.editorBarW === 0 && m.editorGutter === "auto",
      "overflow=false / barW=0 / gutter=auto",
      JSON.stringify({ barW: m.editorBarW, overflow: m.editorOverflow, gutter: m.editorGutter }));
    const offRings = (m.buttonRings || []).filter(
      (b) => b.r <= 0 || Math.abs(b.r - (m.cardRadius - b.inset)) > 0.5,
    );
    check("移动端输入框：工具条按钮圆角都跟外框同心（外圆角 − 各自到底边内距，±0.5px）",
      m.ok === true && (m.buttonRings || []).length >= 4 && offRings.length === 0,
      "每个按钮 r ≈ cardRadius − inset",
      `card=${m.cardRadius} 不符=${JSON.stringify(offRings)} 全部=${JSON.stringify(m.buttonRings)}`);
    if (SHOT_PATH) {
      // 取证时塞一行真文字并切浅色（用户那张截图就是浅色+一行字）：只影响取证，不动判据。
      await cdp.eval(`(() => {
        const ed = document.querySelector('.gosslan-composer-editor');
        if (!ed) return false;
        ed.focus();
        ed.textContent = '在吗？晚点把图发你';
        ed.dispatchEvent(new InputEvent('input', { bubbles: true }));
        document.documentElement.classList.remove('dark');
        return true;
      })()`);
      await sleep(400);
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-composermobile.png"), Buffer.from(shot.data, "base64"));
      console.log("  📷 移动端输入框取证帧 → " + SHOT_PATH.replace(/\.png$/, "-composermobile.png"));
    }
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 移动端布局判据（--only=layoutstore，§6.84）：跑**真的 store.init()**，再用 CDP 把视口宽度
 * 来回跨过那一档。为什么单独起一段：探针里原先唯一的 is-mobile 是夹具自己 toggle 的假读数
 * （见 H.layoutBoot 的注释），所以"摘掉 mq/resize 监听"这种坏法以前整套探针一条都不红。
 * 三条判据 = 宽档不亮 + 跨窄档三面同时翻 + 退回宽档三面同时翻回（单向通过不算这条链的证据）。
 */
async function runLayoutStore(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1200, height: 900, deviceScaleFactor: 1, mobile: false,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.stubApi('saveSettings', null)");
    const mounted = await cdp.eval("window.__probe.install('/src/components/SettingsPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, isolated: true })) + ")");
    await sleep(400);
    const boot = await cdp.eval("window.__probe.layoutBoot()");
    await sleep(500);
    const wide = await cdp.eval("window.__probe.layoutRead()");
    // 查询串的**形状**在这里判（^(max-width: NNNpx)$），值不许抄：那个数与 Tailwind md 的补数关系
    // 已经由 src/utils/platform.test.ts 从库的默认主题现算对账，探针再抄一份就成了第二个载体。
    const shape = typeof wide.q === "string" && /^\(max-width: \d+px\)$/.test(wide.q);
    check("宽档：store 判否且 <html> 上没有 is-mobile —— 这个类只许由真的 applyIsMobile 写",
      mounted && mounted.ok === true && boot && boot.ok === true && shape
        && wide.mq === false && wide.store === false && wide.cls === false,
      "查询形状 + mq/store/cls 三个 false", JSON.stringify({ mounted, boot, wide }));

    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
    });
    await sleep(800);
    const narrow = await cdp.eval("window.__probe.layoutRead()");
    check("跨到 390：查询、store、<html> 类三面各自翻面（是真监听器在驱动，不是夹具自己写）",
      narrow.vw === 390 && narrow.mq === true && narrow.store === true && narrow.cls === true,
      "三个 true", JSON.stringify(narrow));

    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 1200, height: 900, deviceScaleFactor: 1, mobile: false,
    });
    await sleep(800);
    const back = await cdp.eval("window.__probe.layoutRead()");
    check("退回 1200：三面同时翻回 false（只验单向会把“摘掉反向那半”读成绿）",
      back.vw === 1200 && back.mq === false && back.store === false && back.cls === false,
      "三个 false", JSON.stringify(back));

    console.log("  · 布局链自然读数：q=" + wide.q + " 宽档 vw=" + wide.vw
      + " 窄档 vw=" + narrow.vw + " init 抛出的那一步（浏览器里没有 Tauri，属预期）="
      + (back.err || boot.err || "(没抛)"));
    // 归因读数（不是判据）：这条链上 mq change 与 resize 是**两个都能驱动同一格**的机制（§6.77 那一族）。
    // 2026-10-19 实测四发：只摘 mq ⇒ 3/3 绿；只摘 resize ⇒ 3/3 绿；两条都摘 ⇒ 2/3，红的正是跨窄档那一格。
    // ⚠️ 同一次两摘还读出另一件事：**反向那一格只在正向真的亮过之后才有牙** —— 两条监听都没了的时候，
    //    类压根没挂上过，"退回宽档后类为 false"于是也成立。它防的是"只会变窄不会变宽"，不是"这条链没接"；
    //    后者由跨档那一格负责。两格各管一件事，别把反向那格读成正向的证据。
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 网络页那几张卡的宽度在「重新连接实时事件」前后是否变化（用户 2026-10-23：
 * 点完中间那块会缩起来，之后不再变宽）。
 *
 * 直接挂 NetworkSection、不经过设置外壳：卡片宽度是内容驱动还是布局驱动，在这一层就能分开 ——
 * 这里不变而真机变 ⇒ 问题在外壳列宽；这里就变 ⇒ 在组件内部。
 */
async function runNetCard(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", { width: 900, height: 760, deviceScaleFactor: 1, mobile: false });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    // 挂**真实设置面板**（桌面分支是 max-w-xl 的 BaseModal，所有分区竖着排）——
    // 只挂 NetworkSection 量到的是"页面全宽"，盖住了外壳把宽度收窄这件事。
    const mounted = await cdp.eval("window.__probe.install('/src/components/SettingsPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, isolated: true })) + ")");
    await sleep(900);
    const read = () => cdp.eval(`(() => {
      const card = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.getClientRects().length > 0 && el.textContent.includes('实时事件链路'));
      if (!card) return null;
      const modal = card.closest('[class*="max-w-xl"]') || card.closest('[role="dialog"]');
      const btn = [...card.querySelectorAll('button')]
        .find((b) => (b.textContent || '').includes('重新连接'));
      const w = (el) => (el ? +el.getBoundingClientRect().width.toFixed(1) : null);
      return { card: w(card), btn: w(btn), modal: w(modal) };
    })()`);
    const before = await read();
    // 点下去之后逐帧采 1.5s：用户描述的是"一下就缩起来"，瞬态只有采样抓得到。
    const clicked = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').includes('重新连接实时事件'));
      if (!b) return false;
      window.__netCardSamples = [];
      const first = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.textContent.includes('实时事件链路'));
      let k = 0;
      const tick = () => {
        if (first) {
          const r = first.getBoundingClientRect();
          window.__netCardSamples.push({ w: +r.width.toFixed(1), h: +r.height.toFixed(1),
            t: (first.textContent || '').replace(/\s+/g, ' ').slice(0, 28) });
        } else window.__netCardSamples.push(null);
        if (++k < 30) setTimeout(tick, 50);
      };
      b.click();
      tick();
      return true;
    })()`);
    await sleep(1_800);
    const samples = await cdp.eval("window.__netCardSamples || []");
    const after = await read();
    const finite = samples.filter((n) => n && typeof n.w === "number");
    const minW = finite.length ? Math.min(...finite.map((n) => n.w)) : null;
    const maxW = finite.length ? Math.max(...finite.map((n) => n.w)) : null;
    const minH = finite.length ? Math.min(...finite.map((n) => n.h)) : null;
    const maxH = finite.length ? Math.max(...finite.map((n) => n.h)) : null;
    console.log("  ℹ 设置外壳里卡片宽度 → " + JSON.stringify({
      before, after, frames: finite.length, minW, maxW, minH, maxH, samples: finite.slice(0, 6),
    }));
    check("网络页（真实设置面板）：点「重新连接实时事件」前后卡片宽度不变",
      !!mounted && mounted.ok === true && clicked === true && !!before && !!after
        && Math.abs(after.card - before.card) <= 1
        && minW !== null && Math.abs(maxW - minW) <= 1
        && minH !== null && Math.abs(maxH - minH) <= 1,
      "点前后卡片宽/高相差都 <= 1px，且 1.5s 逐帧采样无缩窄/长高",
      JSON.stringify({ before, after, minW, maxW }));

    // ── 同一个动作，**手机宽度**那一档（用户截图就是二级页 360~390 宽）──
    // 移动端走 MobilePageFrame + 二级页容器，与桌面桌面板是两条不同的 DOM 路径。
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
    });
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    const m2 = await cdp.eval("window.__probe.install('/src/components/SettingsPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, isolated: true })) + ")");
    await sleep(700);
    await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').trim() === '网络');
      if (b) b.click();
    })()`);
    await sleep(900);
    const rows = () => cdp.eval(`(() => {
      const card = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.getClientRects().length > 0 && el.textContent.includes('实时事件链路'));
      if (!card) return null;
      return [...card.querySelectorAll('[class*="flex-wrap"]')].map((r) => {
        const b = r.getBoundingClientRect();
        return { h: +b.height.toFixed(1), t: (r.textContent || '').replace(/\s+/g, ' ').slice(0, 34) };
      });
    })()`);
    const rowsBefore = await rows();
    const beforeM = await read();
    const clickedM = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').includes('重新连接实时事件'));
      if (!b) return false;
      window.__netCardSamples = [];
      const first = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.textContent.includes('实时事件链路'));
      let k = 0;
      const tick = () => {
        if (first) {
          const r = first.getBoundingClientRect();
          window.__netCardSamples.push({ w: +r.width.toFixed(1), h: +r.height.toFixed(1),
            t: (first.textContent || '').replace(/\s+/g, ' ').slice(0, 28) });
        } else window.__netCardSamples.push(null);
        if (++k < 30) setTimeout(tick, 50);
      };
      b.click();
      tick();
      return true;
    })()`);
    await sleep(1_800);
    const samplesM = await cdp.eval("window.__netCardSamples || []");
    const afterM = await read();
    const rowsAfter = await rows();
    console.log("  ℹ 手机二级页各行高度 → " + JSON.stringify({ rowsBefore, rowsAfter }));
    const finiteM = samplesM.filter((n) => n && typeof n.w === "number");
    const minM = finiteM.length ? Math.min(...finiteM.map((n) => n.w)) : null;
    const maxM = finiteM.length ? Math.max(...finiteM.map((n) => n.w)) : null;
    const minHM = finiteM.length ? Math.min(...finiteM.map((n) => n.h)) : null;
    const maxHM = finiteM.length ? Math.max(...finiteM.map((n) => n.h)) : null;
    console.log("  ℹ 手机二级页卡片宽度 → " + JSON.stringify({
      before: beforeM, after: afterM, frames: finiteM.length, minM, maxM, minHM, maxHM, samples: finiteM.slice(0, 6),
    }));
    check("网络页（手机二级页）：点「重新连接实时事件」前后卡片宽度不变",
      !!m2 && m2.ok === true && clickedM === true && !!beforeM && !!afterM
        && Math.abs(afterM.card - beforeM.card) <= 1
        && minM !== null && Math.abs(maxM - minM) <= 1
        && minHM !== null && Math.abs(maxHM - minHM) <= 1,
      "点前后卡片宽/高相差都 <= 1px，且 1.5s 逐帧采样无缩窄/长高",
      JSON.stringify({ before: beforeM, after: afterM, minM, maxM }));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 阶段 6 的分档证据段（2026-11-06）：搜索命中 mark 换 token 后的对比度、
 * 以及 C2 焦点框的来源复核（应当只有文本控件的 1px inset，不是 2px 外圈方框）。
 * 360×640 / 390×844 / 430×932 + 768×800（布局组件档）+ 1280×800，亮/暗各一次。
 */
async function runStage6Mobile(cdp, url) {
  const sizes = [
    { w: 360, h: 640, tag: "360x640" },
    { w: 390, h: 844, tag: "390x844" },
    { w: 430, h: 932, tag: "430x932" },
    { w: 768, h: 800, tag: "768x800" },
    { w: 1280, h: 800, tag: "1280x800" },
  ];
  const dir = path.join(ROOT, "docs", "notes", "unslop-review-2026-11-06", "shots", "stage6");
  fs.mkdirSync(dir, { recursive: true });
  const shot = async (name) => {
    const img = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(dir, `${name}.png`), Buffer.from(img.data, "base64"));
  };
  const GROUP = {
    conv_id: "conv-probe", name: "探针会话", kind: "private", avatar: null,
    total: 3, latest_ts: 1,
    messages: [
      { msg_id: "m0", sender_id: "p1", sender_name: "小布", kind: "text", content: "命中 0", ts: 1 },
      { msg_id: "m1", sender_id: "p1", sender_name: "小布", kind: "todo",
        content: '{"title":"命中 待办","assignees":["p1"],"status":"todo","priority":"high"}', ts: 2 },
      { msg_id: "m2", sender_id: "p1", sender_name: "小布", kind: "image",
        content: '{"name":"命中.png","path":"/x/命中.png","size":2048,"sha256":"ab12"}', ts: 3 },
    ],
  };
  const META = `(() => {
    const parse = (s) => {
      const v = (s.match(/-?\\d*\\.?\\d+/g) || []).map(Number);
      let [r = 0, g = 0, b = 0, a = 1] = v;
      if (s.includes('color(srgb')) { r *= 255; g *= 255; b *= 255; }
      return { r, g, b, a };
    };
    const opaqueBg = (el) => {
      let cur = el;
      while (cur) {
        const c = parse(getComputedStyle(cur).backgroundColor);
        if (c.a > 0.99) return c;
        cur = cur.parentElement;
      }
      return { r: 255, g: 255, b: 255, a: 1 };
    };
    const over = (fg, bg) => ({ r: fg.r * fg.a + bg.r * (1 - fg.a),
      g: fg.g * fg.a + bg.g * (1 - fg.a), b: fg.b * fg.a + bg.b * (1 - fg.a) });
    const lum = (c) => {
      const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
      return 0.2126 * f(c.r) + 0.7152 * f(c.g) + 0.0722 * f(c.b);
    };
    const ratio = (a, b) => {
      const la = lum(a), lb = lum(b);
      return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
    };
    const marks = [...document.querySelectorAll('mark')];
    const first = marks[0] || null;
    const base = first ? opaqueBg(first.parentElement || first) : { r: 255, g: 255, b: 255, a: 1 };
    const markBg = first ? over(parse(getComputedStyle(first).backgroundColor), base) : base;
    const markFg = first ? parse(getComputedStyle(first).color) : { r: 0, g: 0, b: 0, a: 1 };
    const input = document.querySelector('input');
    if (input) input.focus();
    const inputCs = input ? getComputedStyle(input) : null;
    const dlg = document.querySelector('[role="dialog"]');
    const dr = dlg ? dlg.getBoundingClientRect() : null;
    return { marks: marks.length,
      markBg: markBg && [markBg.r, markBg.g, markBg.b].map((n) => Math.round(n)),
      markFg: markFg && [markFg.r, markFg.g, markFg.b].map((n) => Math.round(n)),
      contrast: +ratio(markFg, markBg).toFixed(2),
      outlineWidth: inputCs ? inputCs.outlineWidth : '',
      outlineStyle: inputCs ? inputCs.outlineStyle : '',
      outlineColor: inputCs ? inputCs.outlineColor : '',
      boxShadow: inputCs ? inputCs.boxShadow : '',
      overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      dialog: dr ? { l: Math.round(dr.left), r: Math.round(dr.right), t: Math.round(dr.top), b: Math.round(dr.bottom),
        vw: innerWidth, vh: innerHeight } : null };
  })()`;
  const rows = [];
  for (const s of sizes) {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: s.w, height: s.h, deviceScaleFactor: s.w <= 430 ? 2 : 1, mobile: s.w < 768,
    });
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`window.__probe.install('/src/components/search/ChatSearchDialog.vue', '', ${
      JSON.stringify(JSON.stringify({ initialKeyword: "初" }))})`);
    await cdp.eval(`window.__probe.stubApi('searchChatHistory', ${JSON.stringify([GROUP])})`);
    await cdp.eval("window.__probe.setOpen(true)");
    for (let i = 0; i < 80; i += 1) {
      const ok = await cdp.eval(`(() => {
        const d = document.querySelector('[role="dialog"]');
        if (!d) return false;
        const b = d.getBoundingClientRect();
        return b.left >= -1 && b.right <= innerWidth + 1 && b.top >= -1 && b.bottom <= innerHeight + 1;
      })()`);
      if (ok) break;
      await sleep(50);
    }
    await cdp.eval(`window.__probe.typeKeyword('命中')`);
    await sleep(500);
    const light = await cdp.eval(META);
    await shot(`search-${s.tag}-light`);
    await cdp.eval("document.documentElement.classList.add('dark')");
    await sleep(300);
    const dark = await cdp.eval(META);
    await shot(`search-${s.tag}-dark`);
    await cdp.eval("document.documentElement.classList.remove('dark')");
    const inView = (m) => !!m.dialog && m.dialog.l >= -1 && m.dialog.r <= m.dialog.vw + 1
      && m.dialog.t >= -1 && m.dialog.b <= m.dialog.vh + 1;
    check(`stage6·${s.tag}：命中 mark 对比度亮 ≥4.5 / 暗 ≥4.5、无横向溢出、弹窗不越视口`,
      light.marks >= 3 && dark.marks >= 3 && light.contrast >= 4.5 && dark.contrast >= 4.5
        && light.overflowX <= 0 && dark.overflowX <= 0 && inView(light) && inView(dark),
      "marks≥3 / contrast(亮/暗)≥4.5 / overflowX≤0 / dialog 在视口内",
      JSON.stringify({ light, dark }));
    const outlineInvisible = (m) => {
      if (m.outlineStyle === "none") return true;
      const nums = (m.outlineColor.match(/[\d.]+/g) || []).map(Number);
      const alpha = nums.length >= 4 ? nums[3] : 1;
      return m.outlineWidth === "0px" || alpha <= 0.01;
    };
    check(`stage6·${s.tag}：C2 焦点提示来自文本控件的 1px inset（无 2px 可见外框）`,
      outlineInvisible(light) && light.boxShadow.includes("inset"),
      "outline 不可见（style=none 或 alpha≈0）/ boxShadow 含 inset",
      JSON.stringify({ outlineWidth: light.outlineWidth, outlineStyle: light.outlineStyle,
        outlineColor: light.outlineColor, boxShadow: light.boxShadow }));
    rows.push({ size: s.tag, light, dark });
  }
  console.log("  · stage6 分档读数：" + JSON.stringify(rows.map((r) => ({
    size: r.size, marks: r.light.marks, contrastLight: r.light.contrast, contrastDark: r.dark.contrast,
    overflow: r.light.overflowX, focus: r.light.outlineWidth + "/" + (r.light.boxShadow.includes("inset") ? "inset" : "none"),
  }))));
}

/**
 * --only=recoverynotice：自愈提示条不许盖住可操作内容（用户 2026-11-06 截图：
 * 顶部横幅压在左栏搜索行与右栏首行上，且自身顶部露出半截被裁的字）。
 *
 * 分档：1280×800 / 1024×700 / 768×800 / 640×480（矮窗重点）/ 390×844（移动端）。
 * 每条判据都按矩形算：提示卡片 × (列表头 / 聊天头 / 全部可操作元素) 的交叠面积，
 * 以及卡片自身的 scrollHeight-clientHeight（被自身容器裁切 = >0）。
 */
async function runRecoveryNotice(cdp, url) {
  const sizes = [
    { w: 1280, h: 800, tag: "1280x800", mobile: false },
    { w: 1024, h: 700, tag: "1024x700", mobile: false },
    { w: 768, h: 800, tag: "768x800", mobile: false },
    { w: 640, h: 480, tag: "640x480", mobile: false },
    { w: 390, h: 844, tag: "390x844", mobile: true },
  ];
  const dir = path.join(ROOT, "docs", "notes", "unslop-review-2026-11-06", "shots", "recoverynotice");
  fs.mkdirSync(dir, { recursive: true });
  const shot = async (name) => {
    const img = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(dir, `${name}.png`), Buffer.from(img.data, "base64"));
  };
  const META = `(() => {
    const card = document.querySelector('.recovery-card');
    const notice = document.querySelector('.recovery-notice');
    const shell = document.querySelector('#probe-host > div');
    if (!card || !notice || !shell) return { ok: false, why: '卡片/横幅/壳 缺失' };
    const rect = (el) => {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom),
        w: Math.round(r.width), h: Math.round(r.height) };
    };
    const area = (a, b) => {
      if (!a || !b) return 0;
      const w = Math.max(0, Math.min(a.r, b.r) - Math.max(a.l, b.l));
      const h = Math.max(0, Math.min(a.b, b.b) - Math.max(a.t, b.t));
      return w * h;
    };
    const cr = rect(card);
    // 列表列不要用 querySelector('aside')：NavRail 也是 aside，会抓错。
    // 用「搜索输入框所在的 aside」定位真实列表列；再退回搜索框本身。
    const searchEl = shell.querySelector('input[placeholder]');
    const listCol = searchEl ? searchEl.closest('aside') : null;
    const listHeader = listCol ? listCol.firstElementChild : null;
    const searchRect = rect(searchEl);
    const main = shell.querySelector('main');
    const cw = main ? main.firstElementChild : null;
    const chatTop = cw ? (cw.firstElementChild || cw) : null;
    // 标题栏（caption / 移动端搜索条）：旧定位 top:16px 正好横切这一行，
    // 截图里"顶部露出被裁掉的半行小字"就是它的上半截。用它量化"半行字"。
    const titleBar = shell.querySelector('[data-caption]');
    const tr = rect(titleBar);
    const lr = rect(listHeader && listHeader.getBoundingClientRect().width > 0 ? listHeader : searchEl);
    const chr = rect(chatTop);
    const operables = [...shell.querySelectorAll(
      'button, input, a[href], [role="button"], [role="tab"], [tabindex]:not([tabindex="-1"])')]
      .filter((el) => !notice.contains(el) && el.getBoundingClientRect().width > 0);
    let maxOp = 0, maxOpEl = '';
    for (const el of operables) {
      const a = area(cr, rect(el));
      if (a > maxOp) {
        maxOp = a;
        maxOpEl = el.tagName.toLowerCase()
          + (el.getAttribute('aria-label') ? '[' + el.getAttribute('aria-label') + ']' : '')
          + '.' + String(el.className || '').split(' ').slice(0, 2).join('.');
      }
    }
    const sr = shell.getBoundingClientRect();
    return {
      ok: true,
      card: cr, listTop: lr, chatTop: chr, search: searchRect, titleBar: tr,
      searchVisible: !!searchRect && searchRect.w > 0 && searchRect.h > 0,
      titleVisible: !!tr && tr.w > 0 && tr.h > 0,
      overlapList: area(cr, lr), overlapChat: area(cr, chr),
      overlapTitle: area(cr, tr), maxOp, maxOpEl,
      clipCard: card.scrollHeight - card.clientHeight,
      clipBand: notice.scrollHeight - notice.clientHeight,
      inViewport: cr.t >= -1 && cr.b <= innerHeight + 1 && cr.l >= -1 && cr.r <= innerWidth + 1,
      overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
      shellBottom: Math.round(sr.bottom), shellH: Math.round(sr.height), vh: innerHeight,
      position: getComputedStyle(notice).position,
    };
  })()`;
  const rows = [];
  for (const s of sizes) {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: s.w, height: s.h, deviceScaleFactor: s.mobile ? 2 : 1, mobile: s.mobile,
    });
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    const mount = await cdp.eval(`(async () => {
      window.__TAURI_INTERNALS__ = window.__TAURI_INTERNALS__ || {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      window.__TAURI_EVENT_PLUGIN_INTERNALS__ = window.__TAURI_EVENT_PLUGIN_INTERNALS__ || { unregisterListener: () => {} };
      await window.__probe.install('/src/layouts/ResponsiveLayout.vue', '', ${
        JSON.stringify(JSON.stringify({ router: true, hostHeight: `${s.h}px` }))});
      const vueUrl = performance.getEntriesByType('resource').map((e) => e.name || '')
        .find((u) => u.includes('/node_modules/.vite/deps/vue.js?v='));
      const Vue = await import(vueUrl);
      const mod = await import('/src/components/RecoveryNotice.vue');
      const shell = document.querySelector('#probe-host > div');
      if (!shell) return { ok: false };
      const host = document.createElement('div');
      host.id = 'notice-host';
      // 和真实插槽同一位置：TitleBar（仅桌面，带 data-caption）之后；移动端无 TitleBar，等价于 safe-top 之后。
      const safe = shell.querySelector('.safe-top');
      const title = shell.querySelector('[data-caption]');
      const anchor = title || safe;
      if (anchor) anchor.after(host);
      else shell.insertBefore(host, shell.firstChild);
      const app = Vue.createApp(mod.default, { kind: 'recovered', mobile: ${s.mobile} });
      app.mount(host);
      window.__noticeApp = app;
      return { ok: true, position: getComputedStyle(document.querySelector('.recovery-notice')).position };
    })()`);
    await sleep(500);
    const r = await cdp.eval(META);
    await shot(`recovery-${s.tag}-light`);
    await cdp.eval("document.documentElement.classList.add('dark')");
    await sleep(300);
    await shot(`recovery-${s.tag}-dark`);
    const darkOverflow = await cdp.eval("document.documentElement.scrollWidth - document.documentElement.clientWidth");
    await cdp.eval("document.documentElement.classList.remove('dark')");
    check(`自愈条·${s.tag}：不盖住列表头/聊天头/标题栏（矩形交叠面积 = 0，且内容真的在场）`,
      r.ok && r.searchVisible && r.overlapList === 0 && r.overlapChat === 0
        && (!r.titleVisible || r.overlapTitle === 0),
      "searchVisible / overlapList=0 / overlapChat=0 / (标题栏存在时)overlapTitle=0",
      JSON.stringify({ search: r.search, card: r.card, listTop: r.listTop, chatTop: r.chatTop,
        titleBar: r.titleBar, titleVisible: r.titleVisible, overlapList: r.overlapList,
        overlapChat: r.overlapChat, overlapTitle: r.overlapTitle }));
    check(`自愈条·${s.tag}：不和任何可操作元素交叠（按钮/输入/链接/可聚焦）`,
      r.ok && r.maxOp === 0, "maxOp=0", JSON.stringify({ maxOp: r.maxOp, maxOpEl: r.maxOpEl }));
    check(`自愈条·${s.tag}：自身不被容切（scrollHeight-clientHeight ≤ 0）且整卡在视口内`,
      r.ok && r.clipCard <= 0 && r.clipBand <= 0 && r.inViewport && darkOverflow <= 0,
      "clip=0 / inViewport / 无横向溢出",
      JSON.stringify({ clipCard: r.clipCard, clipBand: r.clipBand, inViewport: r.inViewport,
        overflowX: r.overflowX, darkOverflow, shellH: r.shellH, vh: r.vh, shellBottom: r.shellBottom }));
    rows.push({ size: s.tag, mount, r });
  }
  console.log("  · 自愈条分档读数：" + JSON.stringify(rows.map((x) => ({
    size: x.size, position: x.mount.position,
    card: x.r.card && [x.r.card.l, x.r.card.t, x.r.card.r, x.r.card.b],
    listTop: x.r.listTop && [x.r.listTop.l, x.r.listTop.t, x.r.listTop.r, x.r.listTop.b],
    chatTop: x.r.chatTop && [x.r.chatTop.l, x.r.chatTop.t, x.r.chatTop.r, x.r.chatTop.b],
    overlapList: x.r.overlapList, overlapChat: x.r.overlapChat, overlapTitle: x.r.overlapTitle,
    maxOp: x.r.maxOp,
    clipCard: x.r.clipCard, clipBand: x.r.clipBand,
  }))));
}

/**
 * 阶段 4 的移动端分档补测（2026-11-06 追加约束）：
 * 群文件面板（B6 悬空「·」）与独立日志窗（A6 对比度 / B1 标题 / B2 开关）
 * 必须在 360×640 / 390×844 / 430×932 三档 + 768×800（布局组件档）亮/暗各出一次读数。
 * 桌面 1280×800 与 1440 的帧已在阶段 4 落过，不重复。
 */
async function runStage4Mobile(cdp, url) {
  const sizes = [
    { w: 360, h: 640, tag: "360x640" },
    { w: 390, h: 844, tag: "390x844" },
    { w: 430, h: 932, tag: "430x932" },
    { w: 768, h: 800, tag: "768x800" },
  ];
  const dir = path.join(ROOT, "docs", "notes", "unslop-review-2026-11-06", "shots", "stage4");
  fs.mkdirSync(dir, { recursive: true });
  const shot = async (name) => {
    const img = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(dir, `${name}.png`), Buffer.from(img.data, "base64"));
  };
  const LOGS = Array.from({ length: 200 }, (_, i) => ({
    ts: 1_700_000_000_000 + i * 1000,
    level: i % 31 === 0 ? "error" : i % 17 === 0 ? "warn" : "info",
    target: `probe-${i}`,
    message: `日志行 ${String(i).padStart(3, "0")}`,
  }));
  for (const s of sizes) {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: s.w, height: s.h, deviceScaleFactor: s.w <= 430 ? 2 : 1, mobile: s.w < 768,
    });
    // 1) 群文件面板：B6 的元信息行（created_at=0 ⇒ 时间缺失）
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.groupFilesBus()");
    const mounted = await cdp.eval("window.__probe.install('/src/components/GroupFilesPanel.vue', '', '')");
    await cdp.eval("window.__probe.setGroup('g1')");
    await cdp.eval("window.__probe.setOpen(true)");
    await sleep(900);
    const files = await cdp.eval(`(() => {
      const dlg = document.querySelector('[role="dialog"]');
      const row = dlg ? dlg.querySelector('[title$=".bin"]') : null;
      const meta = row && row.parentElement ? row.parentElement.children[1] : null;
      const metaText = meta ? meta.innerText.replace(/\\s+/g, ' ').trim() : '';
      return { dialog: !!dlg, metaText,
        dangling: /·\\s*$/.test(metaText) || /·\\s*·/.test(metaText),
        overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth };
    })()`);
    await shot(`files-${s.tag}-light`);
    await cdp.eval("document.documentElement.classList.add('dark')");
    await sleep(250);
    await shot(`files-${s.tag}-dark`);
    check(`stage4·${s.tag}：群文件元信息时间缺失时无悬空「·」、不横向溢出`,
      mounted && mounted.ok === true && files.dialog === true && files.dangling === false
        && files.metaText.includes("KB") && files.overflowX <= 0,
      "meta 含 KB / 无悬空「·」 / overflowX≤0", JSON.stringify(files));

    // 2) 独立日志窗：同一份 standalone 组件 + 200 行夹具
    await cdp.eval("window.__probe.reset()");
    await cdp.eval(`window.__probe.stubApi('getLogs', ${JSON.stringify(LOGS)})`);
    await cdp.eval(`(() => {
      const pin = (h) => {
        Object.defineProperty(document, 'hidden', { configurable: true, get: () => h });
        Object.defineProperty(document, 'visibilityState', { configurable: true, get: () => (h ? 'hidden' : 'visible') });
      };
      pin(false);
      return true;
    })()`);
    await cdp.eval("window.__probe.install('/src/components/LogViewer.vue', '', "
      + JSON.stringify(JSON.stringify({ standalone: true })) + ")");
    await sleep(900);
    const logs = await cdp.eval(`(() => {
      const host = document.querySelector('#probe-host');
      const text = host ? host.innerText.replace(/\\s+/g, ' ').trim() : '';
      return { text: text.slice(0, 120), rows: document.querySelectorAll('[data-log-row]').length,
        overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth };
    })()`);
    await shot(`logs-${s.tag}-dark`);
    await cdp.eval("document.documentElement.classList.remove('dark')");
    await sleep(250);
    await shot(`logs-${s.tag}-light`);
    check(`stage4·${s.tag}：独立日志窗工具条不重复功能名、不横向溢出`,
      logs.overflowX <= 0 && logs.text.includes("200"),
      "工具条含条数 200 / overflowX≤0", JSON.stringify(logs));
    console.log(`  · stage4·${s.tag} 读数：`
      + JSON.stringify({ metaText: files.metaText, filesOverflowX: files.overflowX,
        logsText: logs.text.slice(0, 40), logsOverflowX: logs.overflowX }));
  }
}

/**
 * 阶段 5 的分档证据段（2026-11-06）：骨架静态化 + 手机端色雾降档。
 *
 * 为什么单开一段：`scrollswitch` 只跑 1200×800 一档，而移动端结论必须按
 * 360×640 / 390×844 / 430×932 三档 + 768×800（md 边界）+ 1280×800 分开给，亮/暗各一次。
 * 600×800 是**真正命中**「≤767 色雾冻结」这条新分支的补点：三档手机在 JS 侧
 * （`resolveAmbientMode` 的 narrow <480）本来就已经是 static，改动前后读数相同；
 * 不补 600 这一档，"改了这条分支"就永远没有读数。
 */
async function runStage5Mobile(cdp, url) {
  const sizes = [
    { w: 360, h: 640, tag: "360x640" },
    { w: 390, h: 844, tag: "390x844" },
    { w: 430, h: 932, tag: "430x932" },
    { w: 600, h: 800, tag: "600x800" },
    { w: 768, h: 800, tag: "768x800" },
    { w: 1280, h: 800, tag: "1280x800" },
  ];
  const dir = path.join(ROOT, "docs", "notes", "unslop-review-2026-11-06", "shots", "stage5");
  fs.mkdirSync(dir, { recursive: true });
  const shot = async (name) => {
    const img = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(dir, `${name}.png`), Buffer.from(img.data, "base64"));
  };
  const rows = [];
  for (const s of sizes) {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: s.w, height: s.h, deviceScaleFactor: s.w <= 430 ? 2 : 1, mobile: s.w < 768,
    });
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_500);
    await cdp.eval(PAGE_FIXTURE);
    // 读数只测"非低端机 + 非 reduce"这一条主路径：低端机判定（cores/memory/UA）是
    // 跑测机器的属性、不是产品行为，先显式压成 no-preference，再用产品同一入口
    // `applyAmbientMode` 写模式（<480 = JS narrow→static；≥480 = drift，交给 CSS 判）。
    await cdp.send("Emulation.setEmulatedMedia", {
      features: [{ name: "prefers-reduced-motion", value: "no-preference" }],
    });
    await cdp.eval(`(async () => {
      const A = await import('/src/utils/ambient.ts');
      if (!document.querySelector('.ambient')) A.installAmbient();
      A.applyAmbientMode(window.innerWidth < 480 ? 'static' : 'drift');
      return true;
    })()`);
    await sleep(400);
    const ambient = () => cdp.eval(`(() => {
      const blobs = [...document.querySelectorAll('.ambient-blob')].map((b) => {
        const st = getComputedStyle(b);
        return { id: (b.className.match(/ambient-blob--([a-d])/) || [])[1] || '',
          display: st.display, anim: st.animationName, dur: st.animationDuration };
      });
      return { mode: document.documentElement.dataset.ambient || '',
        reduced: matchMedia('(prefers-reduced-motion: reduce)').matches,
        media767: matchMedia('(max-width: 767px)').matches,
        blobs, overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth };
    })()`);
    const light = await ambient();
    await shot(`ambient-${s.tag}-light`);
    await cdp.eval("document.documentElement.classList.add('dark')");
    await sleep(250);
    const dark = await ambient();
    await shot(`ambient-${s.tag}-dark`);

    // 骨架：activeConv 有值且 messages 还是 undefined ⇒ 真实加载态（不造替身状态）。
    await cdp.eval(`(() => {
      window.__TAURI_INTERNALS__ = {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      if (!window.__TAURI_EVENT_PLUGIN_INTERNALS__) {
        window.__TAURI_EVENT_PLUGIN_INTERNALS__ = { unregisterListener: () => {} };
      }
      return true;
    })()`);
    const mounted = await cdp.eval("window.__probe.install('/src/components/ChatWindow.vue', '', "
      + JSON.stringify(JSON.stringify({ hostHeight: `${s.h}px` })) + ")");
    await cdp.eval("window.__probe.seedDevice('dev-me')");
    const skel = await cdp.eval(`(async () => {
      const { useChatStore } = await import('/src/stores/useChatStore.ts');
      const chat = useChatStore();
      delete chat.messages['group:skel'];
      chat.activeConv = 'group:skel';
      await new Promise((r) => setTimeout(r, 800));
      const box = document.querySelector('[data-msg-skeleton]');
      if (!box) return { ok: false };
      const kids = [...box.children];
      const anim = (n) => getComputedStyle(n).animationName;
      const r = box.getBoundingClientRect();
      return { ok: true, kids: kids.length, kidAnim: [...new Set(kids.map(anim))],
        boxAnim: anim(box), boxIter: getComputedStyle(box).animationIterationCount,
        pulse: document.querySelectorAll('.animate-pulse').length,
        overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
        rect: { t: +r.top.toFixed(1), b: +r.bottom.toFixed(1), h: +r.height.toFixed(1) },
        viewportH: window.innerHeight };
    })()`);
    await shot(`skeleton-${s.tag}-dark`);
    await cdp.eval("document.documentElement.classList.remove('dark')");
    await sleep(250);
    await shot(`skeleton-${s.tag}-light`);

    const byId = (r, id) => (r && r.blobs || []).find((b) => b.id === id) || {};
    const frozen = s.w <= 767;
    const narrow = s.w < 480;
    // ≤767：A/B 在、C/D 隐藏、A/B 冻结（三档手机是 JS narrow 先冻，600 才是这条 CSS 分支）；
    // >767：四团都在，A/B/C 漂移、D 静态底洗。
    const ambientOk = frozen
      ? ["a", "b"].every((id) => byId(light, id).display !== "none")
        && ["c", "d"].every((id) => byId(light, id).display === "none")
        && ["a", "b"].every((id) => byId(light, id).anim === "none")
      : ["a", "b", "c", "d"].every((id) => byId(light, id).display !== "none")
        && ["a", "b", "c"].every((id) => byId(light, id).anim !== "none")
        && byId(light, "d").anim === "none";
    // 归因：<480 由 JS narrow 判成 static；480–767 的 `mode` 仍是 full，冻结只可能来自
    // 本阶段的 CSS 分支（`@media (max-width:767px)`）—— 这一句防止"改了但没量到"。
    const attributionOk = s.w < 480 ? light.mode === "static" : light.mode !== "static";
    check(`stage5·${s.tag}：色雾 ${frozen ? "≤767 只留 A/B 且冻结" : ">767 四团、A/B/C 漂移"}、无横向溢出、冻结归因可分辨`,
      !!light && !!dark && ambientOk && attributionOk && light.overflowX <= 0,
      frozen
        ? "ab 可见 / cd 隐藏 / ab animationName=none / overflowX≤0"
        : "abcd 可见 / abc 有 animationName / d=none / overflowX≤0",
      JSON.stringify({ light, dark, narrow }));
    const skelOk = !!skel && skel.ok === true
      && skel.kids >= 3 && skel.kidAnim.length === 1 && skel.kidAnim[0] === "none"
      && skel.boxAnim === "gosslan-skeleton-in" && skel.boxIter === "1"
      && skel.pulse === 0 && skel.overflowX <= 0
      && skel.rect.t >= 0 && skel.rect.b <= skel.viewportH + 1;
    check(`stage5·${s.tag}：骨架静态（子块无动画、容器只淡入一次）、无脉冲、无横向溢出、不越视口`,
      skelOk, "kids≥3 / kidAnim=[none] / boxAnim=gosslan-skeleton-in×1 / pulse=0 / overflowX≤0 / 0≤rect≤viewportH",
      JSON.stringify({ mounted: mounted && mounted.ok, skel }));
    rows.push({ size: s.tag, frozen, narrow, light, dark, skel });
  }
  console.log("  · stage5 分档读数：" + JSON.stringify(rows.map((r) => ({
    size: r.size,
    ambientMode: r.light && r.light.mode,
    abAnim: [r.light && r.light.blobs[0] && r.light.blobs[0].anim,
      r.light && r.light.blobs[1] && r.light.blobs[1].anim],
    skelKids: r.skel && r.skel.kids, skelAnim: r.skel && r.skel.boxAnim,
    skelPulse: r.skel && r.skel.pulse, overflow: r.skel && r.skel.overflowX,
  }))));
}

/**
 * 背景动效「能力闸」两态读数（`--only=ambientcap`，2026-11-08 用户要求）。
 *
 * 要证明的不是"代码里有 disabled 这几个字"，而是**两种机器状态下设置页长什么样**：
 *  ① 能力可用：两档都能点，默认显示「缓慢流动」；
 *  ② 能力不支持（系统关掉「透明效果」）：两档都点不了、显示为关、下面一行换成原因。
 *
 * 为什么用两次导航而不是切换媒体后原地读：能力在 store 建仓时读一次（运行期只有媒体查询那一半
 * 有 change 事件），`SettingsPanel` 是隔离挂载的、不跑应用 `init()`。两次独立启动 = 两次真实启动路径，
 * 读数不会依赖"探针碰巧把监听也带起来了"。
 */
async function runAmbientCapability(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  const bootAppearance = async () => {
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.stubApi('saveSettings', null)");
    await cdp.eval("window.__probe.install('/src/components/SettingsPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, isolated: true })) + ")");
    await sleep(800);
    await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')].find((x) => (x.textContent || '').trim() === '外观');
      if (b) b.click();
    })()`);
    await sleep(600);
  };
  const readRow = () => cdp.eval(`(() => {
    // 行根用 .settings-card-row（SettingsRow 的根类）；不挂自定义属性 —— SettingsRow 有两个
    // 根节点，fallthrough 属性会直接失效（Vue 只警告不报错，探针会静默读到 null）。
    // ⚠️ 这段在模板字符串里：注释不许出现反引号与反斜杠。
    const group = [...document.querySelectorAll('[role="radiogroup"]')]
      .find((g) => /背景动效|Background Motion/i.test(g.getAttribute('aria-label') || ''));
    const row = group ? group.closest('.settings-card-row') : null;
    const items = group ? [...group.querySelectorAll('[role="radio"]')] : [];
    return {
      found: !!row,
      labels: items.map((b) => (b.textContent || '').trim()),
      disabled: items.map((b) => b.disabled || b.getAttribute('aria-disabled') === 'true'
        || b.hasAttribute('data-disabled')),
      checked: items.map((b) => b.getAttribute('data-state') === 'checked'
        || b.getAttribute('aria-checked') === 'true'),
      text: row ? (row.innerText || '').replace(/\\s+/g, ' ').slice(0, 200) : '',
      mode: document.documentElement.dataset.ambient || '',
    };
  })()`);

  await cdp.send("Emulation.setEmulatedMedia", { features: [] });
  await bootAppearance();
  const ok = await readRow();
  check("背景动效·能力可用：两档都可选、默认选中「缓慢流动」",
    ok.found === true && ok.labels.length === 2
      && ok.disabled.length === 2 && ok.disabled.every((d) => d === false)
      && ok.checked[0] === true, // 档位顺序 drift,off ⇒ 第一项（缓慢流动）被选中
    "row 在 / 2 档 / disabled=false ×2 / 选中「缓慢流动」",
    JSON.stringify(ok));

  await cdp.send("Emulation.setEmulatedMedia", {
    features: [{ name: "prefers-reduced-transparency", value: "reduce" }],
  });
  await bootAppearance();
  const no = await readRow();
  check("背景动效·能力不支持：默认关、不可选、写明原因（存储里的用户选择不被改写）",
    no.found === true && no.disabled.length === 2 && no.disabled.every((d) => d === true)
      && /透明效果|Transparency effects/i.test(no.text)
      && no.checked[1] === true, // 档位顺序 drift,off ⇒ 第二项（关闭）被选中
    "disabled=true ×2 + 原因文案 + 选中「关闭」",
    JSON.stringify(no));

  await cdp.send("Emulation.setEmulatedMedia", { features: [] });
  await sleep(200);
}

async function runSettingsMobile(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval("window.__probe.stubApi('saveSettings', null)");
    const mounted = await cdp.eval("window.__probe.install('/src/components/SettingsPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, isolated: true })) + ")");
    await sleep(600);
    const read = () => cdp.eval(`(() => {
      const buttons = [...document.querySelectorAll('button')].filter((b) => b.getClientRects().length > 0);
      const outside = buttons.filter((b) => {
        const r = b.getBoundingClientRect();
        return r.right > innerWidth + 1 || r.left < -1;
      });
      const text = document.body.innerText || '';
      // 判据锚点从「input 的某个 px-4/py-3 祖先」搬到控件自身的 [data-theme-color-picker]：
      // 行类名改过一次，旧选择器在 2026-11-09 已经查不到行（presets=0 空转）。没有新锚点时
      // 退回 input[type=color] 所在行 —— 这样同一段探针能把「修前」的旧形状也量出来做反例自证。
      const picker = document.querySelector('[data-theme-color-picker]');
      const input = document.querySelector('[data-custom-color-entry] input[type=color]')
        || document.querySelector('input[type=color]');
      const row = picker ? picker.closest('.settings-card-row')
        : (input ? input.closest('.settings-card-row') : null);
      const rowR = row ? row.getBoundingClientRect() : null;
      const presets = picker
        ? [...picker.querySelectorAll('[data-preset-color]')]
        : (row ? [...row.querySelectorAll('button[aria-pressed]')] : []);
      const presetRects = presets.map((b) => b.getBoundingClientRect()).filter((r) => r.width > 0);
      const entry = document.querySelector('[data-custom-color-entry]');
      const surface = entry ? entry.querySelector('button[aria-pressed]') : null;
      const wheel = entry ? entry.querySelector('.custom-color-wheel') : null;
      const inR = input ? input.getBoundingClientRect() : null;
      const entryR = (entry || input) ? (entry || input).getBoundingClientRect() : null;
      const hexOf = (b) => {
        const own = b.getAttribute('data-preset-color');
        if (own) return own;
        const m = /#[0-9a-f]{6}/i.exec(b.getAttribute('aria-label') || '');
        return m ? m[0] : null;
      };
      return {
        vw: innerWidth,
        scrollW: document.documentElement.scrollWidth,
        buttons: buttons.length,
        outside: outside.map((b) => String(b.getAttribute('aria-label') || b.textContent || '').trim().slice(0, 24)),
        hasList: text.includes('外观') && text.includes('通用设置') && text.includes('关于'),
        hasFont: text.includes('系统默认'),
        // 「减少透明效果」两档（zh/en 都认：探针的 --locale 只改 navigator，应用语言仍读 localStorage）
        reducedRow: /减少透明效果|Reduce transparency/i.test(text),
        reduceOptions: buttons.filter((b) => /^(减少透明|Reduce)$/.test((b.textContent || '').trim())).length,
        colorPresets: presets.length,
        colorPresetWidths: presetRects.map((r) => +r.width.toFixed(1)),
        colorPresetHeights: presetRects.map((r) => +r.height.toFixed(1)),
        colorPresetRadii: presets.map((b) => getComputedStyle(b).borderRadius),
        colorLastPresetRight: presetRects.length ? +Math.max(...presetRects.map((r) => r.right)).toFixed(1) : null,
        colorRowRight: rowR ? +rowR.right.toFixed(1) : null,
        // 选中态归属：aria-pressed 是唯一判据（预置色与自定义入口互斥）。
        selectedPresets: presets.filter((b) => b.getAttribute('aria-pressed') === 'true').map(hexOf),
        customEntryWidth: entryR ? +entryR.width.toFixed(1) : null,
        customEntryHeight: entryR ? +entryR.height.toFixed(1) : null,
        customEntryRight: entryR ? +entryR.right.toFixed(1) : null,
        customSurfaceRadius: surface ? getComputedStyle(surface).borderRadius
          : (input ? getComputedStyle(input).borderRadius : null),
        customSelected: entry ? entry.getAttribute('data-selected') : null,
        customAriaPressed: surface ? surface.getAttribute('aria-pressed') : null,
        customAriaLabel: surface ? surface.getAttribute('aria-label') : null,
        customLabelVisible: entry ? /自定义|Custom/i.test(entry.textContent || '') : false,
        // 未选中自定义时入口填充是色轮（background-image），选中后才是当前自定义色（纯色）。
        customWheelBg: wheel ? getComputedStyle(wheel).backgroundColor : null,
        customWheelImage: wheel ? getComputedStyle(wheel).backgroundImage : null,
        customOutlineStyle: surface ? getComputedStyle(surface).outlineStyle : null,
        customOutlineWidth: surface ? getComputedStyle(surface).outlineWidth : null,
        customInputValue: input ? input.value : null,
        customTabbables: picker
          ? [...picker.querySelectorAll('button, input')]
            .filter((e) => e.tabIndex >= 0 && e.getClientRects().length > 0).length
          : null,
      };
    })()`);
    let s = await read();
    check("移动端设置：一级列表渲染，390 宽下无横向溢出、按钮都在视口内",
      mounted && mounted.ok === true && s.hasList && s.scrollW <= s.vw + 1 && s.outside.length === 0,
      "列表可见 + scrollWidth<=vw + outside=0", JSON.stringify({ mounted, s }));

    // 用户 2026-10-25（第 4 版）：一级列表必须是 4 组且顺序 = 通用 / 网络 / 文件与存储 / 关于。
    const groupLabels = await cdp.eval(`(async () => {
      const { t } = await import('/src/i18n/index.ts');
      return [t('settings.group.general'), t('settings.item.network'),
        t('settings.item.storageFiles'), t('settings.item.about')];
    })()`);
    // 组名锚点从 `.uppercase` 搬到 `[data-settings-group]`：B4 去掉全大写后类名不再是判据，
    // 但「4 组且顺序固定」这条断言原样保留（2026-11-06 判据搬迁，不是放宽）。
    const groups = await cdp.eval(`(() => [...document.querySelectorAll('[data-settings-scroll] [data-settings-group]')]
      .map((e) => (e.textContent || '').trim()).filter(Boolean))()`);
    check("移动端设置：一级列表是 4 组，顺序为 通用 / 网络 / 文件与存储 / 关于",
      JSON.stringify(groups) === JSON.stringify(groupLabels),
      JSON.stringify(groupLabels), JSON.stringify(groups));

    const clicked = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').trim().includes('外观'));
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(500);
    s = await read();
    check("移动端设置：进入「外观」二级页，字体默认档可见且无横向溢出",
      clicked === true && s.hasFont && s.scrollW <= s.vw + 1 && s.outside.length === 0,
      "外观页含系统默认 + 无溢出", JSON.stringify(s));
    // ── 主题色控件取证帧（亮/暗各一组，裁到控件所在行）────────────────────
    const shotRow = async (name) => {
      if (!SHOT_PATH) return null;
      const rect = await cdp.eval(`(() => {
        const p = document.querySelector('[data-theme-color-picker]');
        const target = p || (document.querySelector('input[type=color]')
          && document.querySelector('input[type=color]').closest('.settings-card-row'));
        if (!target) return null;
        const r = target.getBoundingClientRect();
        return {
          x: +Math.max(0, r.x + scrollX - 12).toFixed(1),
          y: +Math.max(0, r.y + scrollY - 10).toFixed(1),
          width: +(r.width + 24).toFixed(1),
          height: +(r.height + 20).toFixed(1),
        };
      })()`);
      if (!rect) return null;
      const shot = await cdp.send("Page.captureScreenshot", { format: "png", clip: { ...rect, scale: 2 } });
      const p = SHOT_PATH.replace(/\.png$/, `-${name}.png`);
      fs.writeFileSync(p, Buffer.from(shot.data, "base64"));
      console.log("  📷 主题色控件取证帧 → " + p);
      return p;
    };
    await shotRow("themecolor-light-default");

    // 用户 2026-11-09：① 自定义入口看不出来（曾是第 7 个同形状圆点）② 点预置色时它也一起变。
    // 判据不再要求「与 preset 同尺寸同形状」（B3），而是**必须不同**：宽 ≥64、有文字、有色轮，
    // 且未选自定义时填充是色轮而不是当前生效色 —— 这是换参照物，不是放宽（旧判据正是缺陷本身）。
    const colorsBase = s;
    const colorsOk = s.colorPresets === 6
      && s.colorPresetWidths.length === 6 && s.colorPresetWidths.every((w) => w >= 20)
      && s.colorRowRight !== null
      && s.colorLastPresetRight <= s.colorRowRight - 1
      && s.selectedPresets.length === 1 && s.selectedPresets[0] === '#2f6bff'
      && s.customEntryWidth >= 64
      && s.customEntryHeight === s.colorPresetHeights[0]
      && s.customSurfaceRadius === s.colorPresetRadii[0]
      && s.customEntryRight <= s.colorRowRight - 1
      && s.customSelected === 'false' && s.customAriaPressed === 'false'
      && s.customOutlineStyle === 'none'
      && /自定义|Custom/i.test(String(s.customAriaLabel))
      && s.customLabelVisible === true
      && s.customTabbables === 7
      && /conic-gradient/.test(String(s.customWheelImage));
    check("移动端外观：预置色一排 6 档且选中态互斥；自定义是独立入口（宽≥64 / 有文字 / 色轮）并保持未选",
      colorsOk,
      "6 预置宽度≥20 + 唯一选中 #2f6bff + 自定义宽≥64 有文字有色轮、aria-pressed=false、无 outline、行内",
      JSON.stringify({ presets: s.colorPresets, widths: s.colorPresetWidths,
        selected: s.selectedPresets, entryW: s.customEntryWidth, entryH: s.customEntryHeight,
        entryRadius: s.customSurfaceRadius, entryRight: s.customEntryRight, rowRight: s.colorRowRight,
        ariaPressed: s.customAriaPressed, ariaLabel: s.customAriaLabel, label: s.customLabelVisible,
        tabbables: s.customTabbables, wheel: s.customWheelBg, wheelImage: s.customWheelImage,
        lastRight: s.colorLastPresetRight }));

    // 点一个预置色：选中态搬家，自定义入口必须**纹丝不动**（用户报的"它也跟着变"）。
    const clickPreset = async (hex) => cdp.eval(`(() => {
      const picker = document.querySelector('[data-theme-color-picker]');
      const b = (picker && picker.querySelector('[data-preset-color="${hex}"]'))
        || [...document.querySelectorAll('button[aria-pressed]')]
          .find((x) => (x.getAttribute('aria-label') || '').includes('${hex}'));
      if (!b) return false;
      b.click();
      return true;
    })()`);
    const presetClicked = await clickPreset('#ff6b35');
    await sleep(300);
    s = await read();
    const presetNotFollowing = s.customWheelImage === colorsBase.customWheelImage
      && s.customWheelBg === colorsBase.customWheelBg
      && s.customInputValue === colorsBase.customInputValue;
    check("移动端外观：点预置色后选中态只属于该预置色；自定义入口保持未选且填充/取色器值不跟着变",
      presetClicked === true
        && s.selectedPresets.length === 1 && s.selectedPresets[0] === '#ff6b35'
        && s.customSelected === 'false' && s.customAriaPressed === 'false'
        && s.customOutlineStyle === 'none'
        && presetNotFollowing,
      "selected=['#ff6b35'] + customSelected=false + 色轮/取色器值完全不变",
      JSON.stringify({ selected: s.selectedPresets, customSelected: s.customSelected,
        customPressed: s.customAriaPressed, wheelBg: s.customWheelBg, wheelBefore: colorsBase.customWheelBg,
        wheelImage: String(s.customWheelImage).slice(0, 48),
        value: s.customInputValue, valueBefore: colorsBase.customInputValue }));
    await shotRow("themecolor-light-preset");

    // 选自定义色：预置色全部取消，入口变成"选中 + 显示当前自定义色"。
    const customSet = await cdp.eval(`(() => {
      const i = document.querySelector('[data-custom-color-entry] input[type=color]');
      if (!i) return false;
      i.value = '#123456';
      i.dispatchEvent(new Event('input', { bubbles: true }));
      return true;
    })()`);
    await sleep(300);
    s = await read();
    check("移动端外观：选自定义色后预置色全部取消选中、入口显示当前自定义色（互斥）",
      customSet === true && s.selectedPresets.length === 0
        && s.customSelected === 'true' && s.customAriaPressed === 'true'
        && s.customOutlineStyle === 'solid' && s.customOutlineWidth === '2px'
        && s.customWheelBg === 'rgb(18, 52, 86)'
        && s.customInputValue === '#123456',
      "selected=[] + aria-pressed=true + outline 2px + 色轮=#123456",
      JSON.stringify({ selected: s.selectedPresets, customSelected: s.customSelected,
        pressed: s.customAriaPressed, outline: s.customOutlineStyle + "/" + s.customOutlineWidth,
        wheelBg: s.customWheelBg, value: s.customInputValue }));
    await shotRow("themecolor-light-custom");

    // 暗色：同一选中态下必须仍然"看得出选中"（outline 来自 token，不是写死的浅色）。
    await cdp.send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: "dark" }] }).catch(() => {});
    await cdp.eval("document.documentElement.classList.add('dark')");
    await sleep(400);
    const darkShot = await shotRow("themecolor-dark-custom");
    const darkRead = await read();
    check("移动端外观：暗色下自定义选中态仍清楚（2px outline + 仍是当前自定义色）",
      (!SHOT_PATH || darkShot !== null)
        && darkRead.customSelected === 'true'
        && darkRead.customOutlineStyle === 'solid' && darkRead.customOutlineWidth === '2px'
        && darkRead.customWheelBg === 'rgb(18, 52, 86)',
      "dark: selected=true + outline 2px + wheel=#123456",
      JSON.stringify({ shot: darkShot, selected: darkRead.customSelected,
        outline: darkRead.customOutlineStyle + "/" + darkRead.customOutlineWidth,
        wheelBg: darkRead.customWheelBg }));

    // 回到默认预置色 + 亮色，避免污染后续「减少透明效果」与返回键检查。
    await clickPreset('#2f6bff');
    await cdp.eval("document.documentElement.classList.remove('dark')");
    await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});
    await sleep(300);
    s = await read();

    // 「减少透明效果」：受影响段就是外观页这一行。点了之后必须真的落到 DOM
    // （`data-reduced-transparency=true` → CSS 退实底），且动效背景冻结到 static、布局不溢出。
    // WKWebView 不支持系统级 prefers-reduced-transparency，所以这条只能验应用内开关。
    const reduceClicked = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => /^(减少透明|Reduce)$/.test((x.textContent || '').trim()));
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(400);
    const reduced = await cdp.eval(`(() => {
      const el = document.querySelector('.glass-1, .glass-2, .glass-3, .frost');
      const cs = el ? getComputedStyle(el) : null;
      return {
        attr: document.documentElement.getAttribute('data-reduced-transparency'),
        ambient: document.documentElement.getAttribute('data-ambient'),
        scrollW: document.documentElement.scrollWidth,
        glassBlur: cs ? (cs.backdropFilter || cs.webkitBackdropFilter || 'none') : null,
      };
    })()`);
    check("移动端外观：减少透明开关落到 DOM（实底 + 动效冻结 + 不改布局）",
      s.reducedRow === true && s.reduceOptions === 1 && reduceClicked === true
        && reduced.attr === 'true' && reduced.ambient === 'static'
        && (reduced.glassBlur === null || reduced.glassBlur === 'none')
        && reduced.scrollW <= s.vw + 1,
      "两档可见 + 点击后 html[data-reduced-transparency=true] + data-ambient=static + 无横向溢出",
      JSON.stringify({ row: s.reducedRow, options: s.reduceOptions, clicked: reduceClicked, reduced }));

    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      const p = SHOT_PATH.replace(/\.png$/, "-settingsmobile.png");
      fs.writeFileSync(p, Buffer.from(shot.data, "base64"));
      console.log("  📷 移动端设置取证帧 → " + p);
    }

    const back = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')].find((x) => {
        const a = x.getAttribute('aria-label') || '';
        return a.includes('返回') || /\\bBack\\b/i.test(a);
      });
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(400);
    s = await read();
    check("移动端设置：返回键回到一级列表（二级页不是死路）",
      back === true && s.hasList === true, "返回后列表重新出现", JSON.stringify(s));

    // ── 按压不变形（用户 2026-10-23：「点击选项整个列表都缩小」）──
    // 真按住一次再读 computed transform，而不是查 data-no-press 存不存在：
    // 类名在 ≠ 效果对。**正控**是标题栏那颗返回键（普通按钮，必须照旧缩）——
    // 没有它，整个探针读不到缩放也可能是量具坏了。
    const pressBy = async (pickJs) => {
      const base = await cdp.eval(`(() => {
        const b = (${pickJs});
        if (!b) return null;
        const q = b.getBoundingClientRect();
        return { x: Math.round(q.left + q.width / 2), y: Math.round(q.top + q.height / 2),
          left: +q.left.toFixed(1), top: +q.top.toFixed(1),
          w: +q.width.toFixed(1), h: +q.height.toFixed(1),
          bg: getComputedStyle(b).backgroundColor };
      })()`);
      if (!base) return null;
      await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: base.x, y: base.y, button: "left", clickCount: 1 });
      await sleep(180);
      const tr = await cdp.eval(`(() => {
        const b = (${pickJs});
        if (!b) return null;
        const q = b.getBoundingClientRect();
        return {
          transform: getComputedStyle(b).transform,
          noPress: b.hasAttribute('data-no-press'),
          text: (b.textContent || '').trim().slice(0, 12),
          left: +q.left.toFixed(1), top: +q.top.toFixed(1),
          w: +q.width.toFixed(1), h: +q.height.toFixed(1),
          bg: getComputedStyle(b).backgroundColor,
        };
      })()`);
      // 抬手点故意挪开：同一元素上 press+release 会合成一次 click（按列表项就会跳页、
      // 按返回就会退出），这条探针只想要 :active 期间的计算样式，不想要副作用。
      await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: base.x, y: Math.max(1, base.y - 260), button: "left", clickCount: 1 });
      await sleep(120);
      return tr ? { ...tr, before: base } : null;
    };
    // ⚠️ 两个选择器必须**各自独立**：写成「文案是外观 或 aria 含返回」的单一谓词时，
    // 头部那颗返回键排在内容前面 ⇒ 两次都会按到它，rowPress 拿到的其实是返回键（实测踩过）。
    const rowPick = `[...document.querySelectorAll('button')].find((x) => (x.textContent || '').trim() === '外观')`;
    const backPick = `[...document.querySelectorAll('button')].find((x) => (x.getAttribute('aria-label') || '').includes('返回'))`;
    const rowPress = await pressBy(rowPick);
    const backPress = await pressBy(backPick);
    const scaled = (t) => !t ? null : (t !== "none" && !/matrix\(1,\s*0,\s*0,\s*1,\s*0,\s*0\)/.test(t));
    check("移动端设置：按住列表项整行不缩放（按压反馈只给普通按钮）",
      rowPress?.noPress === true && /外观/.test(rowPress.text) && scaled(rowPress.transform) === false
        && scaled(backPress?.transform) === true,
      "列表项(外观)带 data-no-press 且 transform 不缩放 + 返回键(正控)照旧缩放",
      JSON.stringify({ rowPress, backPress }));
    // 用户 2026-10-25 重写口径：标准列表交互 = **只换按压底色，几何绝不位移**。
    // 旧实现的内层 translate/inset shadow 被用户读成"整个列表缩了一下"，已删除。
    check("设置列表项：按住时只换底色、宽高与位置零位移（标准列表交互）",
      !!rowPress
        && rowPress.bg !== rowPress.before.bg
        && Math.abs(rowPress.w - rowPress.before.w) <= 0.5
        && Math.abs(rowPress.h - rowPress.before.h) <= 0.5
        && Math.abs(rowPress.left - rowPress.before.left) <= 0.5
        && Math.abs(rowPress.top - rowPress.before.top) <= 0.5,
      "active 背景色变化 + 宽/高/left/top 都不动",
      JSON.stringify({ before: rowPress?.before, during: rowPress }));

    // 量的是**同一个元素**的 left 在「刚进入」与「滑到底」两处的差，不是文案、不是类名。
    // 边距会漂只有两类来源：某一层滚动容器在滚动过程中长出了滚动条（吃掉宽度），或者某个
    // 祖先的 padding 被 class 切换改掉。这段把每一层滚动容器的 clientWidth/offsetWidth 一起打出来，
    // 红了能直接指到是哪一层。
    const openNetwork = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').trim() === '网络');
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(900);
    const drift = await cdp.eval(`(() => {
      const card = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.getClientRects().length > 0 && el.textContent.includes('蓝牙通道'));
      if (!card) return { found: false };
      const scrollers = [];
      for (let el = card.parentElement; el; el = el.parentElement) {
        const cs = getComputedStyle(el);
        if (cs.overflowY === 'auto' || cs.overflowY === 'scroll') {
          scrollers.push({
            cls: String(el.className).slice(0, 60),
            clientW: el.clientWidth,
            offsetW: el.offsetWidth,
            scrollH: el.scrollHeight,
            clientH: el.clientHeight,
            gutter: cs.scrollbarGutter,
            padL: cs.paddingLeft,
          });
        }
      }
      const inner = card.closest('[data-settings-scroll]');
      const readAt = () => +card.getBoundingClientRect().left.toFixed(1);
      const atTop = readAt();
      // ⚠️ 非空转：隔离安装里网络段的异步数据是桩，页面可能根本不够高 ⇒ 滚不动 ⇒
      // 「滚动前后一样」会凭空空转。滚不动就塞一段撑高的填充物，强制进入「滑到底」那一态。
      let forced = false;
      if (inner) {
        if (inner.scrollHeight <= inner.clientHeight + 8) {
          const filler = document.createElement('div');
          filler.setAttribute('data-probe-filler', '');
          filler.style.height = '2000px';
          inner.appendChild(filler);
          forced = true;
        }
        inner.scrollTop = inner.scrollHeight;
      }
      return {
        found: true, atTop, atBottom: readAt(), scrollers, forced,
        scrollTop: inner ? Math.round(inner.scrollTop) : null,
        scrollH: inner ? inner.scrollHeight : null,
        clientH: inner ? inner.clientHeight : null,
      };
    })()`);
    await sleep(300);
    const driftAfter = await cdp.eval(`(() => {
      const card = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.getClientRects().length > 0 && el.textContent.includes('蓝牙通道'));
      return card ? +card.getBoundingClientRect().left.toFixed(1) : null;
    })()`);
    console.log("  ℹ 网络页边距读数 → " + JSON.stringify({ drift, driftAfter }));
    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      const p = SHOT_PATH.replace(/\.png$/, "-network.png");
      fs.writeFileSync(p, Buffer.from(shot.data, "base64"));
      console.log("  📷 网络页取证帧 → " + p);
    }
    check("移动端设置·网络页：滑到底之后卡片左边缘不动（边距不漂）",
      openNetwork === true && drift.found === true && driftAfter !== null
        && drift.scrollTop > 0
        && Math.abs(driftAfter - drift.atTop) <= 1,
      "确实滚动了（scrollTop>0）+ 同一张卡 left 在滚动前后相差 <=1px",
      JSON.stringify({ drift, driftAfter }));
    // 嵌套滚动容器是「滑一会边距变了」的机制本身：外层壳一旦也开滚动，触屏滚到底会串联到
    // 它（整块内容位移），两层又各留一条 gutter（左右各多吃 8px）。这里钉**唯一一层**。
    check("移动端设置·网络页：内容区只有一层滚动容器（没有嵌套滚动）",
      drift.found === true && Array.isArray(drift.scrollers) && drift.scrollers.length === 1,
      "从卡片往上只有 1 个 overflow-y 滚动祖先",
      JSON.stringify(drift.scrollers));

    // 用户 2026-10-25：中继/中转卡片最后一行下面还挂着一道短横线。判外壳的运行时结果，
    // 不判源码里有没有那条 class —— 分隔线由 SettingsRow 画、由 SettingsGroup 隐藏。
    const dividers = await cdp.eval(`(() => {
      const groups = [...document.querySelectorAll('[data-settings-rows]')];
      const offenders = [];
      for (const g of groups) {
        const last = g.lastElementChild;
        if (last && last.classList.contains('h-px') && getComputedStyle(last).display !== 'none') {
          offenders.push(getComputedStyle(last).display);
        }
      }
      return { groups: groups.length, offenders };
    })()`);
    check("移动端设置·网络页：每张卡最后一行都不画分隔线（末行分隔线 computed display=none）",
      !!dividers && dividers.groups >= 3 && dividers.offenders.length === 0,
      "至少 3 张设置卡 + 没有可见的末行分隔线", JSON.stringify(dividers));

    // 资料页与设置二级页同一口径的页边距（用户 2026-10-23：「个人资料周围没有边距」）。
    // 量的是同一张卡在**两个不同页面**上的 left 相等 —— 只比类名是抓不住「有一页忘了 p-4」的。
    await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')].find((x) => {
        const a = x.getAttribute('aria-label') || '';
        return a.includes('返回') || /\\bBack\\b/i.test(a);
      });
      if (b) b.click();
    })()`);
    await sleep(400);
    const openProfile = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').trim() === '个人资料');
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(700);
    const profileLeft = await cdp.eval(`(() => {
      const card = [...document.querySelectorAll('[class*="rounded-"][class*="border"]')]
        .find((el) => el.getClientRects().length > 0 && el.textContent.includes('上传头像'));
      return card ? +card.getBoundingClientRect().left.toFixed(1) : null;
    })()`);
    check("移动端设置·资料页：卡片左边缘与网络页同口径（都有页面边距）",
      openProfile === true && profileLeft !== null && drift.found === true
        && Math.abs(profileLeft - drift.atTop) <= 1 && profileLeft >= 8,
      "资料卡 left == 网络卡 left 且 >=8",
      JSON.stringify({ profileLeft, networkLeft: drift.atTop }));

    // 用户 2026-10-23（移动端资料页）：去掉「我在线」只留绿点、输入框更长、与计数间距更小。
    // 量的都是**几何与文本**，不是类名：类名对了但宽度被别的元素吃掉一样要红。
    const nick = await cdp.eval(`(() => {
      const inp = document.querySelector('[data-profile-fields] input:not([type="file"])');
      if (!inp) return null;
      const row = inp.parentElement;
      const kids = row ? [...row.children] : [];
      // 计数那一格：兄弟里带 “N/M” 文本的那个（不是 input，也不是状态点）
      const counter = kids.find((el) => el !== inp && /\d+\s*[/]\s*\d+/.test(el.textContent || ''))
        || kids[1];
      const dot = [...row.querySelectorAll('span')].find((el) => /rounded-full/.test(String(el.className)));
      const ir = inp.getBoundingClientRect();
      const cr = counter ? counter.getBoundingClientRect() : null;
      return {
        text: (row.textContent || '').replace(/\s+/g, ' ').trim().slice(0, 24),
        inputW: +ir.width.toFixed(1),
        gapToCounter: cr ? +(cr.left - ir.right).toFixed(1) : null,
        hasDot: !!dot,
      };
    })()`);
    console.log("  ℹ 资料页昵称行读数 → " + JSON.stringify(nick));
    check("移动端资料页：只留状态点（无「我在线」文案）、输入框更宽、与计数间距更小",
      !!nick && !/我在线|在线/.test(nick.text) && nick.hasDot
        && nick.inputW >= 140
        && nick.gapToCounter !== null && nick.gapToCounter <= 6,
      "无在线文案 + 有状态点 + input>=140 + 与计数间距<=6",
      JSON.stringify(nick));

    // 2026-10-24 重写：一级/二级**共用同一个滚动容器**，切页显式回顶端。
    // 上面网络页那段已经把它滚到底并塞过填充物 ⇒ 回到一级再进网络，必须从 0 开始。
    await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')].find((x) => {
        const a = x.getAttribute('aria-label') || '';
        return a.includes('返回') || /\\bBack\\b/i.test(a);
      });
      if (b) b.click();
    })()`);
    await sleep(400);
    const reopenNet = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button')]
        .find((x) => (x.textContent || '').trim() === '网络');
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(700);
    const shared = await cdp.eval(`(() => {
      const all = document.querySelectorAll('[data-settings-scroll]');
      const el = all[0];
      return { count: all.length, top: el ? Math.round(el.scrollTop) : null };
    })()`);
    check("移动端设置：二级→一级→再进二级，共享滚动容器回到顶端且全页只有一层",
      reopenNet === true && shared.count === 1 && shared.top === 0,
      "count=1 且 scrollTop=0", JSON.stringify(shared));

    // ── 返回一级时卡片宽度不许闪一下（用户 2026-10-25）──
    // 真机症状：进「网络」、上滑、返回 ⇒ 一级列表卡片先变窄、过一会儿又还原。
    // 机制不是动画：滚动条出现/消失会实时吃掉内容宽度，而 `scrollbar-gutter` 在部分
    // WebView 上不生效（桌面 Chromium 里量不出来）。这里显式把 gutter 降级成 `auto`
    // 模拟那一档，再逐帧量同一个滚动容器的 clientWidth —— 修法要求它与内容长短无关。
    const backSampled = await cdp.eval(`(() => {
      const el = document.querySelector('[data-settings-scroll]');
      if (el) {
        el.style.scrollbarGutter = 'auto';
        el.scrollTop = el.scrollHeight;
      }
      window.__settingsBackWidths = [];
      const back = [...document.querySelectorAll('button')].find((x) => {
        const a = x.getAttribute('aria-label') || '';
        return a.includes('返回') || /\\bBack\\b/i.test(a);
      });
      const tick = () => {
        const s = document.querySelector('[data-settings-scroll]');
        if (s) window.__settingsBackWidths.push(+s.clientWidth.toFixed(1));
        if (window.__settingsBackWidths.length < 40) requestAnimationFrame(tick);
      };
      if (back) back.click();
      tick();
      return !!back;
    })()`);
    await sleep(900);
    const backWidths = await cdp.eval("window.__settingsBackWidths || []");
    const widthSpan = backWidths.length
      ? +(Math.max(...backWidths) - Math.min(...backWidths)).toFixed(1)
      : null;
    check("移动端设置：从二级页返回时一级列表宽度不随滚动条出现/消失而变（gutter 降级档也稳定）",
      backSampled === true && backWidths.length >= 5 && widthSpan !== null && widthSpan <= 0.5,
      "返回后逐帧 clientWidth 极差 <=0.5px",
      JSON.stringify({ frames: backWidths.length, min: backWidths.length ? Math.min(...backWidths) : null,
        max: backWidths.length ? Math.max(...backWidths) : null, span: widthSpan }));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 移动端群任务（--only=tasksmobile）：390 宽下看板行与详情弹窗的布局。
 * 行为（实时同步、筛选、详情内容）由 --only=tasksrt 覆盖，这里只量移动端视口。
 */
/**
 * 聊天滚动稳定性（--only=scrollreact）。
 *
 * 用户 2026-10-25：给倒数第二条消息加表情回应时，整个聊天区上下闪一下。
 * 这里用真 VirtualList + 可变的普通行复现“高度变化”，逐帧采样 scrollTop / 底边间隙：
 * - 贴底：每一帧都必须贴着底（gap ≤1），不能先掉 40px 再弹回；
 * - 同一帧两行变高：delta 必须累计；
 * - 非贴底：只补视口上方行，正在读的参照行不被拽走。
 */
async function runScrollReact(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  const mounted = await cdp.eval(`(async () => {
    // 夹具的 install 才会写 __probe.vue；这段直接手搭 app，所以从资源条目拿页面同一份 Vue。
    const vueUrl = performance.getEntriesByType('resource')
      .map((e) => e.name || '').find((u) => u.includes('/node_modules/.vite/deps/vue.js?v='));
    const V = window.__probe.vue || (vueUrl ? await import(vueUrl) : null);
    if (!V) return { ok: false, why: 'no-vue' };
    window.__probe.vue = V;
    const VL = await import('/src/components/VirtualList.vue');
    document.body.innerHTML = '';
    const host = document.createElement('div');
    host.id = 'sr-host';
    host.style.cssText = 'height:400px;width:420px;position:relative;';
    document.body.appendChild(host);
    const state = V.reactive({ heights: Array.from({ length: 10 }, () => 100) });
    window.__sr = state;
    // ⚠️ items 必须是**稳定的数组**：真实聊天里加表情只改回应 prop，不改 messages 数组。
    // 若把高度塞进 items，每次变高都会触发 watch(items) 的 suppressTransient（hold），
    // 补偿永远被静默期吃掉 —— 那是夹具自造的假红。
    const items = Array.from({ length: 10 }, (_, i) => ({ id: 'r' + i }));
    const app = V.createApp({
      setup() {
        return () => V.h(VL.default, {
          items,
          estimateHeight: () => 100,
          overscan: 2,
          autoScrollOnSwap: false,
        }, {
          default: ({ item }) => {
            const idx = Number(String(item.id).slice(1));
            return V.h('div', {
              'data-sr-row': item.id,
              style: {
                height: state.heights[idx] + 'px',
                background: '#d8dee9',
                borderBottom: '1px solid #94a3b8',
              },
            }, item.id);
          },
        });
      },
    });
    app.mount(host);
    await V.nextTick(); await V.nextTick();
    await new Promise((r) => setTimeout(r, 300));
    const el = host.querySelector('.vlist-no-anchor');
    if (!el) return { ok: false };
    el.scrollTop = el.scrollHeight;
    await new Promise((r) => requestAnimationFrame(() => r()));
    return {
      ok: true,
      anchor: getComputedStyle(el).overflowAnchor,
      scrollTop: el.scrollTop,
      scrollHeight: el.scrollHeight,
      clientHeight: el.clientHeight,
    };
  })()`);
  check("scrollreact：VirtualList 真挂起来了，且原生锚定已关闭",
    mounted && mounted.ok === true && mounted.anchor === "none",
    "mounted + overflow-anchor:none", JSON.stringify(mounted));

  const sample = (mutation) => cdp.eval(`(async () => {
    const V = window.__probe.vue;
    const host = document.getElementById('sr-host');
    const el = host.querySelector('.vlist-no-anchor');
    const pin = () => el && el.__vueParentComponent ? el.__vueParentComponent.setupState.pinned : null;
    const pins = { before: pin() };
    ${mutation}
    await V.nextTick();
    pins.afterNextTick = pin();
    // ⚠️ rAF 在 layout / ResizeObserver **之前**（规范顺序：scroll → rAF → layout → RO → paint）。
    // 只等一帧时，RO 的补偿可能还没发生，读到的是"绘制前"的内部状态；等两帧才对应
    // 用户真正看到的那一帧。这不是放宽阈值：8 帧 gap≤1 的判据原样保留。
    await new Promise((r) => requestAnimationFrame(() => r()));
    await new Promise((r) => requestAnimationFrame(() => r()));
    pins.afterRaf = pin();
    const frames = [];
    for (let i = 0; i < 8; i += 1) {
      await new Promise((r) => requestAnimationFrame(() => r()));
      frames.push({
        top: el.scrollTop,
        gap: el.scrollHeight - el.scrollTop - el.clientHeight,
      });
    }
    return { frames, pins, sh: el.scrollHeight, ch: el.clientHeight };
  })()`);

  // ① 贴底 + 倒数第二条变高：每一帧都必须贴着底，且 top 单调不回落。
  const one = await sample("window.__sr.heights[8] = 140;");
  const oneBadGap = (one.frames || []).filter((f) => f.gap > 1);
  const oneMonotonic = (one.frames || []).every(
    (f, i, a) => i === 0 || f.top >= a[i - 1].top - 0.5,
  );
  check("scrollreact：加一条回应后每一帧都贴底（没有先掉 40px 再弹回）",
    !!one && oneBadGap.length === 0, "8 帧 gap ≤1", JSON.stringify(one));
  check("scrollreact：scrollTop 单调不回落",
    oneMonotonic, "8 帧单调", JSON.stringify(one && one.frames));

  // ② 同一帧两行变高：delta 必须累计。
  //    逐帧 gap 在这里不作为硬判据：两行的 ResizeObserver entry 可能分两批到达，
  //    浏览器在中间帧本来就会多出一次布局；累计是否正确由最终 top 增量（=40）与
  //    `VirtualList.vue` 内联补偿（`shouldAdjustScrollPositionOnItemSizeChange`：
  //    `item.start + item.size <= offset`）求和共同证明。
  const two = await sample("window.__sr.heights[7] += 20; window.__sr.heights[8] += 20;");
  const oneFinalTop = one.frames && one.frames.length ? one.frames[one.frames.length - 1].top : 0;
  const twoFinal = two.frames && two.frames.length ? two.frames[two.frames.length - 1] : null;
  check("scrollreact：同一帧两行变高，最终贴底且累计了 40px",
    !!twoFinal && twoFinal.gap <= 1 && twoFinal.top >= oneFinalTop + 39,
    "final gap ≤1 且 top 增量 ≥39",
    JSON.stringify({ oneFinalTop, twoFinal, two }));

  // ③ 非贴底：上滚到 200px 后让视口上方行变高，参照行不应下坠。
  const away = await cdp.eval(`(async () => {
    const V = window.__probe.vue;
    const host = document.getElementById('sr-host');
    const el = host.querySelector('.vlist-no-anchor');
    window.__sr.heights = Array.from({ length: 10 }, () => 100);
    await V.nextTick(); await V.nextTick();
    el.scrollTop = 200;
    // 换数据会触发 300ms 的 suppressTransient（避免“回到最新”闪现）；等它过掉，
    // 这一段量的是“用户停在历史位置时”的补偿，不是静默期。
    await new Promise((r) => setTimeout(r, 350));
    await new Promise((r) => requestAnimationFrame(() => r()));
    const ref = host.querySelector('[data-sr-row="r5"]');
    const before = ref ? ref.getBoundingClientRect().top : null;
    return { before, top: el.scrollTop };
  })()`);
  const awayAfter = await cdp.eval(`(async () => {
    const V = window.__probe.vue;
    const host = document.getElementById('sr-host');
    const ref = host.querySelector('[data-sr-row="r5"]');
    window.__sr.heights[0] = 140;
    await V.nextTick();
    for (let i = 0; i < 8; i += 1) {
      await new Promise((r) => requestAnimationFrame(() => r()));
    }
    const after = ref ? ref.getBoundingClientRect().top : null;
    const el = host.querySelector('.vlist-no-anchor');
    return { after, top: el.scrollTop };
  })()`);
  const shifted = away && away.before !== null && awayAfter && awayAfter.after !== null
    ? Math.abs(awayAfter.after - away.before) : null;
  check("scrollreact：非贴底时只补视口上方行，正在读的内容不被拽走",
    shifted !== null && shifted <= 1, "参照行位移 ≤1px",
    JSON.stringify({ away, awayAfter, shifted }));
}

/**
 * 单聊标题栏头像（--only=chatheader）。
 *
 * 用户 2026-10-25：名字旁边要有对方头像，点它进资料页；群聊不出现单聊头像。
 * 这里量三件事：头像真的在名字左侧、点它 emit `open-profile`、群聊没有这枚头像；
 * 再加一档 320 宽，确认加了头像后标题栏不横向溢出。
 */
async function runChatHeader(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  const SINGLE = {
    conv: { id: "p-header", kind: "single", name: "好友甲", avatar: null, last_msg: null, last_ts: 0, unread: 0 },
    isGroup: false,
    online: true,
    memberCount: 0,
    showBack: false,
    unreadTotal: 0,
  };
  const GROUP = {
    conv: { id: "g-header", kind: "group", name: "项目群", avatar: null, last_msg: null, last_ts: 0, unread: 0 },
    isGroup: true,
    online: true,
    memberCount: 3,
    showBack: false,
    unreadTotal: 0,
  };
  const mount = async (props) => {
    await cdp.eval(PAGE_FIXTURE);
    const r = await cdp.eval(
      "window.__probe.install('/src/components/chat/ChatHeader.vue', '', "
      + JSON.stringify(JSON.stringify(props)) + ")",
    );
    await sleep(350);
    return r;
  };
  const readHeader = () => cdp.eval(`(() => {
    const host = document.getElementById('probe-host');
    if (!host) return { ok: false };
    const avatars = host.querySelectorAll('.gosslan-avatar-box');
    const name = host.querySelector('.truncate');
    const btn = [...host.querySelectorAll('button')].find((b) => {
      const l = b.getAttribute('aria-label') || '';
      return l.includes('好友甲') || l.includes('项目群');
    });
    const r = btn ? btn.getBoundingClientRect() : null;
    return {
      ok: true,
      avatars: avatars.length,
      label: btn ? btn.getAttribute('aria-label') : null,
      avatarLeft: r ? Math.round(r.left) : null,
      avatarW: r ? Math.round(r.width) : null,
      nameLeft: name ? Math.round(name.getBoundingClientRect().left) : null,
      sw: document.documentElement.scrollWidth,
      vw: innerWidth,
    };
  })()`);

  // ① 单聊：头像在名字左侧、可点、emit open-profile。
  await mount(SINGLE);
  const single = await readHeader();
  check("单聊标题栏出现头像（MessageAvatar，不是手画占位）",
    single.ok === true && single.avatars === 1 && single.avatarW !== null && single.avatarW >= 26,
    "1 枚 ≥26px 头像", JSON.stringify(single));
  check("头像是在名字左侧（不是挤到右侧按钮堆里）",
    single.avatarLeft !== null && single.nameLeft !== null && single.nameLeft > single.avatarLeft,
    "nameLeft > avatarLeft", JSON.stringify(single));
  if (single.avatarLeft !== null) {
    // 点按钮中心
    const pt = await cdp.eval(`(() => {
      const host = document.getElementById('probe-host');
      const b = [...host.querySelectorAll('button')].find((x) => (x.getAttribute('aria-label') || '').includes('好友甲'));
      if (!b) return null;
      const r = b.getBoundingClientRect();
      return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    })()`);
    if (pt) {
      await cdp.click(pt.x, pt.y);
      await sleep(150);
    }
  }
  const emitted = await cdp.eval(
    "(() => window.__probe.events.filter((e) => e[0] === 'open-profile').length)()",
  );
  check("点头像 emit open-profile（资料页入口接上了）", emitted === 1, "1 次", JSON.stringify({ emitted }));

  // ② 群聊：没有单聊头像。
  await mount(GROUP);
  const group = await readHeader();
  check("群聊标题栏不出现单聊头像",
    group.ok === true && group.avatars === 0,
    "0 枚头像", JSON.stringify(group));

  // ③ 320 宽：加了头像也不横向溢出。
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 320, height: 640, deviceScaleFactor: 2, mobile: true,
  });
  await sleep(300);
  await mount(SINGLE);
  const narrow = await readHeader();
  check("320 宽：标题栏没有横向溢出（名字可截断）",
    narrow.ok === true && narrow.sw <= 320,
    "scrollWidth ≤ 320", JSON.stringify(narrow));
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
  });
}

/**
 * 统一后台任务中心（`TaskCenter.vue`）的运行时判据。
 *
 * 2026-10-25 起入口从浮动药丸迁到会话列表页脚，所以这一段拆成两半：
 *   ① 面板本身：共享开关打开、只列未完成、100% 未终态的状态文案、按钮数量；
 *   ② 页脚入口：入口存在、版本号、未完成数、点击打开同一个开关、移动端在 TabBar 之上。
 */
async function runOpsCenter(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    // 任务中心的挂载链会走到 ConversationList 的 setup（`void getCurrentWebview()`），
    // 裸浏览器没有 `__TAURI_INTERNALS__` 就会同步抛（与 runPinKeyboard 同一形状）。
    // 以前这一段"碰巧"继承前一段留在同一页上的夹具；2026-11-03 每段独立新 tab 之后
    // 必须自己带夹具 —— 补的是环境fixture，不是判据。
    await cdp.eval(`(() => {
      if (window.__TAURI_INTERNALS__) return;
      window.__TAURI_INTERNALS__ = {
        metadata: {
          currentWindow: { label: 'main' },
          currentWebview: { label: 'main', windowLabel: 'main' },
        },
        invoke: async () => null,
        transformCallback: (cb) => cb,
        convertFileSrc: (p) => p,
      };
      if (!window.__TAURI_EVENT_PLUGIN_INTERNALS__) {
        window.__TAURI_EVENT_PLUGIN_INTERNALS__ = { unregisterListener: () => {} };
      }
    })()`);
    await cdp.eval(PAGE_FIXTURE);
    const mounted = await cdp.eval(
      "window.__probe.install('/src/components/TaskCenter.vue', '', '')",
    );
    check("任务中心：组件在真实 DOM 里挂起来了", !!mounted && mounted.ok === true,
      "install ok", JSON.stringify(mounted));

    // 种四份真值：五种任务各一条 + 一条 done 终态（它**不该**出现在列表里）。
    // 标题用文件名与正文（与语言无关），判据按这些字符串认行，不认按 locale 拼出来的动作名。
    const seeded = await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore();
      chat.transfers = [
        { id: 't-send', peer_id: 'p1', name: '设计稿.zip', size: 1000, direction: 'send',
          status: 'active', path: null, progress: 0.4, blocked_reason: null, created_at: 5 },
        { id: 't-sent', peer_id: 'p1', name: '会议记录.md', size: 100, direction: 'send',
          status: 'sent', path: null, progress: 1, blocked_reason: null, created_at: 6 },
        { id: 't-recv', peer_id: 'p1', name: '照片.jpg', size: 500, direction: 'receive',
          status: 'active', path: null, progress: 0.6, blocked_reason: null, created_at: 7 },
        { id: 't-done', peer_id: 'p1', name: '已完成.txt', size: 10, direction: 'send',
          status: 'done', path: null, progress: 1, blocked_reason: null, created_at: 8 },
      ];
      chat.contentTransfers = [{
        cid: 'a'.repeat(64), peerId: 'p1', groupId: null, name: 'a'.repeat(64), size: 200,
        direction: 'receive', status: 'incomplete', received: 0, attempts: 2,
        nextAttemptAt: 0, lastError: null, path: null, createdAt: 3, updatedAt: 3,
      }];
      chat.messageOps = [{ msg_id: 'm1', kind: 'text', peer_id: 'p1', group_id: null,
        waiting_for: 1, created_at: 9, preview: '在吗', peer_offline: true,
        can_cancel: true, some_delivered: false }];
      chat.groupHistorySync = { g1: { group_id: 'g1', source: 'p1', synced: 30, total: 100,
        phase: 'running' } };
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return { ops: chat.operations.length, ledger: chat.transfers.length };
    })()`);
    check("任务中心：四份真值汇成 6 件未完成任务（done 那条被排除在列之外）",
      seeded && seeded.ops === 6 && seeded.ledger === 4,
      "ops=6 / ledger=4", JSON.stringify(seeded));

    const READ = `(() => {
      const outside = Array.from(document.querySelectorAll('button'))
        .filter((b) => !b.closest('[role="dialog"]'));
      const dialog = document.querySelector('[role="dialog"]');
      const rows = dialog ? Array.from(dialog.querySelectorAll('li')).map((li) => ({
        title: String((li.querySelector('span') || {}).textContent || '').trim(),
        // 第二颗 span 是右上角那句状态（第一颗是标题）。100% 未确认的行必须在这里
        // 说「已发出，等对方确认」，而不是泛泛的「等待中」/「100%」。
        status: String((li.querySelectorAll('span')[1] || {}).textContent || '').trim(),
        buttons: li.querySelectorAll('button').length,
      })) : [];
      return {
        outsideButtons: outside.length,
        dialog: !!dialog,
        taskOpen: (document.querySelector('[data-task-open]') || {}).getAttribute
          ? document.querySelector('[data-task-open]').getAttribute('data-open')
          : null,
        rows: rows,
        vw: window.innerWidth, vh: window.innerHeight,
        scrollWidth: document.documentElement.scrollWidth,
      };
    })()`;
    const read = () => cdp.eval(READ);

    // 入口已迁到会话列表页脚：这里只挂面板，药丸整颗不该再存在。
    const first = await read();
    check("浮动药丸已消失：面板关闭时页面里没有非弹窗按钮",
      first.outsideButtons === 0 && first.vw > 0,
      "0 颗", JSON.stringify({ outsideButtons: first.outsideButtons }));

    // 用共享开关打开面板（页脚与面板读同一个 store）。
    const openedState = await cdp.eval(`(async () => {
      const A = await import('/src/stores/useAppStore.ts');
      const a = A.useAppStore();
      a.openTaskCenter();
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return { open: a.taskCenterOpen, pinia: !!window.__pinia };
    })()`);
    check("任务面板开关：store 的 taskCenterOpen 真的被置真",
      !!openedState && openedState.open === true,
      "taskCenterOpen=true", JSON.stringify(openedState));
    const opened = await read();
    check("共享开关打开面板，列表行数等于读模型的 6 行",
      opened.dialog === true && opened.rows.length === 6,
      "dialog + 6 行", JSON.stringify({ dialog: opened.dialog, rows: opened.rows.length }));
    const byTitle = (title) => opened.rows.find((r) => r.title === title);
    const recv = byTitle('照片.jpg');
    const sent = byTitle('会议记录.md');
    const msg = byTitle('在吗');
    check("接收中的行有按钮（负责人：接受中没有完成的都是可以取消的）",
      !!recv && recv.buttons >= 1, "≥1", JSON.stringify(recv));
    check("100% 但未终态（sent）的行有按钮（负责人：百分之百没完成的也可以取消）",
      !!sent && sent.buttons >= 1, "≥1", JSON.stringify(sent));
    // 用户 2026-10-24：「列表里面 100% 的为什么没有过滤掉」——口径不是一律隐藏（对方还没确认
    // 就不能假装完成），而是**状态必须说清**：这一行的 100% 是"字节已写出"，
    // 右上角必须写「已发出，等对方确认」。
    const wantAck = await cdp.eval(
      "(async () => { const I = await import('/src/i18n/index.ts');"
      + " return I.t('task.state.waitingAck'); })()",
    );
    check("100% 未确认的行状态写「已发出，等对方确认」（不是泛泛的等待中）",
      !!sent && sent.status === wantAck && wantAck.length > 0,
      wantAck, JSON.stringify({ status: sent && sent.status, wantAck }));
    check("消息行给「取消 + 去会话」两颗按钮（cancel_message 已有真命令）",
      !!msg && msg.buttons === 2, "2", JSON.stringify(msg));

    // 半送达的群消息（用户 2026-10-25：「明明还在排队，点取消却说已送达不能取消」）：
    // 行仍要列（"还有 N 人没收到"是真的），但后端已拒绝取消 ⇒ 不给取消键，
    // 状态改说「部分成员已收到」，而不是泛泛的「排队中」。
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore();
      window.__probePartialBefore = chat.messageOps;
      chat.messageOps = [...chat.messageOps, { msg_id: 'm-partial', kind: 'text', peer_id: null,
        group_id: 'g1', waiting_for: 1, created_at: 10, preview: '群里等回复', peer_offline: false,
        can_cancel: false, some_delivered: true }];
      const t = window.__probe.vue; await t.nextTick(); await t.nextTick(); return true;
    })()`);
    const half = await read();
    const halfRow = half.rows.find((r) => r.title === '群里等回复');
    const wantPartial = await cdp.eval(
      "(async () => { const I = await import('/src/i18n/index.ts');"
      + " return I.t('task.state.partial'); })()",
    );
    check("半送达的群消息：状态「部分成员已收到」且只给去会话（不给必失败的取消键）",
      half.rows.length === 7 && !!halfRow && halfRow.status === wantPartial && halfRow.buttons === 1,
      "7 行 / 状态=部分成员已收到 / 1 颗按钮",
      JSON.stringify({ rows: half.rows.map((r) => ({ t: r.title, s: r.status, b: r.buttons })), wantPartial }));
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      S.useChatStore().messageOps = window.__probePartialBefore;
      const t = window.__probe.vue; await t.nextTick(); await t.nextTick(); return true;
    })()`);
    // 排序：要人处理的那一行必须排最前（blocked → running → queued）。
    // 这一段里 blocked 的有三条（peer_offline 的消息最新），所以第一行必须是它。
    check("DOM 顺序 = 读模型的顺序：需要处理的那一行排最前",
      opened.rows[0] && opened.rows[0].title === '在吗',
      "第一行是 peer_offline 的那条消息",
      JSON.stringify(opened.rows.map((r) => r.title)));
    check("已完成那条不在列表里（DOM 与读模型同一口径）",
      opened.rows.some((r) => r.title === '已完成.txt') === false,
      "不含 已完成.txt", JSON.stringify(opened.rows.map((r) => r.title)));

    // 更新下载那一类（B5）：只证明"store 里的可查询状态真的会变成一行 + 一个取消键"。
    // 相位语义（ready/installing 不列）由读模型单测钉，这里只管接线。
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      S.useChatStore().updaterStatus = { phase: 'downloading', downloaded: 40, total: 100,
        version: '9.9.9', error: null };
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return true;
    })()`);
    const withUpdate = await read();
    const updateRow = withUpdate.rows.find((r) => r.title === 'v9.9.9');
    check("更新下载在任务中心里长成一行（目标版本号当标题）",
      withUpdate.rows.length === 7 && !!updateRow,
      "7 行且含 v9.9.9",
      JSON.stringify({ rows: withUpdate.rows.map((r) => r.title) }));
    check("那一行正好一颗「取消」（install 阶段不可取消，所以不是两颗）",
      !!updateRow && updateRow.buttons === 1, "1 颗", JSON.stringify(updateRow));
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      S.useChatStore().updaterStatus = null;
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return true;
    })()`);

    // 长失败原因（2026-11-10 用户实报「文本挤出横向滚动条」）：判死行的整句人话
    // （msg.fail.* 那一族）只能住**详情行**（块级、换行），不许塞进 shrink-0 的状态槽。
    // 量三件事：状态=短标签、详情含整句、面板与行都没有横向溢出。
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore();
      window.__probeFailBefore = chat.messageOps;
      chat.messageOps = [...chat.messageOps, { msg_id: 'm-fail-long', kind: 'text', peer_id: 'p1',
        group_id: null, waiting_for: 0, created_at: 11, preview: null, peer_offline: false,
        can_cancel: false, failed: true, fail_code: 'SEND_RETRY_EXPIRED', some_delivered: false }];
      const t = window.__probe.vue; await t.nextTick(); await t.nextTick(); return true;
    })()`);
    const failRead = await cdp.eval(`(async () => {
      const I = await import('/src/i18n/index.ts');
      const dialog = document.querySelector('[role="dialog"]');
      const ul = dialog && dialog.querySelector('ul');
      const reason = I.t('msg.fail.retryExpired');
      const li = dialog
        ? [...dialog.querySelectorAll('li')].find((x) => (x.textContent || '').includes(reason))
        : null;
      const spans = li ? [...li.querySelectorAll('span')].map((s) => (s.textContent || '').trim()) : [];
      const detail = li
        ? [...li.querySelectorAll('p')].map((p) => (p.textContent || '').trim())
            .find((s) => s.includes(reason)) || ''
        : '';
      return {
        found: !!li,
        status: spans[1] || '',
        detail,
        wantStatus: I.t('task.state.failed'),
        ulScrollW: ul ? ul.scrollWidth : -1,
        ulClientW: ul ? ul.clientWidth : -1,
        liW: li ? Math.round(li.getBoundingClientRect().width) : -1,
      };
    })()`);
    check("判死行：状态槽只有短标签「发送失败」，整句原因住详情行",
      failRead.found === true && failRead.status === failRead.wantStatus
        && failRead.detail.length > 20,
      "status=发送失败 + detail 含整句",
      JSON.stringify(failRead));
    check("判死行：面板没有横向滚动条（长原因不再把卡片撑出列表宽度）",
      failRead.found === true && failRead.ulScrollW <= failRead.ulClientW + 1
        && failRead.liW <= failRead.ulClientW + 1,
      "ul/li 都不横向溢出",
      JSON.stringify(failRead));
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      S.useChatStore().messageOps = window.__probeFailBefore;
      const t = window.__probe.vue; await t.nextTick(); await t.nextTick(); return true;
    })()`);

    // ④b 移动端 390 与关闭：统一放在下面（先关面板，再以共享开关重开一次量宽度）。

    // 「确认了之后，应该是会在后台任务中加入后台任务重新发送」（负责人 2026-10-26）。
    // 读模型那一半有 npm 单测与一次真实变异（把 state 里的 resending 分支摘掉 ⇒ 那条红），
    // 这里量的只剩接线：**那三个字真上屏，而且只上屏在被标记的那一行**，并且不凭空多出一行。
    const wantResending = await cdp.eval(
      "(async () => { const I = await import('/src/i18n/index.ts');"
      + " return I.t('task.state.resending'); })()",
    );
    const marked = await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore();
      chat.markResending('m1');
      const t = window.__probe.vue; await t.nextTick(); await t.nextTick();
      return { ops: chat.operations.length };
    })()`);
    const resendingRows = await read();
    const m1Row = resendingRows.rows.find((r) => r.title === '在吗');
    // 文本选择的默认方向（负责人 2026-10-26）在**真渲染**那一侧的读数：任务中心那一行是界面 chrome，
    // computed 必须是 none。静态判据只看得到 style.css 里那条规则在不在，看不见级联谁压过了谁
    // （同一条规则被内联样式压掉时，静态判据全绿而界面上照样能划选 —— 本仓踩过那一型）。
    const rowSelect = await cdp.eval(`(() => {
      const li = document.querySelector('[role="dialog"] li');
      return li ? getComputedStyle(li).userSelect : null;
    })()`);
    check("★ 任务中心那一行 computed user-select = none（界面 chrome 默认不可选）",
      rowSelect === "none", "none", JSON.stringify({ rowSelect }));

    check("★ 标记「重发中」后任务中心那一行就说「重发中」（只这一行说，行数不变）",
      !!m1Row && m1Row.status === wantResending && wantResending.length > 0
        && resendingRows.rows.filter((r) => r.status === wantResending).length === 1
        && marked && marked.ops === 6,
      "1 行说「重发中」/ ops 仍 6",
      JSON.stringify({
        status: m1Row && m1Row.status, wantResending, ops: marked && marked.ops,
        states: resendingRows.rows.map((r) => r.status),
      }));

    // 关掉面板：点卡片外的遮罩是 Reka 的 outside-pointerdown 那条路。
    // Reka 的遮罩在 after-leave 之后才卸载，而 headless 页面静止时不出帧 ⇒ 必须泵帧。
    const pumpFrames = async (n = 6) => {
      for (let i = 0; i < n; i += 1) {
        await cdp.send("Page.captureScreenshot", { format: "png" }).catch(() => {});
      }
    };
    const closePanel = async () => {
      await cdp.click(60, 400);
      await sleep(600);
      await pumpFrames();
      return read();
    };
    const closed = await closePanel();
    check("点卡片外能把面板关掉（共享开关回到 false）",
      closed.dialog === false, "dialog=false", JSON.stringify({ dialog: closed.dialog }));

    // 390 宽：面板打开也不许把页面撑出横向滚动。
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
    });
    await sleep(400);
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useAppStore.ts');
      S.useAppStore(window.__pinia).openTaskCenter();
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return true;
    })()`);
    const mOpen = await read();
    check("390 宽、面板打开：没有横向溢出，6 行都在",
      mOpen.dialog === true && mOpen.scrollWidth <= 390 && mOpen.rows.length === 6,
      "dialog + scrollWidth ≤ 390 + 6 行",
      JSON.stringify({ dialog: mOpen.dialog, sw: mOpen.scrollWidth, rows: mOpen.rows.length }));
    await closePanel();
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
    });
    await sleep(400);

    // 空态：所有来源都空 ⇒ 面板只剩一句「没有进行中的任务」，不造假行。
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      // 两个实例都清：本页既跑着真实 app（自己那份 pinia），也挂着探针挂载的那份
      // （window.__pinia）。
      const stores = [S.useChatStore()];
      if (window.__pinia) stores.push(S.useChatStore(window.__pinia));
      for (const c of stores) {
        c.transfers = []; c.contentTransfers = []; c.messageOps = []; c.groupHistorySync = {};
        c.updaterStatus = null;
      }
      const T = await import('/src/stores/useAppStore.ts');
      T.useAppStore().openTaskCenter();
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      await new Promise((r) => setTimeout(r, 300));
      return true;
    })()`);
    const empty = await read();
    const emptyText = await cdp.eval(
      "(() => { const d = document.querySelector('[role=\"dialog\"]'); return d ? (d.innerText || '').trim() : ''; })()",
    );
    check("没有未完成任务时面板显示空态（不留 0 件的假行）",
      empty.dialog === true && empty.rows.length === 0 && String(emptyText).length > 0,
      "dialog + 0 行 + 空态文案",
      JSON.stringify({ dialog: empty.dialog, rows: empty.rows.length, text: String(emptyText).slice(0, 40) }));
    await closePanel();

    // 页脚入口：入口属于会话列表，不属于面板。单独挂一次 ConversationList。
    const pkgVersion = JSON.parse(fs.readFileSync(path.join(ROOT, "package.json"), "utf8")).version;
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
    });
    await sleep(300);
    // 先清空后台任务，让「无任务 ⇒ 不渲染数字 pill」的反例自证有确定 preimage。
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      S.useChatStore(window.__pinia).operations = [];
      return true;
    })()`);
    const mountedFooter = await cdp.eval(
      "window.__probe.install('/src/components/ConversationList.vue', '', "
      + JSON.stringify(JSON.stringify({ view: "chats" })) + ")",
    );
    await cdp.eval("(() => { const h = document.getElementById('probe-host'); if (h) h.style.cssText = 'height:760px;display:flex;flex-direction:column;'; return true; })()");
    await sleep(500);
    const readFooter = () => cdp.eval(`(() => {
      const host = document.getElementById('probe-host');
      const entry = host ? host.querySelector('[data-task-entry]') : null;
      if (!host || !entry) return { present: false };
      const r = entry.getBoundingClientRect();
      const footer = entry.closest('div.shrink-0');
      const fr = footer ? footer.getBoundingClientRect() : null;
      return {
        present: true,
        text: host.innerText || '',
        entryText: String(entry.innerText || '').replace(/\s+/g, ' ').trim(),
        // 页脚已从「图标+数字」改成整行入口：数字单独挂 data-task-count，
        // 不再靠 entryText === "1"（那会随"任务中心"这类行内文案变化而空转）。
        count: (() => { const n = entry.querySelector('[data-task-count]'); return n ? String(n.textContent || '').trim() : null; })(),
        aria: entry.getAttribute('aria-label'),
        left: Math.round(r.left), right: Math.round(r.right),
        height: Math.round(r.height),
        footerBottom: fr ? Math.round(fr.bottom) : null,
        vw: innerWidth, vh: innerHeight, sw: document.documentElement.scrollWidth,
      };
    })()`);
    const foot = await readFooter();
    check("会话列表页脚有任务入口（不再是浮动药丸）",
      mountedFooter && mountedFooter.ok === true && foot.present === true,
      "data-task-entry 存在", JSON.stringify({ mounted: !!mountedFooter, foot }));
    // 用户 2026-11-06 决策：版本号从页脚移到设置「关于」，页脚只留 42px 的「任务中心 · N」。
    // 反例自证：把版本号 span 加回页脚，下面这条立刻红（pkgVersion 仍在读，别删）。
    check("页脚不再显示版本号（反例：版本号加回页脚就红）",
      foot.present && !String(foot.text).includes(`v${pkgVersion}`),
      `不含 v${pkgVersion}`, JSON.stringify({ head: String(foot.text).slice(-80), pkgVersion }));
    check("页脚入口高 42px（画板 listFoot 收紧）",
      foot.present && foot.height === 42,
      "height=42", JSON.stringify({ height: foot.height }));
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore(window.__pinia);
      chat.messageOps = [{ msg_id: 'm-footer', kind: 'text', peer_id: 'p1', group_id: null,
        waiting_for: 1, created_at: 1, preview: '页脚入口', peer_offline: true,
        can_cancel: true, some_delivered: false }];
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return chat.operations.length;
    })()`);
    const counted = await readFooter();
    // 反例自证：0 件时页脚不得渲染数字 pill —— 若 `data-task-count` 被写成常驻节点，
    // 上面那次 `foot` 读数就会拿到 "0"/空串而不是 null，这条判据随即变红。
    check("页脚无任务时不渲染数字 pill（反例自证）",
      foot.present && foot.count === null,
      "count=null", JSON.stringify({ count: foot.count }));
    check("页脚入口带未完成数（与面板同一份读模型）",
      counted.present && counted.count === "1",
      "计数=1", JSON.stringify({ count: counted.count, entryText: counted.entryText }));
    // 形如「任务中心 · 1」（分隔符带空格，数字在末尾）。英文词典下前缀不同，但形状一致。
    check("页脚文案是「任务中心 · N」",
      counted.present && /\s·\s1$/.test(counted.entryText),
      "末段「· 1」", JSON.stringify({ entryText: counted.entryText }));

    // 点页脚入口 → 共享开关打开（面板与入口读同一个 ref）。
    const entryPoint = { x: Math.round((counted.left + counted.right) / 2), y: 0 };
    const entryY = await cdp.eval(`(() => {
      const h = document.getElementById('probe-host');
      const e = h ? h.querySelector('[data-task-entry]') : null;
      if (!e) return null;
      const r = e.getBoundingClientRect();
      return Math.round(r.top + r.height / 2);
    })()`);
    if (entryY !== null) {
      await cdp.click(entryPoint.x, entryY);
      await sleep(200);
    }
    const openedByEntry = await cdp.eval(
      "(async () => { const T = await import('/src/stores/useAppStore.ts'); return T.useAppStore().taskCenterOpen; })()",
    );
    check("点页脚入口打开共享任务面板", openedByEntry === true, "open=true", JSON.stringify({ openedByEntry }));

    // 390 宽：页脚必须整体在 TabBar 之上（`--gosslan-mobile-tabbar-h`），且不横向溢出。
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
    });
    await sleep(500);
    await cdp.eval("(() => { const h = document.getElementById('probe-host'); if (h) h.style.cssText = 'height:820px;display:flex;flex-direction:column;'; return true; })()");
    // 真实 App 由 `applyIsMobile()` 给 <html> 打 `is-mobile`；探针夹具没有 init，
    // 这里显式补上，让页脚与布局读同一条判据。
    await cdp.eval("document.documentElement.classList.add('is-mobile')");
    // 探针的 pinia 建在 1280 宽，`isMobile` 不会自己跟着视口变（真实 App 由 init 的
    // matchMedia 维护）⇒ 这里显式切到移动布局，量与线上同一条分支。
    await cdp.eval(`(async () => {
      const A = await import('/src/stores/useAppStore.ts');
      const a = A.useAppStore();
      a.isMobile = true;
      a.keyboardOpen = false;
      const t = window.__probe.vue;
      await t.nextTick(); await t.nextTick();
      return a.isMobile;
    })()`);
    await sleep(300);
    const mobileFoot = await readFooter();
    const tabbar = await cdp.eval(
      "String(getComputedStyle(document.documentElement).getPropertyValue('--gosslan-mobile-tabbar-h')).trim()",
    );
    const tabbarPx = /rem$/.test(String(tabbar))
      ? (parseFloat(String(tabbar)) || 4) * 16
      : parseFloat(String(tabbar)) || 64;
    check("390 宽：页脚在 TabBar 之上（不会被固定底栏盖住）",
      mobileFoot.present && mobileFoot.footerBottom !== null
        && mobileFoot.footerBottom <= 820 - tabbarPx + 2,
      `footerBottom ≤ ${Math.round(820 - tabbarPx + 2)}`,
      JSON.stringify({ footerBottom: mobileFoot.footerBottom, tabbar, vh: mobileFoot.vh }));
    check("390 宽：页脚不横向溢出",
      mobileFoot.present && mobileFoot.sw <= 390,
      "scrollWidth ≤ 390", JSON.stringify({ sw: mobileFoot.sw }));

    // ── 「去会话」这一发到底成不成（负责人 2026-10-26：「群明明在，点去会话弹『没能打开会话』」）──
    // TaskCenter 打开之后要核对"确实打开了"，而它读的三份都是**本机快照**：会话行、群清单、
    // 两个 loaded 旗标。"我这份快照里看不见"与"它不存在"是两件事 —— 三格把形状分开量：
    //   A 会话行与群都在快照里（正常态，回归网）；
    //   B 群在、会话行还没有（`openConversation` 自己会补建 ⇒ 也不该报失败）；
    //   C 群**在真源里**（getGroups/getConversations 都返回它），但本机快照还没到位 ——
    //     今天这一格弹的就是用户看到的那句「没能打开会话」；修完之后必须到达。
    // 判据不读 toast（探针挂的是裸组件，页面里没有 ToastProvider ⇒ 那句提示不会进 DOM），
    // 而是**用 TaskCenter 同一份输入现算它那个失败条件**：条件为真 ⇔ 用户看到那句报错。
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
    });
    const jumpGid = "g-probe-open";
    const jumpCid = `group:${jumpGid}`;
    const jumpConv = {
      id: jumpCid, kind: "group", name: "探针群", avatar: null, last_msg: "在吗",
      last_ts: 1, unread: 0, mentioned: 0, pinned: 0, muted: 0,
    };
    const jumpGroup = { id: jumpGid, name: "探针群", creator: "dev-me", members: ["dev-me", "p1"] };
    const jumpOnce = async (shape) => {
      // 每种形状重新挂一次面板（install 会清 body ⇒ 上一格的 DOM 不残留）。
      await cdp.eval("window.__probe.install('/src/components/TaskCenter.vue', '', '')");
      await cdp.eval("window.__probe.seedDevice('dev-me')");
      const seeded = await cdp.eval(`(async () => {
        const S = await import('/src/stores/useChatStore.ts');
        const chat = S.useChatStore();
        const conv = ${JSON.stringify(jumpConv)};
        const grp = ${JSON.stringify(jumpGroup)};
        chat.conversations = ${shape === "A" ? "[conv]" : "[]"};
        chat.groups = ${shape === "A" || shape === "B" ? "[grp]" : "[]"};
        chat.groupsLoaded = ${shape === "C" ? "false" : "true"};
        chat.conversationsLoaded = ${shape === "C" ? "false" : "true"};
        chat.friendsLoaded = ${shape === "C" ? "false" : "true"};
        chat.activeConv = null;
        chat.messageOps = [{ msg_id: 'm-jump', kind: 'text', peer_id: 'p1', group_id: ${JSON.stringify(jumpGid)},
          waiting_for: 1, created_at: 1, preview: '在吗', peer_offline: true, can_cancel: true, some_delivered: false }];
        const A = await import('/src/stores/useAppStore.ts');
        A.useAppStore().openTaskCenter();
        const t = window.__probe.vue; await t.nextTick(); await t.nextTick();
        const row = chat.operations.find((r) => r.id === 'm-jump') || null;
        return { convId: row ? row.convId : null, actions: row ? row.actions.join(',') : '' };
      })()`);
      // 真源（后端）在三种形状里都说"这个群在"：只有愿意去读一次的那一格才拿得到答案。
      for (const [name, payload] of [
        ["getMessages", []],
        ["markRead", null],
        ["ensureConversation", jumpConv],
        ["getConversations", [jumpConv]],
        ["getGroups", [jumpGroup]],
        ["getFriends", []],
        ["getPendingMessageOperations", []],
        ["getTransfers", []],
        ["getContentTransfers", []],
      ]) {
        await cdp.eval(`window.__probe.stubApi(${JSON.stringify(name)}, ${JSON.stringify(payload)})`);
      }
      // ★ 定点等，不死睡：等到那颗按钮真的画出盒子（getClientRects 非空）为止，预算 2 秒。
      // 起因是实测两红两绿（2026-10-26）：原来这里是固定 sleep(250) 后一次读几何，机器被别的
      // 事压住时 Reka 的 DialogContent 那一帧还没布局好 ⇒ 形状 A 偶发报「找不到去会话按钮」。
      // 变量是负载，不是段相邻（同一对段单独跑也全绿过；openBefore 一直是 true ⇒ 面板本来就开着，
      // 缺的是那一帧布局）。等待型判据要等"写值的那一方"，这里写值的是布局本身 ⇒ 按条件轮询，
      // 并把实际等了多久带进负载：等满预算还找不到 = 真有缺陷。
      const findJumpButton = `(async () => {
        const A = await import('/src/stores/useAppStore.ts');
        const openBefore = A.useAppStore().taskCenterOpen;
        const I = await import('/src/i18n/index.ts');
        const want = I.t('task.openChat');
        const b = Array.from(document.querySelectorAll('[role="dialog"] button'))
          .find((x) => (x.textContent || '').trim() === want && x.getClientRects().length > 0);
        if (!b) return { found: false, want, openBefore };
        const r = b.getBoundingClientRect();
        return { found: true, openBefore, x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
      })()`;
      const tFind = Date.now();
      let loc = null;
      for (;;) {
        loc = await cdp.eval(findJumpButton);
        if (loc && loc.found) break;
        if (Date.now() - tFind >= 2000) break;
        await sleep(50);
      }
      if (loc) loc.waitedMs = Date.now() - tFind;
      if (loc && loc.found) {
        loc.at = await cdp.eval(`(() => {
          const el = document.elementFromPoint(${loc.x}, ${loc.y});
          const d = el && el.closest('[role="dialog"]');
          return { tag: el && el.tagName, inDialog: !!d, state: d && d.getAttribute('data-state') };
        })()`);
      }
      if (!loc || !loc.found) {        // 找不到按钮时把弹窗里真实渲染出来的文字带回去：下次再红能直接看到是
        // "面板没开 / 行没画 / 文案变了" 中的哪一种，不用再猜。
        const dom = await cdp.eval(`(() => {
          const d = document.querySelector('[role="dialog"]');
          return {
            hasDialog: !!d,
            buttons: [...document.querySelectorAll('[role="dialog"] button')]
              .map((b) => (b.textContent || '').trim()).filter(Boolean).slice(0, 12),
            head: d ? (d.textContent || '').replace(/\\s+/g, ' ').trim().slice(0, 160) : '',
          };
        })()`);
        return { ok: false, why: "button", loc, seeded, dom };
      }
      // 等**布局稳了**再点：down 与 up 之间面板还会长出迟到的一行（昵称/详情异步补齐）
      // 或 Reka DialogContent 开场 transform 还没走完 —— rect 刚非空时坐标在飘，
      // down 落在按钮上、up 已飘到 li，click 永远合不成（2026-11-11 实测 clickLog：
      // down=BUTTON / up=LI；这也是"形状 A 偶发找不到按钮"的同族根因）。
      // 判据 = 按钮矩形**连续两次读数完全一致**（预算 2.5s），才按最后一次矩形中心点下去。
      const rectOf = `(async () => {
        const I = await import('/src/i18n/index.ts');
        const want = I.t('task.openChat');
        const b = [...document.querySelectorAll('[role="dialog"] button')]
          .find((x) => (x.textContent || '').trim() === want);
        if (!b) return null;
        const r = b.getBoundingClientRect();
        return JSON.stringify([r.left, r.top, r.width, r.height].map(Math.round));
      })()`;
      let prevRect = null;
      let finalRect = null;
      const tStable = Date.now();
      for (;;) {
        const got = await cdp.eval(rectOf);
        if (got && got === prevRect) { finalRect = got; break; }
        prevRect = got;
        if (Date.now() - tStable >= 2500) break;
        await sleep(120);
      }
      loc.stableMs = Date.now() - tStable;
      if (!finalRect) return { ok: false, why: "button-unstable", loc, seeded };
      const [rx, ry, rw, rh] = JSON.parse(finalRect);
      loc.x = rx + Math.floor(rw / 2);
      loc.y = ry + Math.floor(rh / 2);
      await cdp.click(loc.x, loc.y);
      await sleep(1500);
      const after = await cdp.eval(`(async () => {
        const S = await import('/src/stores/useChatStore.ts');
        const chat = S.useChatStore();
        const real = {
          active: chat.activeConv,
          rowVisible: chat.conversations.some((c) => c.id === ${JSON.stringify(jumpCid)}),
          groupVisible: chat.groups.some((g) => g.id === ${JSON.stringify(jumpGid)}),
          groupsLoaded: chat.groupsLoaded,
          conversationsLoaded: chat.conversationsLoaded,
        };
        return real;
      })()`);
      // 与 TaskCenter.vue 那一格同一份条件（"我看不见"被当成"它不存在"就是从这里出去的）。
      const failCondition = after.active !== jumpCid || (!after.rowVisible && !after.groupVisible);
      return { ok: true, seeded, after, failCondition, waitedMs: loc.waitedMs, loc };
    };
    // ⚠️ 这三格只判**store 那一半**（到达 + 不报"不存在"）。"屏幕换没换"的另一半权威是路由
    //   （`navState = navOfRoute()`），但探针**判不了它**：给挂载的组件挂上应用那份 mainRouter
    //   实例之后，同页里真实应用与探针应用共用同一个 router 与两套 pinia，实测把隔壁格子的
    //   `chat.operations` 从 6 读成 1、面板行数对不上（2026-10-26 试过，读数在 CHANGELOG）。
    //   所以路由那一半改由 `utils/taskCenterJump.test.ts` 钉接线，别在这里再试一次。
    for (const shape of ["A", "B", "C"]) {
      const r = await jumpOnce(shape);
      check(`★ 任务中心「去会话」形状 ${shape}：群在真源里就必须到达，不许弹「没能打开会话」`,
        r.ok === true && !!r.seeded && r.seeded.convId === jumpCid && r.failCondition === false,
        "到达 group:<gid> 且失败条件为假", JSON.stringify(r));
    }
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 二次确认框（`ConfirmDialog`）的读数与"过一遍确认"的动作 —— **module-level 的家**，
 * 因为 `resend` 与 `delivery` 两段都要它（同一份"点重发先弹框"的契约，不许在第二段抄一遍）。
 *
 * 负责人 2026-10-26："点了之后，它会有个二次确认"。读三样：正文有没有上屏、确认键与取消键的坐标。
 * 按**文本**认，不按 DOM 形状认（页脚两颗键的形状是 ConfirmDialog 自己的事，改样式不该让这段跟着瞎）。
 */
async function confirmBox(cdp) {
  return cdp.eval(`(async () => {
    const { t } = await import('/src/i18n/index.ts');
    const vis = (el) => !!el && el.getClientRects().length > 0;
    const byText = (want) => [...document.querySelectorAll('button')]
      .filter((b) => vis(b) && (b.textContent || '').trim() === want)[0] || null;
    const centre = (el) => {
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    };
    const ok = byText(t('common.confirm'));
    const cancel = byText(t('common.cancel'));
    const body = [...document.querySelectorAll('p')]
      .find((p) => vis(p) && (p.textContent || '').trim() === t('msg.resendConfirm')) || null;
    return { body: !!body, ok: ok ? centre(ok) : null, cancel: cancel ? centre(cancel) : null };
  })()`);
}

/** 点重发 ⇒ 先出确认框 ⇒ 再点确认。返回确认框的读数（要吃它的那格自己断言）。 */
async function confirmGate(cdp, x, y) {
  await cdp.click(x, y);
  await sleep(400);
  const box = await confirmBox(cdp);
  if (box && box.ok) await cdp.click(box.ok.x, box.ok.y);
  await sleep(600);
  return box;
}

/**
 * 「发送失败 / 已取消之后那颗重发」的运行时判据（负责人 2026-10-23："可以有个重试/再次发送…
 * 可打断 可恢复 可取消这种都应该有"）。
 *
 * 这一段判的是**走的是哪条通道**，不是"按钮在不在"：
 * 图片以前漏在 `retryable` 与 `retrySend` 两处的缝里（两处都只排除 `file`），失败的图片被按
 * 普通消息重发了一份 JSON 载荷 ⇒ 对端收到"有名字没有字节"的一张图、本机还转成绿色。
 * 静态判据只能证明"引了这个函数"，**"点一下到底打到哪条命令"只能在这里量**：
 * 用 `H.stubApi` 把两条命令各换一个计数替身，真按一次回执那颗，读调用次数。
 *
 * 附件已被存储清理那一格也在这里判：那时必须**没有**按钮（不给一颗点了没反应的键 = 界面不撒谎）。
 */
async function runResend(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  const IMG_META = JSON.stringify({ name: "白板照片.png", size: 2048, path: "/tmp/probe-a.png", subtype: "image", sha256: "b".repeat(64) });

  /** 真挂一次消息行（props 由页面里那份对象给出），并返回那颗重发的坐标。 */
  const mountAndLocate = async (over) => {
    const msg = Object.assign({
      id: -1, msg_id: "m-rs-1", sender_id: "dev-me", receiver_id: "p1", conv_id: "p1",
      kind: "image", content: IMG_META, ts: 1700000000000, seq: 1, status: "failed",
    }, over);
    const mounted = await cdp.eval("window.__probe.install('/src/components/MessageItem.vue', '', "
      + JSON.stringify(JSON.stringify({ message: msg, isGroup: false, senderName: "我" })) + ")");
    if (!mounted || mounted.ok !== true) return { ok: false, why: "install", mounted };
    const seeded = await cdp.eval("window.__probe.seedDevice('dev-me')");
    if (!seeded || seeded.ok !== true) return { ok: false, why: "seedDevice", seeded };
    await sleep(250);
    const btn = await cdp.eval(`(async () => {
      const I = await import('/src/i18n/index.ts');
      const want = I.t('msg.resend');
      const hit = Array.from(document.querySelectorAll('button'))
        .find((b) => b.getAttribute('aria-label') === want && b.getClientRects().length > 0);
      if (!hit) return { found: false, want: want };
      const r = hit.getBoundingClientRect();
      return { found: true, want: want, x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    })()`);
    return { ok: true, btn };
  };

  /** 每条被点的命令都换成"只计数"的替身；顺带把 store 刷新链上那三条读命令兜住。 */
  const stubAll = async () => {
    for (const [name, payload] of [
      ["sendFileAuto", "t-resend-1"],
      ["sendGroupFile", "t-resend-2"],
      ["sendMessage", { msg_id: "m-rs-new", conv_id: "p1", sender_id: "dev-me", kind: "text", content: "hi", ts: 1700000000001, seq: 2, status: "sending" }],
      ["getTransfers", []],
      ["getContentTransfers", []],
      ["getPendingMessageOperations", []],
      ["mediaPresent", true],
    ]) {
      await cdp.eval(`window.__probe.stubApi(${JSON.stringify(name)}, ${JSON.stringify(payload)})`);
    }
    return true;
  };
  const calls = async (name) => cdp.eval(`window.__probe.apiCalls(${JSON.stringify(name)})`);

  // ── ① 失败的**图片**：必须回文件通道，而不是 send_message ──────────────
  await stubAll();
  const a = await mountAndLocate({});
  check("失败图片这行挂出来了，回执那颗是可点的（可访问名 = msg.resend）",
    a.ok === true && a.btn && a.btn.found === true, "found=true", JSON.stringify(a));
  if (a.ok && a.btn && a.btn.found) {
    await cdp.click(a.btn.x, a.btn.y);
    await sleep(400);
    const box = await confirmBox(cdp);
    const early = await calls("sendFileAuto");
    check("★ 点重发先出二次确认，且**这一步还没有**把命令发出去（旧形态点一下就静默开跑，用户读作没反应）",
      !!box && box.body === true && !!box.ok && early === 0,
      "确认框正文上屏 + 有确认键 + sendFileAuto=0", JSON.stringify({ box, early }));
    if (box && box.ok) await cdp.click(box.ok.x, box.ok.y);
    await sleep(600);
    const file = await calls("sendFileAuto");
    const text = await calls("sendMessage");
    check("★ 点失败图片的重发 ⇒ 走 send_file_auto（恰好一次）",
      file === 1, "sendFileAuto=1", JSON.stringify({ file }));
    check("★ 同一下点击**没有**走 send_message（旧那步把 JSON 载荷当普通消息发出去 = 假成功）",
      text === 0, "sendMessage=0", JSON.stringify({ text }));
  } else {
    check("★ 点重发先出二次确认，且**这一步还没有**把命令发出去（旧形态点一下就静默开跑，用户读作没反应）", false,
      "先要那颗按钮存在", JSON.stringify(a));
    check("★ 点失败图片的重发 ⇒ 走 send_file_auto（恰好一次）", false,
      "先要那颗按钮存在", JSON.stringify(a));
    check("★ 同一下点击**没有**走 send_message（旧那步把 JSON 载荷当普通消息发出去 = 假成功）", false,
      "上一格没成立，这一格没作用点", JSON.stringify(a));
  }

  // ── ② 已取消的图片也要能再发（负责人点名"取消了"那一格）────────────────
  await stubAll();
  const b = await mountAndLocate({ msg_id: "m-rs-2", status: "cancelled" });
  check("已取消的图片行也长出可点的重发（取消不是错误，但同样要能恢复）",
    b.ok === true && b.btn && b.btn.found === true, "found=true", JSON.stringify(b));
  // 用户 2026-10-25：旧图标是一道「禁止」斜线（Ban），看不出"这条没发出去、已经停了"。
  // 新图标是红色圆形感叹号（AlertCircle = 圆 + 竖线 + 点，共 1 圆 2 线）。
  const iconShape = await cdp.eval(`(async () => {
    const { t } = await import('/src/i18n/index.ts');
    const label = t('msg.resend');
    const btn = [...document.querySelectorAll('button')]
      .find((x) => (x.getAttribute('aria-label') || '') === label);
    if (!btn) return null;
    const svg = btn.querySelector('svg');
    const probe = document.createElement('span');
    probe.style.color = 'var(--gosslan-danger-ink)';
    document.body.appendChild(probe);
    const expected = getComputedStyle(probe).color;
    probe.remove();
    return {
      circles: svg ? svg.querySelectorAll('circle').length : 0,
      lines: svg ? svg.querySelectorAll('line').length : 0,
      color: getComputedStyle(btn).color,
      expected,
    };
  })()`);
  check("重发标记是红色圆形感叹号（AlertCircle：1 圆 2 线 + danger 色）",
    !!iconShape && iconShape.circles === 1 && iconShape.lines === 2
      && iconShape.color === iconShape.expected,
    "1 circle + 2 lines + danger-ink 色", JSON.stringify(iconShape));
  if (b.ok && b.btn && b.btn.found) {
    const boxB = await confirmGate(cdp, b.btn.x, b.btn.y);
    check("点它 ⇒ 同样走 send_file_auto", (await calls("sendFileAuto")) === 1,
      "sendFileAuto=1（要先过二次确认）", JSON.stringify({ file: await calls("sendFileAuto"), boxB }));
  } else {
    check("点它 ⇒ 同样走 send_file_auto", false, "先要那颗按钮存在", JSON.stringify(b));
  }

  // ── ③ 群里的失败文件 ⇒ 必须走群文件那条命令，而不是单聊那条 ─────────────
  await stubAll();
  const c = await mountAndLocate({
    msg_id: "gfile-1", conv_id: "group:g1", kind: "file", status: "failed",
  });
  const cOk = c.ok === true && c.btn && c.btn.found;
  if (cOk) {
    await confirmGate(cdp, c.btn.x, c.btn.y);
    const grp = await calls("sendGroupFile");
    const dm = await calls("sendFileAuto");
    check("群文件失败后重发走 send_group_file（而不是把群会话当对端去 send_file_auto）",
      grp === 1 && dm === 0, "sendGroupFile=1 / sendFileAuto=0", JSON.stringify({ grp, dm }));
  } else {
    check("群文件失败后重发走 send_group_file（而不是把群会话当对端去 send_file_auto）", false,
      "先要那颗按钮存在", JSON.stringify(c));
  }

  // ── ④ 载荷里没有路径 ⇒ 不许有按钮（没有可发的字节 = 给了就是界面在撒谎）──
  // ⚠️ 这一格刻意用"content 里没有 path"，**不是**用 mediaPresent=false：
  // 失败的**图片**行今天拿不到可达性信号（`previewSubtype` 在 failed 时直接返回 null，
  // 而 `shouldProbePresence` 只给 subtype=file 那份探测 ⇒ 两路都不跑，`attachmentMissing` 恒 false）。
  // 所以"附件已被存储清理"那一档今天量不到（点它会由后端报错、走 sendFileTo 那条失败 toast，
  // 不是静默成功）；要收那一格得动 `shouldProbePresence` 那条共享判据，不在本批顺手做。
  await stubAll();
  const d = await mountAndLocate({
    msg_id: "m-rs-4",
    content: JSON.stringify({ name: "白板照片.png", size: 2048, subtype: "image" }),
  });
  check("★ 载荷里没有 path ⇒ 那颗重发不渲染（没有可发的字节就不给按钮）",
    d.ok === true && d.btn && d.btn.found === false, "found=false", JSON.stringify(d));

  // ── ⑤ 文本失败：走 resend_message（复用原 msg_id），不再新建一条 ───────
  await stubAll();
  await cdp.eval(`window.__probe.stubApi('resendMessage', ${JSON.stringify({
    id: 5, msg_id: "m-rs-5", conv_id: "p1", sender_id: "dev-me", receiver_id: "p1",
    kind: "text", content: "在吗", ts: 1700000000000, seq: 1, status: "sent",
  })})`);
  const e = await mountAndLocate({ msg_id: "m-rs-5", kind: "text", content: "在吗" });
  if (e.ok === true && e.btn && e.btn.found) {
    await confirmGate(cdp, e.btn.x, e.btn.y);
    check("★ 文本失败重发走 resend_message（复用原 msg_id），且不新建消息",
      (await calls("resendMessage")) === 1 && (await calls("sendMessage")) === 0
        && (await calls("sendFileAuto")) === 0,
      "resendMessage=1 / sendMessage=0 / sendFileAuto=0",
      JSON.stringify({
        resend: await calls("resendMessage"),
        text: await calls("sendMessage"),
        file: await calls("sendFileAuto"),
      }));
  } else {
    check("★ 文本失败重发走 resend_message（复用原 msg_id），且不新建消息", false,
      "先要那颗按钮存在", JSON.stringify(e));
  }

  // ── b 文字气泡那一侧的默认方向：正文必须仍然可选（"单独开启"的那一半）──────
  // 挂的就是上面那条文本消息（`kind: "text"`，正文层 `.gosslan-selectable`）。
  // 读的是 computed，不是类名：全局 `html { user-select: none }` 加进来之后，
  // 开启面靠的是元素自己的声明赢过继承 —— 只有算出来的值能证明这件事真的成立。
  const bubbleSelect = await cdp.eval(`(() => {
    const body = document.querySelector('.gosslan-bubble-text .gosslan-selectable');
    const root = document.querySelector('.gosslan-bubble-text');
    return {
      body: body ? getComputedStyle(body).userSelect : null,
      root: root ? getComputedStyle(root).userSelect : null,
    };
  })()`);
  check("★ 文字气泡正文 computed user-select = text（默认关闭之后仍要单独开得回来）",
    bubbleSelect && bubbleSelect.body === "text" && bubbleSelect.root === "text",
    "正文与气泡根都是 text", JSON.stringify(bubbleSelect));

  // ── ⑥ 确认框里点「取消」⇒ 一条命令都不许发 ────────────────────────────
  // 二次确认不是"多点一下"的装饰：确认键才是动手的那一步，取消必须真的什么都不做。
  // 这一格和 ① 是一对：① 证明"没确认之前没发"，这一格证明"确认被撤回之后也没发"。
  await stubAll();
  await cdp.eval(`window.__probe.stubApi('resendMessage', ${JSON.stringify({
    id: 6, msg_id: "m-rs-6", conv_id: "p1", sender_id: "dev-me", receiver_id: "p1",
    kind: "text", content: "在吗", ts: 1700000000000, seq: 1, status: "sent",
  })})`);
  const f = await mountAndLocate({ msg_id: "m-rs-6", kind: "text", content: "在吗" });
  if (f.ok === true && f.btn && f.btn.found) {
    await cdp.click(f.btn.x, f.btn.y);
    await sleep(400);
    const box = await confirmBox(cdp);
    if (box && box.cancel) await cdp.click(box.cancel.x, box.cancel.y);
    await sleep(500);
    const after = await confirmBox(cdp);
    const n = await calls("resendMessage");
    check("★ 确认框里点「取消」⇒ 不发命令，且框自己收起来",
      n === 0 && !!box && !!box.cancel && !!after && after.body === false,
      "resendMessage=0 + 确认框消失", JSON.stringify({ n, box, after }));
  } else {
    check("★ 确认框里点「取消」⇒ 不发命令，且框自己收起来", false,
      "先要那颗按钮存在", JSON.stringify(f));
  }

  // ── ⑦ 失败的那一颗必须说得出**为什么**（DB v14→v15 的 messages.fail_code）───
  // 静态判据只能证明"源码里读了那一列"；"库里的码真变成悬浮文案"只有 computed/DOM 读数能证明。
  // 两格是同一份挂载的 A/B：只差 `fail_code` 这一列 —— 另一侧（没码）就是通用回落，
  // 它也必须被量到，否则"永远走带原因那一支"的 bug 在这一段是看不见的。
  const readTitle = async () => cdp.eval(`(async () => {
    const { t } = await import('/src/i18n/index.ts');
    const btn = [...document.querySelectorAll('button')]
      .find((x) => (x.getAttribute('aria-label') || '') === t('msg.resend') && x.getClientRects().length > 0);
    if (!btn) return null;
    return { title: btn.getAttribute('title') || '', aria: btn.getAttribute('aria-label') || '' };
  })()`);
  await stubAll();
  const withCode = await mountAndLocate({
    msg_id: "m-rs-7", kind: "text", content: "在吗", fail_code: "SEND_PEER_DELETED",
  });
  const tWith = withCode.ok && withCode.btn && withCode.btn.found ? await readTitle() : null;
  check("★ 有 fail_code ⇒ 失败那颗的悬浮文案带上原因（且码本身绝不上屏）",
    !!tWith && tWith.title.includes("好友") && !tWith.title.includes("SEND_")
      && tWith.title.includes("重新发送"),
    "含『好友』+ 含『重新发送』+ 不含 SEND_", JSON.stringify({ tWith, at: withCode }));

  await stubAll();
  const noCode = await mountAndLocate({ msg_id: "m-rs-8", kind: "text", content: "在吗" });
  const tWithout = noCode.ok && noCode.btn && noCode.btn.found ? await readTitle() : null;
  check("★ 没有 fail_code（v15 之前的老行 / 文件那一族）⇒ 回落到通用『发送失败』，不许空白或裸码",
    !!tWithout && tWithout.title.startsWith("发送失败 · ") && !tWithout.title.includes("SEND_"),
    "『发送失败 · 重新发送』", JSON.stringify({ tWithout, at: noCode }));
  // 名字不跟着变长：读屏用户按到它时听到的是动作，不是一句越来越长的解释。
  check("★ 加了原因之后 aria-label 仍然只有动作『重新发送』（label=动作、title=说明这条分工不许漂）",
    !!tWith && !!tWithout && tWith.aria === "重新发送" && tWithout.aria === "重新发送",
    "aria-label 两处都 = 重新发送", JSON.stringify({ a: tWith?.aria, b: tWithout?.aria }));
}

/**
 * 群消息的成员级投递台账角标 + 「按成员补发」（2026-10-25，Stage 3B）。
 *
 * 钉三件事：
 * ① 角标只说**台账里的数**（已收到 N/M · 失败/取消的人数），全部送达时完全不出现；
 * ② 部分送达/已取消那一格的「重发」按钮点下去走 `resend_group_delivery`，
 *    不是 `send_message` / `resend_message`（后两者会把群会话当单聊对端）；
 * ③ 那一格在视觉上看得见（warning 色），不是"只有一个静态图标"。
 */
async function runDelivery(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  /** 挂一条群消息，并把那一格台账写进 store（组件只读 store，不许自己推）。 */
  const mount = async (msgOver, delivery) => {
    const msg = Object.assign({
      id: -1, msg_id: "gm-probe", sender_id: "dev-me", receiver_id: "g1",
      conv_id: "group:g1", kind: "text", content: "群里等回复",
      ts: 1700000000000, seq: 1, status: "partial_cancelled",
    }, msgOver);
    const mounted = await cdp.eval("window.__probe.install('/src/components/MessageItem.vue', '', "
      + JSON.stringify(JSON.stringify({ message: msg, isGroup: true, senderName: "我" })) + ")");
    if (!mounted || mounted.ok !== true) return { ok: false, why: "install", mounted };
    await cdp.eval("window.__probe.seedDevice('dev-me')");
    await cdp.eval(`(async () => {
      const S = await import('/src/stores/useChatStore.ts');
      const chat = S.useChatStore();
      chat.groupDeliveries['group:g1'] = ${JSON.stringify(delivery ? { [delivery.msg_id]: delivery } : {})};
      return true;
    })()`);
    await sleep(300);
    return { ok: true };
  };

  const readBadge = () => cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const el = document.querySelector('[data-delivery]');
    const btn = Array.from(document.querySelectorAll('button'))
      .find((b) => b.getAttribute('aria-label') === I.t('msg.resend') && b.getClientRects().length > 0);
    const r = btn && btn.getBoundingClientRect();
    return {
      text: el ? el.textContent.trim() : null,
      title: el ? el.getAttribute('title') : null,
      retry: !!btn,
      retryPoint: r ? { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) } : null,
      expectPending: I.t('msg.delivery.pending', { delivered: 2, total: 3 }),
      expectCancelled: I.t('msg.delivery.cancelled', { delivered: 2, cancelled: 1 }),
      expectDetail: I.t('msg.delivery.detail', { delivered: 2, pending: 0, cancelled: 1, failed: 0 }),
      expectFailed: I.t('msg.delivery.failed', { failed: 2 }),
    };
  })()`);

  /** 每条被点的命令都换成"只计数"的替身。 */
  const stubAll = async () => {
    for (const [name, payload] of [
      ["resendGroupDelivery", { outcome: "resent", online: 1, offline: 1, remaining: 1 }],
      ["resendMessage", { msg_id: "gm-probe", conv_id: "group:g1", sender_id: "dev-me", kind: "text", content: "x", ts: 1, seq: 1, status: "sent" }],
      ["sendMessage", { msg_id: "m-new", conv_id: "group:g1", sender_id: "dev-me", kind: "text", content: "x", ts: 1, seq: 1, status: "sending" }],
      ["sendGroupMessage", { msg_id: "m-new-g", conv_id: "group:g1", sender_id: "dev-me", kind: "text", content: "x", ts: 1, seq: 1, status: "sending" }],
      ["getTransfers", []],
      ["getContentTransfers", []],
      ["getPendingMessageOperations", []],
    ]) {
      await cdp.eval(`window.__probe.stubApi(${JSON.stringify(name)}, ${JSON.stringify(payload)})`);
    }
    return true;
  };
  const calls = async (name) => cdp.eval(`window.__probe.apiCalls(${JSON.stringify(name)})`);
  const events = async () => cdp.eval("window.__probe.events.slice()");

  // ── ① 全部送达的墓碑已被后端清掉 ⇒ 角标不出现 ─────────────────────────
  await stubAll();
  const a = await mount({ msg_id: "gm-probe", status: "delivered" }, null);
  const ra = a.ok ? await readBadge() : null;
  check("全部送达（无台账行）时气泡旁不挂常驻数字", a.ok === true && ra && ra.text === null,
    "text=null", JSON.stringify({ a, ra }));

  // ── ② 还有成员没收：说进度（已收到 2/3）──────────────────────────────
  const b = await mount({ msg_id: "gm-probe", status: "sent" },
    { msg_id: "gm-probe", delivered: 2, pending: 1, cancelled: 0, failed: 0 });
  const rb = b.ok ? await readBadge() : null;
  check("★ 还有 1 人没收 ⇒ 角标说「已收到 2/3」（数字只来自台账）",
    b.ok === true && rb && rb.text === rb.expectPending, "text=已收到 2/3",
    JSON.stringify({ rb }));

  // ── ③ 部分送达后被取消：角标有结论、重发可点，且走按成员补发 ──────────
  const c = await mount({ msg_id: "gm-probe", status: "partial_cancelled" },
    { msg_id: "gm-probe", delivered: 2, pending: 0, cancelled: 1, failed: 0 });
  const rc = c.ok ? await readBadge() : null;
  check("★ 已取消剩余 1 人 ⇒ 角标写「2 人已收到，1 人已取消」",
    c.ok === true && rc && rc.text === rc.expectCancelled, "text=2 人已收到，1 人已取消",
    JSON.stringify({ rc }));
  if (rc && rc.retry && rc.retryPoint) {
    // 与 `resend` 段同一个家：群消息那颗重发也要先过二次确认（点了直接动手 = 用户读作没反应）。
    // ⚠️ 这里必须**真的把确认点掉**：确认框留着不关，它那层 fixed 底板会把后面 ③b/③c 的点击吃掉，
    //    读数变成"emit 没发生"——那是夹具串味，不是组件缺陷。
    const boxC = await confirmGate(cdp, rc.retryPoint.x, rc.retryPoint.y);
    check("★ 重发走 resend_group_delivery（不是单聊那两条命令）",
      (await calls("resendGroupDelivery")) === 1 && (await calls("resendMessage")) === 0
        && (await calls("sendMessage")) === 0 && (await calls("sendGroupMessage")) === 0,
      "resendGroupDelivery=1 / 其余 0",
      JSON.stringify({
        group: await calls("resendGroupDelivery"),
        dm: await calls("resendMessage"),
        text: await calls("sendMessage"),
        grp: await calls("sendGroupMessage"),
        boxC,
      }));
  } else {
    check("★ 重发走 resend_group_delivery（不是单聊那两条命令）", false,
      "先要那颗按钮存在", JSON.stringify({ rc }));
  }

  // ── ③b 回执那一层自己的契约：点重发必须 emit retry ───────────────────
  // ⚠️ 必须**独立挂 MessageReceipt**：MessageItem 收到子组件的 retry 之后自己不再往外 emit
  // （它直接调命令）⇒ 挂在 MessageItem 上数 retry 永远是 0，那是夹具错位，不是组件缺陷。
  const receiptMount = await cdp.eval("window.__probe.install('/src/components/message/MessageReceipt.vue', '', "
    + JSON.stringify(JSON.stringify({
      state: "partial_cancelled", title: "部分成员已收到，其余已取消", isGroup: true, msgKey: "gm-probe",
      retryable: true,
      delivery: { msg_id: "gm-probe", delivered: 2, pending: 0, cancelled: 1, failed: 0 },
    })) + ")");
  await cdp.eval("window.__probe.seedDevice('dev-me')");
  await sleep(300);
  const rp = await cdp.eval(`(async () => {
    const I = await import('/src/i18n/index.ts');
    const btn = Array.from(document.querySelectorAll('button'))
      .find((b) => b.getAttribute('aria-label') === I.t('msg.resend') && b.getClientRects().length > 0);
    if (!btn) return { found: false };
    const r = btn.getBoundingClientRect();
    return { found: true, x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
  })()`);
  if (receiptMount && receiptMount.ok === true && rp && rp.found) {
    const before = (await events()).filter((e) => e[0] === "retry").length;
    await cdp.click(rp.x, rp.y);
    await sleep(400);
    const after = (await events()).filter((e) => e[0] === "retry").length;
    check("★ 回执那一格点下去 emit retry 一次", after === before + 1, "retry+1",
      JSON.stringify({ before, after, rp }));
  } else {
    check("★ 回执那一格点下去 emit retry 一次", false, "先要那颗按钮存在",
      JSON.stringify({ receiptMount, rp }));
  }

  // ── ③c 发送中那一格的取消键（负责人 2026-10-26："发送中的话，也是可以取消的"）──
  // 同样必须**独立挂 MessageReceipt**：取消通道由父层（MessageItem）算好再传下来，
  // 挂在 MessageItem 上量不到"回执自己在 sending 且拿到通道时才长键"这一格。
  const mountSending = async (canCancelSend) => {
    const mounted = await cdp.eval("window.__probe.install('/src/components/message/MessageReceipt.vue', '', "
      + JSON.stringify(JSON.stringify({
        state: "sending", title: "发送中", isGroup: false, msgKey: "m-cancel-probe",
        retryable: false, canCancelSend,
      })) + ")");
    await cdp.eval("window.__probe.seedDevice('dev-me')");
    await sleep(300);
    return {
      mounted: !!mounted && mounted.ok === true,
      btn: await cdp.eval(`(async () => {
        const I = await import('/src/i18n/index.ts');
        const hit = Array.from(document.querySelectorAll('button[data-cancel-send]'))
          .find((b) => b.getClientRects().length > 0);
        if (!hit) return { found: false };
        const r = hit.getBoundingClientRect();
        return {
          found: true, labelled: hit.getAttribute('aria-label') === I.t('msg.cancelSend'),
          x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2),
        };
      })()`),
    };
  };
  const s1 = await mountSending(true);
  if (s1.mounted && s1.btn && s1.btn.found) {
    const before = (await events()).filter((e) => e[0] === "cancel").length;
    await cdp.click(s1.btn.x, s1.btn.y);
    await sleep(400);
    const after = (await events()).filter((e) => e[0] === "cancel").length;
    check("★ 发送中的回执长出可点的取消键，点下去 emit cancel 一次（带 aria-label）",
      after === before + 1 && s1.btn.labelled === true, "cancel+1 + 可访问名 = msg.cancelSend",
      JSON.stringify({ before, after, btn: s1.btn }));
    // 反向那一格：算不出取消通道（对端离线/没有通道）时**不许**长出这颗键 ——
    // 按了没反应的按钮比没有按钮更坏（这一族在 10-23 那条"点重发没反应"里记过）。
    const s0 = await mountSending(false);
    check("★ 拿不到取消通道时不渲染那颗键（反向格：不给一颗点了没用的按钮）",
      s0.mounted === true && !!s0.btn && s0.btn.found === false,
      "found=false", JSON.stringify(s0));
  } else {
    check("★ 发送中的回执长出可点的取消键，点下去 emit cancel 一次（带 aria-label）", false,
      "先要那颗按钮存在", JSON.stringify(s1));
    check("★ 拿不到取消通道时不渲染那颗键（反向格：不给一颗点了没用的按钮）", false,
      "上一格没成立，这一格没作用点", JSON.stringify(s1));
  }

  // ── ④ 清扫判死的成员：只说结论，不假装还能补发 ─────────────────────────
  const d = await mount({ msg_id: "gm-probe", status: "failed" },
    { msg_id: "gm-probe", delivered: 0, pending: 0, cancelled: 0, failed: 2 });
  const rd = d.ok ? await readBadge() : null;
  check("★ 2 人未送达 ⇒ 角标写「2 人未送达」", d.ok === true && rd && rd.text === rd.expectFailed,
    "text=2 人未送达", JSON.stringify({ rd }));

  // ── ⑤ 状态图标动效：切换不重建节点 / 占位不塌 / 不重播缩放（2026-11-04 用户报告）──
  // 「发送中→已送达→已读」切换时图标会缩一下再弹回来、气泡跟着抖。旧实现是
  // `<Transition mode="out-in"> + :key="state"`：切一次就摘掉旧节点（占位宽度塌成 0 ⇒ 气泡跳）
  // 再挂新节点并重播 `scale(0.55)`。这一组判据是**可证伪的读数**（不是截图印象）：
  // 同一节点上连续改 state，节点身份必须不变（没有 key 重建）、切前/切中/切后的
  // boundingClientRect 必须完全相同、切换后该占位上不许还挂着重播的进入动画。
  // 正反验证：换回旧写法时这三格必然红（node=rebuilt / 宽度 0→16 / anims 非空）。
  const RECEIPT_READ = `(() => {
    const slot = document.querySelector('[data-receipt]');
    if (!slot) return { found: false };
    const r = slot.getBoundingClientRect();
    const h = slot.parentElement ? slot.parentElement.getBoundingClientRect() : null;
    const layers = Array.from(slot.querySelectorAll('[data-receipt-state]'));
    const anims = slot.getAnimations();
    return {
      found: true,
      node: (window.__receiptNode === undefined
        ? (window.__receiptNode = slot, 'first')
        : (window.__receiptNode === slot ? 'same' : 'rebuilt')),
      rect: [+r.left.toFixed(2), +r.top.toFixed(2), +r.width.toFixed(2), +r.height.toFixed(2)],
      hostW: h ? +h.width.toFixed(2) : null,
      layers: layers.length,
      active: layers.filter((l) => l.getAttribute('data-active') === 'true')
        .map((l) => l.getAttribute('data-receipt-state')).join(','),
      anims: anims.map((a) => a.animationName || a.transitionProperty).join(','),
      scaled: anims.some((a) => (a.effect && a.effect.getKeyframes ? a.effect.getKeyframes() : [])
        .some((k) => k.transform && k.transform !== 'none')),
    };
  })()`;
  const mountReceipt = (state) => cdp.eval(
    "window.__probe.installReceiptLive(" + JSON.stringify(JSON.stringify({ state })) + ")");
  const readReceipt = () => cdp.eval(RECEIPT_READ);
  const sameGeom = (x, y) => !!(x && y && x.found && y.found
    && x.rect.join() === y.rect.join() && x.hostW === y.hostW);

  try {
    const m0 = await mountReceipt("sent");
    await sleep(120);
    const before = await readReceipt();
    await cdp.eval("window.__probe.receiptState('delivered')");
    await sleep(70); // 交叉淡入进行中
    const mid = await readReceipt();
    await sleep(320); // 过渡结束
    const after = await readReceipt();
    check("★ 回执 sent→delivered：节点不重建（没有 :key 重建 ⇒ 没有 enter 重播）",
      m0.ok === true && before.found === true && before.node === "first"
        && mid.node === "same" && after.node === "same",
      "node=first→same→same", JSON.stringify({ m0, before: before.node, mid: mid.node, after: after.node }));
    check("★ 回执 sent→delivered：过渡中与过渡后占位尺寸不变（父容器不会位移）",
      sameGeom(before, mid) && sameGeom(before, after),
      "rect + hostW 三帧完全相同",
      JSON.stringify({ before: before.rect, mid: mid.rect, after: after.rect, hostW: [before.hostW, mid.hostW, after.hostW] }));
    check("★ 回执 sent→delivered：切换后只有透明度变化，占位上没有重播的进入动画/缩放",
      after.active === "delivered" && after.layers === 5 && after.anims === "" && after.scaled === false,
      "active=delivered + 5 层常驻 + anims 空 + 无 transform",
      JSON.stringify({ active: after.active, layers: after.layers, anims: after.anims, scaled: after.scaled }));

    await cdp.eval("window.__probe.receiptState('read')");
    await sleep(70);
    const mid2 = await readReceipt();
    await sleep(320);
    const after2 = await readReceipt();
    check("★ 回执 delivered→read：同样不重建、占位不动、只换透明度",
      after2.node === "same" && sameGeom(after, mid2) && sameGeom(after, after2)
        && after2.active === "read" && after2.anims === "",
      "node=same + rect 相同 + active=read + anims 空",
      JSON.stringify({ node: after2.node, rect: after2.rect, active: after2.active, anims: after2.anims }));

    // 出现动画只在「第一次出现」（挂载）时有一次；reduce 档换成不含 transform 的淡入。
    const appear = await mountReceipt("sending");
    check("★ 回执第一次出现（sending 挂载）才播一次进入动画（不是每次状态切换都播）",
      appear.ok === true && appear.anims.includes("gosslan-receipt-in"),
      "anims 含 gosslan-receipt-in", JSON.stringify(appear));

    await cdp.send("Emulation.setEmulatedMedia", {
      features: [{ name: "prefers-reduced-motion", value: "reduce" }],
    });
    await sleep(120);
    const reduceMount = await mountReceipt("sending");
    const reduceRead = await readReceipt();
    check("★ reduce 档：出现动画换成只淡入（gosslan-receipt-fade，无 transform/scale）",
      reduceMount.ok === true && reduceMount.anims.includes("gosslan-receipt-fade")
        && !reduceMount.anims.includes("gosslan-receipt-in") && reduceRead.scaled === false,
      "anims 含 gosslan-receipt-fade 且无 gosslan-receipt-in / scaled=false",
      JSON.stringify({ mount: reduceMount, scaled: reduceRead.scaled }));
  } finally {
    await cdp.send("Emulation.setEmulatedMedia", { media: "", features: [] }).catch(() => {});
    await sleep(120);
  }
}

async function runTasksMobile(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(async () => {
      window.GID = 'g1';
      window.CONV = 'group:g1';
      window.ME = 'probe-me';
      window.OTHER = 'probe-other';
      window.__mk = (id, seq, kind, def, ts) => ({
        msg_id: 'm-' + id + '-' + seq,
        sender_id: window.OTHER,
        conv_id: window.CONV,
        kind, seq, ts,
        status: 'read',
        content: JSON.stringify(Object.assign({
          todo_id: id, title: id, assignees: [window.ME], status: 'todo',
          creator: window.OTHER, deleted: false, description: '', images: [],
          archived: false, done_at: null, number: 0, priority: 'normal', category: 'task',
        }, def)),
      });
      return true;
    })()`);
    await cdp.eval("window.__probe.todoBus()");
    const now = Date.now();
    await cdp.eval(`window.__TASKS = [
      window.__mk('A', 1, 'todo', { title: '很长的移动端任务标题用来测试换行和右侧操作按钮', number: 1, priority: 'high', description: '移动端描述' }, ${now}),
      window.__mk('B', 2, 'todo', { title: '第二条任务', number: 2 }, ${now + 1}),
    ]`);
    await cdp.eval("window.__probe.todoRows(window.__TASKS)");
    await cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({ groupId: "g1", open: true }))})`);
    await cdp.eval("window.__probe.seedDevice('probe-me')");
    await sleep(900);
    const read = () => cdp.eval(`(() => {
      const buttons = [...document.querySelectorAll('button')].filter((b) => b.getClientRects().length > 0);
      const outside = buttons.filter((b) => {
        const r = b.getBoundingClientRect();
        return r.right > innerWidth + 1 || r.left < -1;
      });
      return {
        vw: innerWidth,
        scrollW: document.documentElement.scrollWidth,
        rows: document.querySelectorAll('button.min-w-0.flex-1').length,
        outside: outside.map((b) => String(b.getAttribute('aria-label') || b.textContent || '').trim().slice(0, 24)),
      };
    })()`);
    let s = await read();
    check("移动端群任务：390 宽下任务行渲染，且无横向溢出/越界按钮",
      s.rows >= 2 && s.scrollW <= s.vw + 1 && s.outside.length === 0,
      "rows>=2 + scrollWidth<=vw + outside=0", JSON.stringify(s));

    const clicked = await cdp.eval(`(() => {
      const b = [...document.querySelectorAll('button.min-w-0.flex-1')]
        .find((x) => (x.textContent || '').includes('很长的移动端'));
      if (!b) return false;
      b.click();
      return true;
    })()`);
    await sleep(500);
    const dlg = await cdp.eval(`(() => {
      const d = document.querySelector('[role="dialog"]');
      if (!d) return { ok: false };
      const r = d.getBoundingClientRect();
      return {
        ok: true,
        inViewport: r.left >= -1 && r.right <= innerWidth + 1
          && r.top >= -1 && r.bottom <= innerHeight + 1,
        w: +r.width.toFixed(1), h: +r.height.toFixed(1),
      };
    })()`);
    check("移动端群任务：点行打开的详情弹窗整个在视口内",
      clicked === true && dlg.ok === true && dlg.inViewport === true,
      "dialog 在视口内", JSON.stringify(dlg));

    /* 详情弹窗的**文本选择**（负责人 2026-10-28：「群任务详情页 标题描述…现在不能复制不能选择」）。
     *
     * 为什么必须在真窗口里读 computed style：`html { user-select: none }` 与 `.gosslan-selectable`
     * 谁赢，静态 grep 两边都能查出"有这条声明"，只有级联算出来的那一个值才是用户手上的事实
     * （同一族的坑见"样式规则可能被内联压过＝整条是死的"）。
     *
     * 两档都取一遍：`@media (pointer: coarse)` 会把 `[data-msg-col]` 里的正文重新关掉，弹窗不在
     * 那一列里 ⇒ 结构上两档都该是 text；但"该"不算证据，桌面档和触屏档各读一次（同一份探针字符串，
     * 不复制第二份比色逻辑）。`coarse` 读数一起打印：不打印就没法说清这一格验的是哪一档。 */
    const SEL_PROBE = `(() => {
      const d = document.querySelector('[role="dialog"]');
      if (!d) return { ok: false };
      const us = (el) => (el ? getComputedStyle(el).userSelect : "missing");
      const open = [...d.querySelectorAll('.gosslan-selectable')];
      const chrome = [...d.querySelectorAll('.text-xs')];
      return {
        ok: true,
        coarse: matchMedia('(pointer: coarse)').matches,
        title: us(d.querySelector('h3')),
        titleText: (d.querySelector('h3')?.textContent || '').trim().slice(0, 12),
        descCount: open.filter((el) => el.tagName === 'P').length,
        openBad: open.filter((el) => us(el) !== 'text').length,
        openTotal: open.length,
        chromeTotal: chrome.length,
        chromeBad: chrome.filter((el) => us(el) !== 'none').length,
      };
    })()`;
    const selFine = await cdp.eval(SEL_PROBE);
    check("移动端群任务：详情弹窗标题与描述在真渲染里可选（桌面档 user-select:text）",
      selFine.ok === true && selFine.coarse === false && selFine.title === "text"
        && selFine.titleText.length > 0 && selFine.descCount >= 1
        && selFine.openBad === 0 && selFine.openTotal >= 2 && selFine.chromeBad === 0,
      "coarse=false + h3=title + 描述 p 在开启清单内 + chrome 标签仍 none", JSON.stringify(selFine));
    // 只开这一次，读完立刻关：这条监听是全局的，留着会把后面几格（还有别段）的指针档改掉。
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 1 });
    const selTouch = await cdp.eval(SEL_PROBE);
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
    check("移动端群任务：同一份开启在触屏档（pointer: coarse）照旧生效",
      selTouch.ok === true && selTouch.coarse === true && selTouch.title === "text"
        && selTouch.descCount >= 1 && selTouch.openBad === 0 && selTouch.chromeBad === 0,
      "coarse=true + 弹窗不吃 [data-msg-col] 那条重新关闭", JSON.stringify(selTouch));

    // §6.76 台账那两条交给库的 window 监听，运行时**各咬一面**。
    // `scroll` 挂在 window 上但必须带 capture —— 列表那层 `overflow-y-auto` 的 scroll **不冒泡**，
    // 只有捕获相的 window 监听收得到；`resize` 不需要旗标。摘掉 `true` ⇒ 第二条红而第三条照绿；
    // 摘掉 `resize` 那条 ⇒ 反过来。这正是 §6.71 静态抓的「只改一侧」在运行时的另一半。
    // ⚠️ 第二条的 scroll 事件是**合成的**（`new Event('scroll')` 打在真元素上，`bubbles:false`）：
    // 这里受审的是**注册旗标**（捕获相收不收得到后代元素上来的这根事件），不是 Chromium 到底在什么时刻发 scroll。
    // 为什么不用真滚动：面板形态那层 `overflow-y-auto` 不受高（`GroupTasksBoard.vue:1062` 的 `min-h-0 flex-1`
    // 挂在 `standalone` 上），实测 `scrollHeight-clientHeight = 0` 滚不动；而窗口形态（真实调用点
    // `GroupTodosWindow.vue:173`）在本探针里会先卡在 `todosLoadedOnce`（`:321`）⇒ 渲染空列表。
    // ⇒ 「用户真滚动列表时菜单收不收」仍然只在**真机清单**上，这条不许被读成真机验过了。
    // 判据读的是**菜单从 DOM 里被撤掉**（Reka 自己只会隐藏浮层，撤掉才说明跑的是我们的 closeRowMenu）。
    const openRowMenu = async () => {
      const hit = await cdp.eval(`(() => {
        const b = [...document.querySelectorAll('button[aria-haspopup="menu"]')]
          .find((x) => x.getClientRects().length > 0);
        if (!b) return false;
        b.click();
        return true;
      })()`);
      await sleep(450);
      return hit && (await cdp.eval(`!!document.querySelector('[role="menu"]')`));
    };
    const menuInDom = () => cdp.eval(`!!document.querySelector('[role="menu"]')`);

    const menuOpened = await openRowMenu();
    const host = await cdp.eval(`(() => {
      const row = document.querySelector('button.min-w-0.flex-1');
      const el = row && row.closest('div.overflow-y-auto');
      return { found: !!el, winY: window.scrollY };
    })()`);
    check("开局核对：行菜单打得开，且行**确实挂在一层 `overflow-y-auto` 里**（那才是 scroll 事件的来源元素），window 自己没滚",
      menuOpened === true && host.found === true && host.winY === 0,
      "菜单在 DOM 里 + closest 找得到滚动层 + window.scrollY=0", JSON.stringify({ menuOpened, host }));

    // 上一发这里读 `ev.composedPath()`，得到 false —— 那是**量具坏了**不是现象：派发结束后 composedPath() 已被清空。
    // 换成在 window 上临时挂一根**冒泡相**探针：它收不到 ⇒ 正面证明这根事件确实到不了 window 的冒泡相，
    // 而菜单照样被撤掉 ⇒ 收它的只能是组件那条带 capture 的 window 监听。
    const fired = await cdp.eval(`(() => {
      const row = document.querySelector('button.min-w-0.flex-1');
      const el = row.closest('div.overflow-y-auto');
      let bubSawIt = false;
      const probe = () => { bubSawIt = true; };
      window.addEventListener("scroll", probe, false);
      el.dispatchEvent(new Event("scroll", { bubbles: false, cancelable: false }));
      window.removeEventListener("scroll", probe, false);
      return { bubSawIt, winY: window.scrollY };
    })()`);
    await sleep(450);
    const menuStillThere = await menuInDom();
    check("从**行自己那层**发一根不冒泡的 scroll ⇒ window 的冒泡相探针收不到（bubSawIt=false，证明这根事件到不了冒泡相）"
      + " 而行菜单从 DOM 撤掉 ⇒ 收它的是组件那条带 capture 的 window 监听（摘掉 `true` 这条当场红）",
      fired.bubSawIt === false && fired.winY === 0 && menuStillThere === false,
      "冒泡相探针没收到 + window 没滚 + 菜单不在 DOM", JSON.stringify({ fired, menuStillThere }));

    const menuOpened2 = await openRowMenu();
    await cdp.send("Emulation.setDeviceMetricsOverride", { width: 390, height: 620, deviceScaleFactor: 2, mobile: true });
    await sleep(800);
    const menuStillThere2 = await menuInDom();
    check("改视口尺寸（resize，这条**不需要** capture，走的是另一根监听）⇒ 同一个菜单也被撤掉："
      + "两条各管一面，一真一假这一对不许只做成一半",
      menuOpened2 === true && menuStillThere2 === false,
      "重开在 DOM 里 + 改尺寸后不在 DOM", JSON.stringify({ menuOpened2, menuStillThere2 }));

    await cdp.send("Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
    await sleep(400);
    // 面板形态（移动端真实入口）：整页铺满 + 页面本身不滚，滚动只留给看板列表。
    const panelMounted = await cdp.eval("window.__probe.install('/src/components/GroupTasksPanel.vue', '', "
      + JSON.stringify(JSON.stringify({ open: true, groupId: "g1" })) + ")");
    await cdp.eval("window.__probe.todoBus(); window.__probe.todoRows(window.__TASKS); window.__probe.seedDevice('probe-me')");
    await sleep(900);
    const panel = await cdp.eval(`(() => {
      const dlg = document.querySelector('[role="dialog"]');
      if (!dlg) return { ok: false };
      const r = dlg.getBoundingClientRect();
      const styles = getComputedStyle(dlg);
      return {
        ok: true,
        w: +r.width.toFixed(1), h: +r.height.toFixed(1),
        vw: innerWidth, vh: innerHeight,
        docScrollH: document.documentElement.scrollHeight,
        overflowY: styles.overflowY,
        rows: document.querySelectorAll('button.min-w-0.flex-1').length,
      };
    })()`);
    check("移动端群任务：面板整页铺满、页面不滚（列表自己滚），任务行仍在",
      panelMounted && panelMounted.ok === true && panel.ok === true
        && panel.w >= panel.vw - 1 && panel.h >= panel.vh - 1
        && panel.docScrollH <= panel.vh + 1 && panel.overflowY === "hidden" && panel.rows >= 2,
      "dialog=vw×vh + overflowY=hidden + 页面不滚 + rows>=2", JSON.stringify(panel));
    if (SHOT_PATH) {
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      const p = SHOT_PATH.replace(/\.png$/, "-tasksmobile.png");
      fs.writeFileSync(p, Buffer.from(shot.data, "base64"));
      console.log("  📷 移动端群任务取证帧 → " + p);
    }
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * 共享目录：Query 模式推广到第二个纯读面板，重点照「慢的 A 后到」与「下载归属」。
 */
async function runShareDirectory(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  await cdp.eval("window.__probe.shareBus()");
  const mounted = await cdp.eval("window.__probe.install('/src/components/ShareDirectory.vue', '', '')");
  await sleep(200);

  const info = () => cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    return {
      dialog: !!dlg,
      text: dlg ? dlg.innerText : '',
      calls: window.__share.calls.slice(),
      downloads: window.__share.downloads.slice(),
      pending: Object.keys(window.__share.pending),
    };
  })()`);

  check("共享目录装得上（QueryClient 与 chat store 都在）",
    mounted && mounted.ok === true && (await info()).dialog === false,
    "mount ok / 关着不渲染", JSON.stringify(mounted));

  await cdp.eval("window.__probe.setConv('A')");
  await cdp.eval("window.__probe.setOpen(true)");
  await sleep(400);
  let s = await info();
  check("打开：只向当前好友请求一次，A 未返回前不显示别的树",
    s.dialog && s.calls.join(",") === "A" && !s.text.includes("b.txt"),
    "calls=[A] / 无 b.txt", JSON.stringify({ calls: s.calls, text: s.text.slice(0, 60) }));

  await cdp.eval("window.__probe.setConv('B')");
  await sleep(300);
  await cdp.eval("window.__probe.resolveShare('B', ['b.txt'])");
  await sleep(400);
  s = await info();
  check("切好友：新 key 拉 B 的树并渲染",
    s.calls.join(",") === "A,B" && s.text.includes("b.txt"),
    "calls=[A,B] / b.txt", JSON.stringify({ calls: s.calls, text: s.text.slice(0, 80) }));

  await cdp.eval("window.__probe.resolveShare('A', ['a.txt'])");
  await sleep(400);
  s = await info();
  check("A 的慢响应后到：不会覆盖当前显示的 B 的树",
    s.text.includes("b.txt") && !s.text.includes("a.txt"),
    "只有 b.txt", JSON.stringify({ text: s.text.slice(0, 80) }));

  await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const name = dlg && dlg.querySelector('[title="b.txt"]');
    if (!name) return false;
    name.closest('div').querySelector('button').click();
    return true;
  })()`);
  await sleep(250);
  s = await info();
  check("下载归属来自树的快照：向 B 要 B 的文件",
    s.downloads.length === 1 && s.downloads[0][0] === "B" && s.downloads[0][1] === "B/b.txt",
    'downloads=[["B","B/b.txt"]]', JSON.stringify(s.downloads));

  await cdp.eval("window.__probe.setConv('A')");
  await sleep(350);
  s = await info();
  check("切回已缓存的好友：旧快照立刻可见，同时按 staleTime 0 重新请求",
    s.text.includes("a.txt") && s.calls.filter((x) => x === "A").length >= 2,
    "a.txt 在 / calls 里 A≥2", JSON.stringify({ calls: s.calls, text: s.text.slice(0, 80) }));
}

/**
 * 图片预览浮层的焦点语义（--only=lightbox）。
 *
 * 迁移前这里只有"打开时 focus 容器、关闭时手动 focus 回去"：Tab 会直接跑到背景页面
 * （不构成焦点陷阱），且关闭归还与卸载时机都由我们自己维护。现在 Tab 环、逃逸拉回、
 * 卸载归还都交给 Reka FocusScope —— 本段读的是真按键 / 真焦点，不是源码里有没有 import。
 */
/**
 * 消息右键：**有选区也必须归应用**（用户 2026-10-23：「有时候会把 web 的右键打开」）。
 *
 * 根因在 `shouldPreventContextMenu` 原先的「有选区一律放行」：选区不会因为右键而消失，
 * 只要之前双击选过词 / 拖选过正文，再右键气泡就会弹 WebKit 原生菜单，应用菜单根本不出现。
 * 这一段用**真右键**跑两条路径：气泡本体，以及群聊昵称行（它在消息行之外 —— 处理器若只挂在
 * 消息行上，这一格就会漏）。两条都要求：应用菜单出现 + 事件被 preventDefault。
 *
 * ⚠️ 默认窗口宽 754px 会落进移动端布局（`app.isMobile=true` ⇒ `openContextMenu` 提前 return），
 * 所以进段先切到 1100px 的桌面视口，并把「宽度 > 767」作为环境判据（不满足直接红，不是跳过）。
 */
async function runContextGuard(cdp, url) {
  /**
   * 桌面右键边界 + 选区复制 + 移动端原生选字分流（用户 2026-10-23 的两条产品决策）。
   *
   * 纪律：
   *  · 视口 / 触摸 / 媒体仿真都在 try/finally 里归还（参照 runNetCard 的写法）；
   *  · 视口断点从 `/src/utils/platform.ts` 现取，不抄 767；
   *  · 每条右键都用**真指针**，并用 window 捕获相记录真实命中的元素是不是在
   *    `[data-msg-col]` 里 —— 不能靠选择器名字推断边界；
   *  · 真机不可用的那部分（Android/iOS 原生选区手柄与系统复制菜单）只验到
   *    "应用没有拦 contextmenu / 没有同时开自定义面板"，报告里必须标 UNVERIFIED。
   *
   * 故障注入（只给本机验收收尾）：GOSSLAN_CTXGUARD_FAIL=check|throw。
   */
  const restoreWidth = await cdp.eval("window.innerWidth").catch(() => null);
  try {
    // ───────────────────────── 桌面视口 ─────────────────────────
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 1100, height: 800, deviceScaleFactor: 1, mobile: false,
      screenWidth: 1100, screenHeight: 800,
    });
    await cdp.send("Page.bringToFront").catch(() => {});
    // 复制断言需要真实的 clipboard 权限（VueUse 会先看 clipboard-write 的许可）。
    await cdp.send("Browser.grantPermissions", {
      origin: new URL(url).origin,
      permissions: ["clipboardReadWrite", "clipboardSanitizedWrite"],
    }).catch(() => {});
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);

    // 断点从生产码现取；导入失败就让这一发红（不静默回落硬编码）。
    const env = await cdp.eval(`(async () => {
      const PL = await import('/src/utils/platform.ts');
      window.__platformProbe = PL;
      return {
        width: innerWidth,
        query: PL.NARROW_LAYOUT_QUERY,
        limit: PL.MOBILE_MAX_WIDTH_PX,
        narrow: matchMedia(PL.NARROW_LAYOUT_QUERY).matches,
      };
    })()`);
    console.log("  · 消息右键段环境：" + JSON.stringify(env));
    check("环境：右键段在桌面视口（宽度 > platform.MOBILE_MAX_WIDTH_PX，断点从生产码现取）",
      !!env && env.width > env.limit && env.narrow === false,
      "width > limit 且不是窄布局", JSON.stringify(env));

    const failMode = process.env.GOSSLAN_CTXGUARD_FAIL || "";
    if (failMode === "check") {
      check("故障注入：故意红一条（验收 finally 仍归还视口）", false, "红", "故障注入");
    }
    if (failMode === "throw") throw new Error("故障注入：ctxguard 主动抛错（验收 finally 仍归还视口）");

    // 命中记录：window 捕获相先于组件处理器，记下真实 target 属于哪个区域。
    await cdp.eval(`(() => {
      window.__ctxHit = null;
      window.addEventListener('contextmenu', (e) => {
        const el = e.target instanceof Element ? e.target : null;
        window.__ctxHit = {
          tag: el ? el.tagName : null,
          inCol: !!(el && el.closest('[data-msg-col]')),
          inReactionEntry: !!(el && el.closest('[data-reaction-entry]')),
          inAvatar: !!(el && el.closest('.gosslan-avatar-box')),
          inChip: !!(el && el.closest('[data-reaction-chip]')),
        };
      }, true);
      return true;
    })()`);

    // 文案从应用词典现取：探针页的 locale 可能是 en（全新 profile），不能手抄中文。
    const L = await cdp.eval(`(async () => {
      const I = await import('/src/i18n/index.ts');
      return { copySel: I.t('msg.copySelection'), copyMsg: I.t('msg.copyMessage') };
    })()`);
    check("非空转·文案：从应用词典现取到「复制选中内容 / 复制消息」两条且不同",
      !!L && !!L.copySel && !!L.copyMsg && L.copySel !== L.copyMsg,
      "两条文案", JSON.stringify(L));

    /**
     * 剪贴板探针 = **测试替身**：只记录应用交给 Clipboard API 的文本，不真的写系统剪贴板。
     *
     * 为什么不调原 API：长跑里窗口失焦时 `clipboard.write` 会挂住 renderer（本轮组合跑实测
     * 45s 无回包）；本仓 `useClipboard` 自己也没有失败信号（库里恒 true），真剪贴板写不写成功
     * 本来就不可断言。这里断言的是「应用要复制的那段文字」——正是"只复制选中内容"的契约。
     * 需要真剪贴板时另跑一次短程手工验证，不在全量探针里做。
     */
    const clipReady = await cdp.eval(`(() => {
      window.__copied = null;
      const c = navigator.clipboard;
      if (c && typeof c.write === 'function') {
        c.write = async (items) => {
          try {
            const item = items && items[0];
            if (item && item.types && item.types.indexOf('text/plain') >= 0) {
              const blob = await item.getType('text/plain');
              window.__copied = await blob.text();
            }
          } catch (_e) { /* 读不到就保持 null，让判据红 */ }
          return undefined;
        };
      }
      if (c && typeof c.writeText === 'function') {
        c.writeText = async (text) => { window.__copied = String(text); };
      }
      document.execCommand = (cmd) => {
        if (String(cmd).toLowerCase() === 'copy') {
          const ta = document.querySelector('textarea');
          if (ta) window.__copied = ta.value;
        }
        return true;
      };
      return !!(c && (typeof c.write === 'function' || typeof c.writeText === 'function'));
    })()`);
    check("环境：剪贴板 API 可用（探针只记录应用要写入的文本，不落系统剪贴板）",
      clipReady === true, "true", String(clipReady));

    const rectOf = (selector, index = 0) => cdp.eval(`(() => {
      const el = document.querySelectorAll(${JSON.stringify(selector)})[${index}];
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return {
        x: Math.round(r.left + r.width / 2),
        y: Math.round(r.top + r.height / 2),
        left: +r.left.toFixed(1), right: +r.right.toFixed(1),
        top: +r.top.toFixed(1), bottom: +r.bottom.toFixed(1),
        w: +r.width.toFixed(1), h: +r.height.toFixed(1),
        pointerEvents: getComputedStyle(el).pointerEvents,
        opacity: getComputedStyle(el).opacity,
      };
    })()`);
    const rightClickAt = async (p) => {
      if (!p) return false;
      await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: p.x, y: p.y });
      await sleep(30);
      await cdp.send("Input.dispatchMouseEvent", { type: "mousePressed", x: p.x, y: p.y, button: "right", clickCount: 1 });
      await cdp.send("Input.dispatchMouseEvent", { type: "mouseReleased", x: p.x, y: p.y, button: "right", clickCount: 1 });
      await sleep(300);
      return true;
    };
    const menuState = () => cdp.eval(`(() => {
      const el = document.querySelector('[role="menu"].gosslan-menu');
      return {
        open: !!el,
        items: el
          ? [...el.querySelectorAll('[role="menuitem"]')].map((n) => (n.innerText || '').trim())
          : [],
      };
    })()`);
    const hitState = () => cdp.eval("window.__ctxHit");
    const closeMenu = async () => {
      await cdp.key("Escape", "Escape", "", 27);
      await sleep(220);
      return !(await menuState()).open;
    };
    /**
     * 激活菜单项：用**键盘** Enter（与既有 ctxmenu 段同一条 Reka 路径）。
     * 纯 pointer / 元素 click() 在 Reka 菜单里会先被 DismissableLayer 收掉，
     * 表现为"菜单开了、动作没跑、__copied 还是上一次的值"（本轮实测踩过）。
     *
     * ⚠️ Enter 偶发不激活（本文件头部那条已知引擎问题）：headless 静止页面不推进帧，
     * Reka 的 item 选中状态可能停在上一拍 ⇒ Enter 落空，`__copied` 仍挂着上一次的值，
     * 后续判据会看起来像"复制错了内容"（同一段单跑绿、组合跑红就是这么来的）。
     * ⇒ 每次激活前**先清空**替身，Enter 后用截图泵帧并重试，直到替身真的被写入。
     */
    const clickItem = async (label) => {
      // 与既有 ctxmenu 段同一条 Reka 键盘路径：↓ 走到目标条目再 Enter。
      // 直接 item.focus()+Enter 偶发不选中（焦点在了、菜单的 currentItem 没更新）⇒ 本轮实测踩过。
      const total = await cdp.eval(`document.querySelectorAll('[role="menu"] [role="menuitem"]').length`);
      if (!total) return false;
      await cdp.eval("window.__copied = null");
      let hit = false;
      for (let step = 0; step <= total; step += 1) {
        const active = await cdp.eval(`(() => {
          const items = [...document.querySelectorAll('[role="menu"] [role="menuitem"]')];
          const a = document.activeElement;
          return {
            idx: items.indexOf(a),
            text: String((a && a.innerText) || '').trim(),
          };
        })()`);
        if (active && active.idx >= 0 && active.text.includes(label)) { hit = true; break; }
        await cdp.key("ArrowDown", "ArrowDown", "", 40);
        await sleep(70);
      }
      if (hit) {
        for (let k = 0; k < 3; k += 1) {
          await cdp.key("Enter", "Enter", "\r", 13);
          await sleep(300);
          if (await cdp.eval("window.__copied !== null")) break;
          // 泵一帧：headless 静止页面不出帧，Reka 的选中/动作回调可能一直没跑。
          await cdp.send("Page.captureScreenshot", { format: "png" }).catch(() => {});
        }
      }
      // 动作如果没把菜单收掉，先 Esc 收干净：带着开着的 portal 去换宿主会把 renderer 卡死。
      if ((await menuState()).open) await closeMenu();
      return hit;
    };
    const copied = () => cdp.eval("window.__copied");
    const selectText = (mode) => cdp.eval(`(() => {
      const root = document.querySelector('#probe-host .gosslan-selectable');
      if (!root) return null;
      const sel = window.getSelection();
      const range = document.createRange();
      if (${JSON.stringify(mode)} === 'part') {
        const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
        let node = walker.nextNode();
        while (node && !(node.textContent || '').trim()) node = walker.nextNode();
        if (!node) return null;
        const n = Math.min(6, (node.textContent || '').length);
        range.setStart(node, 0);
        range.setEnd(node, n);
      } else {
        range.selectNodeContents(root);
      }
      sel.removeAllRanges();
      sel.addRange(range);
      const r = range.getBoundingClientRect();
      return { text: sel.toString(), x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    })()`);
    const clearSel = () => cdp.eval("window.getSelection().removeAllRanges(); 1");
    const mountOne = async (props) => {
      // 换宿主前必须收掉开着的菜单：带着 Reka portal 去 innerHTML='' 会把 renderer 卡死（本轮实测）。
      if ((await menuState()).open) await closeMenu();
      const r = await cdp.eval("window.__probe.install('/src/components/MessageItem.vue', '', "
        + JSON.stringify(JSON.stringify(props)) + ")");
      await sleep(420);
      return r;
    };

    // ── 1) 触发边界：正文 / 昵称 / 引用块开菜单；头像 / 行内空白不开 ──
    //    表情回应胶囊自 2026-10-24 起在 data-msg-col **之内**（它是气泡的底栏），
    //    但仍属控件 ⇒ 期望「命中在列内 + 不弹菜单」（由 `[data-reaction-strip]` 显式排除）。
    const boundaryProps = {
      message: {
        msg_id: "m-ctx-boundary", sender_id: "peer-a", kind: "text",
        content: "「引用 张三：原消息片段|msg-1」\n正文第一段，用于右键边界。",
        ts: 1700000000000, conv_id: "group:g1", seq: 1,
      },
      isGroup: true, senderName: "对方", canReact: true,
      reactions: [{ emoji: "[赞]", count: 2, mine: false, actors: ["peer-b"], latest: "peer-b" }],
    };
    const mounted = await mountOne(boundaryProps);
    const bubble = await rectOf("#probe-host .gosslan-bubble-text");
    const nick = await rectOf("#probe-host [data-msg-col] > div", 0);
    const quote = await rectOf("#probe-host .quote-text");
    const avatar = await rectOf("#probe-host .gosslan-avatar-box");
    const chip = await rectOf("#probe-host [data-reaction-chip]");
    const blankP = await cdp.eval(`(() => {
      const col = document.querySelector('#probe-host [data-msg-col]');
      if (!col) return null;
      const outer = col.parentElement;
      const r = outer.getBoundingClientRect();
      const c = col.getBoundingClientRect();
      return { x: Math.round(r.right - 12), y: Math.round(c.top + c.height / 2), colRight: +c.right.toFixed(1), outerRight: +r.right.toFixed(1) };
    })()`);
    check("非空转·边界：群聊消息装上了，正文/昵称/引用块/头像/表情条/空白六个落点都量得到",
      !!mounted && mounted.ok === true && !!bubble && !!nick && !!quote && !!avatar && !!chip
        && !!blankP && blankP.x > blankP.colRight + 8,
      "六个落点 + 空白点在 data-msg-col 右侧", JSON.stringify({ mounted, bubble, nick, quote, avatar, chip, blankP }));

    const boundaryCases = [];
    for (const [label, point, expectMenu, expectInCol] of [
      ["正文", bubble, true, true],
      ["昵称", nick, true, true],
      ["引用内容", quote, true, true],
      ["头像", avatar, false, false],
      ["行内空白", blankP, false, false],
      ["表情回应胶囊", chip, false, true],
    ]) {
      if (!point) { boundaryCases.push([label, false, "落点没量到"]); continue; }
      await rightClickAt(point);
      const m = await menuState();
      const hit = await hitState();
      boundaryCases.push([label, m.open === expectMenu && hit && hit.inCol === expectInCol, { m, hit, point }]);
    }
    console.log("  · 右键边界实测：" + JSON.stringify(boundaryCases.map(([label, ok, detail]) => ({ label, ok, detail }))));
    for (const [label, ok, detail] of boundaryCases) {
      check("右键边界·" + label + "：" + (detail && detail.m && detail.m.open ? "弹消息菜单" : "不弹消息菜单")
        + "（真实命中在 data-msg-col " + (JSON.stringify(detail && detail.hit && detail.hit.inCol)) + "）",
        ok === true, "与预期一致", JSON.stringify(detail));
      if (detail && detail.m && detail.m.open) await closeMenu();
    }

    // 表情回应入口在列内（绝对定位），必须被显式排除；悬停后真右键，若悬停没生效则合成事件兜底。
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: bubble.x, y: bubble.y });
    await sleep(260);
    const entry = await rectOf("#probe-host [data-reaction-entry]");
    let entryReal = false;
    if (entry && entry.pointerEvents !== "none" && entry.opacity !== "0") {
      await rightClickAt(entry);
      const m = await menuState();
      const hit = await hitState();
      entryReal = true;
      check("右键边界·表情回应入口（列内控件，真指针）：不弹消息菜单",
        m.open === false && hit && hit.inReactionEntry === true,
        "menu=false 且命中在 data-reaction-entry", JSON.stringify({ m, hit, entry }));
    } else {
      const r = await cdp.eval(`(() => {
        const el = document.querySelector('#probe-host [data-reaction-entry]');
        if (!el) return null;
        const ev = new MouseEvent('contextmenu', { bubbles: true, cancelable: true });
        el.dispatchEvent(ev);
        return { prevented: ev.defaultPrevented };
      })()`);
      const m = await menuState();
      check("右键边界·表情回应入口（列内控件，合成事件兜底）：不弹消息菜单",
        !!r && m.open === false, "menu=false", JSON.stringify({ r, m, entry }));
    }
    console.log("  · 表情回应入口：" + JSON.stringify({ entry, entryReal }));

    // 菜单关闭回归：Esc + 外部点击。
    await rightClickAt(bubble);
    const escClosed = await closeMenu();
    check("右键菜单·Esc 关闭且 DOM 撤净", escClosed === true, "menu=false", JSON.stringify({ escClosed }));
    // 点外部关闭不在本段重复：统一外壳那条由既有 `--only=ctxmenu` 段负责（本段只测消息边界/复制）。

    // ── 2) 桌面选区复制：只复制选中文字；无选区不显示该入口；整条复制保留 ──
    const dmProps = {
      message: {
        msg_id: "m-ctx-select", sender_id: "peer-a", kind: "text",
        content: "前言三二一 这段文字用来测试选中复制。", ts: 1700000000000,
        conv_id: "dm:peer-a", seq: 1,
      },
      isGroup: false, senderName: "对方",
    };
    await mountOne(dmProps);
    const part = await selectText("part");
    check("非空转·选区：程序化选中了正文的一段（含少于整条的字符数）",
      !!part && part.text.length > 0 && part.text.length < dmProps.message.content.length,
      "0 < 选中长度 < 整条", JSON.stringify(part));
    await rightClickAt(part);
    const menuSel = await menuState();
    const hitSel = await hitState();
    check("选中文字后右键：菜单出现「复制选中内容」与「复制消息」，且事件被拦、命中在消息内容列",
      menuSel.open === true && menuSel.items.includes(L.copySel) && menuSel.items.includes(L.copyMsg)
        && hitSel && hitSel.inCol === true,
      "两个入口都在 + inCol=true", JSON.stringify({ menuSel, hitSel }));
    const copiedSel = await clickItem(L.copySel);
    const selValue = await copied();
    check("点「复制选中内容」：剪贴板里只有选中的那段，不是整条消息",
      copiedSel === true && selValue === part.text && selValue !== dmProps.message.content,
      "copied == 选中文本", JSON.stringify({ copiedSel, selValue, part: part && part.text }));

    await clearSel();
    const bubbleDm = await rectOf("#probe-host .gosslan-bubble-text");
    await rightClickAt(bubbleDm);
    const menuNoSel = await menuState();
    check("无有效选区：菜单不显示「复制选中内容」，但「复制消息」仍在",
      menuNoSel.open === true && !menuNoSel.items.includes(L.copySel) && menuNoSel.items.includes(L.copyMsg),
      "无选区入口 / 有整条入口", JSON.stringify(menuNoSel));
    const copiedMsg = await clickItem(L.copyMsg);
    const msgValue = await copied();
    check("无选区时「复制消息」仍复制整条内容",
      copiedMsg === true && msgValue === dmProps.message.content,
      "copied == 整条内容", JSON.stringify({ copiedMsg, msgValue }));

    // 选区在打开菜单后被清掉：点入口仍复制右键那一刻的快照。
    await mountOne(dmProps);
    const snap = await selectText("part");
    await rightClickAt(snap);
    await clearSel();
    const copiedSnap = await clickItem(L.copySel);
    const snapValue = await copied();
    check("打开菜单后选区被改写/清空：仍复制右键那一刻的快照（不读 live 选区）",
      copiedSnap === true && snapValue === snap.text,
      "copied == 右键时快照", JSON.stringify({ snapValue, snap: snap && snap.text }));

    // 跨节点选区（正文 + 链接 + 正文）：toString 仍是完整文本。
    const linkProps = {
      message: {
        msg_id: "m-ctx-link", sender_id: "peer-a", kind: "text",
        content: "开头 https://example.com 结尾", ts: 1700000000000, conv_id: "dm:peer-a", seq: 1,
      },
      isGroup: false, senderName: "对方",
    };
    await mountOne(linkProps);
    const all = await selectText("all");
    check("跨节点选区：正文+链接+正文都进了同一个 Range",
      !!all && all.text === linkProps.message.content,
      "选中文本 == 整条内容", JSON.stringify({ all, content: linkProps.message.content }));
    await rightClickAt(all);
    const copiedCross = await clickItem(L.copySel);
    const crossValue = await copied();
    check("跨节点选区复制：链接前后两段都在，不丢不重",
      copiedCross === true && crossValue === linkProps.message.content,
      "copied == 完整文本", JSON.stringify({ copiedCross, crossValue }));

    // ── 3) 连续右键不同消息：菜单上下文与选区归属不串 ──
    if ((await menuState()).open) await closeMenu();
    const pair = await cdp.eval("window.__probe.installMessages(" + JSON.stringify(JSON.stringify([
      {
        message: { msg_id: "m-ctx-a", sender_id: "peer-a", kind: "text", content: "第一条消息：右键我。", ts: 1700000000000, conv_id: "dm:peer-a", seq: 1 },
        isGroup: false, senderName: "对方",
      },
      {
        message: { msg_id: "m-ctx-b", sender_id: "peer-a", kind: "text", content: "第二条消息：也右键我。", ts: 1700000000001, conv_id: "dm:peer-a", seq: 2 },
        isGroup: false, senderName: "对方",
      },
    ])) + ")");
    await sleep(500);
    const cols = await cdp.eval(`(() => [...document.querySelectorAll('#probe-host [data-msg-col]')].map((el) => {
      const r = el.getBoundingClientRect();
      return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    }))()`);
    check("非空转·两消息：同页挂上两条独立的 data-msg-col",
      !!pair && pair.ok === true && Array.isArray(cols) && cols.length === 2,
      "两条列", JSON.stringify({ pair, cols }));
    // A 里选中一段 → 右键 A：出现复制选中；关掉后选区留在 A。
    const aSel = await cdp.eval(`(() => {
      const root = document.querySelectorAll('#probe-host .gosslan-selectable')[0];
      if (!root) return null;
      const sel = window.getSelection();
      const range = document.createRange();
      range.selectNodeContents(root);
      sel.removeAllRanges(); sel.addRange(range);
      const r = range.getBoundingClientRect();
      return { text: sel.toString(), x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    })()`);
    await rightClickAt(aSel);
    const menuA = await menuState();
    check("连续右键·消息 A：A 里有选区 ⇒ A 的菜单显示「复制选中内容」",
      menuA.open === true && menuA.items.includes(L.copySel),
      "A 菜单有选中入口", JSON.stringify(menuA));
    await closeMenu();
    // 不选 B，右键 B：B 的菜单里不应显示复制选中（选区在 A，和 B 不相交）。
    await rightClickAt(cols && cols[1]);
    const menuB1 = await menuState();
    check("连续右键·消息 B（选区仍在 A）：B 的菜单不显示「复制选中内容」",
      menuB1.open === true && !menuB1.items.includes(L.copySel) && menuB1.items.includes(L.copyMsg),
      "B 菜单无选中入口", JSON.stringify(menuB1));
    const copiedB = await clickItem(L.copyMsg);
    const bValue = await copied();
    check("连续右键·消息 B 的「复制消息」复制的是 B（上下文没有串到 A）",
      copiedB === true && bValue === "第二条消息：也右键我。",
      "copied == B 的内容", JSON.stringify({ bValue }));
    // 在 B 里选中 → 右键 B：出现复制选中，且复制的是 B 的那段。
    const bSel = await cdp.eval(`(() => {
      const root = document.querySelectorAll('#probe-host .gosslan-selectable')[1];
      if (!root) return null;
      const sel = window.getSelection();
      const range = document.createRange();
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      let node = walker.nextNode();
      while (node && !(node.textContent || '').trim()) node = walker.nextNode();
      if (!node) return null;
      const n = Math.min(6, (node.textContent || '').length);
      range.setStart(node, 0);
      range.setEnd(node, n);
      sel.removeAllRanges(); sel.addRange(range);
      const r = range.getBoundingClientRect();
      return { text: sel.toString(), x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
    })()`);
    await rightClickAt(bSel);
    const copiedBSel = await clickItem(L.copySel);
    const bSelValue = await copied();
    check("连续右键·消息 B 选中后复制选中：结果是 B 的选区",
      copiedBSel === true && bSelValue === bSel.text && bSelValue !== bValue,
      "copied == B 选区", JSON.stringify({ bSelValue, bSelText: bSel && bSel.text, bValue }));

    // ───────────────────────── 移动端视口 ─────────────────────────
    await clearSel();
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
      screenWidth: 390, screenHeight: 844,
    });
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 1 });
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await sleep(200);
    const mobileEnv = await cdp.eval(`(async () => {
      const PL = await import('/src/utils/platform.ts');
      const col = () => document.querySelector('#probe-host [data-msg-col]');
      return {
        width: innerWidth,
        narrow: matchMedia(PL.NARROW_LAYOUT_QUERY).matches,
        coarse: matchMedia('(pointer: coarse)').matches,
        hasCol: !!col(),
      };
    })()`);
    check("移动端环境：390×844 + 窄布局 + pointer: coarse",
      !!mobileEnv && mobileEnv.width === 390 && mobileEnv.narrow === true && mobileEnv.coarse === true,
      "390 / narrow=true / coarse=true", JSON.stringify(mobileEnv));

    const mobileProps = {
      message: {
        msg_id: "m-ctx-mobile", sender_id: "peer-a", kind: "text",
        content: "移动端正文：长按我应该进系统选字，不要弹自定义面板。",
        ts: 1700000000000, conv_id: "group:g1", seq: 1,
      },
      isGroup: true, senderName: "对方", canReact: false,
    };
    const m2 = await mountOne(mobileProps);
    const mBubble = await rectOf("#probe-host .gosslan-bubble-text");
    const mNick = await rectOf("#probe-host [data-msg-col] > div", 0);
    const cssState = await cdp.eval(`(() => {
      const col = document.querySelector('#probe-host [data-msg-col]');
      const text = document.querySelector('#probe-host .gosslan-selectable');
      return {
        colSelect: col ? getComputedStyle(col).userSelect : null,
        textSelect: text ? getComputedStyle(text).userSelect : null,
        textCallout: text ? (getComputedStyle(text).webkitTouchCallout || '') : null,
      };
    })()`);
    console.log("  · 移动端选字 CSS 实测：" + JSON.stringify(cssState));
    check("移动端 CSS：消息内容列不可选（长按昵称/卡片归自定义面板），正文层显式可选",
      !!m2 && m2.ok === true && cssState.colSelect === "none" && cssState.textSelect === "text",
      "col=none / text=text", JSON.stringify(cssState));

    const sheetState = () => cdp.eval(`(() => ({
      sheet: !!document.querySelector('.gosslan-dialog-sheet'),
      sheetText: (() => {
        const el = document.querySelector('.gosslan-dialog-sheet');
        return el ? (el.innerText || '').trim() : '';
      })(),
      menu: !!document.querySelector('[role="menu"].gosslan-menu'),
    }))()`);
    const touchStart = (p) => cdp.send("Input.dispatchTouchEvent",
      { type: "touchStart", touchPoints: [{ x: p.x, y: p.y }] });
    const touchMove = (p, q) => cdp.send("Input.dispatchTouchEvent",
      { type: "touchMove", touchPoints: [{ x: q.x, y: q.y }] });
    const touchEnd = () => cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
    const ctxEventOn = (selector) => cdp.eval(`(() => {
      const el = document.querySelector(${JSON.stringify(selector)});
      if (!el) return null;
      const ev = new MouseEvent('contextmenu', { bubbles: true, cancelable: true });
      el.dispatchEvent(ev);
      return { prevented: ev.defaultPrevented };
    })()`);

    // ① 长按正文：不起自定义面板；contextmenu 也放行（应用侧证据；系统菜单本身 Chrome 给不了）
    await touchStart(mBubble);
    await sleep(720);
    const holdText = await sheetState();
    // WebKit 可能把 contextmenu 的 target 从文本上提到气泡根：同一次触摸起点是正文 ⇒ 也要放行。
    const textCtxRoot = await ctxEventOn("#probe-host .gosslan-bubble-text");
    await touchEnd();
    await sleep(200);
    check("移动端·长按正文：**不弹** Gosslan 面板（长按留给系统原生选字）",
      holdText.sheet === false && holdText.menu === false,
      "sheet=false / menu=false", JSON.stringify(holdText));
    check("移动端·target 被 WebKit 上提到气泡根：仍放行 contextmenu（同一次触摸起点是正文）",
      !!textCtxRoot && textCtxRoot.prevented === false,
      "prevented=false", JSON.stringify(textCtxRoot));
    const textCtx = await ctxEventOn("#probe-host .gosslan-selectable");
    check("移动端·正文上的 contextmenu 默认行为被放行（不 preventDefault；系统复制菜单依赖它）",
      !!textCtx && textCtx.prevented === false,
      "prevented=false", JSON.stringify(textCtx));

    // ② 长按昵称（非正文）：弹自定义面板；contextmenu 被拦；系统菜单不与面板并存
    await touchStart(mNick);
    await sleep(720);
    const holdNick = await sheetState();
    const nickCtx = await ctxEventOn("#probe-host [data-msg-col] > div");
    const holdNickAgain = await sheetState();
    await touchEnd();
    await sleep(220);
    check("移动端·长按昵称（非正文）：弹 Gosslan 面板，不弹消息右键菜单",
      holdNick.sheet === true && holdNick.menu === false,
      "sheet=true / menu=false", JSON.stringify(holdNick));
    check("移动端·非正文 contextmenu：被拦截（避免系统菜单与自定义面板同时出现）",
      !!nickCtx && nickCtx.prevented === true && holdNickAgain.sheet === true && holdNickAgain.menu === false,
      "prevented=true / 面板仍在 / 无右键菜单", JSON.stringify({ nickCtx, holdNickAgain }));
    check("移动端·面板里没有自定义「复制选中内容」，整条「复制消息」仍在",
      holdNickAgain.sheetText.includes(L.copyMsg) && !holdNickAgain.sheetText.includes(L.copySel),
      "有复制消息 / 无复制选中", JSON.stringify({ sheetText: holdNickAgain.sheetText }));
    await cdp.key("Escape", "Escape", "", 27);
    await sleep(300);
    check("移动端·Esc 关闭面板", (await sheetState()).sheet === false, "sheet=false", "");

    // ③ 短按 / 滚动 / 已有选区：都不许误开面板
    await touchStart(mNick);
    await sleep(120);
    await touchEnd();
    await sleep(620);
    check("移动端·短按非正文：不弹面板", (await sheetState()).sheet === false, "sheet=false", "");
    await touchStart(mNick);
    await touchMove(mNick, { x: mNick.x, y: mNick.y + 40 });
    await sleep(720);
    const scrollState = await sheetState();
    await touchEnd();
    await sleep(200);
    check("移动端·在非正文上滑动（超过抖动容差）：不弹面板", scrollState.sheet === false,
      "sheet=false", JSON.stringify(scrollState));
    // 先按住再建立选区：模拟"选区手柄还在 / 已有选区"时长按非正文的时机。
    await touchStart(mNick);
    await sleep(120);
    const presetSel = await selectText("all");
    await sleep(620);
    const withSel = await sheetState();
    await touchEnd();
    await clearSel();
    check("移动端·已有选区（含拖动选区手柄的时机）：长按非正文也不叠第二个面板",
      !!presetSel && withSel.sheet === false, "sheet=false", JSON.stringify({ withSel, presetSel }));
  } finally {
    // 视口 / 触摸 / 媒体仿真必须归还；即使断言失败或执行抛错也走这里。
    await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
    await cdp.send("Emulation.setEmulatedMedia", { media: "", features: [] }).catch(() => {});
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
    await sleep(180);
    const restored = await cdp.eval("window.innerWidth").catch(() => null);
    check("ctxguard 收尾：视口指标已归还（后续段不再继承 390/1100 的临时视口）",
      restoreWidth !== null && restored === restoreWidth,
      `window.innerWidth 回到 ${restoreWidth}`, JSON.stringify({ restoreWidth, restored }));
  }
}

async function runLightbox(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const mounted = await cdp.eval("window.__probe.lightboxMount()");
  await sleep(350);
  if (!mounted || mounted.ok !== true) {
    check("图片预览装得上（pinia 用的是页面那一份）", false, "mount ok", JSON.stringify(mounted));
    return;
  }
  const read = () => cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const ae = document.activeElement;
    const scope = dlg ? dlg.firstElementChild : null;
    const btns = dlg ? [...dlg.querySelectorAll('button')] : [];
    const img = dlg ? dlg.querySelector('img') : null;
    // 预览样式的三个读数（用户 2026-10-23）：
    //  · imgRadius —— 预览图**不许切圆角**（完整展示）；
    //  · navBg/navShadow —— 左右切换键在**白图**上也要看得见 ⇒ 深色底 + 阴影。
    const navBtn = btns.find((b) => String(b.className).includes('h-11')) || null;
    const navCs = navBtn ? getComputedStyle(navBtn) : null;
    return {
      open: !!dlg,
      modal: dlg ? dlg.getAttribute('aria-modal') : null,
      buttons: btns.length,
      focusIndex: btns.indexOf(ae),
      // 2026-11-08：缩放组并进顶栏后，DOM 第一颗是「缩小」，100% 时它是 disabled ⇒ 不可聚焦。
      // Tab 环的"第一颗"口径从"下标 0"搬成"第一颗可聚焦"（阈值没放宽，量的仍是同一件事）。
      firstEnabled: btns.findIndex((b) => !b.disabled),
      focusInScope: !!(scope && ae && (scope === ae || scope.contains(ae))),
      focusIsScope: !!(scope && ae === scope),
      focusId: ae ? (ae.id || ae.tagName) : 'null',
      alt: img ? img.getAttribute('alt') : null,
      index: window.__lbState ? window.__lbState.index : -1,
      imgRadius: img ? getComputedStyle(img).borderTopLeftRadius : null,
      navBg: navCs ? navCs.backgroundColor : null,
      navShadow: navCs ? navCs.boxShadow : null,
    };
  })()`);

  let s = await read();
  check("打开后是 dialog + aria-modal，焦点被接进浮层容器（不是留在 opener 上）",
    s.open && s.modal === "true" && s.focusInScope && s.focusIsScope,
    "open / aria-modal=true / activeElement 是焦点容器",
    JSON.stringify(s));

  /*
   * 预览图不许切圆角 + 左右切换键在白图上也看得见（用户 2026-10-23）。
   * 量的是**计算样式**，不是类名：`rounded-*` 被删了但 `overflow-hidden` 还在、
   * 或者底色写成 white/10 这类"类名看着有、实际看不见"的写法，只有读计算值才抓得住。
   */
  const navAlpha = (() => {
    const m = /rgba?\(([^)]+)\)/.exec(s.navBg || "");
    if (!m) return null;
    const parts = m[1].split(",").map((x) => x.trim());
    return parts.length === 4 ? Number(parts[3]) : 1;
  })();
  console.log("  ℹ 预览样式读数 → " + JSON.stringify({
    imgRadius: s.imgRadius, navBg: s.navBg, navAlpha, navShadow: s.navShadow,
  }));
  check("图片预览：预览图不切圆角（完整展示）",
    s.imgRadius === "0px", "border-radius 0px", JSON.stringify({ imgRadius: s.imgRadius }));
  check("图片预览：左右切换键有足够深的底色 + 阴影（白图上不隐形）",
    typeof navAlpha === "number" && navAlpha >= 0.3
      && !!s.navShadow && s.navShadow !== "none",
    "底色 alpha>=0.3 且 box-shadow 不为 none",
    JSON.stringify({ navBg: s.navBg, navAlpha, navShadow: s.navShadow }));

  /*
   * 顶部让位**只许算一遍**（2026-10-20，用户报「移动端弹窗上方被刘海/状态栏压住」时
   * 顺出来的另一半缺陷）：外壳 `top` 已经让开自绘 caption，里面那层右上工具条又写了
   * `calc(var(--gosslan-window-safe-top) + env(safe-area-inset-top) + 1rem)` ⇒ 桌面
   * （env=0）工具条实际落在 **2×caption + 16px**，Win 上是 92px 而不是 54px。
   *
   * 量法（不用源码里"有没有读那个变量"当判据 —— 那种断言只会跟着注释走）：
   * 把 `--gosslan-window-safe-top` 钉成 44px（桌面 caption 的替身，env 在 Chrome 恒 0），
   * 读**外壳自己的 top** 与**顶栏/工具条相对外壳的偏移**。
   *
   * 2026-11-08 语义搬迁（同一件事，换了个形状）：工具不再独立浮在 `top:1rem`，
   * 而是并进顶栏那一行（用户要求"缩放不要压图"）。判据从"delta≈16"搬成两条：
   *   ① 顶栏贴外壳顶（delta≈0）—— 让位仍然只在外壳这一层算一次；
   *   ② 工具条整块落在顶栏矩形内 —— 它不可能再单独去和 caption/safe-top 相加。
   * 放宽阈值那种事没做：平移后"算两遍"会直接表现为 `barTop > shellTop`。
   * ⚠️ 这一格买不到移动端的 `env(safe-area-inset-top)` 那一半 —— Chrome 里 env 恒 0，
   *    真机那半只有 iOS/Android 可证（§6.91 末尾的验证步骤）。
   */
  await cdp.eval(`(() => {
    document.documentElement.style.setProperty('--gosslan-window-safe-top', '44px');
    return getComputedStyle(document.documentElement).getPropertyValue('--gosslan-window-safe-top').trim();
  })()`);
  await sleep(120);
  const geo = await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return null;
    const btns = [...dlg.querySelectorAll('button')];
    // 2026-11-08：预览按画板加了顶栏之后，"第一颗按钮的父节点"不再是工具条容器
    // （顶栏在 DOM 里更靠前，但它自己不放按钮；底栏缩略图也是按钮）。判据要量的东西没变
    // —— 工具条相对外壳的偏移 —— 所以把锚点搬到工具条自己的稳定标记上，而不是放宽阈值。
    const bar = dlg.querySelector('[data-lightbox-tools]') ?? (btns.length ? btns[0].parentElement : null);
    const topbar = dlg.querySelector('[data-lightbox-topbar]');
    const d = dlg.getBoundingClientRect();
    const b = bar ? bar.getBoundingClientRect() : null;
    const t = topbar ? topbar.getBoundingClientRect() : null;
    return {
      shellTop: +d.top.toFixed(1),
      barTop: b ? +b.top.toFixed(1) : null,
      topbarDelta: t ? +(t.top - d.top).toFixed(1) : null,
      toolsInside: !!b && !!t
        && b.top >= t.top - 0.5 && b.bottom <= t.bottom + 0.5
        && b.left >= t.left - 0.5 && b.right <= t.right + 0.5,
    };
  })()`);
  check("钉住 44px 让位后：外壳自己从 44px 起算（让位挂在外壳这一层，一处生效）",
    !!geo && geo.shellTop === 44, "shellTop=44", JSON.stringify(geo));
  check("顶栏贴外壳顶部（工具并入顶栏后仍只让位一次，delta≈0）",
    !!geo && geo.topbarDelta !== null && Math.abs(geo.topbarDelta) <= 0.6,
    "topbarDelta≈0", JSON.stringify(geo));
  check("保存/关闭/缩放整块落在顶栏矩形内（不再有独立浮层压图）",
    !!geo && geo.toolsInside === true, "toolsInside=true", JSON.stringify(geo));
  await cdp.eval(`(() => {
    document.documentElement.style.removeProperty('--gosslan-window-safe-top');
    return 1;
  })()`);

  await cdp.key("Tab", "Tab", "", 9);
  s = await read();
  check("Tab 从容器流到第一颗**可聚焦**按钮（缩放组 − 在 100% 时 disabled ⇒ 跳过）",
    s.focusInScope && s.firstEnabled >= 0 && s.focusIndex === s.firstEnabled,
    "focusIndex=firstEnabled", JSON.stringify(s));

  // 焦点陷阱的判据：从**最后一颗**按钮再按 Tab，必须回到第一颗；
  // 没有 FocusScope 时这里会离开浮层（落到背景页面 / 浏览器 chrome）。
  await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const btns = dlg ? [...dlg.querySelectorAll('button')] : [];
    if (btns.length) btns[btns.length - 1].focus();
    return btns.length;
  })()`);
  await cdp.key("Tab", "Tab", "", 9);
  s = await read();
  check("Tab 环：从最后一颗按钮再 Tab 回到第一颗可聚焦按钮（旧实现会逃出浮层）",
    s.focusInScope && s.firstEnabled >= 0 && s.focusIndex === s.firstEnabled,
    "focusInScope 且 focusIndex=firstEnabled", JSON.stringify(s));

  // Shift+Tab 反向环：从第一颗（可聚焦的）回到最后一颗。
  await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const btns = dlg ? [...dlg.querySelectorAll('button')] : [];
    const first = btns.find((b) => !b.disabled);
    if (first) first.focus();
    return btns.length;
  })()`);
  await cdp.send("Input.dispatchKeyEvent", {
    type: "keyDown", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9, modifiers: 8,
  });
  await cdp.send("Input.dispatchKeyEvent", {
    type: "keyUp", key: "Tab", code: "Tab", windowsVirtualKeyCode: 9, nativeVirtualKeyCode: 9, modifiers: 8,
  });
  await sleep(120);
  s = await read();
  check("Shift+Tab 反向环：从第一颗回到最后一颗",
    s.focusInScope && s.buttons > 1 && s.focusIndex === s.buttons - 1,
    "focusIndex=buttons-1", JSON.stringify(s));

  // trapped：程序化把焦点扔到背景按钮上，FocusScope 必须把它拉回来。
  await cdp.eval("document.getElementById('opener').focus()");
  await sleep(120);
  s = await read();
  check("焦点被程序化扔到背景后会被拉回浮层（trapped 生效，不只是 loop）",
    s.focusInScope === true,
    "focusInScope=true", JSON.stringify(s));

  // 业务键仍然归组件：ArrowRight 切到第二张。
  await cdp.key("ArrowRight", "ArrowRight", "", 39);
  await sleep(150);
  s = await read();
  check("ArrowRight 仍然切到下一张（业务按键没被焦点层接管）",
    s.index === 1 && s.alt === "two.gif",
    "index=1 / alt=two.gif", JSON.stringify(s));

  /*
   * 左右切换键的按下反馈与点击穿透（用户 2026-10-23：
   * 「按靠上的地方有可能会把这个图关掉」「点击反馈向下移太夸张了」「点的是图标不要穿透到遮罩」）。
   *
   * 根因：按钮自己挂 `-translate-y-1/2`，而全局 `button:active { transform: scale(.97) }`
   * 与它同优先级且在样式表更靠后 ⇒ 按下瞬间整颗按钮下移 22px（半个按钮高）。
   * 这里用**真指针按住不放**读矩形：中心不许动（只许绕中心缩小），顶边位移 <= 2px。
   * 然后在靠上的位置原位抬起：必须切到上一张且窗不关（旧实现 pointerup 已落到遮罩）。
   * 第二发把抬起扔到遮罩角落：click 会被派发到共同祖先（遮罩），按下源守卫必须拒绝关窗。
   */
  const navRect = () => cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    const btns = dlg
      ? [...dlg.querySelectorAll('button')].filter((b) => String(b.className).includes('h-11'))
      : [];
    const b = btns[0];
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return {
      left: +r.left.toFixed(2), top: +r.top.toFixed(2), w: +r.width.toFixed(2), h: +r.height.toFixed(2),
      cx: +(r.left + r.width / 2).toFixed(2), cy: +(r.top + r.height / 2).toFixed(2),
    };
  })()`);
  const lightboxState = () => cdp.eval(`(() => ({
    open: !!document.querySelector('[role="dialog"]'),
    index: window.__lbState ? window.__lbState.index : -1,
    closes: (window.__probe.events || []).filter((e) => Array.isArray(e) && e[0] === 'close').length,
  }))()`);
  const navTransform = () => cdp.eval(`(() => {
    const b = [...document.querySelectorAll('[role="dialog"] button')]
      .find((x) => String(x.className).includes('h-11'));
    return b ? getComputedStyle(b).transform : null;
  })()`);

  const beforePress = await navRect();
  const pressX = beforePress ? Math.round(beforePress.cx) : 0;
  const pressY = beforePress ? Math.round(beforePress.top + 3) : 0;
  await cdp.send("Input.dispatchMouseEvent",
    { type: "mousePressed", x: pressX, y: pressY, button: "left", clickCount: 1 });
  await sleep(140);
  const whileHeld = await navRect();
  await cdp.send("Input.dispatchMouseEvent",
    { type: "mouseReleased", x: pressX, y: pressY, button: "left", clickCount: 1 });
  await sleep(220);
  const afterTopPress = await lightboxState();
  console.log("  ℹ 切换键按压实测 → " + JSON.stringify({ beforePress, whileHeld, afterTopPress }));
  check("左右切换键：按住时绕中心缩小（|中心位移|<=0.5px 且 |顶边位移|<=2px，不再整体下移）",
    !!beforePress && !!whileHeld
      && Math.abs(whileHeld.cy - beforePress.cy) <= 0.5
      && Math.abs(whileHeld.top - beforePress.top) <= 2,
    "中心不动 / 顶边位移 <= 2px", JSON.stringify({ beforePress, whileHeld }));
  // 正常模式的按压比例必须回到仓库统一的 0.97（组件自挂 0.95 会在这格露出来）。
  const pressRatio = beforePress && whileHeld ? +(whileHeld.w / beforePress.w).toFixed(3) : NaN;
  check("左右切换键：正常模式按压缩放走全局统一值 0.97（不是组件自挂的 0.95）",
    Math.abs(pressRatio - 0.97) <= 0.01, "w 比例 ≈ 0.97", JSON.stringify({ pressRatio, beforePress, whileHeld }));
  check("左右切换键：在靠上位置按下并原位抬起 ⇒ 切到上一张，窗不关（旧实现 click 落遮罩会关窗）",
    !!beforePress && afterTopPress.open === true && afterTopPress.closes === 0
      && afterTopPress.index === 0,
    "open=true / closes=0 / index=0", JSON.stringify(afterTopPress));

  const b2 = await navRect();
  await cdp.send("Input.dispatchMouseEvent", {
    type: "mousePressed",
    x: b2 ? Math.round(b2.cx) : 0,
    y: b2 ? Math.round(b2.cy) : 0,
    button: "left", clickCount: 1,
  });
  await cdp.send("Input.dispatchMouseEvent",
    { type: "mouseReleased", x: 4, y: 4, button: "left", clickCount: 1 });
  await sleep(220);
  const afterEscapeToShade = await lightboxState();
  check("左右切换键：图标上按下、抬起落到遮罩 ⇒ 不许穿透关窗（按下源守卫）",
    afterEscapeToShade.open === true && afterEscapeToShade.closes === 0,
    "open=true / closes=0", JSON.stringify(afterEscapeToShade));

  /*
   * 减少动态效果（用户 2026-10-23 审查）：仓库统一的按压是全局 `button:active { scale(.97) }`，
   * 而 reduce 档用 `transform: none` 关掉它。组件自挂 `active:scale-95`（0,2,0）会压过
   * 那条零特异性规则 ⇒ reduce 用户仍看到缩放。这里真按住读计算值。
   */
  try {
    await cdp.send("Emulation.setEmulatedMedia", {
      features: [{ name: "prefers-reduced-motion", value: "reduce" }],
    });
    await sleep(160);
    const reduceBefore = await navRect();
    const reduceIdle = await navTransform();
    await cdp.send("Input.dispatchMouseEvent", {
      type: "mousePressed",
      x: reduceBefore ? Math.round(reduceBefore.cx) : 0,
      y: reduceBefore ? Math.round(reduceBefore.cy) : 0,
      button: "left", clickCount: 1,
    });
    await sleep(140);
    const reduceHeld = await navRect();
    const reduceHeldTransform = await navTransform();
    await cdp.send("Input.dispatchMouseEvent", {
      type: "mouseReleased",
      x: reduceBefore ? Math.round(reduceBefore.cx) : 0,
      y: reduceBefore ? Math.round(reduceBefore.cy) : 0,
      button: "left", clickCount: 1,
    });
    await sleep(160);
    console.log("  ℹ 减少动态效果按压 → " + JSON.stringify({
      reduceIdle, reduceHeldTransform, reduceBefore, reduceHeld,
    }));
    check("减少动态效果：按住时 transform=none 且尺寸/中心不变（不产生按压缩放）",
      reduceIdle === "none" && reduceHeldTransform === "none"
        && !!reduceBefore && !!reduceHeld
        && reduceHeld.w === reduceBefore.w && reduceHeld.h === reduceBefore.h
        && Math.abs(reduceHeld.cy - reduceBefore.cy) <= 0.5,
      "transform=none / w,h 不变 / 中心不动",
      JSON.stringify({ reduceIdle, reduceHeldTransform, reduceBefore, reduceHeld }));
  } finally {
    await cdp.send("Emulation.setEmulatedMedia", { media: "", features: [] }).catch(() => {});
    await sleep(120);
  }

  /*
   * 反向对照：给按钮临时注入一条 `:active { transform: translateY(10px) !important }`，
   * 按住时同一把尺子必须读到 > 2px。旧代码读到的正是 22px；这格证明「顶边位移」这个量
   * 真的跟着按压 transform 走，而不是恒 0 的空转判据。
   */
  const jumpBefore = await navRect();
  const jumpReady = await cdp.eval(`(() => {
    const st = document.createElement('style');
    st.id = 'probe-jump';
    st.textContent = 'button.probe-jump:active { transform: translateY(10px) !important; }';
    document.head.appendChild(st);
    const b = [...document.querySelectorAll('[role="dialog"] button')]
      .find((x) => String(x.className).includes('h-11'));
    if (!b) return false;
    b.classList.add('probe-jump');
    return true;
  })()`);
  await cdp.send("Input.dispatchMouseEvent", {
    type: "mousePressed",
    x: jumpBefore ? Math.round(jumpBefore.cx) : 0,
    y: jumpBefore ? Math.round(jumpBefore.cy) : 0,
    button: "left", clickCount: 1,
  });
  await sleep(140);
  const jumpHeld = await navRect();
  await cdp.send("Input.dispatchMouseEvent", {
    type: "mouseReleased",
    x: jumpBefore ? Math.round(jumpBefore.cx) : 0,
    y: jumpBefore ? Math.round(jumpBefore.cy) : 0,
    button: "left", clickCount: 1,
  });
  await cdp.eval(`(() => {
    document.getElementById('probe-jump')?.remove();
    document.querySelectorAll('button.probe-jump').forEach((b) => b.classList.remove('probe-jump'));
    return true;
  })()`);
  await sleep(120);
  const jumpDelta = jumpBefore && jumpHeld ? +(jumpHeld.top - jumpBefore.top).toFixed(2) : NaN;
  console.log("  · 反向对照·切换键位移：" + JSON.stringify({ jumpReady, jumpDelta, jumpBefore, jumpHeld }));
  check("反向对照·切换键位移量具：注入 10px 按压位移后同一把尺子读到 > 2px（判据不是恒绿）",
    jumpReady === true && jumpDelta > 2,
    "读到 > 2px", JSON.stringify({ jumpReady, jumpDelta }));

  // 关闭后焦点归还，DOM 撤净（leave 过渡 100ms）。
  await cdp.key("Escape", "Escape", "", 27);
  await sleep(650);
  s = await read();
  const focusBack = await cdp.eval("document.activeElement && document.activeElement.id");
  check("Esc 关闭：浮层 DOM 撤净且焦点回到 opener（FocusScope 的卸载归还）",
    s.open === false && focusBack === "opener",
    "dialog=0 且 activeElement=#opener", JSON.stringify({ s, focusBack }));
}

/**
 * 收藏页 / 任务卡片的图片缩略图四角暗边（--only=favthumb）。
 *
 * 用户 2026-11-05：「收藏页里的图片缩略图，四个圆角处是黑的」—— 亮色主题、白底上四个暗角。
 * 暗角是**合成与抗锯齿**的产物，读 computed style 看不见 ⇒ 这里截真图按像素读：
 * 四角各取 2/4/6px 的 3×3 网格，与图内中心点做逐通道差。
 * 阈值 4 的理由：实测干净态的噪声上限是 1（抗锯齿只抹 1 个通道档位），取 2 倍 = 4；
 * 暗边一旦出现，实测差 ≥ 20，离阈值一个数量级。
 */
async function runFavThumb(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1400, height: 900, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  const MARGIN = 12;
  // 阈值 = 实测噪声上限的 2 倍：干净态四角×3×3×六种组合（亮/暗 × 正常/hover × 有图/占位），
  // 连跑两次离「底色↔内容色」线段最远 2.11 / 1.16（8-bit 量化 + 底色渐变 + 亚像素对齐漂移），
  // 2 倍 ≈ 4.22；取 4（比 2 倍略严，不是放宽）。源图暗垫一旦露出来，
  // 亮色主题实测 ≥69、暗色主题 ≥5.2，都在阈值之上。
  const THRESH = 4;
  const now = Date.now();
  // 收藏页里被用户叫"缩略图"的那张 = 右栏详情预览（kind=image 才走到详情 `<img>`）。
  const fav = {
    id: "fav-shot", msg_id: "m-shot", conv_id: "conv-1", sender_id: "peer-1", kind: "image",
    content: JSON.stringify({ name: "image-172e3789.png", path: "/tmp/image-172e3789.png", size: 887271, subtype: "image" }),
    ts: now - 60_000, favorited_at: now - 60_000,
    media_path: "/tmp/image-172e3789.png", media_size: 887271, available: true,
  };
  const bytes = await cdp.eval("window.__probe.favShotPng()");
  await cdp.eval("window.__probe.stubApi('listFavorites', " + JSON.stringify([fav]) + ")");
  await cdp.eval("window.__probe.stubApi('readFavoritePreview', " + JSON.stringify(bytes) + ")");

  const mounted = await cdp.eval("window.__probe.install('/src/components/FavoritePanel.vue', '', '')");
  await cdp.eval(`(() => {
    const h = document.getElementById('probe-host');
    h.style.width = '1200px'; h.style.maxWidth = '1200px'; h.style.height = '820px';
    h.style.display = 'block'; h.style.overflow = 'hidden';
    return true;
  })()`);
  await sleep(500);
  // 选中那条图片收藏（active 初值是 null，详情不会自己渲染）
  await cdp.eval(`(() => {
    const b = [...document.querySelectorAll('button')].find((x) => (x.innerText || '').includes('image-172e3789'));
    if (b) b.click();
    return !!b;
  })()`);

  let ready = false;
  for (let i = 0; i < 40 && !ready; i += 1) {
    ready = await cdp.eval(`(() => {
      const i = [...document.querySelectorAll('img')].find((x) => String(x.src).startsWith('blob:'));
      return !!(i && i.complete && i.naturalWidth > 0);
    })()`);
    if (!ready) await sleep(200);
  }

  // 元素框 + 真实内容框（object-contain 之后）。缺陷就是"元素框比内容框宽"。
  const geo = () => cdp.eval(`(() => {
    const i = [...document.querySelectorAll('img')].find((x) => String(x.src).startsWith('blob:'));
    if (!i) return null;
    const r = i.getBoundingClientRect();
    const st = getComputedStyle(i);
    // 渲染链逐层读数：img 自己 + 往上三层（详情栏 / 面板 / 宿主）的
    // 底色·圆角·overflow·background-clip·isolation·内阴影 —— 用户要的就是这张表。
    const chain = [];
    let e = i;
    for (let k = 0; k < 4 && e; k += 1) {
      const s = getComputedStyle(e);
      const q = e.getBoundingClientRect();
      chain.push({
        tag: e.tagName.toLowerCase() + (e.className && typeof e.className === "string" ? "." + e.className.split(/\\s+/).slice(0, 3).join(".") : ""),
        w: Math.round(q.width), h: Math.round(q.height),
        bg: s.backgroundColor, radius: s.borderRadius, overflow: s.overflow,
        clip: s.backgroundClip, isolation: s.isolation, shadow: s.boxShadow,
      });
      e = e.parentElement;
    }
    return { x: r.left, y: r.top, w: r.width, h: r.height,
      nw: i.naturalWidth, nh: i.naturalHeight, fit: st.objectFit, radius: st.borderTopLeftRadius, chain };
  })()`);
  const contentRect = (g) => {
    const s = Math.min(g.w / g.nw, g.h / g.nh);
    const cw = g.nw * s;
    const ch = g.nh * s;
    return { x: g.x + (g.w - cw) / 2, y: g.y + (g.h - ch) / 2, w: cw, h: ch };
  };
  const g0 = await geo();
  const rect = g0 ? contentRect(g0) : null;

  const sample = async (r, from) => {
    const shot = await cdp.send("Page.captureScreenshot", {
      format: "png",
      clip: { x: r.x - MARGIN, y: r.y - MARGIN, width: r.w + MARGIN * 2, height: r.h + MARGIN * 2, scale: 1 },
    });
    return cdp.eval("window.__probe.favSample(" + JSON.stringify(shot.data) + "," + r.w + "," + r.h + "," + MARGIN + "," + (from || 1) + ")");
  };
  /**
   * 四角判据：每个采样点必须落在「该角外底色 ↔ 图内容色」这条 RGB **线段**上（容差 THRESH）。
   *
   * 为什么是线段不是"等于两者之一"：圆角裁剪边界必然带 1px 抗锯齿，
   * 那一圈像素是底色与内容的**线性混合**，既不等于底色也不等于内容色；
   * 用"等于之一"会把合法的抗锯齿边全判红（实测半径 12px 时 m=117 全是这种假红）。
   *
   * 为什么线段能抓暗角：源图自带的近黑垫底（≈rgb(36,36,36)）不在该线段上 ——
   * 亮色主题里它比底色与内容色都暗（偏离 ≈68~200）；暗色主题里它是**中性灰**、
   * 而线段是从蓝黑到浅蓝，通道比例不同（整块 ≈16、半混合 ≈6），仍然出线。
   *
   * `fixedRefs` 用于"框里没有图"的占位态：参照改成容器自己的底色与描边色，
   * 否则深色垫底会被当成"内容色"而恒过。
   */
  const distToSegment = (p, a, b) => {
    const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
    const den = ab[0] * ab[0] + ab[1] * ab[1] + ab[2] * ab[2];
    const ap = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
    const t = den ? Math.min(1, Math.max(0, (ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / den)) : 0;
    const q = [a[0] + t * ab[0], a[1] + t * ab[1], a[2] + t * ab[2]];
    return Math.max(Math.abs(p[0] - q[0]), Math.abs(p[1] - q[1]), Math.abs(p[2] - q[2]));
  };
  const worst = (s, fixedRefs) => {
    let m = 0;
    let at = null;
    const per = [];
    for (const c of s.corners) {
      const a = fixedRefs ? fixedRefs[0] : c.out;
      const b = fixedRefs ? fixedRefs[1] : s.inner;
      let cm = 0;
      let cp = null;
      for (const p of c.pts) {
        const d = distToSegment(p.rgb, a, b);
        if (d > cm) { cm = d; cp = { dx: p.dx, dy: p.dy, rgb: p.rgb }; }
        if (d > m) { m = d; at = { corner: c.name, dx: p.dx, dy: p.dy, rgb: p.rgb, refs: [a, b], band: +d.toFixed(2) }; }
      }
      per.push({ corner: c.name, m: +cm.toFixed(2), rgb: cp && cp.rgb });
    }
    return { m, at, per };
  };
  const setTheme = async (dark) => {
    await cdp.eval("(() => { document.documentElement.classList." + (dark ? "add" : "remove") + "('dark'); return true; })()");
    await sleep(250);
  };
  const hoverAt = async (x, y) => {
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: Math.round(x), y: Math.round(y) });
    await sleep(350);
  };

  await setTheme(false);
  const lightNormal = await sample(rect);
  const lightRef = worst(lightNormal);
  check("收藏详情预览：真实字节解码出来了（像素通道这条量具不是空转）",
    !!mounted && mounted.ok === true && ready && !!g0 && !!rect
      && rect.w >= 100
      && Math.max(...[0, 1, 2].map((k) => Math.abs(lightNormal.inner[k] - [244, 246, 249][k]))) <= 3,
    "mount ok + img.complete + 内容矩形 ≥100px + 图内像素是夹具的浅色窗口",
    JSON.stringify({ mounted, ready, geo: g0, rect, inner: lightNormal.inner }));
  check("亮色·加载完成：四角 1/2/3px 网格落在「图内容色↔角外底色」线段上（通道差 ≤ " + THRESH + "）",
    lightRef.m <= THRESH,
    "四角差 ≤" + THRESH,
    JSON.stringify({ diff: lightRef, inner: lightNormal.inner }));

  await hoverAt(rect.x + rect.w / 2, rect.y + rect.h / 2);
  const lightHover = await sample(rect);
  await hoverAt(rect.x - 40, rect.y - 40);
  const lightHoverRef = worst(lightHover);
  check("亮色·hover：四角仍在「内容色↔底色」线段上，差 ≤ " + THRESH + "（悬停遮罩没有把暗边带出来）",
    lightHoverRef.m <= THRESH,
    "四角差 ≤" + THRESH,
    JSON.stringify({ diff: lightHoverRef, inner: lightHover.inner }));

  await setTheme(true);
  const darkNormal = await sample(rect);
  const darkRef = worst(darkNormal);
  check("暗色·加载完成：四角仍在「内容色↔底色」线段上，差 ≤ " + THRESH + "（暗角不许只换主题就看不见）",
    darkRef.m <= THRESH,
    "四角差 ≤" + THRESH,
    JSON.stringify({ diff: darkRef, inner: darkNormal.inner }));

  await hoverAt(rect.x + rect.w / 2, rect.y + rect.h / 2);
  const darkHover = await sample(rect);
  await hoverAt(rect.x - 40, rect.y - 40);
  const darkHoverRef = worst(darkHover);
  check("暗色·hover：四角仍在「内容色↔底色」线段上，差 ≤ " + THRESH,
    darkHoverRef.m <= THRESH,
    "四角差 ≤" + THRESH,
    JSON.stringify({ diff: darkHoverRef, inner: darkHover.inner }));

  // 小缩略图（TodoImageThumb）的加载中占位：框里没有图，角上只该是容器自己的底色。
  const thumbCorner = async () => {
    await cdp.eval("window.__probe.stubApiFail('readContentPreview', '内容不存在')");
    const mounted2 = await cdp.eval(`window.__probe.install('/src/components/TodoImageThumb.vue', '', ${
      JSON.stringify(JSON.stringify({
        isolated: true,
        image: { sha256: "cid-fav-thumb", name: "thumb.png", size: 100 },
        clickable: true,
      }))
    })`);
    await cdp.eval("(() => { const h = document.getElementById('probe-host'); h.style.padding = '24px'; h.style.width = '260px'; h.style.background = '#ffffff'; return true; })()");
    await sleep(600);
    const box = await cdp.eval(`(() => {
      const d = document.querySelector('#probe-host > div');
      if (!d) return null;
      const r = d.getBoundingClientRect();
      const st = getComputedStyle(d);
      const rgb = (v) => (String(v).match(/[0-9.]+/g) || []).slice(0, 3).map(Number);
      return { x: r.left, y: r.top, w: r.width, h: r.height,
        bg: rgb(st.backgroundColor), border: rgb(st.borderTopColor),
        radius: parseFloat(st.borderTopLeftRadius) || 0 };
    })()`);
    if (!box) return { mounted2, box, skel: null };
    /**
     * 采样起点必须**避开圆角描边弧**，而且必须按当前半径现算（2026-11-09 实测）：
     * 45° 上描边内沿 = `r − (r−1)/√2`；`--gosslan-radius-md` 实际是 10px ⇒ 3.64px。
     * 旧注释按 8px 半径写了固定 `from=4`，在这枚 10px 圆角上只比内沿多约 0.5px，
     * 截图取整偏半像素就踩到描边上 —— 读数正好等于 `borderTopColor`（亮 [232,232,237] /
     * 暗 [55,56,59]），四个角只有右下角翻红。这里按半径算，再留 2px 余量（现为 6）。
     */
    const from = Math.max(4, Math.ceil(box.radius - (box.radius - 1) / Math.SQRT2) + 2);
    const skel = await sample(box, from);
    return { mounted2, box, from, skel, ref: worst(skel, [box.bg, box.bg]) };
  };
  await setTheme(false);
  const skelLight = await thumbCorner();
  check("小缩略图·亮色·加载中占位：四角落在「容器底色↔描边色」线段上（通道差 ≤ " + THRESH + "，占位不写死深色垫底）",
    !!skelLight.mounted2 && skelLight.mounted2.ok === true && !!skelLight.ref && skelLight.ref.m <= THRESH,
    "占位四角差 ≤" + THRESH,
    JSON.stringify({ ref: skelLight.ref, from: skelLight.from, box: skelLight.box && { bg: skelLight.box.bg, border: skelLight.box.border, radius: skelLight.box.radius } }));

  await setTheme(true);
  const skelDark = await thumbCorner();
  check("小缩略图·暗色·加载中占位：四角落在「容器底色↔描边色」线段上（通道差 ≤ " + THRESH + "）",
    !!skelDark.mounted2 && skelDark.mounted2.ok === true && !!skelDark.ref && skelDark.ref.m <= THRESH,
    "占位四角差 ≤" + THRESH,
    JSON.stringify({ ref: skelDark.ref, from: skelDark.from, box: skelDark.box && { bg: skelDark.box.bg, border: skelDark.box.border, radius: skelDark.box.radius } }));

  // ── 同形缺陷的两处（用户 2026-11-05 裁决「同形缺陷一起修」）────────────────
  // 合并记录弹窗的图片项 / 消息流图片气泡，走的是同一条判据：
  // 元素框必须贴住内容（贴不住时下面的「元素框 == 内容框」那条先红，像素那条也红）。
  const scenario = async (cmpPath, propsJson) => {
    const m = await cdp.eval("window.__probe.install(" + JSON.stringify(cmpPath) + ", '', "
      + JSON.stringify(JSON.stringify(propsJson)) + ")");
    let ok = false;
    for (let i = 0; i < 50 && !ok; i += 1) {
      ok = await cdp.eval(`(() => {
        const i = [...document.querySelectorAll('img')].find((x) => String(x.src).startsWith('blob:'));
        return !!(i && i.complete && i.naturalWidth > 0);
      })()`);
      if (!ok) await sleep(200);
    }
    if (!ok) return { mounted: m, ready: false };
    // CDP 的 clip 用**文档坐标**，而 getBoundingClientRect 是视口坐标 ——
    // 前面弹窗那一段可能把页面滚了，这里不归零就会整片错位（实测错 ~12px，正好采到特征条）。
    await cdp.eval("(() => { window.scrollTo(0, 0); return true; })()");
    await sleep(150);
    await setTheme(false);
    const g = await geo();
    const r = g ? contentRect(g) : null;
    if (!r) return { mounted: m, ready: false, g };
    const ln = await sample(r);
    await hoverAt(r.x + r.w / 2, r.y + r.h / 2);
    const lh = await sample(r);
    await hoverAt(r.x - 40, r.y - 40);
    await setTheme(true);
    const dn = await sample(r);
    await hoverAt(r.x + r.w / 2, r.y + r.h / 2);
    const dh = await sample(r);
    await hoverAt(r.x - 40, r.y - 40);
    return {
      mounted: m, ready: true, g, rect: r, inner: ln.inner,
      light: worst(ln), lightHover: worst(lh), dark: worst(dn), darkHover: worst(dh),
    };
  };
  const reportScenario = (label, s) => {
    // 结构性判据放第一条：w-full 会把元素框撑到容器满宽，这条量的是"元素框 == 内容框"，
    // 比像素那条更早红，也解释了"为什么像素角会露"（裁剪面与内容角脱开）。
    const d = s.g && s.rect ? { dw: +(s.g.w - s.rect.w).toFixed(1), dh: +(s.g.h - s.rect.h).toFixed(1) } : null;
    check(label + "：元素框贴住内容框（宽/高差 ≤1px）", !!s.ready && !!d && Math.abs(d.dw) <= 1 && Math.abs(d.dh) <= 1,
      "元素框 == 内容框", JSON.stringify({ diff: d, element: s.g && { w: Math.round(s.g.w), h: Math.round(s.g.h), radius: s.g.radius }, content: s.rect && { w: Math.round(s.rect.w), h: Math.round(s.rect.h) } }));
    for (const [key, title] of [["light", "亮色·加载完成"], ["lightHover", "亮色·hover"], ["dark", "暗色·加载完成"], ["darkHover", "暗色·hover"]]) {
      const ref = s[key];
      check(label + "·" + title + "：四角落在「内容色↔底色」线段上（差 ≤ " + THRESH + "）",
        !!s.ready && !!ref && ref.m <= THRESH, "四角差 ≤" + THRESH, JSON.stringify({ diff: ref }));
    }
  };

  // 合并记录弹窗：图片项要等 onMounted 的 probe 拿到字节，所以先把 readContentPreview 打桩。
  const mergeContent = JSON.stringify({
    title: "合并记录",
    items: [{
      sender: "peer-1", kind: "image", ts: now - 30_000,
      content: JSON.stringify({ name: "image-172e3789.png", path: "/tmp/image-172e3789.png", size: 887271, sha256: "cid-shot", subtype: "image" }),
    }],
  });
  await cdp.eval("window.__probe.stubApi('readContentPreview', " + JSON.stringify(bytes) + ")");
  const merge = await scenario("/src/components/message/MergeCardModal.vue", { isolated: true, open: true, content: mergeContent });
  reportScenario("合并记录弹窗图片", merge);

  // 消息流图片气泡：**竖图 + 带尺寸** 才会露 —— 外框宽 208、内容只有约 196（左右各留 6px），
  // 内容角缩在框内、框圆角裁不到。横图/无尺寸时元素框会自己缩到内容高，量不出问题。
  const bubbleUrl = await cdp.eval("(() => { const b = new Uint8Array(window.__probe.favShotPng(545, 800)); return URL.createObjectURL(new Blob([b], { type: 'image/png' })); })()");
  const bubble = await scenario("/src/components/message/MessageImageBubble.vue", { isolated: true, src: bubbleUrl, width: 545, height: 800 });
  reportScenario("消息图片气泡", bubble);

  console.log("  · favthumb 读数：" + JSON.stringify({
    element: g0 && { w: Math.round(g0.w), h: Math.round(g0.h), radius: g0.radius, fit: g0.fit },
    chain: g0 && g0.chain,
    content: rect && { w: Math.round(rect.w), h: Math.round(rect.h) },
    light: lightRef, lightHover: lightHoverRef, dark: darkRef, darkHover: darkHoverRef,
    skelLight: skelLight.ref, skelDark: skelDark.ref,
    // 三处同形：合并记录弹窗图片项 / 消息流图片气泡（用户 2026-11-05 裁决扩到三处）
    merge: merge && {
      element: merge.g && { w: Math.round(merge.g.w), h: Math.round(merge.g.h), radius: merge.g.radius },
      content: merge.rect && { w: Math.round(merge.rect.w), h: Math.round(merge.rect.h) },
      light: merge.light, lightHover: merge.lightHover, dark: merge.dark, darkHover: merge.darkHover,
    },
    bubble: bubble && {
      element: bubble.g && { w: Math.round(bubble.g.w), h: Math.round(bubble.g.h), radius: bubble.g.radius },
      content: bubble.rect && { w: Math.round(bubble.rect.w), h: Math.round(bubble.rect.h) },
      light: bubble.light, lightHover: bubble.lightHover, dark: bubble.dark, darkHover: bubble.darkHover,
    },
  }));
  await setTheme(false);
}

/**
 * 图片灯箱 FLIP 缩放 + 点击热区那一段（--only=imgzoom）。
 *
 * 用户 2026-11-05：「点图片应该放大缩小，现在只有向右一下；点击区域有时候不生效」。
 * 这里不靠肉眼：逐帧（rAF）读**被点缩略图**与**查看器图片**的真实矩形/transform，
 * 证明打开第一帧 ≈ 原图矩形、水平位移恒为 0（缩略图与查看器同轴）、宽度单调放大；
 * 关闭反向缩回且可打断（开场中途关、连点两下都只关一次）。
 * 点击命中率在 MessageImageBubble 上冷（还在退避重试）/ 热（已解码）各真鼠标点 3 次，必须 3/3。
 * reduce 档另起一份：不缩放，直接落终态。
 */
/**
 * 移动端覆盖层的三件硬约束（用户 2026-11-06 追加）：
 * 1) **层级真在顶层**：点击点 `elementFromPoint` 必须落在覆盖层自身节点里；
 * 2) **手势不穿透**：真实触摸拖动/捏合时，底层列表 `scrollTop` 与 `window.scrollY` 零变化，
 *    同时内部缩放照常生效；
 * 3) **关闭立刻可滚**：反复开关 5 次，每次都把底层滚动重新写进去再读回来。
 *
 * 触摸用 CDP `Input.dispatchTouchEvent`（真事件，能触发浏览器原生滚动）——
 * 页面内 `dispatchEvent` 造的合成事件没有默认行为，"没穿透"就变成一句空话。
 */
async function runMobileOverlay(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: true, maxTouchPoints: 5 }).catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 390, height: 844, deviceScaleFactor: 2, mobile: true,
  }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const view = await cdp.eval("({ w: innerWidth, h: innerHeight })");
  check("移动端视口 390×844（mobile=true，真触摸事件）",
    !!view && view.w === 390 && view.h === 844, "390×844", JSON.stringify(view));

  const mounted = await cdp.eval("window.__probe.mobileOverlayMount(false)");
  check("移动端覆盖层挂载：底层列表真的可滚（初始 scrollTop=120）",
    !!mounted && mounted.ok === true && mounted.listTop === 120 && mounted.scrollY === 120,
    "listTop/scrollY 都是 120", JSON.stringify(mounted));

  // 开场 FLIP 期间 onPointerDown 会主动忽略手势（组件里 closing/pendingFlip 那条守卫），
  // 所以量手势之前必须先等它落定，否则读到的是"手势没反应"的假红（本轮真实发生过）。
  await sleep(900);

  const scaleOf = (tf) => {
    const m = /matrix\(([^)]+)\)/.exec(tf || "");
    if (!m) return null;
    const p = m[1].split(",").map(Number);
    return { sx: p[0], sy: p[3], tx: p[4] || 0, ty: p[5] || 0 };
  };
  const read = (x = 195, y = 422) => cdp.eval(`window.__probe.moRead(${x}, ${y})`);

  // ── ① 层级：点击点必须命中覆盖层自己，而不是底下的列表 ──────────────
  const before = await read();
  check("覆盖层在顶层：点击点 elementFromPoint 落在覆盖层自身节点里",
    before.inside === true && !String(before.hit || "").includes("probe-list"),
    "inside=true 且命中不是列表", JSON.stringify(before));

  // ── ② 捏合：内部缩放照常生效（先做，因为单指平移只在放大后才有意义）────
  await cdp.send("Input.dispatchTouchEvent", {
    type: "touchStart", touchPoints: [
      { x: 170, y: 420, id: 2, radiusX: 2, radiusY: 2, force: 1 },
      { x: 220, y: 420, id: 3, radiusX: 2, radiusY: 2, force: 1 },
    ],
  });
  for (let i = 1; i <= 5; i += 1) {
    await cdp.send("Input.dispatchTouchEvent", {
      type: "touchMove", touchPoints: [
        { x: 170 - i * 14, y: 420, id: 2, radiusX: 2, radiusY: 2, force: 1 },
        { x: 220 + i * 14, y: 420, id: 3, radiusX: 2, radiusY: 2, force: 1 },
      ],
    });
  }
  await cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  await sleep(260);
  const zoomed = await read();
  const s0 = scaleOf(before.tf);
  const s1 = scaleOf(zoomed.tf);
  check("捏合后图片缩放 >1（内部缩放手势照常生效）",
    !!s1 && (s1.sx > (s0 ? s0.sx : 1) + 0.03), "scale 增大",
    `${JSON.stringify(s0)} → ${JSON.stringify(s1)}｜ev=${JSON.stringify(zoomed.ev)}｜chain=${JSON.stringify(zoomed.chain)}`);

  // ── ③ 单指拖动：放大后平移照常生效，且底层零变化 ────────────────────
  const tf0 = zoomed.tf;
  await cdp.send("Input.dispatchTouchEvent", {
    type: "touchStart", touchPoints: [{ x: 195, y: 420, id: 4, radiusX: 2, radiusY: 2, force: 1 }],
  });
  for (let i = 1; i <= 6; i += 1) {
    await cdp.send("Input.dispatchTouchEvent", {
      type: "touchMove", touchPoints: [{ x: 195 - i * 12, y: 420 - i * 18, id: 4, radiusX: 2, radiusY: 2, force: 1 }],
    });
  }
  await cdp.send("Input.dispatchTouchEvent", { type: "touchEnd", touchPoints: [] });
  await sleep(180);
  const afterDrag = await read();
  check("拖动覆盖层时底层列表 scrollTop 零变化",
    afterDrag.listTop === before.listTop, `Δ=${afterDrag.listTop - before.listTop}`, `${before.listTop} → ${afterDrag.listTop}`);
  check("拖动覆盖层时 window.scrollY 零变化",
    afterDrag.scrollY === before.scrollY, `Δ=${afterDrag.scrollY - before.scrollY}`, `${before.scrollY} → ${afterDrag.scrollY}`);
  check("拖动时图片 transform 有变化（手势没有被一起锁死）",
    afterDrag.tf !== tf0, "transform 变了",
    `${tf0} → ${afterDrag.tf}｜ev=${JSON.stringify(afterDrag.ev)}｜chain=${JSON.stringify(afterDrag.chain)}`);

  // ── ④ 反复开关 5 次：每次关闭后都能滚，且没有全局 overflow 残留 ────────
  for (let k = 0; k < 5; k += 1) {
    await cdp.eval("window.__probe.moOpen(false)");
    await sleep(320);
    const set = await cdp.eval(`window.__probe.moSetScroll(${60 + k})`);
    check(`第 ${k + 1} 次关闭后底层立刻可滚`,
      !!set && set.ok === true && set.listTop === 60 + k && set.scrollY === 60 + k,
      `写 ${60 + k} 读回 ${set && set.listTop}`, JSON.stringify(set));
    const closed = await read();
    check(`第 ${k + 1} 次关闭后没有全局 overflow 残留（与基线一致）`,
      !!closed.base && closed.bodyOverflow === closed.base.body && closed.htmlOverflow === closed.base.html,
      `body/html = 基线 ${JSON.stringify(closed.base)}`,
      `${closed.bodyOverflow} / ${closed.htmlOverflow} vs ${JSON.stringify(closed.base)}`);
    await cdp.eval("window.__probe.moOpen(true)");
    await sleep(260);
    await cdp.eval("window.__probe.moSetScroll(120)");
  }

  // ── ⑤ 三档尺寸 × 亮暗：结构判据 + 截图 ────────────────────────────
  // 同一份挂载换视口，不再逐档重挂：重挂会反复 import 组件图（vite 偶发依赖优化 reload
  // 会把 __probe 清掉，本轮真实读到过 `Cannot read properties of undefined (reading 'moRect')`），
  // 而覆盖层是 fixed inset，视口一变几何就跟着变 —— 重挂对这几条结构判据没有额外信息量。
  const dir = "test-results/preview-shots";
  fs.mkdirSync(dir, { recursive: true });
  await cdp.eval("window.__probe.moOpen(true)");
  for (const [w, h] of [[360, 640], [390, 844], [430, 932]]) {
    for (const dark of [false, true]) {
      await cdp.send("Emulation.setDeviceMetricsOverride", {
        width: w, height: h, deviceScaleFactor: 2, mobile: true,
      }).catch(() => {});
      await cdp.eval("document.documentElement.classList.toggle('dark', " + (dark ? "true" : "false") + "); true");
      await sleep(320);
      const m = await cdp.eval("window.__probe.moRect()");
      check(`移动端 ${w}×${h}${dark ? "·暗" : "·亮"}：覆盖层铺满视口、无横向溢出`,
        !!m && !!m.rect && m.rect.left === 0 && m.rect.w === w && m.scrollW <= w,
        `rect=${m && m.rect && m.rect.w} scrollW=${m && m.scrollW}`, JSON.stringify(m));
      const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
      const file = `${dir}/mobile-${w}x${h}-${dark ? "dark" : "light"}.png`;
      fs.writeFileSync(file, Buffer.from(shot.data, "base64"));
    }
  }
  console.log(`  · mobileoverlay 截图 → ${dir}/mobile-*.png`);

  // 还原桌面口径（后面各段默认在桌面视口上跑）。
  await cdp.send("Emulation.setTouchEmulationEnabled", { enabled: false }).catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1440, height: 900, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
}

/**
 * `previewwin` 段的 Tauri IPC 桩 —— 用 `Page.addScriptToEvaluateOnNewDocument` 在
 * **页面脚本之前**注入（晚装会触发应用 boot 自检失败 → 整页 reload，见下面调用处注释）。
 * ⚠️ 这是 Node 的模板字符串：里面不许出现反引号。
 */
const PREVIEW_WIN_STUB = `
(() => {
  window.__pw = { gallery: null, handler: null, listens: 0, unlistens: 0, calls: [], opened: 0, fs: false };
  // 文档身份：整页 reload 会换一个新 document ⇒ 换一个新 id。
  // 采样前用它做"这一份文档稳住了"的判据（vite 依赖优化会发一次 full-reload）。
  window.__pwDocId = String(Date.now()) + '.' + Math.random().toString(36).slice(2);
  let seq = 700;
  window.__TAURI_INTERNALS__ = {
    metadata: { currentWindow: { label: 'preview' }, currentWebview: { label: 'preview', windowLabel: 'preview' } },
    transformCallback: (cb) => { const id = ++seq; window['_' + id] = cb; return id; },
    convertFileSrc: (p) => p,
    invoke: async (cmd, args) => {
      window.__pw.calls.push(cmd);
      if (cmd === 'plugin:event|listen') {
        window.__pw.listens += 1;
        window.__pw.handler = window['_' + (args && args.handler)] || null;
        return 1;
      }
      if (cmd === 'plugin:event|unlisten') { window.__pw.unlistens += 1; return null; }
      if (cmd === 'get_image_preview_gallery') {
        // 刻意给一点延迟：换图那一刻要先看到 loading 占位（旧图必须已经撤掉），
        // 否则"没有任何 loading 帧"会让"不残留旧图"这条判据空转成真空。
        await new Promise((r) => setTimeout(r, 40));
        return window.__pw.gallery;
      }
      // 双击的唯一含义（2026-11-09）：全屏切换。桩只记状态，OS 层由 Rust set_fullscreen 落地。
      if (cmd === 'window_toggle_fullscreen') { window.__pw.fs = !window.__pw.fs; return window.__pw.fs; }
      return null;
    },
  };
  if (!window.__TAURI_EVENT_PLUGIN_INTERNALS__) window.__TAURI_EVENT_PLUGIN_INTERNALS__ = { unregisterListener: () => {} };
  const svg = (c, label) => 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(
    '<svg xmlns="http://www.w3.org/2000/svg" width="640" height="400">'
    + '<rect width="640" height="400" fill="' + c + '"/>'
    + '<text x="320" y="215" font-size="64" fill="#ffffff" text-anchor="middle" font-family="sans-serif">' + label + '</text></svg>');
  window.__pwAlbums = [
    { items: [{ name: 'A.png', dataSrc: svg('#2563eb', 'A') }, { name: 'B.png', dataSrc: svg('#16a34a', 'B') }], index: 0 },
    { items: [{ name: 'C.png', dataSrc: svg('#dc2626', 'C') }, { name: 'A.png', dataSrc: svg('#2563eb', 'A') }], index: 1 },
    { items: [{ name: 'B.png', dataSrc: svg('#16a34a', 'B') }, { name: 'C.png', dataSrc: svg('#dc2626', 'C') }], index: 0 },
  ];
  window.__pw.gallery = window.__pwAlbums[0];
})();
`;

/**
 * 独立预览窗口的**文档层**读数（`preview.html` 的根组件 `PreviewWindow.vue`）。
 *
 * 这一格回答的是用户 2026-11-06 那条："窗实例只有一个；点了其他图片就替换内容"。
 * 真宿主里"窗口数=1"由 Rust 侧单例窗口守卫钉住（`lib_window_tests.rs` 的
 * `preview_window_has_exactly_one_creation_site`），这里量的是**替换那一刻**：
 * 连发 10 次 `preview-gallery`，逐帧采样 —— 文档根必须一直在（不空白）、必须是同一个节点
 * （没有关窗再开/重挂）、且 loading 占位期间不许还挂着旧图（不残影）。
 */
async function runPreviewWindow(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1280, height: 768, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
  // Tauri IPC 桩**必须在页面脚本之前**装好（`addScriptToEvaluateOnNewDocument`）。
  // 本轮踩到的形状：挂载后约 1 秒，应用的 boot 自检拿不到 `__TAURI_INTERNALS__.invoke`，
  // 整页 reload 一次（`Page.frameNavigated` 实测），把 `window.__pw` 和已挂载的组件一起清掉。
  await cdp.send("Page.addScriptToEvaluateOnNewDocument", { source: PREVIEW_WIN_STUB });
  // 直接开 `preview.html` 这一份**真文档**（不是把组件硬挂进主窗口的壳里）：
  // 与宿主里的窗口是同一个入口（`src/entries/preview.ts` → `PreviewWindow.vue`），
  // 第一帧还带 `#boot-preview` 骨架。代价是第一次进来时 vite 会为新发现的依赖发一次
  // 整页 reload（`Page.frameNavigated` 实测），把采样清空 —— 所以"准备"最多重试 4 次，
  // 判据是**重载后 `__pwDocId` 连续两次读一致、且状态已 ready**。
  const previewUrl = new URL("preview.html", url).toString();
  let albums = null;
  let first = null;
  let prepared = 0;
  for (let attempt = 1; attempt <= 4; attempt += 1) {
    await cdp.send("Page.navigate", { url: previewUrl });
    await cdp.settled();
    await sleep(2_200);
    albums = await cdp.eval("window.__pwAlbums");
    const before = await cdp.eval("window.__pwDocId || null");
    await sleep(1_500);
    const after = await cdp.eval("window.__pwDocId || null");
    first = await cdp.eval(`(() => {
      const el = document.querySelector('[data-preview-status]');
      return {
        alive: !!window.__pw, has: !!el,
        status: el && el.getAttribute('data-status'), count: el ? Number(el.getAttribute('data-count')) : -1,
        img: document.querySelectorAll('[data-lightbox-img]').length,
        listens: window.__pw ? window.__pw.listens : -1, handler: !!(window.__pw && window.__pw.handler),
        doc: window.__pwDocId || null,
      };
    })()`);
    const stable = !!before && before === after && !!first && first.doc === after;
    if (stable && first.alive && first.status === "ready") { prepared = attempt; break; }
    console.log(`  · previewwin 第 ${attempt} 次准备没稳住（vite 依赖优化整页 reload）：docId ${before} → ${after}`);
  }

  check("相册夹具已就位（3 组、每组 2 张）",
    Array.isArray(albums) && albums.length === 3 && albums.every((a) => a && a.items && a.items.length === 2),
    "3 组 × 2 张", JSON.stringify(albums && albums.map((a) => a.items.map((i) => i.name))));
  check("预览窗口文档挂得起来（AuxWindowShell + 相册）",
    prepared > 0, `第 ${prepared} 次准备后仍在跑`, JSON.stringify({ prepared, first }));
  check("首次挂载：相册取到并渲染出图（ready，2 张）",
    !!first && first.status === "ready" && first.count === 2 && first.img === 1, "ready/count=2/img=1", JSON.stringify(first));
  check("preview-gallery 订阅已建立（窗口已开着时换图靠它）",
    !!first && first.listens >= 1 && first.handler === true, "listen≥1 且 handler 已捕获", JSON.stringify(first));

  // ── 画板结构：深色顶栏 / 底部缩略图条 / 缩放与元数据（2026-11-08）─────────
  // 这一格量的是"三条 chrome 与图片安全区的相对位置"，不是像素级外观：
  // 顶栏和缩略图条都不许盖住图片，否则"图片绝不裁切"会退化成"被 UI 压掉一截"。
  // 2026-11-08 第二条（用户标红"底下重复又压图"）之后，底部只剩缩略图条：
  // 文件名/尺寸/计数/缩放**只在顶栏出现一次**，所以这里同时数一遍"谁有几份"。
  await sleep(400);
  const chrome = await cdp.eval(`(() => {
    const q = (s) => document.querySelector(s);
    const img = q('[data-lightbox-img]');
    const top = q('[data-lightbox-topbar]');
    const bottom = q('[data-lightbox-bottom]');
    const tr = top ? top.getBoundingClientRect() : null;
    const br = bottom ? bottom.getBoundingClientRect() : null;
    const ir = img ? img.getBoundingClientRect() : null;
    const text = (el) => (el ? (el.textContent || '').replace(/\\s+/g, ' ').trim() : '');
    return {
      name: text(top),
      counter: text(q('[data-lightbox-counter]')),
      dim: text(q('[data-lightbox-dim]')),
      topH: tr ? +tr.height.toFixed(1) : -1,
      imgTop: ir ? +ir.top.toFixed(1) : -1,
      imgBottom: ir ? +ir.bottom.toFixed(1) : -1,
      topBottom: tr ? +tr.bottom.toFixed(1) : -1,
      bottomTop: br ? +br.top.toFixed(1) : -1,
      bottomText: text(bottom),
      thumbs: document.querySelectorAll('[data-lightbox-thumb]').length,
      active: document.querySelectorAll('[data-lightbox-thumb][aria-current="true"]').length,
      zoom: text(q('[data-lightbox-zoom]')),
      zooms: document.querySelectorAll('[data-lightbox-zoom]').length,
      counters: document.querySelectorAll('[data-lightbox-counter]').length,
      imgs: document.querySelectorAll('[data-lightbox-img]').length,
    };
  })()`);
  check("预览窗口：深色顶栏显示文件名 + 计数（画板 DesktopPreviewWindow）",
    !!chrome && chrome.topH >= 55 && chrome.name.includes("A.png") && chrome.counter.includes("1 / 2"),
    "顶栏 56px、A.png、1 / 2", JSON.stringify(chrome));
  check("预览窗口：底部缩略图条 2 张、当前张唯一高亮",
    !!chrome && chrome.thumbs === 2 && chrome.active === 1,
    "thumbs=2 / active=1", JSON.stringify(chrome));
  check("预览窗口：图片安全区夹在顶栏与缩略图条之间（两条 chrome 不吃图）",
    !!chrome && chrome.imgs === 1
      && chrome.imgTop >= chrome.topBottom - 0.5 && chrome.imgBottom <= chrome.bottomTop + 0.5,
    "顶栏底 ≤ 图片顶、图片底 ≤ 底栏顶",
    `img[${chrome && chrome.imgTop}, ${chrome && chrome.imgBottom}] / bar[${chrome && chrome.topBottom}, ${chrome && chrome.bottomTop}]`);
  check("预览窗口：缩放读数 100%、元数据取到原图尺寸（不另发请求）",
    !!chrome && chrome.zoom === "100%" && /640\s*×\s*400/.test(chrome.dim),
    "zoom=100% / 原图 · 640 × 400", JSON.stringify(chrome));
  check("预览窗口：元数据/缩放/计数各只有一份（底部不再重复顶栏的信息）",
    !!chrome && chrome.zooms === 1 && chrome.counters === 1
      && !/100%|640\s*×\s*400|1\s*\/\s*2/.test(chrome.bottomText),
    "zoom×1 / counter×1 / 底栏无读数", JSON.stringify({
      zooms: chrome && chrome.zooms, counters: chrome && chrome.counters,
      bottomText: chrome && chrome.bottomText,
    }));

  // ── 缩略图：统一比例 / 同心圆角 / hover 与选中各一层（用户 2026-11-08）────────
  // 三条都量**计算样式与几何**（不是类名）：类名在、样式没生效，或两个分支各画一层，
  // 只有读实际读数才抓得住。反例自证紧跟其后（临时把 DOM 改成坏形状，必须能翻红）。
  const THUMB_RATIO = 86 / 58;
  const thumbIssues = (list) => {
    const ratio = [];
    const radius = [];
    const layers = [];
    (list || []).forEach((t, i) => {
      if (t.fit !== "cover") ratio.push(`#${i} object-fit=${t.fit}`);
      if (!(t.iw > 0 && t.ih > 0) || Math.abs(t.iw / t.ih - THUMB_RATIO) > 0.02) ratio.push(`#${i} ${t.iw}×${t.ih}`);
      if (Math.abs((t.outerRadius - t.innerRadius) - t.pad) > 0.6) {
        radius.push(`#${i} 外 ${t.outerRadius} − 内 ${t.innerRadius} ≠ pad ${t.pad}`);
      }
      if (t.ringLayers > 1) layers.push(`#${i} ${t.ringLayers} 层描边`);
    });
    return { ratio, radius, layers };
  };
  // 「几层描边」= box-shadow 里**画得出来**的层数：顶层逗号切分（括号内不算），
  // 再剔掉全透明占位层 —— Tailwind 的 ring 会连带输出 `rgba(0,0,0,0) 0 0 0 0` 这类
  // 不画任何东西的占位，数进层数会把"只有一层"误判成三层（本轮首跑真实红过）。
  const RING_COUNT_JS = `
    const visibleLayers = (shadow) => {
      if (!shadow || shadow === 'none') return 0;
      const segs = []; let depth = 0; let cur = '';
      for (const ch of shadow) {
        if (ch === '(') depth += 1;
        if (ch === ')') depth -= 1;
        if (ch === ',' && depth === 0) { segs.push(cur.trim()); cur = ''; } else cur += ch;
      }
      if (cur.trim()) segs.push(cur.trim());
      return segs.filter((s) => {
        const m = /rgba?\(([^)]*)\)/.exec(s);
        const alphaZero = (() => {
          if (!m) return false;
          const parts = m[1].split(',').map((x) => x.trim());
          return parts.length === 4 && Number(parts[3]) === 0;
        })();
        // 偏移/模糊/扩散全 0 的层画不出任何东西（就是上面说的占位层）。
        const nums = (s.replace(/rgba?\([^)]*\)/g, '').match(/-?[\\d.]+px/g) || []).map(parseFloat);
        const noGeometry = nums.length >= 3 && nums.every((n) => n === 0);
        return !alphaZero && !noGeometry;
      }).length;
    };
  `;
  const shot = await cdp.eval(`(() => {
    ${RING_COUNT_JS}
    const btns = () => [...document.querySelectorAll('[data-lightbox-thumb]')];
    const read = () => btns().map((b) => {
      const r = b.getBoundingClientRect();
      const img = b.querySelector('[data-lightbox-thumb-img]');
      const ir = img ? img.getBoundingClientRect() : null;
      const bs = getComputedStyle(b);
      const is = img ? getComputedStyle(img) : null;
      const shadow = bs.boxShadow;
      return {
        active: b.getAttribute('aria-current') === 'true',
        w: +r.width.toFixed(2), h: +r.height.toFixed(2),
        pad: parseFloat(bs.paddingTop),
        outerRadius: parseFloat(bs.borderTopLeftRadius),
        iw: ir ? +ir.width.toFixed(2) : -1,
        ih: ir ? +ir.height.toFixed(2) : -1,
        innerRadius: is ? parseFloat(is.borderTopLeftRadius) : -1,
        fit: is ? is.objectFit : '',
        ringLayers: visibleLayers(shadow),
        shadow,
      };
    });
    const out = { before: read(), broken: {} };
    const img0 = btns()[0] && btns()[0].querySelector('[data-lightbox-thumb-img]');
    const act = btns().find((b) => b.getAttribute('aria-current') === 'true');
    if (img0) {
      // 反例 1：内图比例不再统一（宽度被压窄 ⇒ 与 86:58 不符）
      img0.style.width = '70%';
      out.broken.ratio = read();
      img0.style.width = '';
      // 反例 2：不再裁切（object-fit 换成 contain）
      img0.style.objectFit = 'contain';
      out.broken.fit = read();
      img0.style.objectFit = '';
      // 反例 3：内图圆角归零 ⇒ 与外框不再同心
      img0.style.borderRadius = '0px';
      out.broken.radius = read();
      img0.style.borderRadius = '';
    }
    if (act) {
      // 反例 4：选中项再叠一层描边（两层 shadow）
      const prev = act.style.boxShadow;
      act.style.boxShadow = '0 0 0 2px rgb(255,0,0), 0 0 0 4px rgb(0,255,0)';
      out.broken.layers = read();
      act.style.boxShadow = prev;
    }
    out.after = read();
    return out;
  })()`);
  const thumbBefore = thumbIssues(shot && shot.before);
  console.log("  ℹ 缩略图读数 → " + JSON.stringify((shot && shot.before) || null));
  check("预览窗口·缩略图：统一 86:58 且 object-cover（各按原图比例会把条带撑得高低不齐）",
    !!shot && shot.before.length === 2 && thumbBefore.ratio.length === 0,
    "两张都 86:58 / cover", JSON.stringify(thumbBefore.ratio));
  check("预览窗口·缩略图：外框圆角 − 内图圆角 = 内边距（严格同心）",
    !!shot && shot.before.length === 2 && thumbBefore.radius.length === 0,
    "外 10 − 内 8 = pad 2", JSON.stringify(thumbBefore.radius));
  check("预览窗口·缩略图：选中只一层描边（ring-1 被 ring-2 顶替，不叠两层）",
    !!shot && shot.before.filter((t) => t.active).length === 1 && thumbBefore.layers.length === 0,
    "选中层数=1", JSON.stringify(shot && shot.before.map((t) => ({ a: t.active, n: t.ringLayers }))));

  const brokenThumbs = {
    ratio: thumbIssues(shot && shot.broken.ratio).ratio.length > 0,
    fit: thumbIssues(shot && shot.broken.fit).ratio.length > 0,
    radius: thumbIssues(shot && shot.broken.radius).radius.length > 0,
    layers: thumbIssues(shot && shot.broken.layers).layers.length > 0,
  };
  check("反例自证：比例被改 / 去掉 cover / 圆角归零 / 叠第二层描边 —— 四种坏形状都必须翻红",
    brokenThumbs.ratio && brokenThumbs.fit && brokenThumbs.radius && brokenThumbs.layers,
    "四条反例全红", JSON.stringify(brokenThumbs));

  // hover：真指针移到"非当前"那张上，它必须**只多一层淡边**（层数仍是 1，颜色变亮），
  // 且不许把选中项那层描边顶掉/叠成两层。
  const hoverTarget = await cdp.eval(`(() => {
    const b = [...document.querySelectorAll('[data-lightbox-thumb]')]
      .find((x) => x.getAttribute('aria-current') !== 'true');
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
  })()`);
  if (hoverTarget) {
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: hoverTarget.x, y: hoverTarget.y, buttons: 0 });
    await sleep(200);
  }
  const hoverState = await cdp.eval(`(() => {
    ${RING_COUNT_JS}
    const btns = [...document.querySelectorAll('[data-lightbox-thumb]')];
    const pick = (b) => {
      const shadow = getComputedStyle(b).boxShadow;
      return { active: b.getAttribute('aria-current') === 'true', layers: visibleLayers(shadow), shadow };
    };
    return { all: btns.map(pick), hovered: btns.length > 1 ? pick(btns.find((b) => b.getAttribute('aria-current') !== 'true') || btns[0]) : null };
  })()`);
  check("预览窗口·缩略图：hover 只给一层淡边（不与选中态叠成两层）",
    !!hoverState && !!hoverState.hovered
      && hoverState.hovered.layers === 1 && hoverState.all.every((t) => t.layers <= 1)
      // 只数层数不够：层数恒为 1 时"hover 根本没生效"也会绿 ⇒ 再要求描边颜色真的变了。
      && !!shot && shot.before.length > 1 && hoverState.hovered.shadow !== shot.before[1].shadow,
    "每张 1 层描边，且 hover 那张颜色变了", JSON.stringify({
      idle: shot && shot.before[1] && shot.before[1].shadow,
      hovered: hoverState && hoverState.hovered,
    }));

  // ── 连点 10 张：逐帧采样 ─────────────────────────────────────────
  await cdp.eval(`(() => {
    // 采样写**字符串**而不是数组：CDP 读回大数组时偶发拿不到值（本轮实测 typeof 是 object、
    // 读回却是 undefined）。逐帧一行 JSON 是纯字符串，读回稳定。
    window.__pwTrace = '';
    window.__pwTick = 0;
    window.__pwRoot = document.querySelector('[data-preview-status]');
    window.__pwRun = true;
    const loop = () => {
      window.__pwTick += 1;
      const el = document.querySelector('[data-preview-status]');
      window.__pwTrace += JSON.stringify({
        t: Math.round(performance.now()),
        has: !!el,
        same: el === window.__pwRoot,
        status: el ? el.getAttribute('data-status') : null,
        count: el ? Number(el.getAttribute('data-count')) : -1,
        index: el ? Number(el.getAttribute('data-index')) : -1,
        imgs: document.querySelectorAll('[data-lightbox-img]').length,
      }) + '\\n';
      if (window.__pwRun) requestAnimationFrame(loop);
    };
    requestAnimationFrame(loop);
    return true;
  })()`);
  console.log("  · previewwin sampling kick:", JSON.stringify(await cdp.eval("({t: typeof window.__pwTrace, run: !!window.__pwRun, root: !!window.__pwRoot})")));
  console.log("  · previewwin alive:", JSON.stringify(await cdp.eval("({pw: !!window.__pw, albums: Array.isArray(window.__pwAlbums), probe: !!window.__probe, tick: window.__pwTick || 0})")));
  for (let k = 1; k <= 10; k += 1) {
    // 夹具从 Node 侧带过来，不从页面全局再读一份：`window.__pwAlbums` 在挂载后偶发不可见
    // （本轮读到过 `undefined[0]`），而"再读一次页面变量"会把夹具状态和被测状态混在一起。
    await cdp.eval(`(() => {
      try {
        window.__pw.gallery = ${JSON.stringify(albums[k % 3])};
        if (window.__pw.handler) window.__pw.handler({ event: 'preview-gallery', payload: null, id: 1 });
        return 'ok';
      } catch (e) {
        return 'ERR:' + e.message + '|href=' + location.href + '|pw=' + (typeof window.__pw);
      }
    })()`).then((r) => {
      if (String(r).startsWith("ERR:")) console.log(`  · 投递 ${k} 异常：${r}｜事件尾=${JSON.stringify(cdp.eventTail.slice(-4))}`);
    });
    await sleep(45);
  }
  await sleep(700);
  await cdp.eval("window.__pwRun = false; true");
  const trace = await cdp.eval("window.__pwTrace");
  console.log("  · previewwin ticks:", await cdp.eval("window.__pwTick || 0"));
  console.log("  · previewwin 导航尾:", JSON.stringify(cdp.navTail));
  const samples = String(trace || "").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
  console.log("  · previewwin samples:", samples.length);
  if (!Array.isArray(samples) || samples.length === 0) {
    throw new Error("逐帧采样没拿到（__pwSamples=" + JSON.stringify(samples) + "）—— 不是产品结论，是量具没跑");
  }
  const blank = samples.filter((s) => !s.has).length;
  const remount = samples.filter((s) => !s.same).length;
  const stale = samples.filter((s) => s.status === "loading" && s.imgs > 0).length;
  const readyEmpty = samples.filter((s) => s.status === "ready" && s.count === 0).length;
  const last = samples[samples.length - 1];
  // 读数行：判据只在红的时候才印 actual，绿的时候没人看得见到底采到了多少 ——
  // 而"10 连点有没有中间态"正是要拿这些计数去汇报的，所以每次跑都印一行。
  console.log(`  · previewwin 采样：${samples.length} 帧 blank=${blank} remount=${remount} stale=${stale} readyEmpty=${readyEmpty}`);
  check("10 连点：采样帧里没有空白窗（文档根一直在）",
    samples.length >= 30 && blank === 0, `samples=${samples.length} blank=${blank}`,
    `blank=${blank} / ${samples.length} 帧`);
  check("10 连点：始终是同一个根节点（没有关窗再开/重挂）",
    remount === 0, `remount=${remount}`, `remount=${remount} / ${samples.length} 帧`);
  check("10 连点：换图期不残留旧图（loading 帧里没有 [data-lightbox-img]）",
    stale === 0, `stale=${stale}`, `stale=${stale} / ${samples.length} 帧`);
  check("10 连点：不存在 ready 但 0 张图的中态",
    readyEmpty === 0 && last.status === "ready" && last.count === 2,
    `readyEmpty=${readyEmpty} 末帧=${JSON.stringify(last)}`, JSON.stringify(last));

  // ── 双击 = 全屏切换（唯一含义；缩放不再走双击）─────────────────
  // 读数口径：双击前后桩里的全屏状态必须 false→true→false（命令是 window_toggle_fullscreen）；
  // OS 层的全屏由 Rust `set_fullscreen` 落地，退出时平台还原原窗口 frame。
  const dblOnImage = async () => cdp.eval(`(() => {
    const el = document.querySelector('[data-lightbox-img]') || document.querySelector('[data-preview-status]');
    if (!el) return 'no-el';
    el.dispatchEvent(new MouseEvent('dblclick', { bubbles: true }));
    return 'ok';
  })()`);
  const fsBefore = await cdp.eval("!!(window.__pw && window.__pw.fs)");
  await dblOnImage();
  await sleep(200);
  const fsOn = await cdp.eval("!!(window.__pw && window.__pw.fs)");
  // 全屏那一下图片仍要**完整显示**（object-contain，显示比例 = 原图比例）。
  const fitOn = await cdp.eval(`(() => {
    const img = document.querySelector('[data-lightbox-img]');
    if (!img) return null;
    const r = img.getBoundingClientRect();
    return { fit: getComputedStyle(img).objectFit, w: Math.round(r.width), h: Math.round(r.height),
      shown: +(r.width / r.height).toFixed(3), natural: +(img.naturalWidth / img.naturalHeight).toFixed(3) };
  })()`);
  await dblOnImage();
  await sleep(200);
  const fsOff = await cdp.eval("!!(window.__pw && window.__pw.fs)");
  check("双击：一次进入全屏、再一次退出（前后状态 false→true→false）",
    fsBefore === false && fsOn === true && fsOff === false,
    "false → true → false", JSON.stringify({ fsBefore, fsOn, fsOff }));
  check("全屏进出后图片仍不裁切（object-contain，显示比例 = 原图比例）",
    !!fitOn && fitOn.fit === "contain" && Math.abs(fitOn.shown - fitOn.natural) < 0.02,
    "contain + 比例一致", JSON.stringify(fitOn));

  // ── 桌面两档截图（窗口文档的同一份内容）─────────────────────────
  const dir = "test-results/preview-shots";
  fs.mkdirSync(dir, { recursive: true });
  for (const [w, h] of [[1280, 768], [768, 1024]]) {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: w, height: h, deviceScaleFactor: 1, mobile: false,
    }).catch(() => {});
    await sleep(320);
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(`${dir}/desktop-${w}x${h}.png`, Buffer.from(shot.data, "base64"));
  }
  console.log(`  · previewwin 截图 → ${dir}/desktop-*.png`);

  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1440, height: 900, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
}

async function runImageZoom(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  // 桌面真实窗口口径（用户 2026-11-05 明确要求 ≥1440×900）：headless 的 1200×900 不够宽，
  // 覆盖层在更宽的视口下才看得出"水平位移恒 0"这条。只在本段生效，段末清掉。
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1440, height: 900, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const view = await cdp.eval("({ w: innerWidth, h: innerHeight })");
  check("桌面视口 ≥1440×900（覆盖层按视口定位；窗口级补间那条路已删除）",
    !!view && view.w >= 1440 && view.h >= 900,
    "innerWidth/innerHeight ≥1440×900", JSON.stringify(view));

  const vis = (t) => t.frames.filter((f) => Number(f.opacity) >= 0.99);
  const near = (f, o, tol) =>
    !!f && Math.abs(f.left - o.left) <= tol && Math.abs(f.top - o.top) <= tol
    && Math.abs(f.w - o.width) <= tol && Math.abs(f.h - o.height) <= tol;
  const scaleOf = (tf) => {
    const m = /matrix\(([^)]+)\)/.exec(tf || "");
    if (!m) return null;
    const p = m[1].split(",").map(Number);
    return { sx: p[0], sy: p[3], tx: p[4], ty: p[5] };
  };
  /**
   * 等浮层真的撤掉（退场 100ms）。用轮询而不是死等一个固定时长：
   * 这台机器上并行构建/浏览器一忙，主线程会被占住几百毫秒，rAF 与 setTimeout 一起被拖长
   * ⇒ 原来写死 480/520ms 的"关闭后立刻断言"会偶发读到还挂在退场里的 dialog（真的红过）。
   * 轮询本身放在页面里（zoomWaitClosed）：Node 侧 32ms 一 eval 会把关闭动画的 rAF 帧挤掉。
   */
  const waitClosed = async (ms = 2500) => !!(await cdp.eval(`window.__probe.zoomWaitClosed(${ms})`));

  // ── ① 打开：从原图长出来，纯放大、无横向位移 ─────────────────────────
  // 先把关闭键文案预热好（冷 import 会拖慢后面两次点击的时序，见 H.zoomWarm 的说明）。
  await cdp.eval("window.__probe.zoomKick()");
  await cdp.eval("window.__probe.zoomWarm()");
  const mounted = await cdp.eval("window.__probe.zoomMount()");
  check("图片缩放：灯箱挂载成功（真实缩略图 + 640×360 图）",
    !!mounted && mounted.ok === true, "mount ok", JSON.stringify(mounted));
  // 等动画真的落定：轮询"最后一帧宽度 ≥600 且连续两次不变"，而不是死等 760ms。
  // 间隔取 150ms：每次 CDP eval 都占一个主线程时间片，40ms 一询会把动画自己的帧挤掉
  // （实测 n 从 9 掉到 5，判据反而更容易红）。
  let opened = null;
  let prevW = -1;
  let stable = 0;
  for (let i = 0; i < 24; i += 1) {
    opened = await cdp.eval("window.__probe.zoomTake()");
    const vf = vis(opened);
    const w = vf.length ? vf[vf.length - 1].w : -1;
    if (w >= 600 && Math.abs(w - prevW) < 0.5) stable += 1; else stable = 0;
    prevW = w;
    if (stable >= 2) break;
    await sleep(150);
  }
  const openFrames = vis(opened);
  const startFrame = openFrames.reduce((a, b) => (b.w < a.w ? b : a), openFrames[0]);
  const finalFrame = openFrames[openFrames.length - 1];
  check("打开：第一个可见帧 ≈ 被点缩略图矩形（从原图位置长出来，不是从别处滑入）",
    !!startFrame && near(startFrame, opened.origin, 4) && openFrames.length >= 6,
    "起点矩形 ≈ origin(±4px) 且可见帧 ≥6", JSON.stringify({ startFrame, origin: opened.origin, n: openFrames.length }));
  const maxCxDev = openFrames.reduce((m, f) => Math.max(m, Math.abs(f.cx - opened.viewport.w / 2)), 0);
  check("打开：水平位移恒为 0（缩略图与查看器同轴；任何\"向右一下\"都会在这里露头）",
    openFrames.length > 2 && maxCxDev <= 1.5,
    "所有帧 |cx - 视图中心| ≤ 1.5px", JSON.stringify({ maxCxDev, frames: openFrames.length }));
  let monotone = true;
  for (let i = 1; i < openFrames.length; i += 1) {
    if (openFrames[i].w < openFrames[i - 1].w - 0.75) monotone = false;
  }
  check("打开：宽度逐帧单调增大（是纯放大，不是来回滑）",
    monotone && openFrames.length > 2, "宽度列无回落（>0.75px 才算）", JSON.stringify(openFrames.map((f) => f.w)));
  check("打开：终态是查看器落定位置（宽度≈640、中心在视口中心）",
    !!finalFrame && finalFrame.w > 500 && Math.abs(finalFrame.cx - opened.viewport.w / 2) <= 1.5,
    "终态 w>500 且居中", JSON.stringify(finalFrame));
  const startScale = scaleOf(startFrame && startFrame.tf);
  const finalW = finalFrame ? finalFrame.w : 0;
  check("打开：第一帧是 transform scale（不是 left/top/width 布局补间）",
    !!startScale && finalW > 0 && Math.abs(startScale.sx - opened.origin.width / finalW) <= 0.02,
    "矩阵 scaleX ≈ origin.w/final.w", JSON.stringify({ startScale, expect: finalW ? opened.origin.width / finalW : null }));

  // ── ② 关闭：反向缩回原图位置，且真的播完再关 ────────────────────────
  await cdp.eval("window.__probe.zoomClose()");
  await waitClosed();
  await sleep(120);
  const closed = await cdp.eval("window.__probe.zoomTake()");
  const closeFrames = vis(closed).filter((f) => f.t >= (closed.closeAt ?? 0));
  const lastClose = closeFrames[closeFrames.length - 1];
  // 逐帧读数留首尾各 3 段（≥6 帧可复现"从原图长出来 / 缩回原图"的起落），又不把整段日志淹掉。
  console.log("· imgzoom 打开帧:", JSON.stringify({
    origin: closed.origin,
    viewport: closed.viewport,
    n: openFrames.length,
    head: openFrames.slice(0, 3).map((f) => [f.t, f.w, f.h, f.cx, f.tf]),
    mid: openFrames.slice(3, 6).map((f) => [f.t, f.w, f.h, f.cx, f.tf]),
    tail: openFrames.slice(-1).map((f) => [f.t, f.w, f.h, f.cx, f.tf]),
  }));
  console.log("· imgzoom 关闭帧:", JSON.stringify({
    closeAt: closed.closeAt,
    n: closeFrames.length,
    head: closeFrames.slice(0, 3).map((f) => [f.t, f.w, f.h, f.cx, f.cy, f.tf]),
    mid: closeFrames.slice(3, 6).map((f) => [f.t, f.w, f.h, f.cx, f.cy, f.tf]),
    tail: closeFrames.slice(-1).map((f) => [f.t, f.w, f.h, f.cx, f.cy, f.tf]),
  }));
  check("关闭：反向缩回原图位置（最后一帧 ≈ 缩略图矩形，且回缩过程 ≥6 帧可读）",
    !!lastClose && near(lastClose, closed.origin, 4) && closeFrames.length >= 6,
    "收尾矩形 ≈ origin(±4px) 且回缩帧 ≥6", JSON.stringify({ lastClose, origin: closed.origin, n: closeFrames.length }));
  check("关闭：先反向播放再卸载（不是瞬间消失）",
    !!lastClose && lastClose.t - closed.closeAt >= 140 && closed.closes === 1 && closed.open === false,
    "收尾 +≥140ms / close 只发一次 / 浮层已撤", JSON.stringify({ closeAt: closed.closeAt, last: lastClose && lastClose.t, closes: closed.closes, open: closed.open }));

  // ── ③ 可打断：开场动画中途点关闭 ────────────────────────────────────
  await cdp.eval("window.__probe.zoomMount()");
  // "中途"不能靠固定 60ms 赌：等真的跑起来（≥2 可见帧，且还没到终态尺寸）再打断。
  // 这样无论首帧解码多慢，打断点都在动画进行中（否则这条判据只是空测）。
  let midOpen = null;
  for (let i = 0; i < 90; i++) {
    const snap = await cdp.eval("window.__probe.zoomTake()");
    const vf = vis(snap);
    midOpen = vf.length >= 2 ? vf[vf.length - 1] : null;
    if (vf.length >= 2 && midOpen.w < 500) break;
    await sleep(16);
  }
  const interruptHit = await cdp.eval("window.__probe.zoomClose()");
  await waitClosed();
  await sleep(200);
  const interrupted = await cdp.eval("window.__probe.zoomTake()");
  const iFrames = vis(interrupted).filter((f) => f.t >= (interrupted.closeAt ?? 0));
  const iLast = iFrames[iFrames.length - 1];
  check("关闭可打断：开场中途关闭也只关一次，且仍收回原图位置",
    (!!interruptHit && interruptHit.ok === true) && !!midOpen && midOpen.w < 500
      && interrupted.closes === 1 && interrupted.open === false
      && (!iLast || near(iLast, interrupted.origin, 4)),
    "打断点确在动画中（w<500）且 closes=1 / open=false / 收尾≈origin",
    JSON.stringify({
      hit: interruptHit, midW: midOpen && midOpen.w,
      closes: interrupted.closes, open: interrupted.open, closeAt: interrupted.closeAt, n: iFrames.length,
      iLast, frames: iFrames.map((f) => [f.t, f.w, f.tf]),
    }));
  console.log("· imgzoom 打断帧:", JSON.stringify({
    midW: midOpen && midOpen.w, closeAt: interrupted.closeAt, n: iFrames.length,
    frames: iFrames.map((f) => [f.t, f.w, f.top, f.tf]),
  }));

  // ── ④ 连点两下关闭：closing 门闩只放行一次 ──────────────────────────
  await cdp.eval("window.__probe.zoomMount()");
  await sleep(700);
  const firstHit = await cdp.eval("window.__probe.zoomClose()");
  await sleep(50);
  const secondHit = await cdp.eval("window.__probe.zoomClose()");
  await waitClosed();
  await sleep(120);
  const doubleClosed = await cdp.eval("window.__probe.zoomTake()");
  check("关闭连点：两次都命中关闭键，但 close 只发生一次（不会关窗两次/打断回缩）",
    (!!firstHit && firstHit.ok === true) && (!!secondHit && secondHit.ok === true)
      && doubleClosed.closes === 1 && doubleClosed.open === false,
    "两次点击都命中 / closes=1 / open=false",
    JSON.stringify({ firstHit, secondHit, closes: doubleClosed.closes, open: doubleClosed.open }));

  // ── ⑤ reduce 档：不缩放，直接落终态 ───────────────────────────────
  await cdp.send("Emulation.setEmulatedMedia", {
    features: [{ name: "prefers-reduced-motion", value: "reduce" }],
  }).catch(() => {});
  await cdp.eval("window.__probe.zoomMount()");
  await sleep(480);
  const reduced = await cdp.eval("window.__probe.zoomTake()");
  const rFrames = vis(reduced);
  const rMin = rFrames.reduce((m, f) => Math.min(m, f.w), Infinity);
  check("reduce 档：打开不缩放（所有帧都已是终态尺寸，不从缩略图放大）",
    rFrames.length > 0 && rMin > 500,
    "min(w) > 500", JSON.stringify({ rMin, frames: rFrames.map((f) => f.w) }));
  await cdp.eval("window.__probe.zoomClose()");
  await waitClosed();
  await sleep(120);
  const rClosed = await cdp.eval("window.__probe.zoomTake()");
  // 判据从"140ms 内必须撤掉"换成"关闭期间一帧回缩都没有"：
  // 前者量的是 Vue 退场 Transition 的耗时（机器一忙就被拖长，2026-11-05 真红过一次），
  // 后者才是这条要守的东西 —— reduce 档不许有回缩动画。耗时仍打印出来备查。
  const rShrink = vis(rClosed)
    .filter((f) => f.t >= (rClosed.closeAt ?? 0))
    .filter((f) => f.w < 500);
  check("reduce 档：关闭不播回缩（关闭期间没有任何一帧比终态小，且只 close 一次）",
    rClosed.closes === 1 && rClosed.open === false && rShrink.length === 0,
    "closes=1 / open=false / 回缩帧 0",
    JSON.stringify({ closes: rClosed.closes, open: rClosed.open, closeAt: rClosed.closeAt,
      shrink: rShrink.length, frames: vis(rClosed).map((f) => [f.t, f.w]) }));
  await cdp.send("Emulation.setEmulatedMedia", {
    features: [{ name: "prefers-reduced-motion", value: "no-preference" }],
  }).catch(() => {});

  // ── ⑥ 点击命中率：冷（还在退避重试）/ 热（已解码）各真鼠标点 3 次 ─────
  await cdp.eval("window.__probe.install('/src/components/message/MessageImageBubble.vue', '', "
    + JSON.stringify(JSON.stringify({ src: "/probe-img-never-loads.png", mine: true })) + ")");
  await sleep(60);
  const cold = await cdp.eval("window.__probe.imgFrame()");
  check("点击热区：缩略图还没解码（loading）时外框就是可点按钮（role=button / tabindex=0）",
    !!cold && cold.state === "loading" && cold.role === "button" && cold.tab === "0",
    "loading 且 role=button/tab=0", JSON.stringify(cold));
  await cdp.eval("window.__probe.reset()");
  for (let i = 0; i < 3; i += 1) {
    const box = await cdp.eval("window.__probe.imgFrame()");
    if (!box) break;
    await cdp.click(box.cx, box.cy);
    await sleep(120);
  }
  const coldOpened = await cdp.eval("window.__probe.events.filter((e) => e[0] === 'open-id').length");
  check("点击一次必开：冷态（缩略图未加载）真鼠标连点 3 次 → open 3/3",
    coldOpened === 3, "open-id = 3", JSON.stringify({ coldOpened, state: (await cdp.eval("window.__probe.imgFrame()"))?.state }));

  const hotSrc = "data:image/svg+xml," + encodeURIComponent(
    "<svg xmlns='http://www.w3.org/2000/svg' width='640' height='360'><rect width='640' height='360' fill='#2f80ed'/></svg>");
  await cdp.eval("window.__probe.install('/src/components/message/MessageImageBubble.vue', '', "
    + JSON.stringify(JSON.stringify({ src: hotSrc, mine: true })) + ")");
  let hot = await cdp.eval("window.__probe.imgFrame()");
  for (let i = 0; i < 20 && (!hot || hot.state !== "loaded"); i += 1) {
    await sleep(80);
    hot = await cdp.eval("window.__probe.imgFrame()");
  }
  check("点击热区：热态缩略图已解码（loaded）", !!hot && hot.state === "loaded", "state=loaded", JSON.stringify(hot));
  await cdp.eval("window.__probe.reset()");
  for (let i = 0; i < 3; i += 1) {
    const box = await cdp.eval("window.__probe.imgFrame()");
    if (!box) break;
    await cdp.click(box.cx, box.cy);
    await sleep(120);
  }
  const hotOpened = await cdp.eval("window.__probe.events.filter((e) => e[0] === 'open-id').length");
  check("点击一次必开：热态（已解码）真鼠标连点 3 次 → open 3/3",
    hotOpened === 3, "open-id = 3", JSON.stringify({ hotOpened }));

  // ── ⑦ 桌面覆盖层的键盘 / 滚轮 / 双击 / 右键菜单 / 遮罩点击 / 左右切换 ─────
  // 这一组替代了原来的"独立预览窗（无源矩形）居中放大"：窗口那条路已删除，
  // 桌面与移动共用同一覆盖层，桌面缺的只是这些输入设备上的补齐。
  await cdp.eval("window.__probe.zoomMount()");
  await sleep(760);
  const kb0 = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：打开后 index=0、scale=1、只挂一份灯箱",
    !!kb0 && kb0.open && kb0.index === 0 && Math.abs((kb0.scale ?? 0) - 1) <= 0.01,
    "open / index=0 / scale≈1", JSON.stringify(kb0));

  const framesBeforeSwitch = await cdp.eval("window.__probe.zoomTake()");
  await cdp.eval("window.__probe.zoomKey('ArrowRight')");
  await sleep(200);
  const kbR = await cdp.eval("window.__probe.zoomInfo()");
  const switchFrames = vis(await cdp.eval("window.__probe.zoomTake()"))
    .slice(framesBeforeSwitch.frames.length);
  const switchMinW = switchFrames.reduce((m, f) => Math.min(m, f.w), Infinity);
  check("桌面覆盖层：→ 切下一张、← 切回（翻图不重播开场 FLIP）",
    !!kbR && kbR.index === 1 && switchFrames.length >= 2 && switchMinW > 500
      && Math.abs((kbR.scale ?? 0) - 1) <= 0.01,
    "index 0→1 且新帧没有缩回缩略图尺寸", JSON.stringify({
      index: kbR && kbR.index, n: switchFrames.length, minW: switchMinW, scale: kbR && kbR.scale,
    }));
  await cdp.eval("window.__probe.zoomKey('ArrowLeft')");
  await sleep(180);
  const kbL = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：← 切回上一张", !!kbL && kbL.index === 0, "index 1→0", JSON.stringify(kbL));

  await cdp.eval("window.__probe.zoomKey('+')");
  await cdp.eval("window.__probe.zoomKey('+')");
  await sleep(220);
  const kbPlus = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：+ 键放大（scale > 1.3）", !!kbPlus && kbPlus.scale > 1.3,
    "scale > 1.3", JSON.stringify(kbPlus));
  await cdp.eval("window.__probe.zoomKey('-')");
  await sleep(200);
  const kbMinus = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：- 键缩小（scale 回落）",
    !!kbMinus && kbMinus.scale < kbPlus.scale && kbMinus.scale > 1.1,
    "1.1 < scale < 放大后的值", JSON.stringify({ plus: kbPlus && kbPlus.scale, minus: kbMinus && kbMinus.scale }));
  await cdp.eval("window.__probe.zoomKey('0')");
  // 归位是弹性（spring 420/40），220ms 时还在回弹中（读数 1.038）⇒ 等它落定再读。
  await sleep(600);
  const kbZero = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：0 键复位（scale 回到 1）",
    !!kbZero && Math.abs((kbZero.scale ?? 0) - 1) <= 0.01,
    "scale ≈1", JSON.stringify({ scale: kbZero && kbZero.scale }));

  await cdp.eval("window.__probe.zoomWheel(-120)");
  await sleep(220);
  const kbWheelIn = await cdp.eval("window.__probe.zoomInfo()");
  await cdp.eval("window.__probe.zoomWheel(120)");
  await sleep(220);
  const kbWheelOut = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：滚轮缩放（上滚放大 / 下滚缩小）",
    !!kbWheelIn && !!kbWheelOut && kbWheelIn.scale > 1.02 && kbWheelOut.scale < kbWheelIn.scale,
    "上滚 scale↑ / 下滚 scale↓", JSON.stringify({ in: kbWheelIn, out: kbWheelOut }));

  await cdp.eval("window.__probe.zoomKey('+')");
  await cdp.eval("window.__probe.zoomKey('+')");
  await sleep(160);
  const kbBeforeDbl = await cdp.eval("window.__probe.zoomInfo()");
  await cdp.eval("window.__probe.zoomDblclick()");
  await sleep(600);
  const kbDbl = await cdp.eval("window.__probe.zoomInfo()");
  // ⚠️ 判据换向（2026-11-09）：双击原来是"缩放复位"，现已由用户裁决改成**只做全屏切换**
  // （唯一含义，见 ImageLightbox 的 toggleFullscreen 注释与提交 7eb8c2c3）。全屏那条判据
  // 在 `--only=previewwin`（false→true→false）；这里守的是"别加回第二套双击语义"：
  // 放大状态下双击**不许**把 scale 复位。
  check("桌面覆盖层：双击不再复位缩放（唯一含义是全屏；缩放走 +/−/适应/滚轮）",
    !!kbDbl && !!kbBeforeDbl && Math.abs((kbDbl.scale ?? 0) - (kbBeforeDbl.scale ?? 0)) <= 0.01,
    "scale 保持放大值", JSON.stringify({ before: kbBeforeDbl && kbBeforeDbl.scale, after: kbDbl && kbDbl.scale }));

  await cdp.eval("window.__probe.zoomMenu()");
  await sleep(120);
  const kbMenu = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：右键图片出菜单（保存图片 / 关闭）",
    !!kbMenu && kbMenu.menu && kbMenu.menuItems.length === 2 && kbMenu.open,
    "role=menu + 2 个菜单项，灯箱仍在", JSON.stringify({ menu: kbMenu && kbMenu.menuItems, open: kbMenu && kbMenu.open }));
  await cdp.eval("window.__probe.zoomKey('Escape')");
  await waitClosed();
  await sleep(120);
  const kbEsc = await cdp.eval("window.__probe.zoomTake()");
  const kbEscInfo = await cdp.eval("window.__probe.zoomInfo()");
  check("桌面覆盖层：Esc 关闭（菜单同时收起、只发一次 close）",
    !!kbEsc && kbEsc.closes === 1 && kbEsc.open === false && !kbEscInfo.menu,
    "closes=1 / open=false / menu=false", JSON.stringify({ closes: kbEsc && kbEsc.closes, open: kbEsc && kbEsc.open, menu: kbEscInfo && kbEscInfo.menu }));

  await cdp.eval("window.__probe.zoomMount()");
  await sleep(760);
  // 2026-11-08：预览按画板加了顶栏后，原来固定的 (30,30) 落进顶栏 —— 顶栏属于 chrome，
  // 点它不该关窗。判据本身没变（点遮罩要关窗），把落点改成"顶栏下方、图片左侧"的真空遮罩区。
  const shadePoint = await cdp.eval(`(() => {
    const bar = document.querySelector('[data-lightbox-topbar]');
    const r = bar ? bar.getBoundingClientRect() : null;
    return { x: 20, y: Math.round((r ? r.bottom : 0) + 40) };
  })()`);
  await cdp.click(shadePoint.x, shadePoint.y);
  await waitClosed();
  await sleep(120);
  const maskClosed = await cdp.eval("window.__probe.zoomTake()");
  check("桌面覆盖层：点击遮罩关闭（closes=1）",
    !!maskClosed && maskClosed.closes === 1 && maskClosed.open === false,
    "closes=1 / open=false", JSON.stringify({ closes: maskClosed && maskClosed.closes, open: maskClosed && maskClosed.open }));

  // ⑦ 结束时留一份桌面覆盖层读数（用户要 ≥6 帧，上面两组分别打印了打开/关闭的首 6 帧）。

  // ── ⑧ 「回到最新」按钮抢热区：贴底时点图片中心必须命中图片 ──────────────
  const backMounted = await cdp.eval("window.__probe.backMount()");
  await sleep(320);
  await cdp.eval("window.__probe.backSet(0)");
  await sleep(260);
  const back0 = await cdp.eval("window.__probe.backRead()");
  check("回到最新：贴底（gap=0）时按钮不可见且 pointer-events: none",
    !!backMounted && !!back0 && back0.visible === false && !!back0.btn
      && back0.btn.pointerEvents === "none" && back0.btn.opacity === "0"
      && back0.btn.ariaHidden === "true",
    "visible=false / pe=none / opacity=0 / aria-hidden", JSON.stringify(back0));
  check("回到最新：贴底时图片中心命中图片本身（不再被按钮抢热区）",
    !!back0 && back0.hit === "img-frame",
    "elementFromPoint(cx, cy) = img-frame", JSON.stringify({ hit: back0 && back0.hit }));
  await cdp.eval("window.__probe.reset()");
  await cdp.click(back0.cx, back0.cy);
  await sleep(150);
  const back0Events = await cdp.eval("window.__probe.events.slice()");
  check("回到最新：贴底时真鼠标点图片中心 → 图片收到点击、按钮 0 次",
    back0Events.filter((e) => e[0] === "img-click").length === 1
      && back0Events.filter((e) => e[0] === "back").length === 0,
    "img-click=1 / back=0", JSON.stringify(back0Events));

  await cdp.eval("window.__probe.backSet(200)");
  await sleep(260);
  const back200 = await cdp.eval("window.__probe.backRead()");
  check("回到最新：真正离底（gap=200）时按钮出现且可点（证明场景确实重叠，不是空测）",
    !!back200 && back200.visible === true && back200.hit === "back-to-latest"
      && !!back200.btn && back200.btn.pointerEvents === "auto",
    "visible=true / 命中按钮 / pe=auto", JSON.stringify(back200));
  check("回到最新：热区只覆盖按钮本体（按钮上方 4px 仍是图片，::after 不存在）",
    !!back200 && back200.hitAbove === "img-frame" && back200.btn.after === "none",
    "cy-22 → img-frame / ::after=none", JSON.stringify({
      hitAbove: back200 && back200.hitAbove, after: back200 && back200.btn.after,
    }));
  await cdp.eval("window.__probe.reset()");
  await cdp.click(back200.cx, back200.cy);
  await sleep(150);
  const back200Events = await cdp.eval("window.__probe.events.slice()");
  check("回到最新：离底时点它 → 按钮收到 press（可见即真的接上了）",
    back200Events.filter((e) => e[0] === "back").length === 1,
    "back=1", JSON.stringify(back200Events));
  await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
}

/**
 * 「回到最新」位置恒定段（--only=backjump，2026-11-08）。
 *
 * 用户报：上下滚动时这颗圆钮一直在上下跳动。旧实现每帧按滚动位置实测
 * `[data-time-divider]` / `[data-unread-divider]` 与按钮矩形是否相交，相交就按
 * 「行高 + 8px」逐级上移（最多 3 步 ≈ 108px）—— 分割行滚过按钮的那一刻就跳一格，
 * 滚回去又跳回来。本段用一个真滚动容器把分割行"滚过"按钮，按 20px 步长连续滚 40 步，
 * 每步等两帧再采样 `getBoundingClientRect().top`，要求**整条序列只有一个值**。
 *
 * 判据即反例：把动态位移改回来（任何跟随滚动位置的 `avoidOffset`）⇒ 唯一值 > 1 ⇒ 红。
 */
async function runBackJump(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 900, height: 700, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const mounted = await cdp.eval(`(async () => {
    if (!window.__probe.vue) {
      await window.__probe.install('/src/components/UnreadBadge.vue', '', JSON.stringify({ count: 1 }));
    }
    const V = window.__probe.vue;
    if (!V) return { ok: false, why: 'no-vue' };
    const mod = await import('/src/components/chat/BackToLatestButton.vue');
    window.__probe.reset();
    document.body.innerHTML = '';
    const host = document.createElement('div');
    host.id = 'bj-host';
    host.style.cssText = 'position:fixed;left:0;top:0;width:480px;height:520px;background:#111;';
    document.body.appendChild(host);
    const sc = document.createElement('div');
    sc.id = 'bj-scroll';
    sc.style.cssText = 'position:absolute;inset:0;overflow-y:auto;';
    let rows = '<div style="height:240px"></div>';
    for (let i = 1; i <= 8; i += 1) {
      rows += '<div data-time-divider style="height:28px;margin:0 12px">10月' + i + '日 16:21</div>'
        + '<div style="height:300px"></div>';
    }
    sc.innerHTML = rows + '<div style="height:240px"></div>';
    const st = V.reactive({ visible: true });
    const app = V.createApp({
      setup() {
        return () => V.h(mod.default, { visible: st.visible, bottomOffset: 96 });
      },
    });
    if (window.__pinia) app.use(window.__pinia);
    app.mount(host);
    host.insertBefore(sc, host.firstChild);
    window.__probe.bjScroll = (top) => { sc.scrollTop = top; return sc.scrollTop; };
    window.__probe.bjTop = () => {
      const b = document.querySelector('[data-back-to-latest]');
      if (!b) return null;
      const r = b.getBoundingClientRect();
      return { top: Math.round(r.top * 100) / 100, cssBottom: getComputedStyle(b).bottom };
    };
    return { ok: true, max: sc.scrollHeight - sc.clientHeight };
  })()`);
  if (!mounted || !mounted.ok) {
    check("回到最新:夹具挂载（工具层）", false, "mount ok", JSON.stringify(mounted));
    return;
  }
  await sleep(200);
  const series = [];
  for (let i = 0; i <= 40; i += 1) {
    await cdp.eval(`window.__probe.bjScroll(${i * 20})`);
    await cdp.eval("new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)))");
    series.push(await cdp.eval("window.__probe.bjTop()"));
  }
  const tops = series.map((s) => (s ? s.top : null));
  const uniq = [...new Set(tops)];
  const span = Math.max(...tops) - Math.min(...tops);
  console.log("· backjump top 序列（0→800px，每 20px 一采样）:", JSON.stringify(tops));
  console.log("· backjump 唯一值:", JSON.stringify(uniq), "跨度:", span, "px");
  check("回到最新：连续滚动 0→800px 时 top 恒定（不许按滚动位置位移）",
    uniq.length === 1 && span === 0,
    "唯一值 1 个、跨度 0px",
    `唯一值 ${uniq.length} 个 ${JSON.stringify(uniq)}、跨度 ${Math.round(span * 100) / 100}px`);
  await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
}

/**
 * Toast HUD 那一段（--only=toast）。
 *
 * 迁移前是 store 里一个数组 + 每条一个 setTimeout：无上限、无去重、屏幕可能被叠满。
 * 现在数组/停留计时/堆叠/限流/live region 都归 Reka Toast，这里读真 DOM 与真按键：
 * 去重后只剩一条且重复次数显示成「×2」、超过 limit=2 的置 data-limited + inert 且不可见、
 * Esc 按库默认收起 toast 栈且不吞按键、duration 到点自动移除（用 80ms 的短计时，不等 3/6 秒）。
 */
async function runToast(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const mounted = await cdp.eval("window.__probe.install('/src/components/ToastHud.vue', '', '')");
  await sleep(300);
  await cdp.eval(`(async () => {
    const m = await import('/src/utils/toastManager.ts');
    window.__pushToast = m.pushToast;
    window.__toastManager = m.toastManager;
    return true;
  })()`);

  const read = () => cdp.eval(`(() => {
    const nodes = [...document.querySelectorAll('li[data-status]')];
    const visible = nodes.filter((n) => n.getClientRects().length > 0);
    return {
      total: nodes.length,
      visible: visible.length,
      texts: visible.map((n) => String(n.textContent || '').trim()),
      statuses: visible.map((n) => n.getAttribute('data-status')),
      counts: visible.map((n) => {
        const badge = n.querySelector('[data-toast-count]');
        return badge ? String(badge.textContent || '').trim() : '';
      }),
      limited: nodes.filter((n) => n.hasAttribute('data-limited')).length,
      inertLimited: nodes.filter((n) => n.hasAttribute('data-limited')).every((n) => n.hasAttribute('inert')),
      alerts: document.querySelectorAll('[role="alert"]').length,
      viewport: !!document.querySelector('[role="region"][aria-label] ol'),
    };
  })()`);

  let s = await read();
  check("ToastHud 挂出 Reka 的 viewport（ol + aria-label），初始没有 toast",
    mounted && mounted.ok === true && s.viewport === true && s.total === 0,
    "viewport 存在 / total=0", JSON.stringify({ mounted, s }));

  await cdp.eval("window.__pushToast('重复失败', 'error'); window.__pushToast('重复失败', 'error')");
  await sleep(200);
  s = await read();
  check("同一 kind+文案连推两次只留一条，并在条上累加「×2」（A1 合并计数）",
    s.visible === 1 && s.texts[0] === "重复失败×2" && s.statuses[0] === "error" && s.counts[0] === "×2",
    "visible=1 / 重复失败×2 / error", JSON.stringify(s));
  check("失败提示有 live region（role=alert 的 announce 节点）",
    s.alerts >= 1, "role=alert >= 1", "alerts=" + s.alerts);

  // 一条一条推（每条之间留一帧）：Reka 的 stack 序号按**挂载顺序**分配，
  // 一次性批量插入会让 v-for 的挂载顺序与"最新在前"相反，limit 会藏错那一条。
  for (const text of ["信息一", "信息二", "信息三", "信息四"]) {
    await cdp.eval(`window.__pushToast(${JSON.stringify(text)}, 'info')`);
    await sleep(80);
  }
  await sleep(250);
  s = await read();
  check("同屏最多 2 条：超出 limit=2 的旧条目被置 data-limited 且 inert，并且真的不可见",
    s.visible === 2 && s.limited >= 1 && s.inertLimited === true && s.texts.includes("信息四"),
    "visible=2 / limited>=1 / inert / 最新一条在",
    JSON.stringify(s));

  // Esc 走 Reka 默认：关掉 toast 栈。这里真正要钉的回归是**不许 preventDefault** ——
  // Reka 的 ToastRoot 在 window 上监听 Escape，一旦在回调里 preventDefault，同一次按键就会被
  // 判定为"已被处理"，Dialog / Menu / Select 的 Esc 全部失效（--only=select 会因此变红）。
  await cdp.eval(`(() => {
    const b = document.createElement('button');
    b.id = 'toast-outside';
    b.textContent = '外面';
    document.body.appendChild(b);
    b.focus();
    window.__escPrevented = null;
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') window.__escPrevented = e.defaultPrevented;
    });
    return true;
  })()`);
  const beforeEsc = s.visible;
  await cdp.key("Escape", "Escape", "", 27);
  await sleep(500);
  s = await read();
  const escPrevented = await cdp.eval("window.__escPrevented");
  check("Esc 按库默认收起 toast 栈，且不吞按键（defaultPrevented=false）",
    beforeEsc === 2 && s.visible === 0 && escPrevented === false,
    "Esc 前 2 条 / 后 0 条 / 未被 preventDefault",
    JSON.stringify({ beforeEsc, s, escPrevented }));

  await cdp.eval("window.__toastManager.add({ id: 'short-lived', title: '短命', status: 'info', duration: 80, type: 'background', data: { kind: 'info' } })");
  // 80ms 是产品计时，不是等待时间：机器忙时一次固定 sleep 可能还没跑到定时器回调。
  // 有界轮询到 2s —— 仍然证明「到点自动移除」，但不会把机器负载读成产品缺陷。
  for (let i = 0; i < 20; i += 1) {
    await sleep(100);
    s = await read();
    if (!s.texts.includes("短命")) break;
  }
  check("duration 到点自动移除（80ms 的短计时，不靠肉眼等 3/6 秒）",
    s.texts.includes("短命") === false,
    "短命已移除", JSON.stringify(s));
}

/**
 * 设置页下拉（--only=select）。
 *
 * 5 处原生 <select> 已全部换成 Reka Select 的薄适配层；本段读真 DOM / 真鼠标 / 真按键：
 * 触发器文案、listbox/option 语义、当前项勾选、↓+Enter 选中后回写受控值、Esc 收起并归还焦点、
 * 鼠标点条目。另钉一条"组件 DOM 里不得再出现原生 select"——原生弹层在暗夜里由系统绘制，
 * 配色不归我们管（这正是这次迁移的起因）。
 */
async function runSelect(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const mounted = await cdp.eval("window.__probe.selectMount()");
  await sleep(250);
  if (!mounted || mounted.ok !== true) {
    check("设置下拉装得上", false, "mount ok", JSON.stringify(mounted));
    return;
  }

  const read = () => cdp.eval(`(() => {
    const trigger = document.querySelector('#probe-host [role="combobox"]');
    const list = document.querySelector('[role="listbox"]');
    const opts = list ? [...list.querySelectorAll('[role="option"]')] : [];
    const active = document.activeElement;
    const activeOpt = active && active.closest ? active.closest('[role="option"]') : null;
    return {
      triggerText: trigger ? String(trigger.textContent || '').trim() : null,
      expanded: trigger ? trigger.getAttribute('aria-expanded') : null,
      ariaLabel: trigger ? trigger.getAttribute('aria-label') : null,
      activeIsTrigger: document.activeElement === trigger,
      activeOption: activeOpt ? String(activeOpt.textContent || '').trim().replace(/^✓\\s*/, '') : null,
      list: !!list,
      contentClass: list ? String(list.className || '') : '',
      optionCount: opts.length,
      labels: opts.map((o) => String(o.textContent || '').trim().replace(/^✓\\s*/, '')),
      checked: opts.filter((o) => o.getAttribute('data-state') === 'checked')
        .map((o) => String(o.textContent || '').trim().replace(/^✓\\s*/, '')),
      indicators: opts.filter((o) => o.querySelector('[data-state="checked"]')).length,
      nativeSelects: document.querySelectorAll('select').length,
      value: window.__st.selectValue,
      updates: window.__probe.events.filter((e) => e[0] === 'update').map((e) => e[1]),
    };
  })()`);

  let s = await read();
  check("受控下拉初始：combobox 有 aria-label、显示当前项、DOM 里没有原生 select",
    s.ariaLabel === "测试选择" && s.triggerText === "Beta" && s.expanded === "false" && s.nativeSelects === 0,
    "aria-label=测试选择 / 文案=Beta / 无原生 select",
    JSON.stringify(s));

  // 用键盘打开（a11y 用户实际走的路径）：Reka 的 trigger 在 ↓ 上打开并聚焦当前项。
  // 不用合成鼠标做键盘用例的前提：重载下 mouseup 的 click 会晚到并抢走焦点（真机不会），
  // 那会把"库的键盘导航坏了"和"探针时序"混成同一个红。
  await cdp.eval("(() => { const t = document.querySelector('#probe-host [role=\"combobox\"]'); t && t.focus(); return true; })()");
  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  await sleep(700);
  s = await read();
  check("键盘打开：listbox 3 项、当前项有勾选指示、焦点在 Beta、面板吃 .gosslan-menu",
    s.list && s.optionCount === 3 && s.labels.join(",") === "Alpha,Beta,Gamma"
      && s.checked.length === 1 && s.checked[0] === "Beta" && s.indicators === 1
      && s.contentClass.includes("gosslan-menu") && s.activeOption === "Beta",
    "3 项 / 选中 Beta / 1 个 ✓ / .gosslan-menu / 焦点 Beta",
    JSON.stringify(s));

  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  await sleep(180);
  const afterDown = await read();
  await cdp.key("Enter", "Enter", "\r", 13);
  // 等退场动画彻底卸载：DismissableLayer 在关闭动画期间仍占着层级，
  // 过快重开会让旧的最高层吃掉 Esc（探针时距，不是产品行为）。
  await sleep(800);
  s = await read();
  check("键盘 ↓ 走到下一项、Enter 选中：受控值改成 c、触发器文案跟着变、面板收起、焦点回触发器",
    afterDown.activeOption === "Gamma"
      && s.value === "c" && s.triggerText === "Gamma" && s.list === false
      && s.expanded === "false" && s.activeIsTrigger,
    "↓ 后焦点 Gamma / value=c / Gamma / 收起 / 焦点回触发器",
    JSON.stringify({ s, afterDown }));
  check("选择只抬一个新值（v-model 仍是单一来源）",
    s.updates.join(",") === "c", "updates=[c]", JSON.stringify({ updates: s.updates }));

  await cdp.eval("(() => { const t = document.querySelector('#probe-host [role=\"combobox\"]'); t && t.focus(); return true; })()");
  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  await sleep(700);
  const reopened = await read();
  await cdp.eval(`(() => {
    window.__esc = [];
    window.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') window.__esc.push([e.target.tagName, e.defaultPrevented]);
    });
    return { layers: document.querySelectorAll('[data-dismissable-layer]').length };
  })()`);
  await cdp.key("Escape", "Escape", "", 27);
  await sleep(600);
  s = await read();
  check("Esc 收起面板并把焦点还给触发器",
    reopened.list === true && s.list === false && s.activeIsTrigger,
    "打开后 Esc ⇒ 面板消失 + 焦点回触发器",
    JSON.stringify({ reopened: reopened.list, after: s }));

  const pt = await cdp.eval(`(() => {
    const r = document.querySelector('#probe-host [role="combobox"]').getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  })()`);
  await cdp.click(pt.x, pt.y);
  await sleep(700);
  const mouseOpened = await read();
  const optPt = await cdp.eval(`(() => {
    const o = [...document.querySelectorAll('[role="option"]')]
      .find((n) => String(n.textContent || '').trim().includes('Alpha'));
    if (!o) return null;
    const r = o.getBoundingClientRect();
    return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
  })()`);
  if (optPt) {
    await cdp.click(optPt.x, optPt.y);
    await sleep(300);
  }
  s = await read();
  check("鼠标真点开、真命中条目也能选中（不是合成 click）",
    mouseOpened.list === true && !!optPt && s.value === "a" && s.triggerText === "Alpha" && s.list === false,
    "鼠标打开 / value=a / Alpha / 收起",
    JSON.stringify({ mouseOpened: mouseOpened.list, optPt, s }));
}

async function runNavIcon(cdp, url) {
  // 2026-10-22：导航图标已统一到 lucide（navIconPaths.ts 删除）。这里证明**渲染出来的 DOM**
  // 真的是 lucide 图标、选中态只由 stroke-width / data-active 驱动、四枚语义各自映射正确。
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const mount = async (props) => {
    await cdp.eval(
      `window.__probe.install('/src/components/ui/NavIcon.vue', '', ${JSON.stringify(JSON.stringify({ isolated: true, ...props }))})`,
    );
    await sleep(200);
  };
  const read = () => cdp.eval(`(() => {
    const svg = document.querySelector('#probe-host svg');
    if (!svg) return { present: false };
    const path = svg.querySelector('path');
    return {
      present: true,
      cls: svg.getAttribute('class') || '',
      stroke: svg.getAttribute('stroke'),
      strokeWidth: svg.getAttribute('stroke-width'),
      dataActive: svg.getAttribute('data-active'),
      ariaHidden: svg.getAttribute('aria-hidden'),
      viewBox: svg.getAttribute('viewBox'),
      dHead: path ? (path.getAttribute('d') || '').slice(0, 24) : '',
      sizeClass: svg.getAttribute('class') || '',
    };
  })()`);

  await mount({ name: "contacts", active: true });
  const contactsOn = await read();
  await mount({ name: "contacts", active: false });
  const contactsOff = await read();
  check("导航图标由 lucide 渲染（通讯录 = users-round）",
    contactsOn.present === true && /lucide-users-round-icon/.test(contactsOn.cls)
      && contactsOn.viewBox === "0 0 24 24" && contactsOn.ariaHidden === "true",
    "svg.lucide-users-round-icon / viewBox=0 0 24 24 / aria-hidden=true",
    JSON.stringify(contactsOn));
  check("选中态只加粗描边并落 data-active（不从描边库硬填成实心）",
    contactsOn.strokeWidth === "2.35" && contactsOn.dataActive === "true"
      && contactsOff.strokeWidth === "1.9" && contactsOff.dataActive === "false",
    "active: 2.35/true；inactive: 1.9/false",
    JSON.stringify({ on: contactsOn.strokeWidth + "/" + contactsOn.dataActive,
      off: contactsOff.strokeWidth + "/" + contactsOff.dataActive }));

  await mount({ name: "chats", active: true });
  const chats = await read();
  check("聊天语义映射到独立的 lucide 图标（不是抄通讯录的 path）",
    chats.present === true && /lucide-message-circle-icon/.test(chats.cls)
      && chats.dHead !== contactsOn.dHead,
    "lucide-message-circle-icon / path 与通讯录不同",
    JSON.stringify(chats));

  await mount({ name: "favorites", active: true, sizeClass: "h-[22px] w-[22px]" });
  const pc = await read();
  await mount({ name: "favorites", active: true, sizeClass: "h-16 w-16 opacity-25" });
  const mob = await read();
  check("同一语义在 PC 栏与移动端是同一只图标，只换尺寸档",
    pc.present === true && mob.present === true && /lucide-star-icon/.test(pc.cls)
      && pc.dHead === mob.dHead && pc.cls !== mob.cls,
    "lucide-star-icon / path 相同 / class 不同",
    JSON.stringify({ pcClass: pc.cls, mobClass: mob.cls }));

  await mount({ name: "links", active: true });
  const links = await read();
  check("链接语义映射到 lucide compass",
    links.present === true && /lucide-compass-icon/.test(links.cls),
    "lucide-compass-icon", JSON.stringify(links));

  // 唯一造型表还在、且恰好四枚：运行时不直接拿 path（lucide 是唯一来源），只对账键与导出形态。
  const table = await cdp.eval(`(async () => {
    const M = await import('/src/components/ui/navIcons.ts');
    return { keys: Object.keys(M.NAV_ICONS), kinds: Object.values(M.NAV_ICONS).map((v) => typeof v) };
  })()`);
  check("导航造型表仍是唯一入口且恰好四枚",
    table.keys.length === 4 && table.keys.every((k) => ["chats", "contacts", "favorites", "links"].includes(k))
      && table.kinds.every((k) => k === "object" || k === "function"),
    "navIcons.NAV_ICONS 恰有 4 键，值为组件",
    JSON.stringify(table));
}

/**
 * 输入承载面可读性探针（--only=fieldcontrast，2026-11-06 ⑧）。
 *
 * 为什么必须**在特效全开下**量：静态 tokenContrast 只能证明"token 与 token"的比值，
 * 而用户报的是「玻璃 + 浮动背景全开时看不到输入框」—— 那时输入面背后是 `.glass-3`
 * （亮 0.94 / 暗 0.92）叠在漂移色团上，输入面自身填充与面板的差值会被压得更低。
 * 本段真挂 GroupMemberPanel（与用户的截图同一个面板），把 `data-ambient` 设成 `drift`、
 * 不设 `data-frost="off"`，量三件事：
 *   ① 边框 vs **最差**面板合成底 ≥3.0（WCAG 1.4.11 非文本档）；
 *   ② 占位符 vs 输入面 ≥4.5（AA）且 computed 颜色就是 `--gosslan-placeholder`；
 *   ③ 输入承载面合成 alpha ≥0.95（AM-15 的同一把尺子，只是换到"特效开"的路径上）。
 * 末尾做一次反向对照：把边框改透明 + 占位符注回 UA 灰，同一条读数必须翻假。
 */
async function runFieldContrast(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 900, height: 860, deviceScaleFactor: 1, mobile: false,
  });
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(2_000);
  await cdp.eval(PAGE_FIXTURE);
  // installMenu 要求页面那份 vue/pinia 已在 __probe 上 —— 先借一次普通 install 带进来。
  await cdp.eval("window.__probe.install('/src/components/TitleBar.vue', '', '')");
  // 复用页面里的 vue/pinia 实例（installMenu 的第二参数点名业务组件；BaseModal 会 Teleport）。
  const mounted = await cdp.eval(`window.__probe.installMenu(${JSON.stringify(JSON.stringify({ open: true, groupId: "g1" }))}, ${JSON.stringify(JSON.stringify({
    path: "/src/components/GroupMemberPanel.vue",
    emits: ["close", "open-tasks", "mention", "open-profile"],
  }))})`);
  await sleep(400);
  const seeded = await cdp.eval(`(async () => {
    const { useChatStore } = await import('/src/stores/useChatStore.ts');
    const { useAppStore } = await import('/src/stores/useAppStore.ts');
    const chat = useChatStore(window.__pinia);
    const app = useAppStore(window.__pinia);
    // isOwner = group.creator === app.device.device_id ⇒ 两边都种成 dev-me，编辑区才会渲染。
    app.device = { device_id: 'dev-me', name: 'dev-me', avatar: null };
    chat.groups = [{ id: 'g1', name: '探针群', creator: 'dev-me', members: ['dev-me', 'bob'], avatar: null, announcement: '' }];
    window.__probe.vue && await window.__probe.vue.nextTick();
    return { ok: true, myId: app.device.device_id };
  })()`);

  await cdp.eval(`(() => {
    document.documentElement.dataset.ambient = 'drift';
    document.documentElement.removeAttribute('data-frost');
    return true;
  })()`);

  const measure = () => cdp.eval(`(() => {
    const nums = (c) => (c.match(/\\d+(?:.\\d+)?/g) || []).map(Number);
    const over = (base, top) => {
      const a = top.length >= 4 ? top[3] : 1;
      return [0, 1, 2].map((i) => Math.round(top[i] * a + base[i] * (1 - a)));
    };
    const lin = (v) => { const x = v / 255; return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4); };
    const lum = (c) => 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]);
    const ratio = (a, b) => {
      const x = lum(a), y = lum(b);
      return Number(((Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05)).toFixed(2));
    };
    const wide = [...document.querySelectorAll('input')].filter((i) => i.getBoundingClientRect().width > 100);
    const el = wide.find((i) => i.getAttribute('placeholder')) || wide[0];
    if (!el) return { ok: false, why: 'no-input', inputs: document.querySelectorAll('input').length };
    const s = getComputedStyle(el);
    const ph = getComputedStyle(el, '::placeholder');
    const card = el.closest('.glass-3') || el.closest('[role="dialog"]') || document.body;
    const cs = getComputedStyle(card);
    const field = nums(s.backgroundColor);
    const border = nums(s.borderTopColor);
    const glass = nums(cs.backgroundColor);
    const tokenPh = getComputedStyle(document.documentElement).getPropertyValue('--gosslan-placeholder').trim();
    const hex2rgb = (h) => {
      const t = h.replace('#', '');
      return t.length === 3
        ? [t[0] + t[0], t[1] + t[1], t[2] + t[2]].map((x) => parseInt(x, 16))
        : [t.slice(0, 2), t.slice(2, 4), t.slice(4, 6)].map((x) => parseInt(x, 16));
    };
    // 最差面板底：玻璃叠在「白 / 黑 / 三个漂移色相」上，取边框与它们的最小比值。
    const BACKDROPS = [[255, 255, 255], [0, 0, 0], [124, 92, 255], [0, 179, 164], [255, 122, 198]];
    const glassAlpha = glass.length >= 4 ? glass[3] : 1;
    const comps = BACKDROPS.map((b) => over(b, [glass[0], glass[1], glass[2], glassAlpha]));
    const borderVsWorst = Math.min(...comps.map((c) => ratio(border, c)));
    return {
      ok: true,
      bg: s.backgroundColor,
      borderW: s.borderTopWidth,
      borderColor: s.borderTopColor,
      glassBg: cs.backgroundColor,
      placeholderColor: ph.color,
      placeholderOpacity: ph.opacity,
      tokenPlaceholder: tokenPh,
      tokenMatches: nums(ph.color).length >= 3
        && hex2rgb(tokenPh).every((v, i) => Math.abs(v - nums(ph.color)[i]) <= 1),
      fieldAlpha: Number((field.length >= 4 ? field[3] : 1).toFixed(3)),
      borderVsWorst: Number(borderVsWorst.toFixed(2)),
      phVsField: ratio(nums(ph.color), field),
    };
  })()`);

  const boot = await cdp.eval(`(() => {
    const inputs = document.querySelectorAll('input').length;
    const named = [...document.querySelectorAll('input')]
      .filter((i) => i.getBoundingClientRect().width > 100).length;
    return { inputs, named, text: (document.body.innerText || '').slice(0, 80) };
  })()`);
  check("fieldcontrast 对照：群管理面板真挂上、有可量的输入框（否则下面几条是空跑）",
    mounted && mounted.ok === true && boot.named >= 1, "mounted.ok=true 且 ≥1 个宽输入框", JSON.stringify({ mounted, boot }));

  const report = {};
  for (const dark of [false, true]) {
    await cdp.eval(`document.documentElement.classList.toggle('dark', ${dark}); true`);
    await sleep(300);
    const r = await measure();
    report[dark ? 'dark' : 'light'] = r;
    check(`fieldcontrast：${dark ? "暗色" : "亮色"} + 玻璃/浮动背景全开时，输入面边框 vs 最差面板底 ≥3.0`,
      r.ok === true && r.borderW !== "0px" && r.borderVsWorst >= 3.0,
      "border 非 0px / 比值 ≥3.0", JSON.stringify(r));
    check(`fieldcontrast：${dark ? "暗色" : "亮色"}占位符 vs 输入面 ≥4.5，且颜色就是 token`,
      r.ok === true && r.phVsField >= 4.5 && r.tokenMatches === true && Number(r.placeholderOpacity) === 1,
      "比值 ≥4.5 / computed=--gosslan-placeholder / opacity=1", JSON.stringify(r));
    check(`fieldcontrast：${dark ? "暗色" : "亮色"}输入承载面合成 alpha ≥0.95（AM-15 同尺）`,
      r.ok === true && r.fieldAlpha >= 0.95, "alpha ≥0.95", JSON.stringify({ fieldAlpha: r.fieldAlpha, bg: r.bg }));
  }

  // 高对比档（2026-11-07 审计第 8 条）：暗色 + prefers-contrast:more 的字段边框必须
  // 比常规暗色更亮。没有这格，`--gosslan-field-border` 在高对比块里"漏抬"就量不出来。
  const lumaOf = (c) => {
    const n = (c.match(/\d+(?:\.\d+)?/g) || []).map(Number);
    const lin = (v) => { const x = v / 255; return x <= 0.03928 ? x / 12.92 : Math.pow((x + 0.055) / 1.055, 2.4); };
    return 0.2126 * lin(n[0]) + 0.7152 * lin(n[1]) + 0.0722 * lin(n[2]);
  };
  await cdp.send("Emulation.setEmulatedMedia", {
    media: "",
    features: [{ name: "prefers-contrast", value: "more" }],
  });
  await cdp.eval(`document.documentElement.classList.add('dark'); true`);
  await sleep(300);
  const hc = await measure();
  report.darkHighContrast = hc;
  check("fieldcontrast：暗色 + prefers-contrast:more 的字段边框比常规暗色更亮，且仍 ≥3.0",
    hc.ok === true && lumaOf(hc.borderColor) > lumaOf(report.dark.borderColor) + 0.05 && hc.borderVsWorst >= 3.0,
    "亮度差 >0.05 / 比值 ≥3.0",
    JSON.stringify({ hcBorder: hc.borderColor, baseBorder: report.dark.borderColor, hcRatio: hc.borderVsWorst }));
  // 反例自证：把字段边框注回常规暗色值 ⇒ 上面的"更亮"必须翻假，证明这一格没空转。
  await cdp.eval(`(() => {
    document.documentElement.style.setProperty('--gosslan-field-border', '#788dae');
    return true;
  })()`);
  await sleep(200);
  const hcBad = await measure();
  check("fieldcontrast 反例：高对比档把字段边框注回 #788dae ⇒ \"更亮\"判据必须翻假（判据不空转）",
    hcBad.ok === true && !(lumaOf(hcBad.borderColor) > lumaOf(report.dark.borderColor) + 0.05),
    "亮度差消失", JSON.stringify({ borderColor: hcBad.borderColor }));
  await cdp.eval(`(() => {
    document.documentElement.style.removeProperty('--gosslan-field-border');
    document.documentElement.classList.remove('dark');
    return true;
  })()`);
  await cdp.send("Emulation.setEmulatedMedia", { media: "", features: [] });

  // 反向对照：同一条读数必须能翻假（否则上面三条是空转）。
  await cdp.eval(`(() => {
    const wide = [...document.querySelectorAll('input')].filter((i) => i.getBoundingClientRect().width > 100);
    const el = wide.find((i) => i.getAttribute('placeholder')) || wide[0];
    if (!el) return false;
    el.dataset.beforeBorder = el.style.borderColor;
    el.style.borderColor = 'transparent';
    const s = document.createElement('style');
    s.id = '__fieldcontrast_before';
    s.textContent = 'input::placeholder, textarea::placeholder { color: rgb(156,163,175) !important; opacity: 1 !important; }';
    document.head.appendChild(s);
    return true;
  })()`);
  await sleep(200);
  const bad = await measure();
  // 暗色 UA 灰恰好还能过 4.5（6.05），但它**不是 token** —— 真实判据里 tokenMatches 那一半会红。
  // 所以反例的失败条件是「边框 <3.0 或 占位符比值/身份不达标」，不是两条数值同时掉。
  check("fieldcontrast 反例：边框透明 + 占位符注回 UA 灰 ⇒ 边框与占位符判据至少各红一条（判据不空转）",
    bad.ok === true && bad.borderVsWorst < 3.0 && (bad.phVsField < 4.5 || bad.tokenMatches !== true),
    "border <3.0 且 (placeholder <4.5 或 颜色≠token)", JSON.stringify(bad));
  await cdp.eval(`(() => {
    const wide = [...document.querySelectorAll('input')].filter((i) => i.getBoundingClientRect().width > 100);
    const el = wide.find((i) => i.getAttribute('placeholder')) || wide[0];
    if (el) el.style.borderColor = '';
    document.getElementById('__fieldcontrast_before')?.remove();
    document.documentElement.dataset.ambient = 'off';
    return true;
  })()`);
  console.log("  ℹ fieldcontrast 读数 → " + JSON.stringify(report));
  void seeded;
}

/**
 * 前端泄漏形状探针（--only=leak，2026-11-04）。
 *
 * 为什么是"形状判据"而不是内存数字：绝对堆/CPU 会随机器与版本漂移（见 perf/README 的量具边界），
 * 但**泄漏有确定性的形状**——切 N 次会话、再全部卸载之后，监听器与定时器必须回到挂载前的水位，
 * 堆在两批切换之间不许随批次单调抬升。这里量三件事：
 *   ① 切会话 30 次（6 个会话轮转）后 DOM 元素数不随批次增长；
 *   ② 第 2→3 批的 GC 后堆增量不随批次持续抬升（阈值见实测基线，留 GC 噪声）；
 *   ③ `app.unmount()` 之后 `JSEventListeners` / 活着的 interval 与 rAF 回到挂载前水位
 *      （夹具自己挂的那 1 个 document click 监听要扣掉）。
 *
 * 反例自证：`GOSSLAN_LEAK_INJECT=1` 时在挂载后故意留一个 1s interval，
 * ③ 的定时器水位必然多 1 → 这一段必须红。删掉真正的清理代码时形状与它同源。
 */
async function runLeak(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1200, height: 800, deviceScaleFactor: 1, mobile: false,
  });
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(3_000);
  /**
   * 打桩 + 夹具 + 定时器水位记账。
   *
   * ⚠️ 为什么要做成可重跑的一组：`window.__leak` / `window.__probe` 都挂在页面上，
   * 而**别的会话改 `src/` 会触发 vite 全量热重载**，一重载这些全丢 —— 长跑（`GOSSLAN_IDLE_MS`）
   * 中途被清空过一次（2026-11-05，真踩到：堆读数还没取到就 `__leak` 已 undefined）。
   * 所以长跑不假设页面会一直在原地，而是每段先探活，丢了就重建夹具、那一段从头再量。
   */
  const installHarness = async () => {
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(() => {
      window.__TAURI_INTERNALS__ = {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      if (!window.__TAURI_EVENT_PLUGIN_INTERNALS__) {
        window.__TAURI_EVENT_PLUGIN_INTERNALS__ = { unregisterListener: () => {} };
      }
    })()`);
    await cdp.send("Performance.enable");
    await cdp.send("HeapProfiler.enable");

    // 定时器水位记账：必须在挂载前包（挂载后才包就抓不到组件自己起的那些）。
    // setTimeout 的包装把一次性回调执行时自动出账 —— 没人会替它 clearTimeout。
    await cdp.eval(`(() => {
      const live = { interval: new Set(), timeout: new Set(), raf: new Set(), where: new Map(), product: new Set() };
      window.__leak = { live };
      const oi = window.setInterval.bind(window), ci = window.clearInterval.bind(window);
      const ot = window.setTimeout.bind(window), ct = window.clearTimeout.bind(window);
      const oraf = window.requestAnimationFrame.bind(window), craf = window.cancelAnimationFrame.bind(window);
      window.setInterval = (...a) => { const id = oi(...a); live.interval.add(id); return id; };
      window.clearInterval = (id) => { live.interval.delete(id); ci(id); };
      window.setTimeout = (fn, ms, ...rest) => {
        if (typeof fn !== 'function') return ot(fn, ms, ...rest);
        let id = 0;
        id = ot((...aa) => {
          live.timeout.delete(id);
          live.where.delete(id);
          live.product.delete(id);
          fn(...aa);
        }, ms, ...rest);
        live.timeout.add(id);
        // 诊断用：记谁起的（只看前 4 行，够定位文件）；这里不用模板串，避免 Node 侧先插值。
        const stack = new Error().stack || "";
        live.where.set(id, ms + "ms @ " + stack.split(String.fromCharCode(10)).slice(2, 5).join(" | "));
        // 只把产品代码起的定时器记进 product：依赖目录里的 300s GC 定时器（vue-query）不算产品泄漏。
        if (stack.indexOf("/src/") !== -1 && stack.indexOf("/node_modules/") === -1) live.product.add(id);
        return id;
      };
      window.clearTimeout = (id) => { live.timeout.delete(id); live.where.delete(id); live.product.delete(id); ct(id); };
      window.requestAnimationFrame = (fn) => {
        let id = 0;
        id = oraf((t) => { live.raf.delete(id); fn(t); });
        live.raf.add(id);
        return id;
      };
      window.cancelAnimationFrame = (id) => { live.raf.delete(id); craf(id); };
    })()`);
  };
  await installHarness();

  async function sample(label) {
    await cdp.send("HeapProfiler.collectGarbage");
    await sleep(250);
    const { metrics } = await cdp.send("Performance.getMetrics");
    const m = (k) => metrics.find((x) => x.name === k)?.value ?? null;
    const page = await cdp.eval(`({
      dom: document.querySelectorAll('*').length,
      interval: window.__leak.live.interval.size,
      timeout: window.__leak.live.timeout.size,
      productTimeout: window.__leak.live.product.size,
      raf: window.__leak.live.raf.size,
      pending: [...window.__leak.live.where.values()].filter((s) => s.indexOf('/src/') !== -1).slice(0, 4),
    })`);
    // 全局监听器单独记账：window/document 上的多是 store 单例（常驻），组件自己的多在元素上。
    const win = await cdp.send("Runtime.evaluate", { expression: "window" });
    const doc = await cdp.send("Runtime.evaluate", { expression: "document" });
    const wl = await cdp.send("DOMDebugger.getEventListeners", { objectId: win.result.objectId });
    const dl = await cdp.send("DOMDebugger.getEventListeners", { objectId: doc.result.objectId });
    const heap = await cdp.send("Runtime.getHeapUsage");
    return {
      label,
      heapMB: +(heap.usedSize / 1048576).toFixed(2),
      heapTotalMB: +(heap.totalSize / 1048576).toFixed(2),
      nodes: m("Nodes"),
      listeners: m("JSEventListeners"),
      taskS: m("TaskDuration"),
      dom: page.dom,
      interval: page.interval,
      timeout: page.timeout,
      productTimeout: page.productTimeout,
      raf: page.raf,
      windowListeners: wl.listeners.length,
      documentListeners: dl.listeners.length,
      elementListeners: (m("JSEventListeners") ?? 0) - wl.listeners.length - dl.listeners.length,
      pending: page.pending,
    };
  }

  const base = await sample("基线（未挂载）");

  /** 挂真 ChatWindow + 灌种子。页面被热重载清空后重建夹具时也要重跑这一段。 */
  async function mountAndSeed() {
    const mounted = await cdp.eval(
      "window.__probe.install('/src/components/ChatWindow.vue', '', '{\"hostHeight\":\"800px\"}')",
    );
    await cdp.eval("window.__probe.seedDevice('dev-leak')");
    const seed = await cdp.eval(`(async () => {
      const { useChatStore } = await import('/src/stores/useChatStore.ts');
      const chat = useChatStore();
      const makeRows = (conv, seedN, n) => {
        const out = [];
        for (let i = 0; i < n; i += 1) {
          const seq = seedN + i + 1;
          out.push({ id: seedN + i, msg_id: 'm-' + conv + '-' + seq, local_id: 'm-' + conv + '-' + seq,
            conv_id: conv, sender_id: i % 2 ? 'dev-peer' : 'dev-leak', sender_name: i % 2 ? '对方' : '我',
            receiver_id: i % 2 ? 'dev-leak' : 'dev-peer', kind: 'text',
            content: ('第 ' + seq + ' 条，切换用。').repeat(3),
            status: 'sent', seq, ts: 1700000000000 + seq * 1000 });
        }
        return out;
      };
      window.__leak.convs = Array.from({ length: 6 }, (_, i) => 'group:lk' + i);
      for (const [i, conv] of window.__leak.convs.entries()) chat.messages[conv] = makeRows(conv, i * 100, 40);
      chat.activeConv = window.__leak.convs[0];
      if (${JSON.stringify(process.env.GOSSLAN_LEAK_INJECT === "1")}) {
        window.__leak.injected = setInterval(() => {}, 1000);
      }
      await new Promise((r) => setTimeout(r, 600));
      return { ok: true, convs: window.__leak.convs.length, rows: 240 };
    })()`);
    return { mounted, seed };
  }

  const first = await mountAndSeed();
  check("ChatWindow 挂得起来（泄漏段的入口）",
    !!first.mounted && first.mounted.ok === true, "install ok", JSON.stringify(first.mounted));
  check("泄漏段种子数据就位（6 个会话 × 40 条）",
    !!first.seed && first.seed.ok === true && first.seed.convs === 6 && first.seed.rows === 240,
    "6 × 40", JSON.stringify(first.seed));

  const afterMount = await sample("挂载后");

  const batches = [];
  for (let b = 1; b <= 3; b += 1) {
    for (let i = 0; i < 10; i += 1) {
      // 每批都从 idx 1 走到 idx 5（各两轮），**收尾固定落在 idx 5**。
      // 这不是为了让判据好看，而是为了让三批的"终点状态"可比：早先用 (b*10+i)%6 时三批分别停在
      // 不同会话上，DOM 509 vs 528、监听器 313 vs 322 —— 差的 9 个是"这个会话渲染了更多行"，
      // 不是泄漏（2026-11-05 真红过一次）。终点不一致时，"监听器不增长"量到的是更换会话的内容差。
      const idx = 1 + (i % 5);
      await cdp.eval(`(async () => {
        const { useChatStore } = await import('/src/stores/useChatStore.ts');
        useChatStore().activeConv = window.__leak.convs[${idx}];
      })()`);
      await sleep(120);
    }
    await sleep(400);
    batches.push(await sample(`第 ${b} 批（累计 ${b * 10} 次切换）`));
  }

  // 可选的待机长跑（手动用，不进默认门禁）：GOSSLAN_IDLE_MS=900000 ⇒ 两段 15 分钟空闲，
  // 取 GC 后堆、DOM、监听器与 TaskDuration 增量（≈ 渲染主线程占用率）。
  //
  // ⚠️ 每段都先探活再计时：共享工作区里别的会话改 `src/` 会让 vite 全量热重载，页面一重载
  // `window.__leak` 就没了（2026-11-05 真踩到：13 分钟读数作废）。丢了就重建夹具、
  // **这一段从头再量** —— 只记"连续未被打断"的那一段，不把两次挂载混成一条趋势。
  const idleMs = Number(process.env.GOSSLAN_IDLE_MS || 0);
  const idleSamples = [];
  if (idleMs > 0) {
    const alive = () => cdp.eval(
      "!!(window.__leak && window.__leak.live && window.__probe && window.__probe.app)",
    );
    async function rebuild() {
      await cdp.send("Page.navigate", { url });
      await cdp.settled();
      await sleep(3_000);
      await installHarness();
      const m = await mountAndSeed();
      console.log("  · 夹具已重建（挂载=" + !!(m.mounted && m.mounted.ok)
        + " 种子=" + !!(m.seed && m.seed.ok) + "）");
    }
    for (let i = 1; i <= 2; i += 1) {
      const mins = Math.round(idleMs / 60000);
      for (let attempt = 1; ; attempt += 1) {
        if (!(await alive())) await rebuild();
        const t0 = await sample(`空闲第 ${i} 段起点`);
        const started = Date.now();
        let lost = false;
        while (Date.now() - started < idleMs) {
          await sleep(10_000);
          if (!(await alive())) { lost = true; break; }
        }
        if (lost) {
          console.log("  · 空闲第 " + i + " 段第 " + attempt + " 次被热重载打断 ⇒ 重建夹具，本段从头再量");
          await rebuild();
          continue;
        }
        const s = await sample(`空闲第 ${i} 段（${mins} 分钟）`);
        // 分母用真实墙钟（探活与 GC 都不计进 CPU% 的分子，但计进耗时）。
        const secs = Math.round((Date.now() - started) / 1000);
        s.wallSecs = secs;
        s.heapDeltaMB = +(s.heapMB - t0.heapMB).toFixed(2);
        s.cpuPct = +(((s.taskS - t0.taskS) / secs) * 100).toFixed(2);
        idleSamples.push(s);
        break;
      }
    }
  }

  const unmounted = await cdp.eval("(() => { window.__probe.app.unmount(); return true; })()");
  await sleep(600);
  const afterUnmount = await sample("卸载后");
  // 夹具把 app 挂在 window.__probe 上（生产里根 App 常驻、从不卸载）⇒ 手动松手，
  // 否则量到的是"探针自己攥着 vnode 树"的保留，不是产品泄漏。
  await cdp.eval(`(() => {
    window.__probe.app = null;
    window.__probe.state = null;
    window.__st = null;
    window.__qc = null;
    window.__pinia = null;
    return true;
  })()`);
  await sleep(1_200);
  const afterCleanup = await sample("松手后");
  await sleep(5_000);
  const afterSettle = await sample("松手 5s 后");

  const table = [base, afterMount, ...batches, ...idleSamples, afterUnmount, afterCleanup, afterSettle];
  console.log("  · 泄漏形状读数（每行都是 GC 后现读）：");
  for (const r of table) {
    console.log(`     ${r.label.padEnd(24)} heap=${String(r.heapMB).padStart(7)}MB total=${String(r.heapTotalMB).padStart(7)}MB`
      + ` nodes=${String(r.nodes).padStart(6)} listeners=${String(r.listeners).padStart(5)}`
      + ` (win=${r.windowListeners} doc=${r.documentListeners} el=${r.elementListeners})`
      + ` dom=${String(r.dom).padStart(5)} interval=${r.interval} timeout=${r.timeout}`
      + ` productTimeout=${r.productTimeout} raf=${r.raf}`
      + (r.cpuPct === undefined ? "" : ` cpu=${r.cpuPct}% Δheap=${r.heapDeltaMB}MB`));
  }
  // 这一段不单独落账本：报告直接取上面的现读表。

  const b2 = batches[1], b3 = batches[2];
  check("切会话 30 次后 DOM 元素数不随批次增长（第 3 批 ≤ 第 2 批 + 60）",
    b3.dom <= b2.dom + 60, "batch3.dom ≤ batch2.dom + 60",
    JSON.stringify({ batch2: b2.dom, batch3: b3.dom }));
  // 阈值依据（2026-11-04 本机 Brave/156）：6 会话 × 40 条夹具下，batch2→batch3 的 GC 后堆差
  // 实测 0.69～1.05MB（三次运行）；取 2.5MB ≈ 实测上界的 2.4 倍，既压得住 GC 噪声，
  // 又能在"每次切换真留一坨"时迅速红（240 条消息 × 30 次 ≈ 远大于 2.5MB）。
  check("切会话 30 次后第 3 批相对第 2 批没有持续抬升（堆增量 ≤ 2.5MB，GC 后现读）",
    b3.heapMB - b2.heapMB <= 2.5, "heap(batch3) - heap(batch2) ≤ 2.5MB",
    JSON.stringify({ batch2: b2.heapMB, batch3: b3.heapMB, delta: +(b3.heapMB - b2.heapMB).toFixed(2) }));
  check("30 次切换期间监听器没有净增（batch3 ≤ batch2 + 8）",
    b3.listeners <= b2.listeners + 8, "listeners(batch3) ≤ listeners(batch2) + 8",
    JSON.stringify({ batch2: b2.listeners, batch3: b3.listeners }));
  // 元素级监听器（el=…）只进读数表、不进判据：Vue 卸载不清 `_vei`，元素上的监听器随节点一起
  // 回收；本夹具在页面里长期持有 vue/pinia 模块，会保留一部分已脱离 DOM 的 vnode 树，
  // 于是 el 计数天然回不到基线。这里能用的是"切 30 次不增长"（batch2→batch3 持平）那条。
  check("ChatWindow 卸载并松开夹具引用后全局监听器不净增（窗口级 ≤ 挂载后 + 2）",
    afterCleanup.windowListeners + afterCleanup.documentListeners
      <= afterMount.windowListeners + afterMount.documentListeners + 2,
    "window+document listeners(afterCleanup) ≤ 挂载后 + 2",
    JSON.stringify({ afterMount: afterMount.windowListeners + afterMount.documentListeners, afterCleanup: afterCleanup.windowListeners + afterCleanup.documentListeners }));
  // 定时器：interval / rAF 必须是严格归零（共享 nowTick 也是引用计数，卸载后必须停）。
  check("ChatWindow 卸载后没有活着的 interval（回到基线水位）",
    afterCleanup.interval === base.interval,
    "interval(afterCleanup) === interval(base)",
    JSON.stringify({ base: base.interval, afterMount: afterMount.interval, afterCleanup: afterCleanup.interval }));
  check("ChatWindow 卸载后没有活着的 rAF（回到基线水位）",
    afterSettle.raf <= base.raf,
    "raf(afterSettle) ≤ raf(base)",
    JSON.stringify({ base: base.raf, afterCleanup: afterCleanup.raf, afterSettle: afterSettle.raf }));
  check("ChatWindow 卸载后没有产品代码起的一次性 timeout 残留（5s 后 === 基线）",
    afterSettle.productTimeout === base.productTimeout,
    "productTimeout(afterSettle) === productTimeout(base)",
    JSON.stringify({ base: base.productTimeout, afterCleanup: afterCleanup.productTimeout, afterSettle: afterSettle.productTimeout, pending: afterSettle.pending }));

  if (idleSamples.length === 2) {
    const [i1, i2] = idleSamples;
    check("两段空闲之间 DOM 元素数持平（±0）",
      i2.dom === i1.dom, "idle2.dom === idle1.dom", JSON.stringify({ idle1: i1.dom, idle2: i2.dom }));
    check("两段空闲之间监听器不增长（≤ +2）",
      i2.listeners <= i1.listeners + 2, "idle2.listeners ≤ idle1.listeners + 2",
      JSON.stringify({ idle1: i1.listeners, idle2: i2.listeners }));
    check("两段空闲之间 GC 后堆增量 ≤ 0.5MB（待机预算基线，15 分钟一段）",
      i2.heapMB - i1.heapMB <= 0.5, "heap(idle2) - heap(idle1) ≤ 0.5MB",
      JSON.stringify({ idle1: i1.heapMB, idle2: i2.heapMB, delta: i2.heapDeltaMB }));
    check("待机时渲染主线程占用 < 1%（TaskDuration 增量 / 墙钟）",
      i2.cpuPct < 1, "idle cpu% < 1", JSON.stringify({ idle1: i1.cpuPct, idle2: i2.cpuPct }));
  }

  if (unmounted !== true) {
    throw new Error("unmount 没有返回 true");
  }
}

async function runSegmented(cdp, url) {
  // 焦点模拟与 reaction 段同口径：RovingFocus 用 .focus() 移动，方向键要真的送到被聚焦项。
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    const mount = async (extra = {}) => {
      const props = {
        modelValue: "a",
        options: [{ value: "a", label: "甲" }, { value: "b", label: "乙" }, { value: "c", label: "丙" }],
        size: "sm",
        ariaLabel: "测试分段",
        ...extra,
      };
      await cdp.eval(
        `window.__probe.install('/src/components/ui/SegmentedControl.vue', '', ${JSON.stringify(JSON.stringify(props))})`,
      );
      await sleep(200);
    };
    const info = () => cdp.eval("window.__probe.segmentedInfo()");
    const events = () => cdp.eval("window.__probe.events");

    await mount();
    const s0 = await info();
    check("分段控件由 Reka 渲染成 radiogroup + 3 个 radio",
      s0.present === true && s0.items.length === 3 && s0.label === "测试分段",
      "radiogroup / 3 个 radio / aria-label", JSON.stringify(s0));
    check("RovingFocus 的 Tab 停靠点在整组上，组内 radio 初始都是 -1",
      s0.present === true && s0.groupTab === 0 && s0.items.every((x) => x.tab === -1),
      "groupTab=0 / 组内全 -1",
      JSON.stringify({ groupTab: s0.groupTab, tabs: s0.items.map((x) => x.tab) }));

    await cdp.eval("window.__probe.reset(); window.__probe.groupFocus()");
    await sleep(80);
    const sFocus = await info();
    check("Tab 进组后焦点落到当前选中项（不是停在组容器上）",
      sFocus.active.includes("甲"), "activeText 含甲", sFocus.active);
    // 真按键：keydown 与 keyup 之间留出一帧。RadioGroupItem 在 focus 的
    // setTimeout(0) 里按“方向键还按着”决定是否 click；同帧发 keyup 会把这次点击吃掉。
    await cdp.send("Input.dispatchKeyEvent", {
      type: "keyDown", key: "ArrowRight", code: "ArrowRight",
      windowsVirtualKeyCode: 39, nativeVirtualKeyCode: 39,
    });
    await sleep(80);
    await cdp.send("Input.dispatchKeyEvent", {
      type: "keyUp", key: "ArrowRight", code: "ArrowRight",
      windowsVirtualKeyCode: 39, nativeVirtualKeyCode: 39,
    });
    await sleep(250);
    const ev1 = await events();
    const s1 = await info();
    check("→ 从选中项移到下一项并选中（emit update=b）",
      ev1.some((e) => e[0] === "update" && e[1] === "b"),
      "update=b", JSON.stringify(ev1));
    check("焦点真的落在第二项，且第二项成为新的 Tab 停靠点",
      s1.active.includes("乙") && s1.items[1].tab === 0,
      "activeText 含乙 / item1.tab=0",
      JSON.stringify({ active: s1.active, tabs: s1.items.map((x) => x.tab) }));

    await mount();
    await cdp.eval("window.__probe.reset()");
    const pt = await cdp.eval("window.__probe.radioPoint(2)");
    check("对照：拿得到第三颗分段的落点", !!pt && pt.x > 0 && pt.y > 0, "坐标 >0", JSON.stringify(pt));
    if (pt) {
      await cdp.click(pt.x, pt.y);
      await sleep(200);
      const ev2 = await events();
      check("点击第三项：emit update=c", ev2.some((e) => e[0] === "update" && e[1] === "c"),
        "update=c", JSON.stringify(ev2));
    }

    await mount({ disabled: true });
    await cdp.eval("window.__probe.reset()");
    const dpt = await cdp.eval("window.__probe.radioPoint(1)");
    if (dpt) await cdp.click(dpt.x, dpt.y);
    await sleep(200);
    const ev3 = await events();
    check("禁用态：点任何一项都不发 update", ev3.length === 0, "0 个事件", JSON.stringify(ev3));
  } finally {
    await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: false }).catch(() => {});
  }
}

async function runSlider(cdp, url) {
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: true });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    // setChatStyle 会落库并广播；探针只验交互，替掉这两条后端命令。
    await cdp.eval("window.__probe.stubApi('saveSettings', null)");
    await cdp.eval("window.__probe.stubApi('broadcastChatStyle', null)");
    const installed = await cdp.eval(
      "window.__probe.install('/src/components/settings/ChatStyleSection.vue', '')",
    );
    check("对照：字号设置段挂得起来（挂不上下面就是空跑）",
      !!installed && installed.ok === true, "install ok", JSON.stringify(installed));
    if (!installed || installed.ok !== true) return;
    await sleep(300);
    const info = () => cdp.eval("window.__probe.sliderInfo()");
    const s0 = await info();
    check("字号滑块由 Reka 渲染成 role=slider，带 aria-valuemin/max/now 与 valuetext",
      s0.present === true && s0.min === "0" && s0.max === "4" && s0.now === "2"
        && String(s0.text).includes("px"),
      "slider / 0..4 / now=2 / valuetext 含 px", JSON.stringify(s0));
    check("初始 store 字号就是 md（now=2 与业务值一致）",
      s0.present === true && s0.font === "md", "font=md", s0.font);

    await cdp.eval("window.__probe.sliderFocus()");
    await cdp.key("ArrowRight", "ArrowRight", "", 39);
    await sleep(150);
    const s1 = await info();
    check("→ 一档：aria-valuenow=3 且 store 字号跟着变",
      s1.now === "3" && s1.font !== "md", "now=3 / font 改变",
      JSON.stringify({ now: s1.now, font: s1.font }));

    await cdp.key("Home", "Home", "", 36);
    await sleep(150);
    const s2 = await info();
    check("Home 跳到最小档（0）", s2.now === "0", "now=0", s2.now);

    await cdp.key("End", "End", "", 35);
    await sleep(150);
    const s3 = await info();
    check("End 跳到最大档（4）", s3.now === "4", "now=4", s3.now);

    const pt = await cdp.eval(`(function () {
      const s = window.__probe.sliderInfo();
      if (!s.present || !s.root) return null;
      return { x: s.root.x + Math.round(s.root.w * 0.25), y: s.root.y + Math.round(s.root.h / 2) };
    })()`);
    check("对照：拿得到滑块轨道 25% 处的落点", !!pt && pt.x > 0 && pt.y > 0, "坐标 >0", JSON.stringify(pt));
    if (pt) {
      await cdp.click(pt.x, pt.y);
      await sleep(200);
      const s4 = await info();
      check("点击轨道 25%：就近吸附到第 1 档（0..4）", s4.now === "1", "now=1",
        JSON.stringify({ now: s4.now, font: s4.font }));
    }
  } finally {
    await cdp.send("Emulation.setFocusEmulationEnabled", { enabled: false }).catch(() => {});
  }
}

async function runTodoPick(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const props = {
    label: "类型",
    current: "需求",
    currentClass: "",
    modelValue: "requirement",
    options: [
      { value: "requirement", label: "需求" },
      { value: "bug", label: "缺陷" },
      { value: "custom", label: "自定义…" },
    ],
  };
  await cdp.eval(
    `window.__probe.install('/src/components/TodoPickField.vue', '', ${JSON.stringify(JSON.stringify(props))})`,
  );
  await sleep(200);
  const menu = () => cdp.eval("window.__probe.menu()");
  const events = () => cdp.eval("window.__probe.events");

  const pt = await cdp.eval("window.__probe.firstMenuTrigger()");
  check("对照：拿得到三选一字段的菜单入口（拿不到下面就是空跑）",
    !!pt && pt.x > 0 && pt.y > 0, "坐标 >0", JSON.stringify(pt));
  if (!pt) return;
  await cdp.click(pt.x, pt.y);
  await sleep(200);
  const m0 = await menu();
  check("点开三选一字段：3 条选项全部由 Reka 收进菜单集合",
    m0.present === true && m0.items.length === 3, "3 条 menuitem", JSON.stringify(m0.items));
  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  const m1 = await menu();
  check("↓ 跳过禁用的当前项，高亮「缺陷」（键盘导航不是停在禁用项上）",
    m1.activeText.includes("缺陷"), "activeText=缺陷", m1.activeText);
  await cdp.eval("window.__probe.reset()");
  await cdp.key("Enter", "Enter", "\r", 13);
  await sleep(200);
  const ev = await events();
  const gone = await menu();
  // 「关掉之后」的读数必须站在收尾完成的那一刻上（INV-P31 第 4 条）：菜单的卸载走 leave 收尾，
  // 机器忙时 200ms 走不完 ⇒ 不泵就读到"还在"。这条红在隔离跑里不复现、在全量跑里复现，
  // 差的正是这份负载 —— 所以判据吃泵后那份，两份都打印，别把量具的形状升级成产品判据。
  const pumpFails = await pumpFrames(cdp, 10);
  const afterPump = await menu();
  console.log(
    `  · 读数（不判绿红）：回车后菜单 present 只等不泵=${gone.present}｜泵帧后=${afterPump.present}（截图失败 ${pumpFails} 次）`,
  );
  check("回车选中：emit update:modelValue=bug 且菜单收起",
    ev.some((e) => e[0] === "update" && e[1] === "bug") && afterPump.present === false,
    "update=bug + 菜单消失", JSON.stringify(ev));
}

async function runTaskCard(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  const TODO_ID = "todo-probe-1";
  const CID = "a".repeat(64);
  const payload = {
    todo_id: TODO_ID,
    title: "探针任务：把周报发出去",
    assignees: ["dev-other"],
    status: "todo",
    creator: "dev-me",
    deleted: false,
    description: "@小布 记得带上周报",
    images: [{ id: CID, name: "白板照片.jpg", size: 2048, sha256: CID, subtype: "image" }],
    archived: false,
    done_at: null,
  };
  const MSG = JSON.stringify({
    msg_id: "m-probe-1", sender_id: "dev-me", kind: "todo",
    content: JSON.stringify(payload), ts: 1700000000000,
  });
  // #116 用的第二份：描述长到必然超过那个框的三行 ⇒ 能证明"这层确实在裁"
  const MSG_LONG = JSON.stringify({
    msg_id: "m-probe-clip", sender_id: "dev-me", kind: "todo",
    content: JSON.stringify({ ...payload, description: "@小布 " + "补齐到四行之多的填充文字。".repeat(24) }),
    ts: 1700000000000,
  });
  // 自己视角的标签从 i18n 取，不在这里抄「@你」字面量（本仓刚给这条加了禁令）
  const labels = await cdp.eval(`(async () => {
    const u = await import('/src/utils/todos.ts');
    const i = await import('/src/i18n');
    return { todo: i.t(u.TODO_STATUS_LABEL_KEY.todo), done: i.t(u.TODO_STATUS_LABEL_KEY.done),
      selfTag: i.t('mention.self') };
  })()`);

  const mount = async (props) => {
    await cdp.eval(`window.__probe.install('/src/components/TodoCardBubble.vue', '', ${JSON.stringify(JSON.stringify(props))})`);
    await sleep(1_200); // 缩略图那一族是"字节后到"的：先 mount 再等一次取字节的 promise
  };
  const text = () => cdp.eval("window.__probe.text()");

  // —— 先按"对端视角"挂一次（没有 self 标签、没有实时状态表）——
  await cdp.eval(`window.__probe.stubApi('readContentPreview', [137,80,78,71,13,10,26,10])`);
  await mount({
    message: JSON.parse(MSG),
    mentionNames: ["小布", "我"],
    selfMention: null,
  });
  const t0 = await text();
  check("卡片渲染出这条任务的标题（用户报的是「看不见」，那就先判标题真在 DOM 里）",
    t0.includes("把周报发出去"), "含标题", t0.slice(0, 80));

  // —— 用户 2026-10-25 的 hover 两半（上半区铺到分隔线 / 有回应时下半区是横条）——
  const hoverGeom = await cdp.eval(`(() => {
    const card = document.querySelector('[data-todo-card]');
    const body = card ? card.querySelector(':scope > [role="button"]') : null;
    const footer = card ? card.querySelector(':scope > button') : null;
    if (!body || !footer) return null;
    const b = body.getBoundingClientRect(), f = footer.getBoundingClientRect();
    const shell = document.createElement('div');
    shell.className = 'msg-shell';
    shell.setAttribute('data-has-reactions', 'true');
    card.parentElement.appendChild(shell);
    shell.appendChild(card);
    return {
      gap: +(f.top - b.bottom).toFixed(1),
      joinedRadius: getComputedStyle(card).borderBottomLeftRadius,
    };
  })()`);
  check("任务卡主体 hover 一直铺到底部操作条的分隔线（两者之间没有白缝）",
    !!hoverGeom && Math.abs(hoverGeom.gap) <= 0.5,
    "主体矩形底边 == 操作条顶边", JSON.stringify(hoverGeom));
  check("任务卡有表情回应时下圆角交给回应底栏（hover 下半区是横条而不是圆角底色）",
    !!hoverGeom && hoverGeom.joinedRadius === "0px",
    "data-has-reactions 下 [data-todo-card] 的 border-bottom-*-radius = 0px",
    JSON.stringify(hoverGeom));
  check("卡片不许把载荷当原始 JSON 画出来（内部字段名一个都不该露出）",
    !t0.includes("todo_id") && !t0.includes("done_at"), "不出现内部字段名", t0.slice(0, 80));
  check("状态胶囊显示载荷快照那一档（没传实时表 ⇒ 退回创建时）",
    t0.includes(labels.todo) && !t0.includes(labels.done), labels.todo, t0.slice(0, 80));
  check("对端视角里 @ 到的名字仍是原文（不是「@你」）",
    t0.includes("@小布") && !t0.includes(labels.selfTag), "@小布", t0.slice(0, 80));

  // —— 同一个数据换"我自己"的视角：同一段文本必须换标签 ——
  await mount({
    message: JSON.parse(MSG),
    mentionNames: ["小布", "我"],
    selfMention: { name: "小布", label: labels.selfTag },
  });
  const t1 = await text();
  const selfEls = await cdp.eval(`document.querySelectorAll('.mention-token--self').length`);
  check("换成我的视角：同一段 @ 渲染成 i18n 里那个自我标签（§9 的运行时那一半）",
    t1.includes(labels.selfTag) && selfEls === 1, "标签出现且 --self 恰好 1 个",
    `${JSON.stringify(t1.slice(0, 60))} / --self=${selfEls}`);

  // —— #116：描述里的 @ 高亮会不会被那层 `max-h + overflow-hidden` 裁一半 ——
  // ⚠️ 只钉「高亮完整可见」会变成恒真（这层根本没裁的时候它也成立）⇒ 必须配一条
  //    「裁切机制确实活着」的对照（③），两者同时成立才算判到了风险本身。
  await mount({
    message: JSON.parse(MSG), mentionNames: ["小布", "我"],
    selfMention: { name: "小布", label: labels.selfTag },
  });
  const clip = await cdp.eval("window.__probe.mentionClip()");
  const lhPx = Number(String(clip.lineHeight).replace(/[^0-9.]/g, "")) || 0;
  check("描述里那枚 @ 高亮完整落在裁切框内（上缘与下缘都不被切）",
    clip.tokTop >= clip.boxTop - 1 && clip.tokBottom <= clip.boxBottom + 1,
    "token 上下缘都在框内", `tok=${clip.tokTop}..${clip.tokBottom} box=${clip.boxTop}..${clip.boxBottom}`);
  check("高亮没把行盒撑破（token 高 ≤ computed line-height × 1.05；行高由样式现读不写死）",
    lhPx > 0 && clip.tokH <= lhPx * 1.05, `≤ ${(lhPx * 1.05).toFixed(2)}（行高 ${clip.lineHeight}）`,
    `${clip.tokH} / fontSize=${clip.fontSize}`);
  const longDesc = await (async () => {
    await mount({
      message: JSON.parse(MSG_LONG), mentionNames: ["小布", "我"],
      selfMention: { name: "小布", label: labels.selfTag },
    });
    return cdp.eval("window.__probe.mentionClip()");
  })();
  check("对照：把描述写到 4 行 ⇒ 那个框确实在裁（scrollHeight > clientHeight）—— 证明上面两条不是恒真",
    longDesc.scrollH > longDesc.clientH, "scrollHeight > clientHeight",
    `${longDesc.scrollH} > ${longDesc.clientH}? 高亮=${longDesc.tokH}px 行高=${longDesc.lineHeight}`);

  // —— 实时状态表那一环（#23：载荷是创建时快照，卡片必须查父层那张表）——
  // 同一张表现在还管着编号：类型字母由**当前**类型现推（用户 2026-09-30 规则 3），
  // 而"超过 4 位只显后四位 + 全码要能查到"（规则 5/6）只有真渲染出来才量得动。
  await mount({
    message: JSON.parse(MSG),
    mentionNames: ["小布"],
    selfMention: null,
    liveTodoPairs: [[TODO_ID, "done", "bug", 12345]],
  });
  const t2 = await text();
  check("传了实时表说这条已完成 ⇒ 胶囊换成已完成（查不到才退回快照，查到就不许再显示旧值）",
    t2.includes(labels.done) && !t2.includes(labels.todo), labels.done, t2.slice(0, 80));
  const codeCell = await cdp.eval("window.__probe.el('.font-mono')");
  const cText = codeCell ? codeCell.text : "";
  const cTitle = codeCell ? String(codeCell.title || "") : "";
  const cAria = codeCell ? String(codeCell.aria || "") : "";
  check("编号那格的字母来自**实时表里的当前类型**（夹具的创建快照既没类型也没号 ⇒ 不查表一个字都出不来）",
    cText === "B2345", "可见文本 B2345", JSON.stringify(codeCell));
  check("五位数字 ⇒ 可见只有后四位，而 title 与 aria 都带完整编号 B12345（短码不许被当成全码）",
    cTitle.includes("B12345") && cAria.includes("B12345") && !cText.includes("12345"),
    "title/aria 含 B12345、可见文本不含", JSON.stringify(codeCell));

  // 反面对照：不传实时表 ⇒ 卡片只剩那份"既没类型也没号"的创建快照，那一格必须整个不出现。
  // 少了这一条，上面两句就成了探针自己造出来的号。
  await mount({ message: JSON.parse(MSG), mentionNames: ["小布"], selfMention: null });
  const codeOff = await cdp.eval("window.__probe.el('.font-mono')");
  check("对照：不传实时表 ⇒ 那格没有任何补出来的号（宁可空白，也不按顺序数一个会随集合漂移的号）",
    codeOff === null, "找不到 .font-mono", JSON.stringify(codeOff));

  // —— 键盘可达 + 按 Enter 真的开了那份统一预览 ——
  await mount({
    message: JSON.parse(MSG),
    mentionNames: ["小布"],
    selfMention: null,
    liveTodoPairs: [[TODO_ID, "done", "bug", 12345]],
  });
  const thumb = await cdp.eval(`window.__probe.el('[role="button"]')`);
  check("卡片里的缩略图是键盘可达的（role=button + tabindex=0 + 有可访问名）",
    !!thumb && thumb.tabindex === "0" && !!thumb.aria, "role=button/tabindex=0/aria-label",
    JSON.stringify(thumb));
  const focused = await cdp.eval("window.__probe.focusThumb()");
  await cdp.eval("window.__probe.reset()");
  await cdp.key("Enter", "Enter", "\r", 13);
  const pv = await cdp.eval("window.__probe.previewState()");
  check("焦点在缩略图上按 Enter：统一预览 store 被打开，且来源标记是这张卡的 task-card:<todoId>",
    focused === true && pv.open === true && pv.source === "task-card:" + TODO_ID
    && pv.n === 1 && pv.index === 0,
    "open=true source=task-card:" + TODO_ID + " n=1 index=0", JSON.stringify(pv));

  // —— #116：@ 色块落在**最后一行可见行**时，会不会被卡片那段固定行高的裁切盒削掉 ——
  // `.mention-token` 有上下各 1px 内衬（`style.css`），而任务卡描述是 `max-h-[4.2em] overflow-hidden`。
  // 判的是矩形，不是肉眼：色块底边越过裁切盒 = 削。
  const clipMsg = JSON.parse(MSG);
  clipMsg.content = JSON.stringify({
    ...JSON.parse(clipMsg.content),
    description: "第一行 @小布\n第二行\n第三行结尾 @小布",
  });
  await mount({
    message: clipMsg,
    mentionNames: ["小布"],
    selfMention: { name: "小布", label: labels.selfTag },
  });
  const geo = await cdp.eval(`(() => {
    const toks = document.querySelectorAll('.mention-token--self');
    const last = toks[toks.length - 1];
    if (!last) return { found: false };
    const box = last.closest('p');
    if (!box) return { found: false, reason: '色块不在 <p> 里' };
    const t = last.getBoundingClientRect(), b = box.getBoundingClientRect();
    return { found: true, count: toks.length,
      bottomOver: +(t.bottom - b.bottom).toFixed(1), topUnder: +(b.top - t.top).toFixed(1),
      boxH: +b.height.toFixed(1), tokH: +t.height.toFixed(1),
      clipped: box.scrollHeight > box.clientHeight + 1 };
  })()`);
  check("#116：描述裁切盒落在整行上（最后一行的 @ 色块不被削半截；色块自带上下各 1px 内衬 ⇒ 容差 1px）",
    geo.found === true && geo.bottomOver <= 1 && geo.topUnder <= 1,
    "bottomOver<=1 且 topUnder<=1", JSON.stringify(geo));

  // —— 点「查看任务」必须带**这条**的 id（带错/带空就是开别人的任务）——
  await cdp.eval("window.__probe.reset()");
  const clicked = await cdp.eval(`(() => {
    const btns = Array.from(document.querySelectorAll('button'));
    const b = btns[btns.length - 1];
    if (!b) return false;
    b.click();
    return true;
  })()`);
  const ev = await cdp.eval("window.__probe.events");
  const opened = ev.filter((e) => e[0] === "open-id").map((e) => e[1]);
  check("卡片底部那个入口 emit 的是**这条**的 todo_id（不是 undefined、也不是别条）",
    clicked === true && opened.length === 1 && opened[0] === TODO_ID,
    "1 次 open 且带 " + TODO_ID, JSON.stringify(ev));

  // —— 三个命中区互不干扰（本轮修复）：主体开面板 / 底部开这条详情 / 图片只开预览 ——
  // 重新挂一份带实时状态的卡（上面那步的事件已清空）
  await mount({
    message: JSON.parse(MSG),
    mentionNames: ["小布"],
    selfMention: null,
    liveTodoPairs: [[TODO_ID, "doing", "task", 7]],
  });

  // 区①：点主体（标题所在的 role=button 区域，注意卡片里还有图片缩略图也是 role=button，
  // 用「包着编号 .font-mono 的那个」精确取主体，不许靠 document.querySelector 取到第一个）
  await cdp.eval("window.__probe.reset()");
  const bodyClick = await cdp.eval(`(() => {
    const mono = document.querySelector('.font-mono');
    const region = mono && mono.closest('[role="button"][tabindex="0"]');
    if (!region) return { ok: false, why: '找不到主体命中区' };
    // 点的是内部标题 span（事件 target 是后代），验证处理器不在按钮上而在整块主体上
    const title = region.querySelector('.truncate');
    (title || region).click();
    return { ok: true };
  })()`);
  let ev2 = await cdp.eval("window.__probe.events");
  let panel = ev2.filter((e) => e[0] === "open-panel").length;
  let detail = ev2.filter((e) => e[0] === "open-id").length;
  check("点卡片主体：只 emit open-panel（打开面板），不直达任何一条详情",
    bodyClick.ok === true && panel === 1 && detail === 0,
    "open-panel×1 / open-id×0", JSON.stringify(ev2));

  // 区①键盘：聚焦主体后 Enter 与 Space 都开面板（且 Space 不滚页）
  await cdp.eval("window.__probe.reset()");
  const kb1 = await cdp.eval(`(() => {
    const mono = document.querySelector('.font-mono');
    const region = mono && mono.closest('[role="button"][tabindex="0"]');
    if (!region) return false;
    region.focus();
    return document.activeElement === region;
  })()`);
  await cdp.key("Enter", "Enter", "\r", 13);
  await cdp.key(" ", "Space", " ", 32);
  const evK = await cdp.eval("window.__probe.events");
  check("键盘焦点在卡片主体：Enter 与 Space 各打开一次面板（鼠标/触摸/键盘三入口不冲突）",
    kb1 === true && evK.filter((e) => e[0] === "open-panel").length === 2
      && evK.filter((e) => e[0] === "open-id").length === 0,
    "open-panel×2", JSON.stringify(evK));

  // 区③：点图片缩略图 —— 只开统一预览，open-panel / open-id 一个都不许有
  await cdp.eval("window.__probe.reset()");
  const imgClick = await cdp.eval(`(() => {
    // 缩略图是 80×80 那块（含 h-20 w-20），主体命中区里没有这个尺寸类
    const t = Array.from(document.querySelectorAll('[role="button"]'))
      .find((el) => el.classList.contains('h-20'));
    if (!t) return { ok: false, why: '找不到缩略图' };
    t.click();
    return { ok: true };
  })()`);
  const pv2 = await cdp.eval("window.__probe.previewState()");
  const ev3 = await cdp.eval("window.__probe.events");
  check("点卡片图片：只打开统一预览（冒泡被图片区截断，不顺路开面板/详情）",
    imgClick.ok === true && pv2.open === true && pv2.source === "task-card:" + TODO_ID
      && ev3.filter((e) => e[0] === "open-panel" || e[0] === "open-id").length === 0,
    "预览开且无开面板事件", JSON.stringify({ pv: pv2, ev: ev3 }));

  // 区③的**另一半**（用户 2026-10-12 原话：「点图片的周围那些区域 点击事件应该是展开任务列表」）。
  // 上面那条只证了"点缩略图不顺路开面板"；"点空白那一圈要开面板"此前**没有任何正向断言** ——
  // 只有源码侧 ㊲ 那条"容器不许挂 @click.stop"的形状禁令。禁令在、正向行为坏了照样绿，
  // 而 2026-10-12 那个缺陷恰好就是这个形状（容器一 stop，整条图片带不再冒泡）。
  // 派发目标取图片带容器本身：事件的 target 是那一层 div，不是任何缩略图 ⇒
  // 这正好是"缩略图之间的空隙 / px-3 内边距 / 右侧留白"的等价形状，冒泡必须一路通到命中区①。
  await cdp.eval("window.__probe.reset()");
  const bandClick = await cdp.eval(`(() => {
    const t = Array.from(document.querySelectorAll('[role="button"].h-20'))[0];
    const band = t ? t.parentElement : null;
    if (!band) return { ok: false, why: '找不到图片带容器' };
    band.click();
    return { ok: true };
  })()`);
  const evBand = await cdp.eval("window.__probe.events");
  check("点图片带里空白那一圈（target=容器本身）：必须展开任务面板，且不多发 open-id",
    bandClick.ok === true && evBand.filter((e) => e[0] === "open-panel").length === 1
      && evBand.filter((e) => e[0] === "open-id").length === 0,
    "open-panel×1 / open-id×0", JSON.stringify({ bandClick, ev: evBand }));

  // 区③键盘（回归保护）：缩略图 Enter 同样只开预览
  await cdp.eval("window.__probe.reset()");
  await cdp.eval("window.__probe.focusThumb()");
  await cdp.key("Enter", "Enter", "\r", 13);
  const pv3 = await cdp.eval("window.__probe.previewState()");
  const ev4 = await cdp.eval("window.__probe.events");
  check("键盘在缩略图上按 Enter：只开预览，不触发主体的 open-panel（两区域键盘处理互不串线）",
    pv3.open === true && ev4.filter((e) => e[0] === "open-panel" || e[0] === "open-id").length === 0,
    "仅预览", JSON.stringify({ pv: pv3, ev: ev4 }));

  // 区①里的链接：描述含真 URL 时，点链接不许顺手弹面板（链接走外部打开；插件在探针里
  // 调不起来会被组件自己 catch，我们只断言"没有面板事件"）。注意本仓的链接是无 href 的
  // <a>（点击统一走 opener，MessageLinkText 全仓同一形状）⇒ 用描述里的 a 来认。
  const linkMsg = JSON.parse(MSG);
  linkMsg.content = JSON.stringify({ ...payload, description: "看这个 https://example.com/spec 就好" });
  await mount({ message: linkMsg, mentionNames: ["小布"], selfMention: null });
  await cdp.eval("window.__probe.reset()");
  const linkClick = await cdp.eval(`(async () => {
    const a = document.querySelector('p a');
    if (!a) return { ok: false, why: '描述里的链接没渲染成 a' };
    a.click();
    await new Promise((r) => setTimeout(r, 50));
    return { ok: true };
  })()`);
  const ev5 = await cdp.eval("window.__probe.events");
  check("描述里的 URL 链接点击不被主体拦截（只走链接，不弹任务面板/详情）",
    linkClick.ok === true
      && ev5.filter((e) => e[0] === "open-panel" || e[0] === "open-id").length === 0,
    "无面板事件", JSON.stringify(linkClick) + " " + JSON.stringify(ev5));

  // —— 图片超过上限 ⇒ 只画前几张 + 出「查看更多」，且它表现得和「查看任务」一模一样 ——
  // 用户 2026-10-12：任务卡片图多到 10 张时堆满卡面；点「查看更多」要像「查看任务」那样
  // 打开列表并直达这条任务。上限的唯一家在 utils/todos.ts，这里**现读**不写死。
  const LIMIT = await cdp.eval(`(async () => {
    const u = await import('/src/utils/todos.ts');
    return u.TODO_CARD_IMAGE_VISIBLE;
  })()`);
  const mkImages = (n, cidBase) =>
    Array.from({ length: n }, (_, i) => ({
      id: cidBase + i, name: `图${i}.jpg`, size: 2048,
      sha256: (cidBase + i).repeat(Math.ceil(64 / (cidBase + i).length)).slice(0, 64),
      subtype: "image",
    }));

  const moreLabel = await cdp.eval(`(async () => {
    const i = await import('/src/i18n');
    return i.t('todo.viewMoreImages');
  })()`);

  // 缩略图的形状锚点：`TodoImageThumb` 根节点 = `role=button` + `h-20 w-20`（80×80）。
  // ⚠️ 这里**不许**改用"某个 role=button 祖先的 children"去数：卡片主体（命中区①）自己也是
  //   `role=button`，那样数出来恒为 1，量的是主体不是缩略图 —— 2026-10-12 那一版探针正是这么
  //   把"只画 4 张"读成"只画 1 张"的（判据红得像是产品缺陷，实际是尺子读错了对象）。
  const MEASURE = `(() => {
    const thumbs = Array.from(document.querySelectorAll('[role="button"].h-20'));
    const band = thumbs.length ? thumbs[0].parentElement : null;
    // 卡片根 = 挂进 #probe-host 的那个元素（TodoCardBubble 的模板根就是一个 div）。
    // ⚠️ 这里原来借 .bubble-tail 的 closest('div') 定位卡片，而尖角现在是父层
    //   （MessageItem 用 :tail="!isGroup" 透传）控制的 prop ⇒ 本段**单独挂组件**时永远没有
    //   尖角，锚点读空、cardH 恒 -1，两条高度判据一起红（看着像产品把卡片撑坏了）。
    //   量具不许寄生在被测形状上，改成量挂载根。
    //   （注释里不能出现反引号：这一整块是 JS 模板字符串，反引号会当场截断它。）
    const host = document.getElementById('probe-host');
    const card = host ? host.firstElementChild : null;
    const label = ${JSON.stringify(moreLabel)};
    const more = Array.from(document.querySelectorAll('button'))
      .find((b) => (b.textContent || '').trim().startsWith(label));
    return {
      rendered: thumbs.length,
      bandH: band ? +band.getBoundingClientRect().height.toFixed(1) : -1,
      moreH: more ? +more.getBoundingClientRect().height.toFixed(1) : 0,
      cardH: card ? +card.getBoundingClientRect().height.toFixed(1) : -1,
      // 正控：量到的这一格必须真的**含着**图片带（锚点滑到兄弟/内层小盒子时 cardH 会小于 bandH，
      // 而"估多了/估少了"两条都可能照样绿 —— 那是在量别的东西）。
      cardHoldsBand: !!(card && band && card.contains(band)
        && card.getBoundingClientRect().height >= band.getBoundingClientRect().height - 0.5),
      // 「查看更多」在不在命中区①**里面**（决定它要不要自己 stop）
      moreInBody: more ? !!more.closest('[role="button"][tabindex="0"]') : false,
    };
  })()`;

  await cdp.eval("window.__probe.reset()");
  await mount({
    message: JSON.parse(JSON.stringify({
      ...JSON.parse(MSG), content: JSON.stringify({ ...payload, images: mkImages(LIMIT + 6, "f") }),
    })),
    mentionNames: ["小布"],
    selfMention: null,
  });
  const manyGeo = await cdp.eval(MEASURE);
  check(`图片 ${LIMIT + 6} 张 ⇒ 卡片只画 ${LIMIT} 张（其余去详情弹窗看）`,
    manyGeo.rendered === LIMIT, `恰好 ${LIMIT} 张`, JSON.stringify(manyGeo));
  check("超限时出现「查看更多」按钮",
    manyGeo.moreH > 0, `那颗高度 > 0`, JSON.stringify(manyGeo));

  await cdp.eval("window.__probe.reset()");
  const moreClicked = await cdp.eval(`(() => {
    const label = ${JSON.stringify(moreLabel)};
    const b = Array.from(document.querySelectorAll('button'))
      .find((x) => (x.textContent || '').trim().startsWith(label));
    if (!b) return false;
    b.click();
    return true;
  })()`);
  const evMore = await cdp.eval("window.__probe.events");
  const moreOpened = evMore.filter((e) => e[0] === "open-id").map((e) => e[1]);
  const morePanel = evMore.filter((e) => e[0] === "open-panel").length;
  // ⚠️ 必须**按文案**认这颗按钮，不许用"没有 svg 的那个 button"之类的形状去猜：
  // 「查看更多」自己带一个 ChevronRight ⇒ 猜"无 svg"永远选不中它，会退到最后一颗
  // （=底部「查看任务」），于是这条判据量的是别的按钮，产品缺陷被读成绿。
  // 且"一模一样"要求**只有** open(todoId)：多一个 open-panel 就是面板被开两次、
  // 第二次不带 id ⇒ 直达这条任务的效果被冲掉。
  check("点「查看更多」= 点「查看任务」：只 emit open 带**这条**的 todo_id，不多冒 open-panel",
    moreClicked === true && moreOpened.length === 1 && moreOpened[0] === TODO_ID && morePanel === 0,
    "1 次 open-id=" + TODO_ID + " 且 open-panel×0", JSON.stringify(evMore) + " " + JSON.stringify(manyGeo));

  // 反面对照：刚好上限张数 ⇒ 一个缩略图都不少，且**没有**「查看更多」（否则 4 张也弹按钮）
  await cdp.eval("window.__probe.reset()");
  await mount({
    message: JSON.parse(JSON.stringify({
      ...JSON.parse(MSG), content: JSON.stringify({ ...payload, images: mkImages(LIMIT, "e") }),
    })),
    mentionNames: ['小布'],
    selfMention: null,
  });
  const exactGeo = await cdp.eval(MEASURE);
  check(`对照：正好 ${LIMIT} 张 ⇒ 全画出来且不出现「查看更多」（判据不是恒真）`,
    exactGeo.rendered === LIMIT && exactGeo.moreH === 0,
    `${LIMIT} 张且无更多按钮`, JSON.stringify(exactGeo));

  // —— 高度契约：每种张数都按"同一份估算 vs 同一个 DOM"对照 ——
  // ⚠️ 三条纪律：① 估算端现读，不在探针里抄数（抄了一份就钉不住真正的同步）；
  // ② 每条记录**必须有各自的 msg_id** —— messageHeight 的缓存键是 `fontSize|msg_id`，
  //   两条记录共用一个号时，第二次读到的是第一次的缓存（2026-10-12 那版就这么读出
  //   "有图 == 无图"，把估算端读成"没长"）；③ 两个方向都要量：估少了 ⇒ 相邻消息互相遮挡，
  //   估多了 ⇒ 卡片之间出现一大片空洞（本文件顶部那条契约说的是前者，后者同样是真的）。
  const COUNTS = [0, 1, 2, 3, LIMIT, LIMIT + 1, LIMIT + 6];
  const rows = [];
  for (const n of COUNTS) {
    await mount({
      message: JSON.parse(JSON.stringify({
        ...JSON.parse(MSG), content: JSON.stringify({ ...payload, images: mkImages(n, `h${n}`) }),
      })),
      mentionNames: ["小布"],
      selfMention: null,
    });
    const g = await cdp.eval(MEASURE);
    const est = await cdp.eval(`(async () => {
      const h = await import('/src/utils/messageHeight.ts');
      const rec = { msg_id: 'm-probe-h-${n}', sender_id: 'dev-me', kind: 'todo',
        content: JSON.stringify({ ...${JSON.stringify(payload)}, images: ${JSON.stringify(mkImages(n, `h${n}`))} }),
        ts: 1700000000000 };
      return h.estimateMessageHeight(rec, undefined,
        { messages: [], isGroup: false, selfId: 'dev-me', fontSize: 'md' });
    })()`);
    rows.push({ n, rendered: g.rendered, band: g.bandH, more: g.moreH, real: g.cardH, holds: g.cardHoldsBand, est });
  }
  console.log("  · 高度实测表（张数/渲染/图片带/查看更多/卡片真实/估算）: " + JSON.stringify(rows));
  // 锚点正控：上面两条只判"落在区间里"，锚点若滑到某个更小的内层盒子，两条都可能照样绿
  // （real 变小 ⇒ real ≤ est 更成立）。所以另钉一条：有图的那几行，量到的必须是**含图片带**的祖先。
  check("锚点正控：量到卡片的那一格必须真的含着图片带（锚点读错对象时这条先红）",
    rows.filter((r) => r.n > 0).every((r) => r.holds === true),
    "有图的行 holds 全 true", JSON.stringify(rows.map((r) => [r.n, r.holds])));
  check("每种张数：卡片真实高度 ≤ 估算（估少了就是虚拟列表遮挡）",
    rows.every((r) => r.real > 0 && r.est > 0 && r.real <= r.est),
    "全部 real ≤ est", JSON.stringify(rows));
  check("每种张数：估算不许比真实多出一整行以上（估多了＝卡片之间出现空洞）",
    rows.every((r) => r.est - r.real <= 100), "est-real ≤ 100", JSON.stringify(rows));
  check("只画前几张时，图片带高度按可见张数收敛（第 5 张往后不再长高）",
    rows.filter((r) => r.n >= LIMIT).every((r) => r.band === rows.find((x) => x.n === LIMIT).band),
    "≥上限的图片带等高", JSON.stringify(rows.map((r) => [r.n, r.band])));
}

/**
 * 群任务看板**实时同步**行为测试（`--only=tasksrt`）。
 *
 * 不挂源码字符串、不直接改 store：在真浏览器里挂真的 `GroupTasksBoard`，把
 * `getGroupTodoMessages`（DB 快照）与 `onMessageReceived`（事件订阅）两条 api 替成
 * 可控夹具，然后从**后端事件方向**推 message-received，断言看板 DOM 真的更新、
 * 计数正确、不重复、不被旧事件回滚、订阅可摘、重开与持久化一致。
 *
 * 这一族曾真坏过：看板改折 groupTodoRows（51dac87）后，独立窗口的订阅仍只重载
 * messages —— 事件收到了、IPC 也发了，看板一动不动。源码形状测试发现不了
 * "订阅接到了错误的数据源"，所以这里必须走真实订阅→重读→折叠→渲染整条链。
 */
async function runTasksRealtime(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);

  // 有界等待：全量连跑时长会话里 150ms 去抖定时器偶发 >450ms 才落地（固定 sleep
  // 在 solo 跑绿、全集跑红）。条件满足即继续，到点才报红，不把时序写成脆弱断言。
  const waitFor = async (fn, timeoutMs = 3_000, stepMs = 100) => {
    const deadline = Date.now() + timeoutMs;
    let v = await fn();
    while (!v && Date.now() < deadline) {
      await sleep(stepMs);
      v = await fn();
    }
    return v;
  };

  // 页面内常量与记录工厂（形状与后端落库一致：conv_id/seq/ts/msg_id/kind/content）
  const SETUP = `(async () => {
    window.GID = 'g1';
    window.CONV = 'group:g1';
    window.ME = 'probe-me';
    window.OTHER = 'probe-other';
    window.__mk = (id, seq, kind, def, ts) => ({
      msg_id: 'm-' + id + '-' + seq,
      sender_id: window.OTHER,
      conv_id: window.CONV,
      kind, seq, ts,
      status: 'read',
      content: JSON.stringify(Object.assign({
        todo_id: id, title: id, assignees: [window.ME], status: 'todo',
        creator: window.OTHER, deleted: false, description: '', images: [],
        archived: false, done_at: null, number: 0, priority: 'normal', category: 'task',
      }, def)),
    });
    return true;
  })()`;
  await cdp.eval(SETUP);
  await cdp.eval("window.__probe.todoBus()");

  /** 读看板当下：筛选标签页（DOM 顺序 = all/mine/created/archived）、列表行标题、弹窗文本。 */
  const view = async () =>
    cdp.eval(`(() => {
      const pills = Array.from(document.querySelectorAll('[role="tab"]')).map((b) => ({
        key: b.getAttribute('data-filter'),
        label: (b.textContent || '').replace(/\\s+/g, ' ').trim(),
        pressed: b.getAttribute('aria-selected') === 'true',
        count: Number((b.querySelector('span') || {}).textContent || '0'),
      }));
      // 行标题按钮：活动列表与归档列表都是 button.min-w-0.flex-1
      const rowTitles = Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
        .map((b) => (b.querySelector('.truncate') || {}).textContent || '');
      const dialogs = document.querySelectorAll('[role="dialog"]').length;
      const dialogText = (document.querySelector('[role="dialog"]') || {}).textContent || '';
      return {
        pills,
        rowTitles,
        uniqTitles: [...new Set(rowTitles)],
        dialogs,
        dialogText,
      };
    })()`);

  // —— 初始快照：对端已建 A（待办，指派给我）——
  await cdp.eval(`(async () => {
    const now = Date.now();
    window.__probe.todoRows([
      window.__mk('A', 1, 'todo', {
        title: '写周报', number: 1, priority: 'high',
        description: '本周进展与下周计划：完成登录链路的断线重连与文件续传验证。',
      }, now),
    ]);
    return window.__probe.todoRows.length;
  })()`);
  await cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({ groupId: "g1", open: true }))})`);
  await cdp.eval(`window.__probe.seedDevice('probe-me')`);
  await waitFor(async () => (await view()).uniqTitles.includes("写周报"), 4_000);

  const v0 = await view();
  // 身份（seedDevice）刻意在 install 之后才种：这是**真实时序**的一种（渲染先起、身份后到）。
  // 默认页签必须等到身份已知才判；否则「我的」被数成 0、锁死在「全部」（5.20.0 实际缺陷）。
  check("初始：看板列出 A，页签顺序 全部→我的→我创建→已归档，默认选中「我的」，计数 all=1/mine=1/created=0/archived=0",
    v0.pills.length === 4
      && v0.pills.map((p) => p.key).join(",") === "all,mine,created,archived"
      && v0.pills.map((p) => p.count).join(",") === "1,1,0,0"
      && v0.pills.find((p) => p.pressed)?.key === "mine"
      && v0.uniqTitles.includes("写周报"),
    "行=" + JSON.stringify(v0.uniqTitles) + " pills=" + JSON.stringify(v0.pills), JSON.stringify(v0.pills));
  const reads0 = (await cdp.eval("window.__probe.todoStats()")).reads;
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-tasks.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 群任务看板取证帧 → " + SHOT_PATH.replace(/\.png$/, "-tasks.png"));
  }
  check("首屏只发一次全表读取（ensure 已加载不重复打 IPC）",
    reads0 === 1, "reads=1", "reads=" + reads0);

  // —— 订阅真实事件（独立窗口的那条路径）——
  await cdp.eval(`(async () => {
    const chat = await window.__probe.chatStore();
    window.__unwatch = await chat.watchGroupTodos('g1');
    return true;
  })()`);
  const st1 = await cdp.eval("window.__probe.todoStats()");
  check("watchGroupTodos 注册了一次 message-received 订阅",
    st1.subscribed === 1, "subscribed=1", JSON.stringify(st1));

  // —— 展开 A 的详情：验证实时更新不把展开态关掉 ——
  await cdp.eval(`(() => {
    const btns = Array.from(document.querySelectorAll('button.min-w-0.flex-1'));
    const a = btns.find((b) => (b.textContent || '').includes('写周报'));
    if (!a) return false;
    a.click();
    return true;
  })()`);
  await sleep(200);
  const vDetail0 = await view();
  check("点行打开了任务详情弹窗", vDetail0.dialogs === 1 && vDetail0.dialogText.includes("写周报"),
    "dialog 含旧标题", "dialogs=" + vDetail0.dialogs);

  // 矮窗口下详情内容会超出可视高度：footer 在滚动区之外（设计如此），
  // 但要证明内容区真的能滚到底、描述不是被 footer 永久盖住。
  const scrollInfo = await cdp.eval(`(() => {
    const dlg = document.querySelector('[role="dialog"]');
    if (!dlg) return { found: false };
    const sc = [...dlg.querySelectorAll('*')].find((e) => {
      const st = getComputedStyle(e);
      return /(auto|scroll)/.test(st.overflowY) && e.scrollHeight > e.clientHeight + 1;
    });
    if (!sc) return { found: false, why: '没有可滚动内容区' };
    sc.scrollTop = sc.scrollHeight;
    return {
      found: true,
      top: Math.round(sc.scrollTop),
      max: sc.scrollHeight - sc.clientHeight,
      text: dlg.innerText,
    };
  })()`);
  check("任务详情内容区可滚到底（描述在 footer 之上可完整到达，不是被永久遮住）",
    scrollInfo.found === true && scrollInfo.top > 0 && scrollInfo.top === scrollInfo.max
      && String(scrollInfo.text || "").includes("本周进展与下周计划"),
    "scrollTop=max 且描述存在", JSON.stringify({ found: scrollInfo.found, top: scrollInfo.top, max: scrollInfo.max }));
  if (SHOT_PATH) {
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(SHOT_PATH.replace(/\.png$/, "-taskdetail.png"), Buffer.from(shot.data, "base64"));
    console.log("  📷 群任务详情取证帧 → " + SHOT_PATH.replace(/\.png$/, "-taskdetail.png"));
  }

  // —— 对端一批变更（模拟另一个成员连发）：A 改成完成并改名、新增 B、新增 C 后完成并归档。
  //    同步推 5 个事件，其中 B 的创建事件重复一次 —— 150ms 去抖后只许重读一次。 ——
  await cdp.eval(`(async () => {
    const now = Date.now();
    const rows = [
      window.__mk('A', 1, 'todo', { title: '写周报', number: 1 }, now - 2000),
      window.__mk('A', 2, 'todo_update', { title: '周报已发出', status: 'done', done_at: now, number: 1 }, now),
      window.__mk('B', 3, 'todo', { title: '修打印机', number: 2 }, now),
      window.__mk('C', 4, 'todo', { title: '订场地', number: 3 }, now),
      window.__mk('C', 5, 'todo_update', { title: '订场地', status: 'done', done_at: now, archived: true, number: 3 }, now + 1),
    ];
    window.__probe.todoRows(rows);
    const events = [rows[1], rows[2], rows[3], rows[4], rows[2] /* B 重复帧 */];
    window.__probe.todoEmit(events);
    return events.length;
  })()`);
  // 等到「1 次重读」落地而不是睡固定时长（长会话下定时器可能延迟）。
  await waitFor(async () =>
    ((await cdp.eval("window.__probe.todoStats()")).reads - reads0) === 1);
  await waitFor(async () => (await view()).uniqTitles.includes("修打印机"));
  const st2 = await cdp.eval("window.__probe.todoStats()");
  check("5 个事件（含 1 个重复帧）只合并成 1 次重读（150ms 去抖真实生效）",
    st2.reads - reads0 === 1, "Δreads=1", "Δreads=" + (st2.reads - reads0));

  const v1 = await view();
  check("新增/改名/完成/归档后：活动 all=2、mine=2、归档=1（计数与列表一致）",
    v1.pills.map((p) => p.count).join(",") === "2,2,0,1",
    "2,2,0,1", JSON.stringify(v1.pills));
  check("活动列表出现新任务 B 与改名后的 A，归档的 C 不在活动列表，且无重复行",
    v1.uniqTitles.includes("修打印机") && v1.uniqTitles.includes("周报已发出")
      && !v1.uniqTitles.includes("写周报") && !v1.uniqTitles.includes("订场地")
      && v1.rowTitles.length === v1.uniqTitles.length,
    JSON.stringify(v1.rowTitles), JSON.stringify(v1.rowTitles));
  check("更新前展开的详情弹窗仍开着，且内容已是改名后的 A（展开态保留 + 内容实时）",
    v1.dialogs === 1 && v1.dialogText.includes("周报已发出") && !v1.dialogText.includes("订场地"),
    "dialog 跟到新标题", "dialogs=" + v1.dialogs);
  check("筛选没被实时更新重置（仍停在「我的」）",
    v1.pills.find((p) => p.pressed)?.key === "mine", "mine pressed", JSON.stringify(v1.pills.map((p) => p.pressed)));

  // —— 切到「全部」，再来一批重复/旧序事件：筛选保留、终态不被旧帧回滚 ——
  await cdp.eval(`(() => {
    document.querySelector('[role="tab"][data-filter="all"]').click();
    return true;
  })()`);
  await sleep(150);
  await cdp.eval(`window.__probe.todoEmit([window.__mk('A', 1, 'todo', { title: '写周报', number: 1 }, Date.now() - 9000)])`);
  await cdp.eval(`window.__probe.todoEmit([window.__mk('A', 1, 'todo', { title: '写周报', number: 1 }, Date.now() - 9000)])`);
  // 旧事件只触发重读、不允许回滚；状态在落地前后都成立，给定时器一个固定窗口即可
  // （unlisten 的清理会摘掉尚未落地的定时器，不会污染后面的"reads 不变"断言）。
  await sleep(300);
  const v2 = await view();
  check("旧 seq / 重复事件后：列表不回滚到旧标题（DB 快照是真相），筛选仍在「全部」",
    v2.uniqTitles.includes("周报已发出") && !v2.uniqTitles.includes("写周报")
      && v2.pills.find((p) => p.pressed)?.key === "all",
    JSON.stringify(v2.uniqTitles), JSON.stringify(v2.uniqTitles));

  // —— 归档筛选：C 在归档里，且只有它一条 ——
  await cdp.eval(`(() => {
    document.querySelector('[role="tab"][data-filter="archived"]').click();
    return true;
  })()`);
  await sleep(150);
  const v3 = await view();
  const archivedPill = v3.pills.find((p) => p.key === "archived");
  check("「已归档」里正好是 C 一条（归档计数与列表一致）",
    archivedPill?.count === 1 && v3.uniqTitles.length === 1 && v3.uniqTitles[0] === "订场地",
    JSON.stringify(v3.uniqTitles) + " count=" + archivedPill?.count, JSON.stringify(v3.uniqTitles));

  // —— 取消订阅：之后的事件不再触发重读（监听器真的被摘掉，没有泄漏的第二条）——
  await cdp.eval(`(() => { window.__unwatch(); return true; })()`);
  const readsBefore = (await cdp.eval("window.__probe.todoStats()")).reads;
  await cdp.eval(`(async () => {
    const now = Date.now();
    const rows = JSON.parse(JSON.stringify(window.__todoRows));
    rows.push(window.__mk('D', 6, 'todo', { title: '新任务 D', number: 4 }, now));
    window.__probe.todoRows(rows);
    window.__probe.todoEmit([rows[rows.length - 1]]);
    return true;
  })()`);
  await sleep(350);
  const st3 = await cdp.eval("window.__probe.todoStats()");
  const v4 = await view();
  check("unlisten 后再推事件：不发重读、看板也不出现新任务（订阅确实摘干净）",
    st3.reads === readsBefore && st3.unsubscribed === true && !v4.uniqTitles.includes("新任务 D"),
    "reads 不变", "reads " + readsBefore + "→" + st3.reads + " unsub=" + st3.unsubscribed);

  // —— 重新订阅（相当于窗口重新聚焦/换群再换回）：漏下的变更立刻补回来 ——
  await cdp.eval(`(async () => {
    const chat = await window.__probe.chatStore();
    await chat.watchGroupTodos('g1');
    window.__probe.todoEmit([window.__todoRows[window.__todoRows.length - 1]]);
    return true;
  })()`);
  await cdp.eval(`(() => {
    document.querySelector('[role="tab"][data-filter="all"]').click(); // 回「全部」看活动行
    return true;
  })()`);
  await waitFor(async () => (await view()).uniqTitles.includes("新任务 D"), 3_000);
  const v5 = await view();
  check("重新订阅后事件再次生效：D 出现在看板（自愈，不需要重开窗口）",
    v5.uniqTitles.includes("新任务 D"), JSON.stringify(v5.uniqTitles), JSON.stringify(v5.uniqTitles));

  // —— 关闭再打开：重新挂一块看板，首屏读到的与"DB"一致（持久化一致性）——
  const finalRows = await cdp.eval("JSON.parse(JSON.stringify(window.__todoRows))");
  await cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({ groupId: "g1", open: true }))})`);
  await cdp.eval(`window.__probe.seedDevice('probe-me')`);
  await waitFor(async () =>
    (await view()).pills.map((p) => p.count).join(",") === "3,3,0,1", 4_000);
  const v6 = await view();
  check("面板关闭重开：首屏直接呈现持久化终态（A 改名/B 新增/C 归档/D 已到），不靠事件补",
    v6.uniqTitles.includes("周报已发出") && v6.uniqTitles.includes("修打印机")
      && v6.uniqTitles.includes("新任务 D") && !v6.uniqTitles.includes("订场地")
      && v6.pills.map((p) => p.count).join(",") === "3,3,0,1",
    "3,3,0,1", JSON.stringify({ t: v6.uniqTitles, pills: v6.pills.map((p) => p.count) }));
  void finalRows;

  // —— 「我的」为空 ⇒ 实际选中「全部」（用户 2026-11-09 要求这条读数）——
  // 换一个**不是任何任务负责人**的身份重新挂看板：mine=0，默认必须落到「全部」，
  // 不能停在空空的「我的」上。身份仍在 install 之后种（同一时序），所以这条同时守住
  // 「身份晚到也不能先判」。
  const mountBoard = () => cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({ groupId: "g1", open: true }))})`);
  await mountBoard();
  await cdp.eval(`window.__probe.seedDevice('probe-other')`);
  await waitFor(async () => {
    const v = await view();
    return v.pills.length === 4 && v.pills.find((p) => p.key === "mine")?.count === 0;
  }, 4_000);
  const vEmpty = await view();
  check("「我的」为空：默认选中「全部」（不停在空的「我的」）",
    vEmpty.pills.find((p) => p.pressed)?.key === "all"
      && vEmpty.pills.find((p) => p.key === "mine")?.count === 0,
    "mine=0 ⇒ 选中 all", JSON.stringify(vEmpty.pills));

  // 还原身份与看板，后续检查继续按 probe-me 跑
  await mountBoard();
  await cdp.eval(`window.__probe.seedDevice('probe-me')`);
  await waitFor(async () => (await view()).pills.map((p) => p.count).join(",") === "3,3,0,1", 4_000);

  // 第三档（overdue）那一行本段原本没有，必须自己造一条**创建记录**（`kind:'todo'` 那条带绝对号，
  // `foldTodos` 只认它；`todo_update` 不行）。两条实测到的前提，写在这里省下一次重复踩：
  //   ① 只把行 push 进 `window.__todoRows`（DB 快照）**不够** —— 看板的重读由事件驱动，
  //      而本段前面已经 `__unwatch()`、`install()` 重挂时旧监听随之摘掉 ⇒ 不先重新订阅，
  //      emit 出去只有 bulk 那条路会读，而它的 ids 来自 `conversations.filter(kind==='group')`，
  //      这册 mock 的会话列表是空的（实测 `convGroupIds: []`）⇒ 永远写不到 `group:g1`。
  //      所以顺序必须是 **push 行 → `watchGroupTodos('g1')` → emit**（照 D 那条已验证的路）。
  //   ② 反过来，上一版我把"store 没吃到那 7 行"记成了卡点 —— **那是假前提**：按①的顺序重跑后
  //      store 立即变成 7 行、DOM 里也出现「取回快递」。`putTodoRows`/`reloadGroupTodoRows`
  //      本身没有过滤（`putTodoRows` 只按 `convIds` 建键、整表替换那一个群）。
  const T_OVERDUE_ROW = "取回快递"; // status=overdue ⇒ 条应为 warning-solid
  const injected = await cdp.eval(`(async () => {
    const chat = await window.__probe.chatStore();
    const rows = JSON.parse(JSON.stringify(window.__todoRows));
    const E = window.__mk('E', 9, 'todo', { title: '${T_OVERDUE_ROW}', number: 88, status: 'overdue' }, Date.now());
    rows.push(E);
    window.__probe.todoRows(rows);
    await chat.watchGroupTodos('g1');
    window.__probe.todoEmit([E]);
    return true;
  })()`);
  const rowTitlesNow = () => cdp.eval(`(() => Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
    .map((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim()))()`);
  const arrived = await waitFor(async () => (await rowTitlesNow()).includes(T_OVERDUE_ROW), 4_000);
  check("overdue 那一行真的走到了 DOM（这格红 ⇒ 下面的色条读数不作数，不能当成「色条画错」）",
    !!injected && arrived === true, `${T_OVERDUE_ROW} 在行标题里`, JSON.stringify(await rowTitlesNow()));

  // ---------------- 状态色条 ↔ 真实渲染的绑定（决策 3/4 换档那一刀的另一半天） ----------------
  // 为什么非补不可（这三层的静默是**跑出来的**，不是推的）：把 `todos.ts` 的 `done` 单独改回
  // 非 solid 档（`--gosslan-success`，压面板实测 2.54）⇒ `npm test` **1362/1362 全绿**、
  // `--only=msgovf` **78/78 全绿**。`todos.test.ts` 断的是 `includes("warning"/"success")`
  // （`*-solid` 也含这个词，新旧两档一起过），`--gosslan-success-solid` 在 `LogViewer.vue`
  // 还有两个消费者 ⇒ 连孤儿检测都不响；而契约行读的是 `style.css` 里 token 自己的值，
  // **从不读"这一档到底画没画在这个元素上"**。两档真实值差着 2.54 与 9.26 那一截。
  // 已有状态里有一行 done（周报已发出）和一行 todo（修打印机），两行各自画着自己那一档的左缘条；
  // 第三档 overdue 板上原本没有，由本段下面自己造一条（造法见那一段的注释）。
  // ⚠️ 更正我自己写过的两条假前提（都实测推翻过，写在这里省下一次重复踩）：
  //    「注新 id 进不了 DOM，因为看板按会话里已有的卡片取 id」—— **错**：`getGroupTodoMessages(ids)`
  //    的 ids 是**群会话 id**（`refreshOpenTodos` 取 `conversations.filter(kind==="group")`），不是任务 id；
  //    这册 mock 更是整份返回、根本不吃 ids。
  //    「store 没吃到那 7 行 ⇒ 卡点在 `putTodoRows`」—— **也错**：`reloadGroupTodoRows` 里是
  //    `putTodoRows(prev, [convId], rows)` 整表替换、没有任何过滤。真正的原因是**事件驱动的那次重读
  //    当时没有订阅者**（`__unwatch()` + `install()` 重挂后旧的监听随之摘掉），emit 出去只剩 bulk 那条路，
  //    而 bulk 的 ids 来自 `conversations` —— 这册 mock 里**一条群会话都没有**（实测 `convGroupIds: []`）
  //    ⇒ 永远写不到 `group:g1`。按「push 行 → `watchGroupTodos('g1')` → emit」重跑，store 立刻 7 行、
  //    DOM 里也出现那一行。所以这不是产品缺陷，是探针夹具的时序。
  // ⚠️ 口径：done 行钉 `--gosslan-success-solid`、todo 行钉 `--gosslan-status-offline`、
  //    overdue 行钉 `--gosslan-warning-solid`，都是**写死的 token 名**，不是从 `TODO_STATUS_BAR` 现推 ——
  //    从那张表推自己等于没断言。
  //    这正好补上实测过的那一半静默：把 `done` 单独改回 `--gosslan-success` 时，
  //    `npm test` 1362/1362 绿、`--only=msgovf` 78/78 绿，此前**没有任何一层**看得见。
  const T_DONE_ROW = "周报已发出"; // status=done ⇒ 条应为 success-solid
  const T_TODO_ROW = "修打印机"; // status=todo  ⇒ 条应为 status-offline（中性灰）
  await cdp.eval(`(() => { const b = document.querySelector('[role="tab"][data-filter="all"]');
    if (b) b.click(); return !!b; })()`); // 切「全部」：两行都得在 DOM 里
  /**
   * 按行标题找到那一行左缘那道 2px 色条，读它自己的底色；顺带回读整行文字与当前行标题清单。
   *
   * ⚠️ 定位起点用**本段自己已经跑绿的那把尺**（`view()` 里的 `button.min-w-0.flex-1`），
   *    不写 `#probe-host` 前缀：这台机器上挂载点的 id 不止一个名字（本文件里
   *    `getElementById('mhost') || getElementById('probe-host')` 就是先例），
   *    第一版用 `#probe-host span[...]` 起头 ⇒ 两行一律读到 null。
   *    色条用 `:scope > span` 只认**行的直接子元素**，这样同时证明了"它是整行那道左缘条"，
   *    而不是行里某个也带 aria-hidden 的图标。
   *    `rowText` 是给"状态真的换档了"那格用的独立可观测量：色条读到的值与行文字来自同一次 eval，
   *    所以读到旧渲染时行文字也一定是旧的 —— 不用睡固定时长去猜渲染落地（第二版就是这么错的：
   *    等到"有 rgb"就往下走，结果两格读到的是换档前的绿/灰）。
   */
  const barsRead = () => cdp.eval(`(() => {
    const rowOf = (title) => {
      const btn = Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
        .find((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim() === title);
      if (!btn) return null;
      return btn.closest('div.relative'); };
    const one = (title) => {
      const row = rowOf(title);
      if (!row) return '!norow';
      const bar = row.querySelector(':scope > span[aria-hidden="true"]');
      if (!bar) return '!nobar:' + Array.from(row.children)
        .map((c) => c.tagName + (c.getAttribute('aria-hidden') === 'true' ? '[ah]' : '')).join(',');
      return getComputedStyle(bar).backgroundColor; };
    const titles = Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
      .map((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim());
    return { d: one('${T_DONE_ROW}'), t: one('${T_TODO_ROW}'), o: one('${T_OVERDUE_ROW}'),
      titles: [...new Set(titles)] }; })()`);
  await waitFor(async () => { const b = await barsRead(); return String(b.d).startsWith("rgb") && String(b.t).startsWith("rgb") && String(b.o).startsWith("rgb"); }, 4_000);

  const wasDarkBar = await cdp.eval("document.documentElement.classList.contains('dark')");
  for (const dark of [false, true]) {
    const tn = dark ? "暗" : "亮";
    const st = await setAppearance(cdp, dark);
    check(`色条绑定·${tn}：主题档真的切过去了（写的是 appearance，不是 computed 的 dark）`,
      !!st && st.ok === "ok" && st.dark === dark, `dark=${dark}`, JSON.stringify(st));
    await sleep(200);
    const bars = await barsRead();
    check(`色条绑定·${tn}：三行都读到了自己的底色（读不到 rgb 就是没画/没选中，诊断串不算绿）`,
      String(bars.d).startsWith("rgb") && String(bars.t).startsWith("rgb") && String(bars.o).startsWith("rgb"),
      "三个都以 rgb 开头", JSON.stringify(bars));
    const solidD = await pageColor(cdp, "--gosslan-success-solid");
    const plainD = await pageColor(cdp, "--gosslan-success");
    const offline = await pageColor(cdp, "--gosslan-status-offline");
    // 两档在**亮暗两个外观下都必须可区分**：`--gosslan-*` 是状态点/色条档（对面板判 3.0），
    // `--gosslan-*-solid` 是实底填充档（对深墨/白字判 4.5）。2026-11-09 配色求解重做后，
    // 暗色也不再收敛成同一个值（旧注释里的“暗档同值”是当时那版求解器的实测，已过时）。
    // 所以 `mustDiffer` 不再分外观：两档一样就等于把“实底”和“状态点”混成了同一个语义。
    const mustDiffer = true;
    check(`色条绑定·${tn}：done 行的左缘条画的就是 success-solid${mustDiffer ? "（且不是压线 2.54 的 success 档）" : ""}`,
      sameColor(bars.d, solidD) && (!mustDiffer || !sameColor(bars.d, plainD)),
      mustDiffer ? `== ${solidD} 且 != ${plainD}` : `== ${solidD}`,
      `${bars.d}｜solid=${solidD}｜plain=${plainD}`);
    check(`色条绑定·${tn}：todo 行的左缘条画的是中性灰 status-offline，且与 done 行不同色（防"整片涂成一族"）`,
      sameColor(bars.t, offline) && !sameColor(bars.d, bars.t),
      `== ${offline} 且异色`, `todo=${bars.t}｜offline=${offline}｜done=${bars.d}`);
    const solidW = await pageColor(cdp, "--gosslan-warning-solid");
    const plainW = await pageColor(cdp, "--gosslan-warning");
    check(`色条绑定·${tn}：overdue 行的左缘条画的就是 warning-solid${mustDiffer ? "（且不是 warning 档）" : ""}`,
      sameColor(bars.o, solidW) && (!mustDiffer || !sameColor(bars.o, plainW)),
      mustDiffer ? `== ${solidW} 且 != ${plainW}` : `== ${solidW}`,
      `${bars.o}｜solid=${solidW}｜plain=${plainW}`);
    check(`色条绑定·${tn}：warning 与 warning-solid 是**两个可区分的档**（状态点档 ≠ 实底档）`,
      !sameColor(plainW, solidW), `!= ${plainW} / ${solidW}`, `warning=${plainW}｜solid=${solidW}`);
    check(`色条绑定·${tn}：success 与 success-solid 是**两个可区分的档**（状态点档 ≠ 实底档）`,
      !sameColor(plainD, solidD), `!= ${plainD} / ${solidD}`, `success=${plainD}｜solid=${solidD}`);
  }
  const backBar = await setAppearance(cdp, wasDarkBar === true);
  check("色条绑定不外溢：跑完回到进页面时那一档（store 与 class 都要回来）",
    !!backBar && backBar.ok === "ok" && backBar.dark === (wasDarkBar === true),
    `dark=${wasDarkBar === true}`, JSON.stringify(backBar));
  // 尺子非空转：色条的底色是 token 类，压不过 inline ⇒ inline 改色必须被读回来
  await cdp.eval(`(() => { const btn = Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
      .find((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim() === '${T_DONE_ROW}');
    if (!btn) return false;
    const row = btn.closest('div.relative');
    const hit = row ? row.querySelector(':scope > span[aria-hidden="true"]') : null;
    if (hit) { hit.style.transition = 'none'; hit.style.background = 'rgb(1, 2, 3)'; } return !!hit; })()`);
  await sleep(120);
  const forcedBar = await barsRead();
  check("色条尺非空转：inline 把 done 行那道压成 rgb(1, 2, 3) 必须被读回来",
    forcedBar.d === "rgb(1, 2, 3)", "rgb(1, 2, 3)", String(forcedBar.d));
  await cdp.eval(`(() => { const btn = Array.from(document.querySelectorAll('button.min-w-0.flex-1'))
      .find((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim() === '${T_DONE_ROW}');
    if (!btn) return false;
    const row = btn.closest('div.relative');
    const hit = row ? row.querySelector(':scope > span[aria-hidden="true"]') : null;
    if (hit) { hit.style.background = ''; hit.style.transition = ''; } return true; })()`);

  // —— 卡片**上半区**：滚到那条并闪一下，且**不**打开详情（负责人 2026-10-29）——
  // 重新挂一块带视口高度与 highlight 支持的看板：换一批行，目标是最后一条。
  await cdp.eval(`(async () => {
    const now = Date.now();
    window.__probe.todoRows(Array.from({ length: 6 }, (_, i) => window.__mk('H' + i, 10 + i, 'todo', {
      title: 'row-h' + i, number: 10 + i,
    }, now - i * 1000)));
    return window.__probe.todoRows.length;
  })()`);
  await cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({ groupId: "g1", open: true, hostHeight: 220, focusProp: true }))})`);
  await waitFor(async () => (await view()).rowTitles.length >= 6, 4_000);
  await cdp.eval("(async () => { window.__st.focus = { id: 'H5', seq: 1, mode: 'highlight' }; return true; })()");
  const hl = await waitFor(async () => {
    const r = await cdp.eval(`(() => {
      const row = document.querySelector('[data-todo-row="H5"]');
      if (!row || !row.classList.contains('todo-row-flash')) return null;
      const box = row.getBoundingClientRect();
      return {
        flashing: true,
        onScreen: box.top >= -1 && box.bottom <= window.innerHeight + 1,
        dialogs: document.querySelectorAll('[role="dialog"]').length,
      };
    })()`);
    return r;
  }, 4_000);
  check("卡片上半区：目标行拿到闪烁类、落到视口内、且**没有**打开详情弹窗",
    !!hl && hl.flashing && hl.onScreen && hl.dialogs === 0,
    JSON.stringify(hl), JSON.stringify(hl));
  // 反向：同一张卡片再来一次（序号 +1）必须重新闪 —— 详情那条 watch 靠 open 翻转去重，
  // 高亮这条不许跟着它一起"第二次就不灵"。
  await cdp.eval("(async () => { window.__st.focus = { id: 'H5', seq: 2, mode: 'highlight' }; return true; })()");
  const again = await waitFor(async () => {
    const r = await cdp.eval(`(() => {
      const row = document.querySelector('[data-todo-row="H5"]');
      return row ? row.classList.contains('todo-row-flash') : false;
    })()`);
    return r ? { flashingAgain: true } : null;
  }, 2_000);
  check("卡片上半区：同一条连点第二次仍然重新闪", !!again && again.flashingAgain, JSON.stringify(again), JSON.stringify(again));
  // 反向那条也要在：两条路合并成同一个入参之后，`detail` 必须仍然**展开详情**
  // （合成一个 watch 最容易的退化就是"顺手把 detail 也变成只闪一下"）。
  await cdp.eval("(async () => { window.__st.focus = { id: 'H3', seq: 3, mode: 'detail' }; return true; })()");
  const det = await waitFor(async () => {
    const r = await cdp.eval(`(() => {
      const d = document.querySelector('[role="dialog"]');
      return d ? { open: true, hasTitle: (d.textContent || '').includes('row-h3') } : null;
    })()`);
    return r;
  }, 3_000);
  check("详情路径：focus(mode=detail) 仍然直接展开那条任务（合并 watch 后没退化成只闪）",
    !!det && det.open && det.hasTitle, JSON.stringify(det), JSON.stringify(det));
}

/**
 * 输入框那两个浮层的**真布局**判据（`--only=inputpanel`）。
 *
 * 为什么这一格非用真布局不可（评审登记过、此前故意没补）：`MessageComposer` 里的表情面板与
 * @ 候选列表都是 CSS `absolute bottom-full` **往上长**、留在输入框卡片里面。
 * 单独把 `EmojiPicker` 挂起来量，"往上长"这个方向没有参照物 ⇒ 量不到那一型真实缺陷
 *（面板顶部被视口上边缘切掉 / 被某个祖先的 overflow 裁掉）。
 *
 * ⚠️ 宿主壳只做一件事：把输入卡片压到视口底部（真实聊天窗里它就是 flex 的最后一项）。
 *    不给组件加新属性、不改样式、不改产品码 —— 为可测性加 `data-*` 也算动应用码（这条本仓付过一次版本号）。
 *    几何读数全部走现成的 `window.__probe.floatLayer(sel)`（它同时给 inViewport、被谁裁、
 *    有没有打断层链的祖先），不在这里另开第二份几何家。
 */
/**
 * 群任务窗口「左列表 410px + 右详情常驻」两栏（`--only=taskpane`）。
 *
 * 只钉结构契约，不钉画板文案：1000（群任务窗口初始宽度 = 主窗口 1000×680）与 780
 * 两种内容宽时左列 410±1、右栏还有 ≥280；680 时回退单栏（右栏消失、点行才开原弹窗）。
 * 筛选页签顺序按画板 我的/全部/我创建/已归档，默认「我的」——`--only=tasksrt` 继续管实时同步。
 */
async function runTaskPane(cdp, url) {
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1000, height: 760, deviceScaleFactor: 1, mobile: false,
  });
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(async () => {
      window.GID = 'g1'; window.CONV = 'group:g1';
      window.ME = 'probe-me'; window.OTHER = 'probe-other';
      window.__mk = (id, seq, kind, def, ts) => ({
        msg_id: 'm-' + id + '-' + seq, sender_id: window.OTHER, conv_id: window.CONV,
        kind, seq, ts, status: 'read',
        content: JSON.stringify(Object.assign({
          todo_id: id, title: id, assignees: [window.ME], status: 'todo',
          creator: window.OTHER, deleted: false, description: '', images: [],
          archived: false, done_at: null, number: 0, priority: 'normal', category: 'task',
        }, def)),
      });
      return true;
    })()`);
    await cdp.eval("window.__probe.todoBus()");
    const now = Date.now();
    await cdp.eval(`window.__TASKS = [
      window.__mk('A', 1, 'todo', { title: '写周报', number: 1, priority: 'high' }, ${now}),
      window.__mk('B', 2, 'todo', { title: '对账单', number: 2 }, ${now + 1}),
      // C 只派给别人：用来验「选中项被筛选掉后必须回落」（2026-11-08 选中态那条）。
      window.__mk('C', 3, 'todo', { title: '他建的', number: 3, assignees: [window.OTHER] }, ${now + 2}),
    ]`);
    await cdp.eval("window.__probe.todoRows(window.__TASKS)");
    await cdp.eval(`window.__probe.install('/src/components/GroupTasksBoard.vue', '', ${JSON.stringify(JSON.stringify({
      groupId: "g1", open: true, fill: true, twoPane: true, hostHeight: 620,
    }))})`);
    await cdp.eval("window.__probe.seedDevice('probe-me')");
    // 用 `fill` 而不是 `standalone`：后者的首屏门是 `todosLoadedOnce`，只由真实窗口入口
    // `GroupTodosWindow` 的 `loadGroupTodos` 置位；探针直连组件时没有这条入口。
    // 两栏的高度契约由 `fill` 同样满足（都是 `h-full min-h-0`），宽度与回退规则不受影响。
    await cdp.eval("document.querySelector('#probe-host').style.width = '780px'");
    // 结构读数：两栏时根节点正好两个孩子（左列 / 右栏）；单栏时孩子是 display:contents 的包装。
    const read = () => cdp.eval(`(() => {
      const host = document.querySelector('#probe-host');
      const root = host && host.firstElementChild;
      const kids = root ? Array.from(root.children) : [];
      const list = kids[0] || null;
      const detail = kids.length > 1 ? kids[1] : null;
      const tabs = root ? Array.from(root.querySelectorAll('[role="tab"]')) : [];
      const active = tabs.find((b) => b.getAttribute('aria-selected') === 'true');
      // 选中态判据要读**计算后的底色**：主色淡底由 color-mix 现算，
      // 拿 class 名比对等于只验了自己写的字符串。tint 也在这里现量一份参照。
      const tintProbe = document.createElement('div');
      tintProbe.style.background = 'var(--gosslan-primary-light)';
      document.body.appendChild(tintProbe);
      const tint = getComputedStyle(tintProbe).backgroundColor;
      tintProbe.remove();
      const rows = Array.from(host.querySelectorAll('[data-todo-row]')).map((r) => ({
        id: r.dataset.todoRow,
        current: r.getAttribute('aria-current'),
        bg: getComputedStyle(r).backgroundColor,
        title: (((r.querySelector('.truncate') || {}).textContent) || '').trim(),
      }));
      return {
        hostW: host ? Math.round(host.getBoundingClientRect().width) : 0,
        listW: list ? Math.round(list.getBoundingClientRect().width) : 0,
        detailW: detail ? Math.round(detail.getBoundingClientRect().width) : 0,
        hasDetail: !!detail,
        tabs: tabs.map((b) => (b.textContent || '').trim()),
        active: active ? (active.textContent || '').trim() : '',
        detailText: detail ? (detail.textContent || '') : '',
        listText: list ? (list.textContent || '') : '',
        dialogs: document.querySelectorAll('[role="dialog"]').length,
        dialogText: Array.from(document.querySelectorAll('[role="dialog"]'))
          .map((d) => d.textContent || '').join(' '),
        titles: Array.from(host.querySelectorAll('button.min-w-0.flex-1'))
          .map((b) => (((b.querySelector('.truncate') || {}).textContent) || '').trim()),
        rowTexts: Array.from(host.querySelectorAll('button.min-w-0.flex-1'))
          .map((b) => (b.textContent || '').trim()),
        rows, tint,
      };
    })()`);
    /** 选中态的唯一判据：恰好一行 aria-current，且它的底色 = 主色淡底；其余行透明。 */
    const selectedOk = (r) => {
      const sel = r.rows.filter((x) => x.current === "true");
      return sel.length === 1 && sel[0].bg === r.tint
        && r.rows.filter((x) => x.current !== "true").every((x) => x.bg === "rgba(0, 0, 0, 0)");
    };
    const until = async (fn, ms = 3_000) => {
      const t0 = Date.now();
      while (Date.now() - t0 < ms) {
        if (await fn()) return true;
        await sleep(100);
      }
      return false;
    };
    await until(async () => {
      const r = await read();
      return r.listW > 0 && r.hasDetail && r.titles.includes("写周报");
    }, 5_000);
    const wide = await read();
    check("两栏（780）：左列就是 410px", Math.abs(wide.listW - 410) <= 1, "410±1", String(wide.listW));
    check("两栏（780）：右栏仍可用（≥280px）", wide.detailW >= 280, ">=280", String(wide.detailW));
    check("两栏（780）：页签顺序 = 全部/我的/我创建/已归档",
      wide.tabs.length === 4 && wide.tabs[0].startsWith("全部") && wide.tabs[1].startsWith("我的")
        && wide.tabs[2].startsWith("我创建") && wide.tabs[3].startsWith("已归档"),
      "全部,我的,我创建,已归档", JSON.stringify(wide.tabs));
    check("两栏（780）：默认落在「我的」", wide.active.startsWith("我的"), "我的", wide.active);
    check("两栏（780）：详情常驻右栏，不再弹窗",
      wide.dialogs === 0 && !!wide.titles[0] && wide.detailText.includes(wide.titles[0]),
      "右栏 = 列表首条 + 0 dialog", JSON.stringify({ d: wide.dialogs, first: wide.titles[0], text: wide.detailText.slice(0, 30), list: wide.listText.slice(0, 60) }));

    const shotDir = path.join(ROOT, "test-results", "ui-2026-11-08");
    fs.mkdirSync(shotDir, { recursive: true });
    const shot = async (name) => {
      const s = await cdp.send("Page.captureScreenshot", { format: "png" });
      fs.writeFileSync(path.join(shotDir, `${name}.png`), Buffer.from(s.data, "base64"));
    };
    await shot("taskpane-780");

    // 初始尺寸改成「与主窗口同尺寸」（2026-11-08：读 tauri.conf.json 的 1000×680）——
    // 两栏在这个真实初始宽度下必须照旧：左列 410、右栏 ≥280、仍不弹窗。
    await cdp.eval("document.querySelector('#probe-host').style.width = '1000px'");
    await sleep(400);
    const wide1000 = await read();
    check("两栏（1000，初始尺寸）：左列仍是 410px",
      Math.abs(wide1000.listW - 410) <= 1, "410±1", String(wide1000.listW));
    check("两栏（1000，初始尺寸）：右栏仍可用（≥280px）",
      wide1000.detailW >= 280, ">=280", String(wide1000.detailW));
    check("两栏（1000，初始尺寸）：详情仍常驻右栏、不弹窗",
      wide1000.dialogs === 0 && !!wide1000.titles[0] && wide1000.detailText.includes(wide1000.titles[0]),
      "右栏 = 列表首条 + 0 dialog",
      JSON.stringify({ d: wide1000.dialogs, first: wide1000.titles[0] }));
    await shot("taskpane-1000");

    // ---------------- 横排容器不许吃纵向滚动（2026-11-08 用户截图：页签挂着一条竖滚动条） ----------------
    // 量法全部读**运行时**：竖滚动条宽度 = offsetWidth − clientWidth − 左右边框（本仓全局
    // `::-webkit-scrollbar` 固定 8px ⇒ 真有槽位就不会是 0）；溢出量 = scrollHeight − clientHeight；
    // 槽位 = 计算后的 scrollbar-gutter。横排判定：单行（高 ≤64）且 overflowX ∈ auto/scroll
    // —— `overflow-x-auto` 会把另一轴的 `visible` 计算成 `auto`，正是本次缺陷的入口。
    const readStrips = () => cdp.eval(`(() => {
      const out = [];
      for (const el of document.querySelectorAll('#probe-host *')) {
        const s = getComputedStyle(el);
        const h = el.getBoundingClientRect().height;
        if (!(h > 0 && h <= 64)) continue;
        const hx = s.overflowX === 'auto' || s.overflowX === 'scroll';
        const stable = (s.scrollbarGutter || '').indexOf('stable') >= 0;
        if (!hx && !stable) continue;
        const bw = (parseFloat(s.borderLeftWidth) || 0) + (parseFloat(s.borderRightWidth) || 0);
        out.push({
          role: el.getAttribute('role') || '',
          cls: String(el.className || '').slice(0, 120),
          h: Math.round(h),
          barW: Math.round(el.offsetWidth - el.clientWidth - bw),
          vOver: Math.round(el.scrollHeight - el.clientHeight),
          gutter: s.scrollbarGutter,
          overflowY: s.overflowY,
          horizontal: hx,
        });
      }
      return out;
    })()`);
    /** 一条问题都不许有：有竖滚动条 / 有纵向溢出 / 在横排上预留了会生效的纵向槽位。 */
    const stripProblems = (rows) => rows.filter((r) => (r.horizontal && (r.barW > 0 || r.vOver > 0))
      || (r.gutter.indexOf('stable') >= 0 && r.overflowY !== 'visible'));
    const strips = await readStrips();
    check("横排容器：role=tablist 那一条真的被量到（空集不许当绿）",
      strips.some((r) => r.role === "tablist"), "量到 role=tablist", JSON.stringify(strips));
    check("横排容器：没有纵向滚动条、没有纵向溢出、不预留纵向槽位",
      stripProblems(strips).length === 0,
      "barW=0 / vOver=0 / gutter=auto",
      JSON.stringify(stripProblems(strips).length ? stripProblems(strips) : strips));
    // 反例自证①：把 `overflow-y: scroll` 加回去 ⇒ 竖滚动条回来 ⇒ 必须翻红。
    const forcedBar = await cdp.eval(`(() => {
      const el = document.querySelector('#probe-host [role="tablist"]');
      if (!el) return null;
      const prev = el.style.overflowY;
      el.style.overflowY = 'scroll';
      const s = getComputedStyle(el);
      const bw = (parseFloat(s.borderLeftWidth) || 0) + (parseFloat(s.borderRightWidth) || 0);
      const row = {
        role: 'tablist', cls: 'forced-scroll', h: Math.round(el.getBoundingClientRect().height),
        barW: Math.round(el.offsetWidth - el.clientWidth - bw),
        vOver: Math.round(el.scrollHeight - el.clientHeight),
        gutter: s.scrollbarGutter, overflowY: s.overflowY, horizontal: true,
      };
      el.style.overflowY = prev;
      return row;
    })()`);
    check("反例自证①：页签加回 overflow-y: scroll 时判据必须翻红",
      !!forcedBar && stripProblems([forcedBar]).length === 1,
      "翻红（barW>0）", JSON.stringify(forcedBar));
    // 反例自证②：横排上预留纵向槽位（scrollbar-gutter: stable）同样必须翻红。
    const forcedGutter = await cdp.eval(`(() => {
      const el = document.querySelector('#probe-host [role="tablist"]');
      if (!el) return null;
      const prevY = el.style.overflowY;
      const prevG = el.style.scrollbarGutter;
      el.style.overflowY = 'auto';
      el.style.scrollbarGutter = 'stable';
      const s = getComputedStyle(el);
      const bw = (parseFloat(s.borderLeftWidth) || 0) + (parseFloat(s.borderRightWidth) || 0);
      const row = {
        role: 'tablist', cls: 'forced-gutter', h: Math.round(el.getBoundingClientRect().height),
        barW: Math.round(el.offsetWidth - el.clientWidth - bw),
        vOver: Math.round(el.scrollHeight - el.clientHeight),
        gutter: s.scrollbarGutter, overflowY: s.overflowY, horizontal: true,
      };
      el.style.overflowY = prevY;
      el.style.scrollbarGutter = prevG;
      return row;
    })()`);
    check("反例自证②：横排上 scrollbar-gutter: stable 时判据必须翻红",
      !!forcedGutter && forcedGutter.gutter.indexOf('stable') >= 0
        && stripProblems([forcedGutter]).length === 1,
      "翻红（gutter=stable）", JSON.stringify(forcedGutter));

    // ---------------- 选中态（2026-11-08：右栏有内容，左列必须能一眼看出是哪一条） ----------------
    const sel0 = await read();
    check("两栏（选中态）：默认选中首条——恰好一行 aria-current，底色 = 主色淡底",
      selectedOk(sel0), "1 行淡底 + 其余透明", JSON.stringify({ rows: sel0.rows, tint: sel0.tint }));
    // 反例自证：把选中行底色清成透明，上面那条判据必须翻红（否则它只是在验"有两行"）。
    const brokenSel = await cdp.eval(`(() => {
      const host = document.querySelector('#probe-host');
      const tp = document.createElement('div');
      tp.style.background = 'var(--gosslan-primary-light)';
      document.body.appendChild(tp);
      const tint = getComputedStyle(tp).backgroundColor;
      tp.remove();
      const rows = Array.from(host.querySelectorAll('[data-todo-row]'));
      const sel = rows.find((r) => r.getAttribute('aria-current') === 'true');
      const prev = sel ? sel.style.background : '';
      if (sel) sel.style.background = 'rgba(0, 0, 0, 0)';
      const broken = {
        tint,
        rows: rows.map((r) => ({
          id: r.dataset.todoRow,
          current: r.getAttribute('aria-current'),
          bg: getComputedStyle(r).backgroundColor,
        })),
      };
      if (sel) sel.style.background = prev;
      return broken;
    })()`);
    check("反例自证：选中行底色被清成透明时判据必须翻红", !selectedOk(brokenSel),
      "翻红", JSON.stringify(brokenSel.rows));

    // hover 与选中必须是**两层不同的东西**：悬停一条**未选中**行 → 中性 tint；
    // 选中行底色不变（主色淡底不会被 hover 盖掉）。
    const unsel = sel0.rows.find((x) => x.current !== "true");
    const unselRect = unsel ? await cdp.eval(`(() => {
      const row = Array.from(document.querySelectorAll('#probe-host [data-todo-row]'))
        .find((r) => r.dataset.todoRow === '${unsel.id}');
      if (!row) return null;
      const r = row.getBoundingClientRect();
      return { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2) };
    })()`) : null;
    if (unselRect) {
      await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: unselRect.x, y: unselRect.y });
      await sleep(300);
    }
    const hov = await read();
    const hovUnsel = hov.rows.find((x) => x.id === (unsel && unsel.id));
    const hovSel = hov.rows.find((x) => x.current === "true");
    check("两栏（hover vs 选中）：hover 只给中性 tint，选中仍是主色淡底、两者不同",
      !!hovUnsel && !!hovSel && hovUnsel.bg !== "rgba(0, 0, 0, 0)"
        && hovUnsel.bg !== hov.tint && hovSel.bg === hov.tint,
      "悬停行=中性 tint / 选中行=淡底",
      JSON.stringify({ hover: hovUnsel && hovUnsel.bg, sel: hovSel && hovSel.bg, tint: hov.tint }));
    await cdp.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 2, y: 2 });
    await sleep(250);

    // 键盘 ↑/↓：按**屏幕顺序**移动一条，选中与右栏必须一起动。
    // 不假设初始选中哪一条（列表是异步落地的，选中会保留已可见的那条），只按当前 DOM 顺序算邻居。
    const keyOn = (id, key) => cdp.eval(`(() => {
      const row = Array.from(document.querySelectorAll('#probe-host [data-todo-row]'))
        .find((r) => r.dataset.todoRow === '${id}');
      const btn = row && row.querySelector('button');
      if (!btn) return false;
      btn.focus();
      btn.dispatchEvent(new KeyboardEvent('keydown', { key: '${key}', bubbles: true }));
      return true;
    })()`);
    const order = sel0.rows.map((x) => x.id);
    const selIdx = order.indexOf(sel0.rows.find((x) => x.current === "true")?.id);
    const key = selIdx < order.length - 1 ? "ArrowDown" : "ArrowUp";
    const wantId = order[key === "ArrowDown" ? selIdx + 1 : selIdx - 1];
    await keyOn(order[selIdx], key);
    await sleep(500);
    const kb = await read();
    const kbSel = kb.rows.find((x) => x.current === "true");
    const wantTitle = kb.rows.find((x) => x.id === wantId)?.title;
    check(`两栏（键盘 ${key === "ArrowDown" ? "↓" : "↑"}）：选中按屏幕顺序移动一条，右栏同步`,
      !!kbSel && kbSel.id === wantId && !!wantTitle && kb.detailText.includes(wantTitle),
      `${wantId} 选中 + 右栏=${wantTitle}`,
      JSON.stringify({ rows: kb.rows, detail: kb.detailText.slice(0, 40) }));
    // 反向再来一次：回到原来那条（证明不是"只会往前跳"）。
    await keyOn(wantId, key === "ArrowDown" ? "ArrowUp" : "ArrowDown");
    await sleep(500);
    const kbBack = await read();
    check("两栏（键盘反向）：选中回到上一条，右栏同步",
      kbBack.rows.find((x) => x.id === order[selIdx])?.current === "true"
        && kbBack.detailText.includes(kbBack.rows.find((x) => x.id === order[selIdx])?.title || "\u0000"),
      `${order[selIdx]} 选中 + 右栏同步`,
      JSON.stringify({ rows: kbBack.rows, detail: kbBack.detailText.slice(0, 40) }));

    // 筛选后原选中项不在结果里：必须回落，不许「右边有内容、左边没有对应行」。
    const clickTab = (key) => cdp.eval(`(() => {
      const tab = document.querySelector('#probe-host [role="tab"][data-filter="${key}"]');
      if (!tab) return false;
      tab.click();
      return true;
    })()`);
    await clickTab("all");
    await sleep(500);
    const clickedC = await cdp.eval(`(() => {
      const b = Array.from(document.querySelectorAll('#probe-host button.min-w-0.flex-1'))
        .find((x) => (x.textContent || '').includes('他建的'));
      if (b) b.click();
      return !!b;
    })()`);
    await sleep(500);
    const cSel = await read();
    check("两栏（全部）：点「他建的」后 C 行选中、右栏同步",
      clickedC && cSel.rows.find((x) => x.id === "C")?.current === "true"
        && cSel.detailText.includes("他建的"),
      "C 选中 + 右栏=他建的",
      JSON.stringify({ rows: cSel.rows, detail: cSel.detailText.slice(0, 40) }));
    await shot("taskpane-selected");
    await clickTab("mine");
    await sleep(600);
    const back = await read();
    const firstRow = back.rows[0];
    check("两栏（筛选回落）：C 被「我的」筛掉后回落到首行，左右不再错位",
      back.rows.length === 2 && !!firstRow && firstRow.current === "true"
        && !back.listText.includes("他建的") && !!firstRow.title
        && back.detailText.includes(firstRow.title),
      "首行选中 + 无 C + 右栏=首行标题",
      JSON.stringify({ ids: back.rows.map((x) => x.id), cur: back.rows.filter((x) => x.current === "true").map((x) => x.id), detail: back.detailText.slice(0, 40) }));

    // 窄窗回退：把宿主压到 680（窗口最小宽度以下是真实场景），右栏必须让位给单栏弹窗。
    await cdp.eval("document.querySelector('#probe-host').style.width = '680px'");
    await sleep(400);
    const narrow = await read();
    check("窄窗（680）：回退单栏，右栏不再占位",
      narrow.listW === 0 && !narrow.hasDetail,
      "list 无自身宽度 + 无右栏", JSON.stringify({ listW: narrow.listW, hasDetail: narrow.hasDetail }));
    // 宽窗自动落到第一条后，切窄会按"已有选中项"直接开弹窗 —— 先收掉，才能验"点行才开"。
    if (narrow.dialogs >= 1) {
      await cdp.send("Input.dispatchKeyEvent", { type: "keyDown", key: "Escape", code: "Escape", windowsVirtualKeyCode: 27 });
      await cdp.send("Input.dispatchKeyEvent", { type: "keyUp", key: "Escape", code: "Escape", windowsVirtualKeyCode: 27 });
      await sleep(400);
    }
    const clicked = await cdp.eval(`(() => {
      const b = Array.from(document.querySelectorAll('#probe-host button.min-w-0.flex-1'))
        .find((x) => (x.textContent || '').includes('写周报'));
      if (b) b.click();
      return !!b;
    })()`);
    await sleep(800);
    const narrowOpen = await read();
    check("窄窗（680）：点行仍打开原详情弹窗",
      clicked && narrowOpen.dialogs >= 1 && narrowOpen.dialogText.includes("写周报"),
      "clicked + >=1 dialog", JSON.stringify({ clicked, dialogs: narrowOpen.dialogs, rows: narrowOpen.rowTexts }));
    await shot("taskpane-680");
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

async function runInputPanels(cdp, url) {
  await cdp.send("Page.navigate", { url });
  await cdp.settled(); // 段间导航竞态收进活体探针（工具层，不动判据）
  await sleep(3_000);
  await cdp.eval(PAGE_FIXTURE);
  const props = JSON.stringify({
    convId: "group:input-panel",
    mentionMembers: [{ id: "p1", name: "小布" }, { id: "p2", name: "阿蓝" }],
  });
  const mounted = await cdp.eval("window.__probe.install('/src/components/chat/MessageComposer.vue', '', "
    + JSON.stringify(props) + ")");
  check("输入框挂得起来（两个浮层才有得量；挂不起来这一整段只能记未量）",
    !!mounted && mounted.ok === true, "install ok", JSON.stringify(mounted));

  await cdp.eval(`(() => {
    document.body.style.cssText = "margin:0;height:100vh;display:flex;flex-direction:column;justify-content:flex-end";
    const host = document.body.lastElementChild;
    if (host) host.style.flex = "none";
    return !!document.querySelector('.gosslan-composer');
  })()`);
  await sleep(400);
  const card = await cdp.eval(`(() => {
    const c = document.querySelector('.gosslan-composer');
    if (!c) return { ok: false };
    const r = c.getBoundingClientRect();
    return { ok: true, top: Math.round(r.top), bottom: Math.round(r.bottom), vh: window.innerHeight };
  })()`);
  check("宿主壳成立：输入卡片真的贴在视口底部（不贴底就没有「往上长」这回事，下面全部不作数）",
    !!card && card.ok === true && card.bottom <= card.vh + 2 && card.vh - card.bottom < 40,
    "bottom ≈ innerHeight", JSON.stringify(card));

  const pointOf = (key) => cdp.eval(`(async () => {
    const { t } = await import('/src/i18n/index.ts');
    const label = t(${JSON.stringify(key)});
    const b = Array.from(document.querySelectorAll('.gosslan-composer button'))
      .find((x) => x.getAttribute('aria-label') === label);
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2, top: Math.round(r.top) };
  })()`);
  const realClick = async (p) => {
    await cdp.send("Input.dispatchMouseEvent",
      { type: "mousePressed", x: p.x, y: p.y, button: "left", clickCount: 1 });
    await cdp.send("Input.dispatchMouseEvent",
      { type: "mouseReleased", x: p.x, y: p.y, button: "left", clickCount: 1 });
    await sleep(400);
  };

  // ── ① 表情面板 ──────────────────────────────────────────────
  const emojiBtn = await pointOf("chat.composer.emoji");
  check("那颗表情按钮找得到（按 i18n 的 aria-label 认，不写死中文串）",
    !!emojiBtn, "找得到一颗 button", JSON.stringify(emojiBtn));
  if (!emojiBtn) return;
  await realClick(emojiBtn);
  // Reka Popover 把面板 Portal 到 body（不再挂在输入卡片里），所以选择器要跟着走。
  // 这正是迁移要的：卡片以后加圆角/overflow 也裁不到面板。
  const SEL_DLG = '[data-composer-emoji] [role="dialog"]';
  const dlg = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_DLG) + ")");
  check("真点之后表情面板由 Reka Portal 挂到 body（不是还塞在输入卡片里）",
    !!dlg && dlg.ok === true && dlg.parentIsBody === true && dlg.escapes === true,
    "挂在 body 且没有应用祖先裁得到它",
    JSON.stringify(dlg && { why: dlg.why, parentIsBody: dlg.parentIsBody, escapes: dlg.escapes }));
  check("表情面板整个在视口内（往上长 ⇒ 上边缘才是真实风险，这条量的就是它）",
    !!dlg && dlg.ok === true && dlg.inViewport === true,
    "inViewport=true", JSON.stringify([dlg && dlg.rect, dlg && dlg.vh]));
  // ⚠️ 裁切这一条不能直接拿 floatLayer 的 clipped 原样判：这个应用是桌面壳，`body` 本来就写死
  // `overflow:hidden`，而输入框那两张面板是 **absolute**（不是那几族 Teleport 到 body 的 fixed），
  // 于是 body 一定会被算进裁切祖先 —— 那不是缺陷，是壳的形状。真正要判的是**中间那层卡片**
  // （输入框自己那张 `.gosslan-composer` 或它的包裹层）会不会把往上长的面板切掉。
  const shellRoot = (x) => x === "body" || x === "html" || String(x).startsWith("body:") || String(x).startsWith("html:");
  const dlgCutters = ((dlg && dlg.clipped) || []).filter((x) => !shellRoot(x));
  check("面板底边落在按钮顶边之上（bottom-full 那句真的生效），且没有**中间层**卡片裁得到它",
    !!dlg && dlg.ok === true && Number(dlg.rect.bo) <= emojiBtn.top + 2 && dlgCutters.length === 0,
    "panel.bottom ≤ 按钮 top 且非壳层裁切祖先为空",
    JSON.stringify([dlg && dlg.rect, emojiBtn.top, (dlg && dlg.clipped) || []])
    + "（壳层 body/html 已按上面的理由排除，排除前原样是这一串）");
  const hitDlg = await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_DLG)});
    if (!el) return null;
    const r = el.getBoundingClientRect();
    const top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
    return !!(top && el.contains(top));
  })()`);
  check("面板中心那一点归面板自己接（既不『看不见却接得住』，也不反过来被别层盖住）",
    hitDlg === true, "elementFromPoint 落在面板内部", "hit=" + hitDlg);

  // ★ 这条变异专门证「中间层裁切」这一型缺陷**只有这条判据看得见**：把 Reka 的
  // popper 层搬回输入卡片里、并给卡片 `overflow:hidden`（旧实现的真实形状）。
  // 注意此时面板的矩形与 inViewport **都不变**（它照样画在视口里、只是被祖先剪掉一块）⇒
  // 只判视口那条会放它过去。没有这一格，上面那条裁切判据等于没被证明会咬。
  await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_DLG)});
    if (!el) return false;
    const box = el.closest('[data-reka-popper-content-wrapper]') || el;
    const card = document.querySelector('.gosslan-composer');
    if (!card) return false;
    window.__emojiHome = { parent: box.parentElement, next: box.nextSibling,
      pos: box.style.position, transform: box.style.transform, left: box.style.left, top: box.style.top };
    card.style.overflow = "hidden";
    const h = box.getBoundingClientRect().height;
    box.style.position = "absolute";
    box.style.transform = "none";
    box.style.left = "0px";
    // 放到卡片顶边之上，让矩形留在视口里：这一格要证的是"被祖先裁"，不是"跑出视口"。
    box.style.top = (-h) + "px";
    card.appendChild(box);
    return true;
  })()`);
  const cut = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_DLG) + ")");
  const cutters = ((cut && cut.clipped) || []).filter((x) => !shellRoot(x));
  check("变异：把面板搬回输入卡片并 overflow:hidden ⇒ 中间层裁切必须被报出来（且 inViewport 仍为真 ⇒ 证明这条不是视口那条的别名）",
    !!cut && cut.ok === true && cutters.length > 0 && cut.inViewport === true,
    "非壳层裁切祖先 ≥ 1 且 inViewport 仍 true",
    JSON.stringify([cut && cut.clipped, cut && cut.inViewport, cut && cut.rect]));
  await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_DLG)});
    if (!el) return false;
    const box = el.closest('[data-reka-popper-content-wrapper]') || el;
    const h = window.__emojiHome;
    if (h && h.parent) h.parent.insertBefore(box, h.next);
    const card = document.querySelector('.gosslan-composer');
    if (card) card.style.removeProperty("overflow");
    if (h) { box.style.position = h.pos; box.style.transform = h.transform;
      box.style.left = h.left; box.style.top = h.top; }
    delete window.__emojiHome;
    return true;
  })()`);
  const cutBack = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_DLG) + ")");
  check("变异可逆：搬回 body 后裁切祖先回到只剩壳层（对照自己不留残留）",
    !!cutBack && ((cutBack.clipped) || []).filter((x) => !shellRoot(x)).length === 0,
    "非壳层裁切祖先为空", JSON.stringify(cutBack && cutBack.clipped));

  await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_DLG)});
    if (!el) return false;
    const box = el.closest('[data-reka-popper-content-wrapper]') || el;
    box._o = { left: box.style.left, top: box.style.top, transform: box.style.transform };
    box.style.left = "0px"; box.style.top = "180vh"; box.style.transform = "none";
    return true;
  })()`);
  const pushed = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_DLG) + ")");
  check("变异：把面板整块推到视口下方外 ⇒ inViewport 必须翻假（证明那条不是恒真）",
    !!pushed && pushed.ok === true && pushed.inViewport === false,
    "inViewport=false", JSON.stringify(pushed && pushed.rect));
  await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_DLG)});
    if (!el) return false;
    const box = el.closest('[data-reka-popper-content-wrapper]') || el;
    if (!box._o) return false;
    box.style.left = box._o.left; box.style.top = box._o.top;
    box.style.transform = box._o.transform; delete box._o;
    return true;
  })()`);
  const back = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_DLG) + ")");
  check("变异可逆：撤掉那两行内联样式后它又整个回到视口内（没把页面改坏一次）",
    !!back && back.ok === true && back.inViewport === true, "inViewport=true", JSON.stringify(back && back.rect));

  // 关掉表情面板，再走 @ 那一条（两层浮层不叠着：全局互斥那一族已经判过，这里只要干净起点）
  await realClick(emojiBtn);
  const closed = await cdp.eval(`!!document.querySelector(${JSON.stringify(SEL_DLG)})`);
  check("再点一次那颗按钮面板就收起（DOM 撤净，不留看不见的一层）",
    closed === false, "role=dialog 为 0 个", "还在=" + closed);

  // 选中一个表情：焦点必须回到编辑器，token 必须真的进了草稿。
  // 这条守的是 Reka Popover 的 closeAutoFocus 与 EmojiPicker 自己的焦点归还
  // 不再互相抢 —— 选完表情还要再点一下输入框才能接着打字，是肉眼很容易漏掉的回归。
  await realClick(emojiBtn);
  await sleep(250);
  const pick = await cdp.eval(`(() => {
    const b = document.querySelector('[data-emoji-panel] button');
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return { x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) };
  })()`);
  check("表情面板里拿得到一格真实表情的落点", !!pick, "格子非空", JSON.stringify(pick));
  if (pick) await realClick(pick);
  await sleep(300);
  const afterPick = await cdp.eval(`(() => {
    const ed = document.querySelector('.gosslan-composer [contenteditable="true"]');
    // ⚠️ token 现在是**图片节点**，不是「[名字]」文字：MessageComposer.createEmojiToken
    //    （2026-11-04 用户要求"输入框里直接看到表情本身"）把图形放进 <img>，[名字]
    //    只留在 data-emoji 上给发送回读；composerInteraction.test.ts 也钉着这条。
    //    旧判据读 innerText 找 "[" ⇒ 只剩 token 尾随的那个 nbsp，恒假红。
    const token = ed ? ed.querySelector('.emoji-token[data-emoji]') : null;
    return { focused: document.activeElement === ed, text: ed ? ed.innerText : null,
      token: token ? token.getAttribute('data-emoji') : null,
      open: !!document.querySelector('[data-emoji-panel]') };
  })()`);
  check("选完表情：面板收起、焦点回到编辑器、token 进了草稿（选完能直接接着打字）",
    afterPick.open === false && afterPick.focused === true
      && typeof afterPick.token === "string" && afterPick.token.trim() !== "",
    "open=false 且 activeElement=编辑器 且草稿里有 data-emoji 的 token", JSON.stringify(afterPick));
  await cdp.eval(`(() => { const ed = document.querySelector('.gosslan-composer [contenteditable="true"]');
    if (ed) { ed.innerHTML = ''; ed.dispatchEvent(new InputEvent('input', { bubbles: true })); } })()`);

  // ── ② @ 候选列表 ────────────────────────────────────────────
  const edPoint = await cdp.eval(`(() => {
    const e = document.querySelector('.gosslan-composer [contenteditable="true"]')
      || document.querySelector('.gosslan-composer [data-focus-ring-ok]');
    if (!e) return null;
    const r = e.getBoundingClientRect();
    return { x: r.x + Math.min(24, r.width / 2), y: r.y + r.height / 2 };
  })()`);
  check("编辑器找得到（真点击才能把 caret 放进去，eval 里 focus() 不算真焦点）",
    !!edPoint, "找得到可编辑区", JSON.stringify(edPoint));
  if (!edPoint) return;
  await realClick(edPoint);
  await cdp.eval("window.__probe.reset()");
  await cdp.send("Input.insertText", { text: "@" });
  await sleep(500);
  const SEL_LIST = '.gosslan-composer .frost:not([role="dialog"])';
  const lst = await cdp.eval("window.__probe.floatLayer(" + JSON.stringify(SEL_LIST) + ")");
  check("真输入一个 @ 就浮出候选列表（走的是组件自己的 input 事件，不是我们把状态摆好）",
    !!lst && lst.ok === true, "列表挂载", JSON.stringify(lst && lst.why));
  const rows = await cdp.eval(`(() => {
    const el = document.querySelector(${JSON.stringify(SEL_LIST)});
    return el ? el.querySelectorAll("button").length : -1;
  })()`);
  check("列表里真的列出了成员（>0；名单来自 props，不是夹具自己塞的 DOM）",
    Number(rows) > 0, ">0 行", "rows=" + rows);
  check("候选列表整个在视口内，且长在卡片上方（和表情面板同一个往上长的方向）",
    !!lst && lst.ok === true && lst.inViewport === true && Number(lst.rect.bo) <= card.top + 2,
    "inViewport 且 list.bottom ≤ 卡片 top", JSON.stringify([lst && lst.rect, card.top]));

  // 对照：换一个普通字符 ⇒ 列表必须不出现（没有这一格，上面三条可以由"列表一直在"冒充）
  await cdp.eval(`(() => {
    const e = document.querySelector('.gosslan-composer [contenteditable="true"]')
      || document.querySelector('.gosslan-composer [data-focus-ring-ok]');
    if (e) { e.innerHTML = ""; e.dispatchEvent(new InputEvent("input", { bubbles: true })); }
  })()`);
  await cdp.send("Input.insertText", { text: "x" });
  await sleep(450);
  const noList = await cdp.eval(`!!document.querySelector(${JSON.stringify(SEL_LIST)})`);
  check("对照：把 @ 换成普通字符 ⇒ 候选列表必须不出现（证明那三条不是恒真）",
    noList === false, "列表为 0 个", "还在=" + noList);

  // 键盘出口 + 载荷：重新输入 @ → ArrowDown → Enter 选中 → 回车发送 ⇒ 读 send 的 mentionIds
  await cdp.eval(`(() => {
    const e = document.querySelector('.gosslan-composer [contenteditable="true"]')
      || document.querySelector('.gosslan-composer [data-focus-ring-ok]');
    if (e) { e.innerHTML = ""; e.dispatchEvent(new InputEvent("input", { bubbles: true })); }
  })()`);
  await realClick(edPoint);
  await cdp.send("Input.insertText", { text: "@小" });
  await sleep(450);
  await cdp.key("ArrowDown", "ArrowDown", "", 40);
  await cdp.key("Enter", "Enter", "\r", 13);
  await sleep(500);
  const token = await cdp.eval(`(() => {
    const tk = document.querySelector('.gosslan-composer .mention-token[data-mention-id]');
    return tk ? tk.getAttribute("data-mention-id") : null;
  })()`);
  check("方向键 + 回车真的选中了那一条：编辑器里落下带 data-mention-id 的 token",
    typeof token === "string" && token.length > 0, "一个带 id 的 token", "token=" + JSON.stringify(token));
  await cdp.key("Enter", "Enter", "\r", 13);
  await sleep(500);
  const sent = await cdp.eval(`(() => {
    const s = (window.__probe.events || []).filter((e) => e[0] === "send");
    return s.length ? JSON.parse(s[s.length - 1][1]) : null;
  })()`);
  check("再按一次回车把这条发出去，载荷里的 mentionIds 认得那个 id（DOM 上只有 token，名单在载荷里）",
    !!sent && Array.isArray(sent.mentionIds) && sent.mentionIds.length > 0,
    "send 载荷带 mentionIds", JSON.stringify(sent));
  check("发出去之后输入框清空、候选列表不残留（同一次动作的两半，不许只做成一半）",
    await cdp.eval(`(() => {
      const e = document.querySelector('.gosslan-composer [contenteditable="true"]')
        || document.querySelector('.gosslan-composer [data-focus-ring-ok]');
      return !!(e && !e.textContent.trim()) && !document.querySelector(${JSON.stringify(SEL_LIST)});
    })()`) === true, "编辑器空、列表不在", "读到的仍是残留");

  // 鼠标出口：点击「发送」按钮也必须真的 emit。此前探针只走过 Enter，
  // 而按钮上有 `@mousedown.prevent`（保持编辑器焦点）；这条单独证明那个 prevent
  // 没有顺带把 click 吃掉。
  await cdp.eval("window.__probe.reset()");
  await realClick(edPoint);
  await cdp.send("Input.insertText", { text: "按钮发送" });
  await sleep(300);
  const sendBtn = await cdp.eval(`(async () => {
    const { t } = await import('/src/i18n/index.ts');
    const label = t("common.send");
    const b = Array.from(document.querySelectorAll('.gosslan-composer button'))
      .find((x) => (x.textContent || '').trim() === label);
    if (!b) return null;
    const r = b.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2, disabled: !!b.disabled };
  })()`);
  if (sendBtn) await realClick(sendBtn);
  const clickSent = await cdp.eval(`(window.__probe.events || []).filter((e) => e[0] === "send").length`);
  check("真点『发送』按钮也 emit send（不是只有回车这一条出口；mousedown.prevent 不许吃掉 click）",
    !!sendBtn && sendBtn.disabled === false && clickSent > 0,
    "按钮可用且 send 事件 ≥1", JSON.stringify({ sendBtn, clickSent }));

  // ★ 补 §6.73 自己登记的那格覆盖空洞：`MessageComposer` 那条 document click 已经交给
  //   `useEventListener`，但**此前没有任何一条断言判它**。这条判"点开 @ 名单之后，点输入卡片之外 ⇒ 名单收起"，
  //   并且同时钉住"编辑器里那个 @ 还在"——只有 mention 状态被清、草稿没被动，才是这条监听干的；
  //   清空草稿的是发送那条路（上面刚验过），两件事分得开。
  await cdp.eval("window.__probe.reset()");
  await realClick(edPoint);
  await cdp.send("Input.insertText", { text: "@" });
  await sleep(500);
  const openedAgain = await cdp.eval(`!!document.querySelector(${JSON.stringify(SEL_LIST)})`);
  // 视口左上角：离贴底那张卡片最远，一定落在 `.gosslan-composer` 之外。
  await realClick({ x: 24, y: 24 });
  const outsideClick = await cdp.eval(`(() => {
    const e = document.querySelector('.gosslan-composer [contenteditable="true"]')
      || document.querySelector('.gosslan-composer [data-focus-ring-ok]');
    return { list: !!document.querySelector(${JSON.stringify(SEL_LIST)}), draft: e ? e.textContent : null };
  })()`);
  check("点输入卡片之外 ⇒ @ 候选列表收起而草稿里那个 @ 还在（这条走的是已交给 useEventListener 的 document click，不是发送那条清空路）",
    openedAgain === true && outsideClick.list === false && typeof outsideClick.draft === "string"
      && outsideClick.draft.includes("@"),
    "开 → 点外 → 关，且草稿含 @", JSON.stringify({ openedAgain, outsideClick }));
}


/**
 * ③ 预览图不许被切割（2026-11-07）。
 *
 * 用户报「预览状态图片四角是黑的」。判据全部走运行时，不读 CSS 源码：
 *  1. 预览图的 `border-radius` 必须是 0、`object-fit` 必须是 `contain`；
 *  2. 从图片到 `data-lightbox-stage` 之间不许出现任何 `overflow != visible` 的祖先；
 *  3. 图片矩形四角用 `elementFromPoint` 命中图片本身（被遮住/裁掉就命中别人）；
 *  4. 图片四周安全边距 ≥ 8px；
 *  5. 反面对照：给 stage 加 `overflow:hidden` + 给图片加 18px 圆角 ⇒ 上面 1/2 必须真的红。
 *
 * 用带四角标记的 SVG data URL：四角各一块纯红方块，长宽比 4:3（不是 1:1），
 * 这样 `cover` 一裁就会把左右两块切掉，肉眼和截图都能看出来。
 */
async function runPreviewClip(cdp, url) {
  const shotDir = path.join(ROOT, "test-results", "ui-2026-11-07");
  fs.mkdirSync(shotDir, { recursive: true });
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 980, height: 700, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});

  const svg = [
    '<svg xmlns="http://www.w3.org/2000/svg" width="400" height="300">',
    '<rect width="400" height="300" fill="#ffffff"/>',
    '<rect x="0" y="0" width="56" height="56" fill="#ff0000"/>',
    '<rect x="344" y="0" width="56" height="56" fill="#00ff00"/>',
    '<rect x="0" y="244" width="56" height="56" fill="#0000ff"/>',
    '<rect x="344" y="244" width="56" height="56" fill="#ff00ff"/>',
    '<text x="200" y="160" font-size="28" text-anchor="middle" fill="#111">preview 400x300</text>',
    "</svg>",
  ].join("");
  const dataUrl = "data:image/svg+xml;base64," + Buffer.from(svg).toString("base64");

  const READ = `(() => {
    const img = document.querySelector('[data-lightbox-img]');
    const stage = document.querySelector('[data-lightbox-stage]');
    if (!img || !stage) return null;
    const cs = getComputedStyle(img);
    const r = img.getBoundingClientRect();
    const clipping = [];
    let el = img.parentElement;
    while (el && el !== document.body) {
      const c = getComputedStyle(el);
      const ov = [c.overflow, c.overflowX, c.overflowY].join('/');
      if (!/visible\\/visible\\/visible/.test(ov)) clipping.push(el.tagName + '.' + (el.className || '').toString().slice(0, 40) + ' → ' + ov);
      el = el.parentElement;
    }
    const pts = [[r.left + 3, r.top + 3], [r.right - 3, r.top + 3], [r.left + 3, r.bottom - 3], [r.right - 3, r.bottom - 3]];
    const hits = pts.map(([x, y]) => {
      const e = document.elementFromPoint(x, y);
      return e && e === img ? 'img' : (e ? e.tagName + '.' + String(e.className || '').slice(0, 30) : 'none');
    });
    return {
      radius: cs.borderRadius,
      objectFit: cs.objectFit,
      box: { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1) },
      natural: [img.naturalWidth, img.naturalHeight],
      margin: {
        left: +(r.left).toFixed(1), top: +(r.top).toFixed(1),
        right: +(innerWidth - r.right).toFixed(1), bottom: +(innerHeight - r.bottom).toFixed(1),
      },
      clipping, cornerHit: hits,
      stageOverflow: getComputedStyle(stage).overflow,
    };
  })()`;

  const setDark = async (dark) => {
    await cdp.eval(`(() => { document.documentElement.classList.toggle('dark', ${dark}); return true; })()`);
    await sleep(400);
  };
  const shot = async (name) => {
    const s = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(shotDir, name + ".png"), Buffer.from(s.data, "base64"));
  };
  const mount = async () => {
    const props = {
      images: [{ name: "corner.svg", dataSrc: dataUrl }],
      index: 0,
      open: true,
    };
    return cdp.eval("window.__probe.install('/src/components/message/ImageLightbox.vue', '', "
      + JSON.stringify(JSON.stringify(props)) + ")");
  };

  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    const installed = await mount();
    await sleep(1_400);
    if (!installed || installed.ok !== true) {
      check("灯箱挂得起来（预览不裁切判据的前置）", false, "install ok", JSON.stringify(installed));
      return;
    }

    const rows = [];
    for (const dark of [false, true]) {
      await setDark(dark);
      await sleep(400);
      const r = await cdp.eval(READ);
      await shot(`previewclip-${dark ? "dark" : "light"}`);
      rows.push({ dark, r });
    }
    console.log("  ℹ 预览图读数：" + JSON.stringify(rows.map((x) => ({ dark: x.dark, ...x.r }))));

    check("预览图：border-radius = 0 且 object-fit = contain（亮/暗两套）",
      rows.every((x) => x.r && (x.r.radius === "0px" || x.r.radius === "0")
        && x.r.objectFit === "contain"),
      "radius 0 / contain", JSON.stringify(rows.map((x) => [x.r?.radius, x.r?.objectFit])));

    check("预览图：到 stage 之间没有任何 overflow 裁切祖先",
      rows.every((x) => x.r && x.r.clipping.length === 0),
      "clipping = []", JSON.stringify(rows.map((x) => x.r?.clipping)));

    check("预览图：四角 elementFromPoint 都必须命中图片本身（被遮/被裁就命中别的）",
      rows.every((x) => x.r && x.r.cornerHit.every((h) => h === "img")),
      "4/4 命中 img", JSON.stringify(rows.map((x) => x.r?.cornerHit)));

    check("预览图：四周安全边距 ≥ 8px，且原图 400×300 完整落在视口内",
      rows.every((x) => x.r && Math.min(x.r.margin.left, x.r.margin.top, x.r.margin.right, x.r.margin.bottom) >= 8
        && x.r.natural[0] === 400 && x.r.natural[1] === 300),
      "min margin >= 8px 且 natural 400x300", JSON.stringify(rows.map((x) => [x.r?.margin, x.r?.natural])));

    // 反面对照：stage 加 overflow:hidden、图片加 18px 圆角 —— 读数必须真的变坏。
    await cdp.eval(`(() => {
      const img = document.querySelector('[data-lightbox-img]');
      const stage = document.querySelector('[data-lightbox-stage]');
      if (img) img.style.borderRadius = '18px';
      if (stage) stage.style.overflow = 'hidden';
      return true;
    })()`);
    await sleep(400);
    const broken = await cdp.eval(READ);
    console.log("  ℹ 反面对照读数：" + JSON.stringify(broken));
    check("反面对照：stage 加 overflow:hidden + 图片加 18px 圆角后，radius 与裁剪祖先必须双双变坏",
      !!broken && broken.radius !== "0px" && broken.clipping.length > 0,
      "radius != 0 且 clipping 非空",
      JSON.stringify(broken && { radius: broken.radius, clipping: broken.clipping }));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * ⑦（合并版，2026-11-07，第三次按像素重写）：**滚动条出现/消失不许改变内容宽度**。
 *
 * 用户第三次报同一症状：「关于」那个分区的页边距比上面带滚动条的分区小。
 * WKWebView 实测（设置窗口默认 780×600）：
 *   会滚分区 card 216..764（clientW 572 / offsetW 580）；不滚分区 card 208..772（clientW 580）。
 * 根因不在 padding：WKWebView **只在真的出现滚动条时**才兑现 `scrollbar-gutter: stable both-edges`；
 * 不滚的分区两侧 gutter 一个像素都没有 ⇒ 比标题竖线（`--gosslan-scroll-inset`）各宽 8px。
 * Chromium 会无条件下预留，所以这条差异在 Chromium 上看不见 —— 前几轮"声明存在"的判据因此全绿。
 *
 * 修法：共享容器的滚动条**常驻**（`overflow-y-scroll`），两类分区走同一档几何。
 *
 * 判据分四层（全部运行时，不读 CSS 源码）：
 *  1. 同一设置窗口里切「通用」（会滚）与「关于」（不滚）：内容盒宽 / 卡片 x / 文字起始 x 相等；
 *  2. 卡片**左/右缘**必须与标题那条竖线逐像素相等，且两分区之间也相等（阈值 0，不是 0.5/1px）；
 *  3. 共享容器 computed `overflow-y` 必须是 `scroll`（常驻轨道）；反例改回 `auto` 读数必须真的变成 auto；
 *  4. 反面对照：把 `scrollbar-gutter` 改成 `auto`（等价于"没有两侧预留"），跨临界点必须真的差 ≥7px。
 *
 * 亮/暗各一套。**引擎边界**：Chromium 里 `auto` 与 `scroll` 的几何完全相同（第 3 层的反例只能
 * 证明"读数跟着真实 computed 值走"）；真实的 WKWebView 几何用 `scripts/probes/settings-gutter-wk.swift`
 * 单独量（macOS only），那边的 208..772 → 216..764 是本条缺陷的直接证据。
 *
 * 其余滚动面（日志 / 群任务 / 会话列表 / 搜索 / 收藏 / 转发 / 群成员 / 各类弹窗）共用
 * 同一组规范类（`.overflow-y-auto` + `.gosslan-scroll` / `.scrollbar-both`），静态守卫 SC-01 逐个文件钉住；
 * 本段再把"规范类在两种状态下宽度不变"用一份合成夹具量一遍，避免只靠类名推断。
 */
async function runScrollStable(cdp, url) {
  const shotDir = path.join(ROOT, "test-results", "ui-2026-11-07");
  fs.mkdirSync(shotDir, { recursive: true });
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});

  /** 读"右栏滚动容器"的几何：内容盒宽、卡片 x、文字起始 x、以及滚动条自身宽度。 */
  const READ = `(() => {
    const s = [...document.querySelectorAll('div')].find((el) => {
      const c = String(el.className || '');
      const isPanelScroll = c.includes('gosslan-scroll') || c.includes('scrollbar-both');
      // 2026-11-07：设置窗口的滚动容器改成**常驻轨道**（overflow-y-scroll）之后，
      // 这里必须两种都认；只认 auto 会让整段找不到容器 ⇒ 静默空转。
      const hasScroll = c.includes('overflow-y-auto') || c.includes('overflow-y-scroll');
      return isPanelScroll && hasScroll && el.getClientRects().length > 0;
    });
    if (!s) return null;
    const cs = getComputedStyle(s);
    const rectOf = (el) => { if (!el) return null; const b = el.getBoundingClientRect();
      return { x: +b.x.toFixed(2), w: +b.width.toFixed(2), r: +b.right.toFixed(2) }; };
    const visible = [...s.querySelectorAll('*')].filter((el) => el.getClientRects().length > 0);
    const card = visible.find((el) => {
      const c = String(el.className || '');
      return (c.includes('rounded-') || c.includes('settings-group')) && el.querySelector('span, p, label, input, button');
    });
    const textEl = visible.find((el) => {
      const tag = el.tagName.toLowerCase();
      if (!/^(span|p|h2|label)$/.test(tag)) return false;
      return (el.textContent || '').trim().length > 0 && !el.children.length;
    });
    return {
      gutter: cs.scrollbarGutter,
      overflowY: cs.overflowY,
      padL: cs.paddingLeft, padR: cs.paddingRight,
      offW: +s.offsetWidth.toFixed(2), clientW: +s.clientWidth.toFixed(2),
      barW: +(s.offsetWidth - s.clientWidth).toFixed(2),
      scrollH: s.scrollHeight, clientH: s.clientHeight,
      canScroll: s.scrollHeight > s.clientHeight + 1,
      card: rectOf(card), text: rectOf(textEl),
      // 标题（header h2）走 px-[var(--gosslan-scroll-inset)]，是内容页"那条竖线"的基准；
      // 卡片的左右缘必须与它逐像素相等 —— 这才是用户说的"看起来一致"。
      header: rectOf(s.parentElement ? s.parentElement.querySelector('h2') : null),
      textTxt: textEl ? (textEl.textContent || '').trim().slice(0, 16) : null,
    };
  })()`;

  /** 合成夹具：同一组规范类，内容高 = 可滚 / 不可滚两档，量内容盒宽与居中偏移。 */
  const CANON = `(() => {
    const mk = (id, tall, gutter) => {
      const wrap = document.createElement('div');
      wrap.setAttribute('data-canon', id);
      wrap.style.cssText = 'position:fixed;left:0;top:0;width:320px;height:180px;';
      const s = document.createElement('div');
      s.className = 'overflow-y-auto scrollbar-both';
      s.style.cssText = 'box-sizing:border-box;width:320px;height:180px;padding:0 20px;background:#fff;';
      if (gutter) s.style.scrollbarGutter = gutter;
      const inner = document.createElement('div');
      inner.style.height = tall ? '900px' : '60px';
      inner.textContent = id;
      s.appendChild(inner);
      wrap.appendChild(s);
      document.body.appendChild(wrap);
      const cs = getComputedStyle(s);
      return {
        id,
        gutter: cs.scrollbarGutter,
        clientW: +s.clientWidth.toFixed(2),
        barW: +(s.offsetWidth - s.clientWidth).toFixed(2),
        innerW: +inner.getBoundingClientRect().width.toFixed(2),
        innerX: +inner.getBoundingClientRect().x.toFixed(2),
        canScroll: s.scrollHeight > s.clientHeight + 1,
      };
    };
    const a = mk('tall', true, '');
    const b = mk('short', false, '');
    const c = mk('short-auto', false, 'auto');
    const d = mk('tall-auto', true, 'auto');
    // ⑤ .gosslan-scroll（14 个内容页统一消费的那一档）：量「控件右缘 ↔ 滚动条带左缘」的固定空隙，
    //    并当场把 padding-inline 清零，证明这条读数有牙（0 与 8 是可区分的两个数）。
    const mkG = () => {
      const wrap = document.createElement('div');
      wrap.setAttribute('data-canon', 'gosslan');
      wrap.style.cssText = 'position:fixed;left:0;top:200px;width:320px;height:180px;';
      const s = document.createElement('div');
      s.className = 'gosslan-scroll overflow-y-auto';
      s.style.cssText = 'box-sizing:border-box;width:320px;height:180px;background:#fff;';
      const inner = document.createElement('div');
      inner.style.height = '900px';
      s.appendChild(inner);
      wrap.appendChild(s);
      document.body.appendChild(wrap);
      const cs = getComputedStyle(s);
      const sr = s.getBoundingClientRect();
      const barW = +(s.offsetWidth - s.clientWidth).toFixed(2); // both-edges ⇒ 两侧合计
      const trackW = barW / 2;
      const gap = () => +(sr.right - trackW - inner.getBoundingClientRect().right).toFixed(2);
      const gapL = () => +(inner.getBoundingClientRect().left - sr.left - trackW).toFixed(2);
      const withPad = { gapR: gap(), gapL: gapL() };
      s.style.paddingInline = '0px';
      const noPad = { gapR: gap(), gapL: gapL() };
      s.style.paddingInline = '';
      return {
        id: 'gosslan',
        padL: +(parseFloat(cs.paddingLeft) || 0).toFixed(2),
        padR: +(parseFloat(cs.paddingRight) || 0).toFixed(2),
        barW, trackW: +trackW.toFixed(2),
        gapR: withPad.gapR, gapL: withPad.gapL,
        noPadR: noPad.gapR,
      };
    };
    const g = mkG();
    // 只拆自己建的五个 wrap（绝不许动 #probe-host —— 里面挂着设置窗口）
    for (const el of [...document.querySelectorAll('[data-canon]')]) el.remove();
    return { a, b, c, d, g };
  })()`;

  const nav = async (key) => {
    await cdp.eval(`(async () => {
      const R = await import('/src/router/main.ts');
      await R.mainRouter.push({ name: 'settings-section', params: { key: ${JSON.stringify(key)} } });
      await new Promise((r) => setTimeout(r, 800));
      return true;
    })()`);
    await sleep(700);
  };
  const setHeight = async (h) => {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: 980, height: h, deviceScaleFactor: 1, mobile: false,
    }).catch(() => {});
    await sleep(700);
  };
  const setDark = async (dark) => {
    await cdp.eval(`(() => { document.documentElement.classList.toggle('dark', ${dark}); return true; })()`);
    await sleep(400);
  };
  const shot = async (name) => {
    const s = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(shotDir, name + ".png"), Buffer.from(s.data, "base64"));
  };

  try {
    await setHeight(700);
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    const mounted = await cdp.eval("window.__probe.install('/src/components/SettingsWindow.vue', '', "
      + JSON.stringify(JSON.stringify({ router: true, hostHeight: "700px" })) + ")");
    await sleep(900);
    if (!mounted || mounted.ok !== true) {
      check("设置独立窗口挂得起来（滚动宽度那条判据的前置）", false, "install ok", JSON.stringify(mounted));
      return;
    }

    // 规范类合成夹具（独立于设置窗口）：先量一次，后面两条判据共用这份读数。
    const canon = await cdp.eval(CANON);
    console.log("  ℹ 规范类合成夹具（可滚/不可滚 + 去掉 gutter 的反面）：" + JSON.stringify(canon));

    // 「关于」内容（安全 + 关于 + 更新卡）比一般窗口还高，必须放到足够高的视口才有"不滚"那一档
    // （实测 1100 仍会滚 ⇒ 不是窗口不够高，是内容真的长；2200 下 clientH ~2065 > scrollH 1619）。
    const TALL_H = 2200;
    const rows = [];
    for (const dark of [false, true]) {
      await setDark(dark);
      // ① 三类分区、同一窗口、同一容器、同一宽度：
      //   「通用」（默认高度下是否溢出随内容而定）/「网络」（一定溢出 ⇒ 用户说的"上面带滚动条的那块很正常"）
      //   /「关于」（默认高度下不滚 ⇒ 用户报的那块）。x 只取决于容器内缩，与视口高度无关。
      await nav("general");
      await setHeight(700);
      const gen = await cdp.eval(READ);
      await nav("about");
      await setHeight(TALL_H);
      const about = await cdp.eval(READ);
      await nav("network");
      await setHeight(700);
      const net = await cdp.eval(READ);
      // ② 反面对照：回到"不滚"那一档（关于 @700），把预留策略改成 auto。
      const setGutter = async (v) => cdp.eval(`(() => {
        const s = [...document.querySelectorAll('div')].find((el) => {
          const c = String(el.className || '');
          const isPanelScroll = c.includes('gosslan-scroll') || c.includes('scrollbar-both');
          const hasScroll = c.includes('overflow-y-auto') || c.includes('overflow-y-scroll');
          return isPanelScroll && hasScroll && el.getClientRects().length > 0;
        });
        if (s) s.style.scrollbarGutter = ${JSON.stringify(v)};
        return !!s;
      })()`);
      await nav("about");
      await setHeight(700);
      await setGutter("auto");
      const counter = await cdp.eval(READ);
      await setGutter("");
      await setHeight(TALL_H);
      // 反面对照 ②：把"常驻轨道"改回 `auto`。Chromium 里 auto+stable both-edges 的几何与 scroll
      // 完全相同（这正是这条 bug 在 Chromium 上看不出来的原因），所以这里只能证明**读数跟着
      // 真实 computed 值走**：改回 auto 后 overflowY 必须真的读成 auto，否则那条判据读的是常量。
      const setOverflowY = async (v) => cdp.eval(`(() => {
        const s = [...document.querySelectorAll('div')].find((el) => {
          const c = String(el.className || '');
          const hasScroll = c.includes('overflow-y-auto') || c.includes('overflow-y-scroll');
          return (c.includes('gosslan-scroll') || c.includes('scrollbar-both')) && hasScroll
            && el.getClientRects().length > 0;
        });
        if (s) s.style.overflowY = ${JSON.stringify(v)};
        return !!s;
      })()`);
      await setOverflowY("auto");
      const overflowAuto = await cdp.eval(READ);
      await setOverflowY("");
      await setHeight(TALL_H);
      const counterDeltaW = (about && counter && typeof about.clientW === "number"
        && typeof counter.clientW === "number") ? +(about.clientW - counter.clientW).toFixed(2) : null;
      rows.push({ dark, gen, about, net, counter, counterDeltaW, overflowAuto });

      // 截图各取"该档真实样子"：通用 700（滚动条在）、关于 2200（内容不滚，但轨道常驻）。
      await nav("general");
      await setHeight(700);
      await shot(`scrollstable-${dark ? "dark" : "light"}-general`);
      await nav("about");
      await setHeight(TALL_H);
      await shot(`scrollstable-${dark ? "dark" : "light"}-about`);
    }

    const d = (a, b, k) => (a && b && typeof a[k] === "number" && typeof b[k] === "number"
      ? +(a[k] - b[k]).toFixed(2) : null);
    const out = rows.map((r) => ({
      dark: r.dark,
      clientW: [r.gen?.clientW, r.about?.clientW],
      overflowY: [r.gen?.overflowY, r.about?.overflowY],
      card: { gen: r.gen?.card, about: r.about?.card },
      header: { gen: r.gen?.header, about: r.about?.header },
      textX: [r.gen?.text?.x, r.about?.text?.x],
      barW: [r.gen?.barW, r.about?.barW],
      canScroll: [r.gen?.canScroll, r.about?.canScroll],
      h: { gen: [r.gen?.scrollH, r.gen?.clientH], about: [r.about?.scrollH, r.about?.clientH] },
      narrow: {
        netCanScroll: r.net?.canScroll,
        clientW: [r.net?.clientW, r.about?.clientW],
        cardX: [r.net?.card?.x, r.about?.card?.x],
        cardR: [r.net?.card?.r, r.about?.card?.r],
      },
      counter: r.counter ? {
        canScroll: r.counter.canScroll, barW: r.counter.barW, gutter: r.counter.gutter,
        deltaW: r.counterDeltaW,
      } : null,
      overflowAuto: r.overflowAuto ? { overflowY: r.overflowAuto.overflowY, barW: r.overflowAuto.barW } : null,
    }));
    console.log("  ℹ 滚动宽度读数（设置独立窗口）：" + JSON.stringify(out));

    check("设置窗口：会滚的「通用」与不滚的「关于」内容盒宽逐像素相等（亮/暗两套）",
      rows.every((r) => r.gen && r.about && r.about.canScroll === false
        && Math.abs(r.gen.clientW - r.about.clientW) <= 0.5),
      "「关于」不滚且两者 clientWidth 差 <= 0.5px", JSON.stringify(out.map((o) => o.clientW)));

    // 2026-11-07（用户第三次报，按像素结案）：卡片**左/右边缘**必须与标题那条竖线、
    // 以及与另一个分区**完全相同**（阈值 0，不许 0.5/1px 的模糊档）。这条是"看起来一致"的
    // 直接读数 —— 用户说的不是盒子宽，而是卡片离窗口两边的留白。
    check("设置窗口：两类分区的卡片左/右缘与标题竖线逐像素相等（阈值 0）",
      rows.every((r) => {
        const ps = [r.gen, r.about];
        return ps.every((p) => p && p.card && p.header
          && d(p.card, p.header, "x") === 0 && d(p.card, p.header, "r") === 0)
          && d(r.gen?.card, r.about?.card, "x") === 0
          && d(r.gen?.card, r.about?.card, "r") === 0;
      }),
      "card.x === header.x 且 card.right === header.right，两分区亦相同（0px）",
      JSON.stringify(out.map((o) => ({ card: o.card, header: o.header }))));

    // 常驻轨道：无论当前分区滚不滚，容器都必须已经"有滚动条"（`overflow-y: scroll`）。
    // 为什么必须是常驻：WKWebView 只在真的出现滚动条时才兑现 `stable both-edges` 的两侧预留，
    // 不滚的分区因此比会滚的分区各宽 8px（Chromium 会无条件下预留 ⇒ 这条 bug 只在 WKWebView 出现）。
    check("设置窗口：共享滚动容器常驻轨道（computed overflow-y === scroll），两类分区同一档",
      rows.every((r) => r.gen?.overflowY === "scroll" && r.about?.overflowY === "scroll"),
      "gen/about 的 computed overflow-y 都是 scroll", JSON.stringify(out.map((o) => o.overflowY)));

    check("反面对照：把常驻轨道改回 auto，读数必须真的变成 auto（否则上面那条读的是常量）",
      rows.every((r) => r.overflowAuto?.overflowY === "auto"),
      "改回 auto 后 computed overflow-y === auto", JSON.stringify(out.map((o) => o.overflowAuto)));

    check("设置窗口：「通用」与「关于」的文字起始 x 相等（不是只量盒子）",
      rows.every((r) => r.gen?.text && r.about?.text && Math.abs(r.gen.text.x - r.about.text.x) <= 1),
      "文字起始 x 差 <= 1px", JSON.stringify(out.map((o) => o.textX)));

    // 第三个分区（网络）与「关于」逐像素对账：`canScroll` 在探针环境里可能为 false（探针没有
    // Tauri 数据，内容比真机短），所以这里只断言几何 —— 真机"会滚/不滚"这一对的像素证明在
    // `scripts/probes/settings-gutter-wk.swift`（WKWebView，780×600：网络 216..764 / 关于修前 208..772）。
    check("设置窗口：另一个分区（网络）与「关于」卡片左/右缘、内容盒宽逐像素相等（0px）",
      rows.every((r) => r.net && r.about
        && r.net.clientW === r.about.clientW
        && d(r.net.card, r.about.card, "x") === 0
        && d(r.net.card, r.about.card, "r") === 0),
      "net/about 的 clientW / card.x / card.right 全为 0px 差",
      JSON.stringify(out.map((o) => o.narrow)));

    check("反面对照：去掉 scrollbar-gutter 预留后，不滚的分区必须真的变宽（≥ 7px），否则量具恒绿",
      rows.every((r) => r.counter && typeof r.counterDeltaW === "number"
        && Math.abs(r.counterDeltaW) >= 7),
      "|deltaW| >= 7px", JSON.stringify(out.map((o) => o.counter)));

    check("规范类合成夹具：.scrollbar-both 可滚/不可滚两档内容宽相等；改成 auto 后必须出现 ≥7px 差值",
      !!canon && canon.a && canon.b && canon.c && canon.d
        && canon.a.canScroll === true && canon.b.canScroll === false
        && Math.abs(canon.a.innerW - canon.b.innerW) <= 0.5
        && Math.abs(canon.a.innerX - canon.b.innerX) <= 0.5
        && Math.abs(canon.c.innerW - canon.d.innerW) >= 7,
      "tall/short 内容宽与 x 差 <= 0.5px；auto 档差 >= 7px", JSON.stringify(canon));

    check("规范类合成夹具：`.gosslan-scroll` 控件与滚动条带之间左右各留 8px（不是贴边）",
      !!(canon && canon.g) && canon.g.barW === 16 && canon.g.trackW === 8
        && canon.g.padL === 8 && canon.g.padR === 8
        && canon.g.gapR === 8 && canon.g.gapL === 8
        && canon.g.noPadR === 0,
      "gapL = gapR = 8px，且 padding 清零后 gapR = 0（这条读数有牙）", JSON.stringify(canon && canon.g));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

/**
 * ④ 悬浮输入区：输入卡与消息区必须是**同一整块画布**（2026-11-07 用户口径）。
 *
 * 外壳 `absolute + bg-transparent` 之后不再占位，让位量必须由 ResizeObserver 实测：
 * 量四件事 —— 外壳真透明 / 消息区 paddingBottom == 外壳高度 / 「回到最新」让位 /
 * 滚到底时末条消息不被输入卡盖住；再拿「把让位清零」的反面证明量具有牙。
 */
async function runComposerFloat(cdp, url) {
  const shotDir = path.join(ROOT, "test-results", "ui-2026-11-07");
  fs.mkdirSync(shotDir, { recursive: true });
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1280, height: 800, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});

  const READ = `(() => {
    const shell = document.querySelector('[data-composer-shell]');
    const msg = document.querySelector('[data-msg-area]');
    const card = document.querySelector('.gosslan-composer');
    const btn = document.querySelector('[data-back-to-latest]');
    const scroller = document.querySelector('.vlist-no-anchor');
    if (!shell || !msg || !card || !scroller) return null;
    const cs = getComputedStyle(shell);
    const sr = shell.getBoundingClientRect();
    const mr = msg.getBoundingClientRect();
    const cr = card.getBoundingClientRect();
    const br = btn ? btn.getBoundingClientRect() : null;
    return {
      shellBg: cs.backgroundColor,
      shellImg: cs.backgroundImage,
      borderTop: parseFloat(cs.borderTopWidth) || 0,
      shadow: cs.boxShadow,
      shellH: +sr.height.toFixed(2),
      shellW: +sr.width.toFixed(2),
      msgW: +mr.width.toFixed(2),
      msgPadBottom: +((parseFloat(getComputedStyle(msg).paddingBottom) || 0)).toFixed(2),
      cardTop: +cr.top.toFixed(2),
      scrollerBottom: +scroller.getBoundingClientRect().bottom.toFixed(2),
      gapBtn: br ? +(mr.bottom - br.bottom).toFixed(2) : null,
    };
  })()`;

  const SCROLL = `(() => {
    const s = document.querySelector('.vlist-no-anchor');
    if (!s) return false;
    s.scrollTop = s.scrollHeight;
    return true;
  })()`;

  /** 末条消息（最大 index）的底边相对输入卡顶边：>0 表示被盖住。 */
  const LASTROW = `(() => {
    const s = document.querySelector('.vlist-no-anchor');
    const card = document.querySelector('.gosslan-composer');
    if (!s || !card) return null;
    const rows = [...s.querySelectorAll('[data-vlist-index]')].map((n) => {
      const r = n.getBoundingClientRect();
      return { idx: Number(n.getAttribute('data-vlist-index')), bottom: r.bottom };
    }).filter((r) => Number.isFinite(r.idx));
    if (!rows.length) return null;
    const maxIdx = Math.max(...rows.map((r) => r.idx));
    const last = rows.find((r) => r.idx === maxIdx);
    const cardTop = card.getBoundingClientRect().top;
    return {
      lastIdx: maxIdx,
      lastBottom: +last.bottom.toFixed(2),
      cardTop: +cardTop.toFixed(2),
      coveredPx: +(last.bottom - cardTop).toFixed(2),
    };
  })()`;

  const setTheme = async (dark, ambient) => {
    await cdp.eval(`(() => {
      document.documentElement.classList.toggle('dark', ${dark});
      document.documentElement.setAttribute('data-ambient', ${JSON.stringify(ambient)});
      document.documentElement.removeAttribute('data-frost');
      return true;
    })()`);
    await sleep(500);
  };
  const setWidth = async (w) => {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width: w, height: 800, deviceScaleFactor: 1, mobile: w <= 430,
    }).catch(() => {});
    await sleep(700);
  };
  const setPad = async (v) => cdp.eval(`(() => {
    const m = document.querySelector('[data-msg-area]');
    if (!m) return false;
    m.style.paddingBottom = ${JSON.stringify(v)};
    return true;
  })()`);
  const shot = async (name) => {
    const s = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(shotDir, name + ".png"), Buffer.from(s.data, "base64"));
  };

  const rows = [];
  try {
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(3_000);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(() => {
      window.__TAURI_INTERNALS__ = {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      if (!window.__TAURI_EVENT_PLUGIN_INTERNALS__) {
        window.__TAURI_EVENT_PLUGIN_INTERNALS__ = { unregisterListener: () => {} };
      }
    })()`);
    const mounted = await cdp.eval(
      "window.__probe.install('/src/components/ChatWindow.vue', '', '{\"hostHeight\":\"800px\"}')",
    );
    check("ChatWindow 挂得起来（悬浮输入区的入口）",
      !!mounted && mounted.ok === true, "install ok", JSON.stringify(mounted));
    await cdp.eval("window.__probe.seedDevice('dev-me')");

    await cdp.eval(`(async () => {
      const { useChatStore } = await import('/src/stores/useChatStore.ts');
      const chat = useChatStore();
      const conv = 'group:float';
      const rows = [];
      for (let i = 0; i < 60; i += 1) {
        const seq = i + 1;
        rows.push({ id: seq, msg_id: 'm-float-' + seq, local_id: 'm-float-' + seq, conv_id: conv,
          sender_id: 'dev-me', sender_name: '我', receiver_id: 'float', kind: 'text',
          content: ('第' + seq + '条，悬浮输入区让位对照。').repeat(3),
          status: 'sent', seq, ts: 1700000000000 + seq * 1000 });
      }
      chat.activeConv = conv;
      chat.messages[conv] = rows;
      await new Promise((r) => setTimeout(r, 1200));
      return true;
    })()`);

    const states = [
      { name: "light", dark: false, ambient: "off" },
      { name: "dark", dark: true, ambient: "off" },
      { name: "dark-drift", dark: true, ambient: "drift" },
    ];
    const widths = [1280, 768, 430, 390, 360];
    for (const st of states) {
      await setTheme(st.dark, st.ambient);
      for (const w of widths) {
        await setWidth(w);
        const before = await cdp.eval(READ);
        await cdp.eval(SCROLL);
        await sleep(500);
        const last = await cdp.eval(LASTROW);
        // 反面对照：把让位清零，末条必须真的被输入卡盖住（证明量具有牙）。
        await setPad("0px");
        await cdp.eval(SCROLL);
        await sleep(400);
        const counter = await cdp.eval(LASTROW);
        // 还原必须写回实测高度：写空会让内联 style 空着（Vue 已渲染过，不会再补）。
        await setPad(`${before.shellH}px`);
        await sleep(200);
        rows.push({ ...st, w, before, last, counter });
        if (w === 1280 || w === 390) await shot(`composerfloat-${st.name}-${w}`);
      }
    }

    const isTransparent = (bg) => /rgba\(0, 0, 0, 0\)|transparent/.test(String(bg));
    console.log("  ℹ 悬浮输入区读数：" + JSON.stringify(rows.map((r) => ({
      s: r.name, w: r.w,
      h: r.before?.shellH, pad: r.before?.msgPadBottom,
      wShell: r.before?.shellW, wMsg: r.before?.msgW,
      bg: r.before?.shellBg, border: r.before?.borderTop, shadow: r.before?.shadow,
      gapBtn: r.before?.gapBtn, covered: r.last?.coveredPx, counterCovered: r.counter?.coveredPx,
    }))));

    check("外壳在亮/暗/特效全开 与 5 档宽度下都是真透明：无底色、无背景图、无 border-top、无阴影",
      rows.every((r) => r.before && isTransparent(r.before.shellBg)
        && r.before.shellImg === "none" && r.before.borderTop === 0
        && (r.before.shadow === "none" || r.before.shadow === "")),
      "bg transparent + no image + border-top 0 + shadow none",
      JSON.stringify(rows.map((r) => r.before?.shellBg)));

    check("消息区让位 == 外壳实测高度（差 ≤1px），且两者等宽（同一整块画布）",
      rows.every((r) => r.before && Math.abs(r.before.msgPadBottom - r.before.shellH) <= 1
        && Math.abs(r.before.shellW - r.before.msgW) <= 0.5),
      "|pad - shellH| <= 1 且 |shellW - msgW| <= 0.5",
      JSON.stringify(rows.map((r) => [r.before?.shellH, r.before?.msgPadBottom])));

    check("「回到最新」让位 ≥ 外壳高度 + 16px（不被输入卡压住）",
      rows.every((r) => r.before && typeof r.before.gapBtn === "number"
        && r.before.gapBtn >= r.before.shellH + 15),
      "gapBtn >= shellH + 15", JSON.stringify(rows.map((r) => r.before?.gapBtn)));

    check("滚到底时末条消息底边不越过输入卡顶边（盖住 px ≤ 0.5）",
      rows.every((r) => r.last && r.last.coveredPx <= 0.5),
      "coveredPx <= 0.5", JSON.stringify(rows.map((r) => r.last?.coveredPx)));

    check("反面对照：把消息区让位清零后末条必须被输入卡盖住（≥20px，否则量具恒绿）",
      rows.every((r) => r.counter && r.counter.coveredPx >= 20),
      "counter coveredPx >= 20", JSON.stringify(rows.map((r) => r.counter?.coveredPx)));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
    await cdp.eval(`(() => {
      document.documentElement.removeAttribute('data-ambient');
      document.documentElement.classList.remove('dark');
      return true;
    })()`).catch(() => {});
  }
}

/**
 * ⑤+⑥ 同心几何：内圆角 = 外圆角 − 内外间距（2026-11-07）。
 *
 * 两件事一起量：
 *   · 品牌底盘（68px orb，外圆角 16）里的方形标记位图：44px → 4px、56px → 10px；
 *   · 主窗右上角头像：右内距必须等于纵向内距（40px 标题栏 / 28px 圆 ⇒ 各 6），
 *     且与 macOS 26 的 ~20px 窗口圆角同心（圆心偏差 ≤1px）。
 * 反面对照：把右侧簇的 padding-right 改回 12px，内距差必须跳出来（否则量具恒绿）。
 */
async function runConcentric(cdp, url) {
  const shotDir = path.join(ROOT, "test-results", "ui-2026-11-07");
  fs.mkdirSync(shotDir, { recursive: true });
  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setEmulatedMedia", { features: [] }).catch(() => {});
  const HEIGHT = 800;

  const boot = async (width, mobile) => {
    await cdp.send("Emulation.setDeviceMetricsOverride", {
      width, height: HEIGHT, deviceScaleFactor: 1, mobile,
    }).catch(() => {});
    await cdp.send("Page.navigate", { url });
    await cdp.settled();
    await sleep(2_200);
    await cdp.eval(PAGE_FIXTURE);
    await cdp.eval(`(async () => {
      window.__TAURI_INTERNALS__ = {
        metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
        invoke: async () => null, transformCallback: (cb) => cb, convertFileSrc: (p) => p,
      };
      window.__TAURI_EVENT_PLUGIN_INTERNALS__ = window.__TAURI_EVENT_PLUGIN_INTERNALS__ || { unregisterListener: () => {} };
      document.documentElement.setAttribute('data-ambient', 'off');
      await window.__probe.install('/src/layouts/ResponsiveLayout.vue', '', ${
        JSON.stringify(JSON.stringify({ router: true, hostHeight: `${HEIGHT}px` }))
      });
      return true;
    })()`);
    await sleep(800);
  };

  const ORB = `(() => {
    const orb = document.querySelector('[data-orb]');
    const mark = document.querySelector('[data-orb-mark]');
    if (!orb || !mark) return null;
    const r = orb.getBoundingClientRect();
    const m = mark.getBoundingClientRect();
    return {
      orbSize: +r.width.toFixed(2),
      orbRadius: getComputedStyle(orb).borderTopLeftRadius,
      markSize: +m.width.toFixed(2),
      markRadius: getComputedStyle(mark).borderTopLeftRadius,
      inset: +(((r.width - m.width) / 2)).toFixed(2),
    };
  })()`;

  const AVATAR = `(() => {
    const host = document.getElementById('probe-host');
    const btn = document.querySelector('.tap-safe.relative');
    if (!host || !btn) return null;
    const hr = host.getBoundingClientRect();
    const br = btn.getBoundingClientRect();
    const bh = getComputedStyle(host);
    const hostRight = hr.right - (parseFloat(bh.borderRightWidth) || 0);
    const hostTop = hr.top + (parseFloat(bh.borderTopWidth) || 0);
    const radius = Math.min(br.width, br.height) / 2;
    const WINDOW_CORNER = 20; // macOS 26 系统窗口圆角（Windows 11 为 8，见任务台账 #23）
    return {
      gapTop: +(br.top - hostTop).toFixed(2),
      gapRight: +(hostRight - br.right).toFixed(2),
      avatar: +br.width.toFixed(2),
      radius: +radius.toFixed(2),
      devX: +Math.abs((hostRight - br.right) + radius - WINDOW_CORNER).toFixed(2),
      devY: +Math.abs((br.top - hostTop) + radius - WINDOW_CORNER).toFixed(2),
      isMac: /Mac/.test(navigator.userAgent),
    };
  })()`;

  const rows = {};
  try {
    await boot(1280, false);
    rows.desktopOrb = await cdp.eval(ORB);
    rows.avatar = await cdp.eval(AVATAR);
    const shot = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(shotDir, "concentric-desktop-1280.png"), Buffer.from(shot.data, "base64"));

    // 反面对照：把右侧簇的右内距改回 12px，内距差必须 ≠ 0。
    rows.avatarCounter = await cdp.eval(`(() => {
      const slot = document.querySelector('[data-no-drag-region]');
      if (!slot) return null;
      slot.style.paddingRight = '12px';
      const host = document.getElementById('probe-host');
      const btn = document.querySelector('.tap-safe.relative');
      const hr = host.getBoundingClientRect();
      const br = btn.getBoundingClientRect();
      const bh = getComputedStyle(host);
      const out = {
        gapTop: +(br.top - (hr.top + (parseFloat(bh.borderTopWidth) || 0))).toFixed(2),
        gapRight: +((hr.right - (parseFloat(bh.borderRightWidth) || 0)) - br.right).toFixed(2),
      };
      slot.style.paddingRight = '';
      return out;
    })()`);

    await boot(390, true);
    rows.mobileOrb = await cdp.eval(ORB);
    const shot2 = await cdp.send("Page.captureScreenshot", { format: "png" });
    fs.writeFileSync(path.join(shotDir, "concentric-mobile-390.png"), Buffer.from(shot2.data, "base64"));

    console.log("  ℹ 同心读数：" + JSON.stringify(rows));

    check("桌面品牌底盘：68px 外圆角 20px，44px 方形标记削成同心 8px（内距 12）",
      !!rows.desktopOrb && rows.desktopOrb.orbSize === 68 && rows.desktopOrb.orbRadius === "20px"
        && rows.desktopOrb.markSize === 44 && rows.desktopOrb.markRadius === "8px"
        && rows.desktopOrb.inset === 12,
      "orb 68/20 + mark 44/8 + inset 12", JSON.stringify(rows.desktopOrb));

    check("移动端品牌底盘：56px 方形标记削成同心 14px（内距 6）",
      !!rows.mobileOrb && rows.mobileOrb.markSize === 56 && rows.mobileOrb.markRadius === "14px"
        && rows.mobileOrb.inset === 6,
      "mark 56/14 + inset 6", JSON.stringify(rows.mobileOrb));

    check("右上角头像：右内距 == 纵向内距（各 6px，差 ≤1px）",
      !!rows.avatar && Math.abs(rows.avatar.gapTop - rows.avatar.gapRight) <= 1,
      "|gapTop - gapRight| <= 1", JSON.stringify(rows.avatar));

    check("右上角头像与窗口圆角同心（圆心偏差 ≤1px；非 macOS 走等距 fallback）",
      !!rows.avatar && (!rows.avatar.isMac || (rows.avatar.devX <= 1 && rows.avatar.devY <= 1)),
      "devX/devY <= 1（macOS）", JSON.stringify(rows.avatar));

    check("反面对照：右内距改回 12px 后两向内距差必须 ≥5px（否则量具恒绿）",
      !!rows.avatarCounter && Math.abs(rows.avatarCounter.gapTop - rows.avatarCounter.gapRight) >= 5,
      "counter |gapTop - gapRight| >= 5", JSON.stringify(rows.avatarCounter));
  } finally {
    await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  }
}

// ---------------------------------------------------------------------------
// `--only=palette`：配色**按场景普查**（2026-11-08）
// ---------------------------------------------------------------------------
//
// 触发事件：用户实测截图 —— 表情回应胶囊的计数字压在主色淡底上看不清、容器/hover 跟主题色不搭。
// 根因不是某个 token 选错，而是**尺子的形状错了**：tokenContrast 只做「token 对 token」的配对，
// 而真实渲染出来的组合经常是「主色 + 透明度/color-mix 叠出来的有效色 + hover 再叠一层」，
// 这些颜色在 token 表里根本不存在（旧默认态 = `--gosslan-hover` 的 5% 墨迹，叠在自己的蓝气泡上
// 就变成"灰字压蓝底"，读数 2.x）。所以这一段不读 token，只读**真元素合成的 computed 颜色**：
//   ① 页面里按亮/暗 × 内置主色逐档写入运行时 token（等价 applyTheme 的终态）；
//   ② `bgOf()` 从元素往上把每一层 background（含 alpha）合成到不透明，`measure()` 再把
//      文字自身的 color alpha × 链上 opacity 合成到那个有效底上；
//   ③ 用 themePalette 的 APCA/WCAG 双约束判（阈值仍取 APCA_LIMITS，不在本文件里另写一份）。
// 场景清单按用户点名的 9 类：表情胶囊四态（两种气泡）/ 气泡内链接 / 引用条 / 时间分割线 /
// 未读徽标 / 按钮 hover+active / 列表选中行 / 代码块 / toast 两变体（含计数）/ 占位符 / 传输队列计数。
// 反例自证三条：胶囊文字改回固定浅色、胶囊 hover 叠成透明透出气泡、阈值降档 —— 每条都必须让判据翻红。

/** 内置主色档：从设置页 presets 现解析（加一档自动进矩阵，不用手工同步第二份清单）。 */
const PALETTE_PRESETS = (() => {
  const src = fs.readFileSync(path.join(ROOT, "src/components/settings/AppearanceSection.vue"), "utf8");
  const m = /const presets\s*=\s*\[([^\]]*)\]/.exec(src);
  return [...(m?.[1] ?? "").matchAll(/"(#[0-9a-fA-F]{3,6})"/g)].map((x) => x[1]);
})();

/**
 * 页面侧量具（**只装一次**）。缺 `::placeholder` 这类伪元素时用第二参读它的 computed 颜色。
 * 阈值表在页面里从 `APCA_LIMITS` 现取 —— 本文件不存第二份数字。
 */
const PAL_HELPERS = `(async () => {
  if (window.__pal) return "kept";
  const T = await import("/src/utils/themePalette.ts");
  const C = await import("/src/utils/color.ts");
  const parse = (s) => {
    const str = String(s || "").trim();
    if (!str || str === "transparent" || str === "none") return [0, 0, 0, 0];
    const cm = /color\\(srgb\\s+([^\\s/)]+)\\s+([^\\s/)]+)\\s+([^\\s/)]+)(?:\\s*\\/\\s*([^)]+))?\\)/.exec(str);
    if (cm) return [Number(cm[1]) * 255, Number(cm[2]) * 255, Number(cm[3]) * 255, cm[4] == null ? 1 : Number(cm[4])];
    const m = /rgba?\\(([^)]+)\\)/.exec(str);
    if (!m) return [0, 0, 0, 0];
    const p = m[1].split(/[,\\s\\/]+/).filter((v) => v !== "").map(Number);
    return [p[0], p[1], p[2], p.length > 3 && !Number.isNaN(p[3]) ? p[3] : 1];
  };
  const over = (top, bottom) => [0, 1, 2].map((i) => top[i] * top[3] + bottom[i] * (1 - top[3]));
  /** 从元素往上把每层 background 合成到不透明（这正是 token 表里不存在的那一层）。 */
  const bgOf = (el) => {
    const chain = [];
    let n = el;
    while (n && n.nodeType === 1) { chain.push(n); n = n.parentElement; }
    let out = [255, 255, 255];
    for (let i = chain.length - 1; i >= 0; i -= 1) {
      const st = getComputedStyle(chain[i]);
      const c = parse(st.backgroundColor);
      if (c[3] > 0) out = over(c, out);
      // 同一道渐变（两端同色）等价于一层纯色叠层 —— :active 的 pressed 状态用的就是它。
      // 多色渐变/图片没有单一"有效色"，这里不猜（保持 background-color 的结果）。
      const img = String(st.backgroundImage || "");
      if (img.indexOf("linear-gradient(") === 0) {
        const stops = img.match(/rgba?\\([^)]*\\)|color\\([^)]*\\)/g) || [];
        if (stops.length > 1 && stops.every((s) => s === stops[0])) {
          const o = parse(stops[0]);
          if (o[3] > 0) out = over(o, out);
        }
      }
    }
    return out;
  };
  const NEED = {
    body: [T.APCA_LIMITS.body, 7],
    secondary: [T.APCA_LIMITS.secondary, 4.5],
    weak: [T.APCA_LIMITS.weak, 4.65],
    onSolid: [T.APCA_LIMITS.button, 4.55],
    nontext: [T.APCA_LIMITS.icon, 3.0],
    solid: [0, 4.5],
    // 气泡内容（正文/链接/引用条）：气泡配色由 chatStyle 自己的契约管（白字 ≥4.8、
    // 「我方 accent 实底 vs 对方气泡」≥3.45 的可归属性），不可能同时满足 APCA 85 的正文档。
    // 这里按 APCA 对内容的最低档 60 + WCAG 4.5 断言 —— 不是放宽门禁，是**换参照物**：
    // 主题 token 那一路（按钮/徽标/列表/占位符/toast）仍然是严格档。
    content: [T.APCA_LIMITS.weak, 4.5],
  };
  window.__pal = {
    apply(seed, dark, canvas) {
      // ⚠️ 必须同时改 **store**，不能只改 CSS 变量：气泡的 mine 底色/文字是
      // resolveChatColors(preset, app.themeColor, app.dark) 在 JS 里算出来的
      // （utils/chatStyle.ts）。只切 .dark 类会让"页面是亮色、气泡却是暗色"——
      // 实测量到 mineText #d4d4d4 压 #234baf 这种根本不存在于任何一套主题的组合。
      const S = window.__pinia && window.__pinia._s && window.__pinia._s.get("app");
      if (S) { try { S.appearance = dark ? "dark" : "light"; S.themeColor = seed; } catch (e) { /* 只读则忽略 */ } }
      C.applyTheme(seed, "", !!dark);
      document.documentElement.classList.toggle("dark", !!dark);
      document.body.style.background = canvas || "var(--gosslan-chat)";
      return true;
    },
    measure(sel, idx, target, pseudo) {
      const list = document.querySelectorAll(sel);
      const el = list[idx || 0];
      if (!el) return { miss: sel + "#" + (idx || 0), count: list.length };
      const bg = bgOf(el);
      const raw = parse(getComputedStyle(el, pseudo || null).color);
      let a = raw[3];
      let n = el;
      while (n && n.nodeType === 1) { a *= Number(getComputedStyle(n).opacity || 1); n = n.parentElement; }
      const fg = [0, 1, 2].map((i) => raw[i] * a + bg[i] * (1 - a));
      const lc = Math.abs(T.apcaLc(fg, bg));
      const ratio = T.wcagRatio(fg, bg);
      const need = NEED[target];
      // 诊断层：读数对不上 token 表里的值时，必须先分清是取色口径（叠层/透明度/父层）
      // 还是 token 本身没写进去。raw 与 layers 只能靠量，不能靠猜。
      const layers = [];
      let m = el;
      while (m && m.nodeType === 1 && layers.length < 4) {
        layers.push(m.tagName.toLowerCase() + ":" + getComputedStyle(m).backgroundColor);
        m = m.parentElement;
      }
      const vars = {};
      for (const v of ["--gosslan-react-bg", "--gosslan-react-bg-hover", "--gosslan-react-bg-mine",
        "--gosslan-react-bg-mine-hover", "--gosslan-react-ink", "--gosslan-react-ink-mine",
        "--gosslan-primary", "--gosslan-primary-active", "--gosslan-on-primary"]) {
        vars[v.replace("--gosslan-", "")] = String(getComputedStyle(document.documentElement).getPropertyValue(v)).trim();
      }
      return {
        lc: +lc.toFixed(1), ratio: +ratio.toFixed(2), need,
        ok: lc >= need[0] && ratio >= need[1],
        fg: fg.map((v) => Math.round(v)), bg: bg.map((v) => Math.round(v)),
        tag: el.tagName.toLowerCase(),
        cls: String(el.className || "").slice(0, 70),
        opa: +a.toFixed(2),
        raw: getComputedStyle(el, pseudo || null).color,
        layers, vars,
      };
    },
  };
  return "fresh";
})()`;

async function runPalette(cdp, url) {
  const shotDir = path.join(ROOT, "test-results", "theme-shots");
  fs.mkdirSync(shotDir, { recursive: true });

  await cdp.send("Page.bringToFront").catch(() => {});
  await cdp.send("Emulation.setDeviceMetricsOverride", {
    width: 1120, height: 900, deviceScaleFactor: 1, mobile: false,
  }).catch(() => {});
  await cdp.send("Page.navigate", { url });
  await cdp.settled();
  await sleep(2_500);
  await cdp.eval(PAGE_FIXTURE);
  const helper = await cdp.eval(PAL_HELPERS);
  check("palette 量具装上（有效色合成 + APCA/WCAG 双约束，阈值取 themePalette.APCA_LIMITS）",
    helper === "fresh" || helper === "kept", "fresh|kept", String(helper));
  // ⚠️ 量颜色时**必须停掉过渡**：胶囊与按钮都带 `transition`，`apply` 之后 70ms 读到的是
  // 「上一个主题 → 这个主题」的中间帧（实测 `--gosslan-react-bg` 明明是 #312d2b，量到 #474341）。
  // 这不是产品缺陷，是量具把动画帧当成了终态。停掉过渡后读到的才是 CSS 最终计算值，
  // 与用户最终看到的颜色一致（截图取证时同样适用）。
  await cdp.eval(`(() => {
    const old = document.getElementById('__pal_still'); if (old) old.remove();
    const st = document.createElement('style'); st.id = '__pal_still';
    st.textContent = '*,*::before,*::after{transition:none!important;animation:none!important}';
    document.head.appendChild(st);
    return true;
  })()`);
  // ⚠️ `hover:` 工具类在 Tailwind v4 里包在 `@media (hover: hover)` 里：headless 默认报
  // `hover: none` ⇒ 所有 hover 档都会量成"和默认态一样"，是**量具假绿**而不是产品没 hover。
  // 显式声明"细指针 + 可悬停"，等价桌面鼠标。
  await cdp.send("Emulation.setEmulatedMedia", {
    media: "",
    features: [{ name: "hover", value: "hover" }, { name: "pointer", value: "fine" }, { name: "any-hover", value: "hover" }],
  }).catch(() => {});
  check("palette 量具环境 = 可悬停（否则 `hover:` 工具类整类不生效，四态只会量到两态）",
    await cdp.eval("matchMedia('(hover: hover)').matches === true"), "hover:hover", "matchMedia");
  await cdp.send("DOM.enable").catch(() => {});
  await cdp.send("CSS.enable").catch(() => {});

  // 裸浏览器里没有 `__TAURI_INTERNALS__`：`ConversationList` 在 setup 里同步调
  // `getCurrentWebview().onDragDropEvent(...)`，缺 metadata 会当场 TypeError，整段从那一行起断掉。
  // 打桩只做"让 setup 跑通"，不改变任何颜色口径（invoke 永不回包 ⇒ 拖拽监听挂空）。
  await cdp.eval(`(() => {
    window.__TAURI_INTERNALS__ = window.__TAURI_INTERNALS__ || {
      metadata: { currentWindow: { label: 'main' }, currentWebview: { label: 'main', windowLabel: 'main' } },
      invoke: async () => new Promise(() => {}), transformCallback: (cb) => cb, convertFileSrc: (p) => p,
    };
    return true;
  })()`);

  const install = async (cmp, props) => {
    const r = await cdp.eval(`window.__probe.install(${JSON.stringify(cmp)}, '', ${JSON.stringify(JSON.stringify(props || {}))})`);
    await sleep(260);
    return r;
  };

  /** forcePseudoState 用 DOM.querySelectorAll 拿 nodeId（一个场景装一次，档位循环里复用）。 */
  const sceneNodeIds = async (specs) => {
    const ids = new Map();
    if (!specs.some((s) => s.pseudo)) return ids;
    const { root } = await cdp.send("DOM.getDocument", { depth: 0 });
    for (const sp of specs) {
      if (!sp.pseudo) continue;
      const r = await cdp.send("DOM.querySelectorAll", { nodeId: root.nodeId, selector: sp.sel }).catch(() => null);
      ids.set(sp.label, (r && r.nodeIds && r.nodeIds[sp.idx || 0]) || 0);
    }
    return ids;
  };

  let cells = 0;
  const sweep = async (name, canvas, specs) => {
    const ids = await sceneNodeIds(specs);
    const worst = new Map();
    const missing = [];
    for (const seed of PALETTE_PRESETS) {
      for (const dark of [false, true]) {
        await cdp.eval(`window.__pal.apply(${JSON.stringify(seed)}, ${dark}, ${JSON.stringify(canvas)})`);
        await sleep(70);
        for (const sp of specs) {
          const nodeId = ids.get(sp.label) || 0;
          if (nodeId) await cdp.send("CSS.forcePseudoState", { nodeId, forcedPseudoClasses: [sp.pseudo] }).catch(() => {});
          const r = await cdp.eval(`window.__pal.measure(${JSON.stringify(sp.sel)}, ${sp.idx || 0}, ${
            JSON.stringify(sp.target)}, ${JSON.stringify(sp.pseudo || "")})`);
          if (nodeId) await cdp.send("CSS.forcePseudoState", { nodeId, forcedPseudoClasses: [] }).catch(() => {});
          cells += 1;
          if (!r || r.miss) { missing.push(`${sp.label}@${seed}/${dark ? "dark" : "light"}`); continue; }
          const margin = Math.min(r.need[0] > 0 ? r.lc / r.need[0] : Infinity, r.ratio / r.need[1]);
          const cur = worst.get(sp.label);
          if (!cur || margin < cur.margin) worst.set(sp.label, { seed, dark, r, margin });
        }
      }
    }
    const fails = [...worst.values()].filter((v) => !v.r.ok);
    const hex = (rgb) => "#" + rgb.map((v) => v.toString(16).padStart(2, "0")).join("");
    const detail = [...worst.entries()]
      .map(([k, v]) => `${k} ${hex(v.r.fg)}→${hex(v.r.bg)}(α${v.r.opa}) Lc${v.r.lc}/W${v.r.ratio}${
        v.r.ok ? "" : ` FAIL raw=${v.r.raw} layers=${JSON.stringify(v.r.layers)} vars=${JSON.stringify(v.r.vars)}`}@${v.seed}${v.dark ? "暗" : "亮"}`)
      .join(" · ");
    const missDetail = missing.length === 0 ? "" : ` · 缺席：${[...new Set(missing.map((m) => m.split("@")[0]))].join(",")}`
      + `（前 ${Math.min(4, missing.length)} 格：${missing.slice(0, 4).join(" / ")}）`;
    check(`palette·${name}：${PALETTE_PRESETS.length} 内置主色 × 亮/暗 × ${specs.length} 项全部达标`,
      missing.length === 0 && fails.length === 0,
      "缺席 0 且 全部 ok=true",
      `缺席 ${missing.length} 未达标 ${fails.length}${missDetail} · 最差档：${detail}`);
    return { name, worst, missing, fails };
  };

  const CHIPS = [
    { emoji: "👍", count: 3, mine: false, actors: ["peer-b"], latest: "peer-b" },
    { emoji: "🎉", count: 5, mine: true, actors: ["me-1", "peer-b"], latest: "me-1" },
  ];
  const peerProps = {
    message: {
      msg_id: "m-pal-peer", sender_id: "peer-a", kind: "text",
      content: "「引用 张三：被引用的原话|m-pal-src」\n这条要量链接 https://example.com/pal 与胶囊四态，正文写得稍长一些。",
      ts: 1700000000000, conv_id: "group:g1", seq: 1,
    },
    canReact: true, isGroup: true, senderName: "测试者", reactions: CHIPS,
  };
  const ownProps = JSON.parse(JSON.stringify(peerProps));
  ownProps.message.msg_id = "m-pal-own";
  ownProps.message.sender_id = "dev-me";

  const PILL = [
    { label: "胶囊·默认", sel: "[data-reaction-chip]", idx: 0, target: "secondary" },
    { label: "胶囊·hover", sel: "[data-reaction-chip]", idx: 0, target: "secondary", pseudo: "hover" },
    { label: "胶囊·已选", sel: "[data-reaction-chip]", idx: 1, target: "secondary" },
    { label: "胶囊·已选+hover", sel: "[data-reaction-chip]", idx: 1, target: "secondary", pseudo: "hover" },
  ];

  // ① 别人的气泡：四态 + 链接 + 引用条 + 时间分割线
  const peerMount = await install("/src/components/MessageItem.vue", peerProps);
  check("palette·别人的气泡挂出来了（四态胶囊才有得量）", !!peerMount && peerMount.ok === true, "install ok", JSON.stringify(peerMount));
  // ⚠️ seedDevice 读的是 `window.__pinia`，而 pinia 是 install 才建的 ⇒ 必须在挂载**之后**种身份。
  // 反过来（先种再装）会得到 `ok:false / 先跑 install`，于是「自己的气泡」实际渲染成别人的气泡：
  // 那样四态胶囊量的是 peer 底色，读数看着像"深字浅底"，红/绿都不可信。
  const seeded = await cdp.eval("window.__probe.seedDevice('dev-me')");
  check("palette 夹具设备 = dev-me（「我发的」气泡与 mine 胶囊才成立）",
    !!seeded && seeded.ok === true && seeded.at === "dev-me", "device=dev-me", JSON.stringify(seeded));
  check("palette 主色矩阵非空：内置 presets 至少 6 档（少一档等于漏跑一套主题）",
    PALETTE_PRESETS.length >= 6, "presets >= 6", JSON.stringify(PALETTE_PRESETS));
  await sleep(200);
  const peerScene = await sweep("别人的气泡", "var(--gosslan-chat)", [
    ...PILL,
    { label: "气泡正文", sel: "[data-msg-body]", idx: 0, target: "content" },
    { label: "气泡内链接", sel: "[data-msg-body] a", idx: 0, target: "content" },
    { label: "引用条文字", sel: ".quote-text", idx: 0, target: "content" },
    { label: "时间分割线", sel: "[data-time-divider]", idx: 0, target: "secondary" },
  ]);

  // ② 自己的气泡（主色实底）：同一套四态 + 正文链接
  // 每次 install 默认新建一份 pinia ⇒ 上一段种的身份会跟着丢，所以这里挂完再种一次。
  const ownMount = await install("/src/components/MessageItem.vue", ownProps);
  check("palette·自己的气泡挂出来了", !!ownMount && ownMount.ok === true, "install ok", JSON.stringify(ownMount));
  const seededOwn = await cdp.eval("window.__probe.seedDevice('dev-me')");
  check("palette·自己的气泡身份 = dev-me（否则量到的是左列）",
    !!seededOwn && seededOwn.ok === true && seededOwn.at === "dev-me", "device=dev-me", JSON.stringify(seededOwn));
  await sleep(120);
  await sweep("自己的气泡", "var(--gosslan-chat)", [
    ...PILL.map((p) => ({ ...p, label: p.label.replace("胶囊", "胶囊·自己的气泡") })),
    { label: "自己气泡正文", sel: "[data-msg-body]", idx: 0, target: "content" },
    { label: "自己气泡内链接", sel: "[data-msg-body] a", idx: 0, target: "content" },
  ]);

  // ③ 未读徽标（danger 实底 + 白字；WCAG 口径，不追加 APCA —— 红实底 APCA 天然偏低）
  const badgeMount = await install("/src/components/UnreadBadge.vue", { count: 12 });
  check("palette·未读徽标挂出来了", !!badgeMount && badgeMount.ok === true, "install ok", JSON.stringify(badgeMount));
  await sweep("未读徽标", "var(--gosslan-list)", [
    { label: "未读徽标计数", sel: "#probe-host > *", idx: 0, target: "solid" },
  ]);

  // ④ 三档按钮：默认 / hover / active（`ForcePseudoState`，等价真鼠标按下与悬停的 CSS）
  for (const btn of [
    { file: "/src/components/ui/PrimaryBtn.vue", name: "主色按钮", tone: "onSolid" },
    { file: "/src/components/ui/SecondaryBtn.vue", name: "次按钮", tone: "secondary" },
    { file: "/src/components/ui/DangerBtn.vue", name: "危险按钮", tone: "solid" },
  ]) {
    const m = await install(btn.file, {});
    check(`palette·${btn.name}挂出来了`, !!m && m.ok === true, "install ok", JSON.stringify(m));
    await sweep(btn.name, "var(--gosslan-panel)", [
      { label: `${btn.name}·默认`, sel: "#probe-host button", idx: 0, target: btn.tone },
      { label: `${btn.name}·hover`, sel: "#probe-host button", idx: 0, target: btn.tone, pseudo: "hover" },
      { label: `${btn.name}·active`, sel: "#probe-host button", idx: 0, target: btn.tone, pseudo: "active" },
    ]);
  }

  // ⑤ 列表选中行（标题 + 预览；预览带 `opacity-90`，有效色同样要合成）
  const rowMount = await install("/src/components/conversation/ConversationListItem.vue", {
    conv: {
      id: "c-pal-1", kind: "group", name: "配色普查群", avatar: null,
      last_msg: "这条预览文字要在选中行上读得清", last_ts: 1700000000000,
      unread: 3, mentioned: 0, pinned: 0, muted: 0, members: ["dev-me"],
    },
    active: true, online: null,
  });
  check("palette·列表选中行挂出来了", !!rowMount && rowMount.ok === true, "install ok", JSON.stringify(rowMount));
  await sweep("列表选中行", "var(--gosslan-list)", [
    { label: "选中行标题", sel: "[data-conv-name]", idx: 0, target: "body" },
    { label: "选中行预览", sel: "#probe-host .text-fine", idx: 0, target: "secondary" },
  ]);

  // ⑥ 代码块（自带固定深底，不跟主题走 —— 正好证明我们没把它覆盖掉）
  const codeMount = await install("/src/components/CodeBlock.vue", {
    code: "const seed = '#2f6bff';\nconsole.log(seed);\n", language: "ts", attached: true,
  });
  check("palette·代码块挂出来了", !!codeMount && codeMount.ok === true, "install ok", JSON.stringify(codeMount));
  await sweep("代码块", "var(--gosslan-chat)", [
    { label: "代码块正文", sel: ".code-pre", idx: 0, target: "secondary" },
  ]);

  // ⑦ toast 两变体（普通 = hud 底、错误 = danger 底）+ 计数 chip
  const toastMount = await install("/src/components/ToastHud.vue", {});
  check("palette·ToastHud 挂出来了", !!toastMount && toastMount.ok === true, "install ok", JSON.stringify(toastMount));
  await cdp.eval(`(async () => { const m = await import('/src/utils/toastManager.ts');
    window.__pushPalToast = (k, kind) => { m.pushToast(k, kind); m.pushToast(k, kind); }; return true; })()`);
  await cdp.eval("window.__pushPalToast('配色普查普通', 'info'); window.__pushPalToast('配色普查错误', 'error')");
  await sleep(260);
  await sweep("toast", "var(--gosslan-chat)", [
    { label: "toast 正文", sel: "li[data-status] .min-w-0", idx: 0, target: "solid" },
    { label: "toast 计数", sel: "[data-toast-count]", idx: 0, target: "solid" },
  ]);

  // ⑧ 会话列表：搜索框占位符 + 传输队列计数
  const listMount = await install("/src/components/ConversationList.vue", { view: "chats" });
  check("palette·会话列表挂出来了", !!listMount && listMount.ok === true, "install ok", JSON.stringify(listMount));
  await cdp.eval(`(async () => {
    const { useChatStore } = await import('/src/stores/useChatStore.ts');
    // 必须绑**这一份** pinia：每次 install 都新建 pinia，裸调 useChatStore() 得到的是另一份，
    // 组件里的 taskCount 永远读不到 ⇒ 「传输队列计数」整格缺席（首跑就是这样）。
    const chat = useChatStore(window.__pinia);
    chat.conversations = [
      { id: 'c-pal-1', kind: 'group', name: '配色普查群', avatar: null, last_msg: '预览文字',
        last_ts: 1700000000000, unread: 2, mentioned: 0, pinned: 0, muted: 0, members: ['dev-me'] },
    ];
    // ⚠️ 种的是 transfers，不是 operations：operations 是 useChatStore 里的 **computed**
    // （deriveOperations(transfers/…)，见 useChatStore.ts 那段注释），赋值会被静默丢掉 ⇒
    // taskCount 恒为 0 ⇒ 「传输队列计数」整格缺席（首跑就是这样，缺 12 格）。
    chat.transfers = [
      { id: 't-pal', peer_id: 'p1', name: '配色普查.pdf', size: 1000, direction: 'send',
        status: 'active', path: null, progress: 0.4, blocked_reason: null, created_at: 5 },
    ];
    return true;
  })()`);
  await sleep(260);
  await sweep("会话列表", "var(--gosslan-list)", [
    { label: "搜索框占位符", sel: "#probe-host input", idx: 0, target: "weak", pseudo: "::placeholder" },
    { label: "传输队列计数", sel: "[data-task-count]", idx: 0, target: "body" },
  ]);

  check("palette 矩阵不是空转：至少量到 9 类场景 × 12 档（≥ 190 格）",
    cells >= 190, "cells >= 190", `cells=${cells}`);

  // ---- 反例自证（三条都必须翻红）----
  // 回到"自己的气泡"：这是用户实测那张截图的位置（胶囊压在主色实底上）。
  // 新装一份 pinia ⇒ 必须重新种身份，否则下面量到的又是左列（那样三条反例的证据都不成立）。
  await install("/src/components/MessageItem.vue", ownProps);
  await cdp.eval("window.__probe.seedDevice('dev-me')");
  await sleep(150);
  await cdp.eval("window.__pal.apply('#2f6bff', false, 'var(--gosslan-chat)')");
  await sleep(120);
  const inject = async (css) => {
    await cdp.eval(`(() => { const old = document.getElementById('__pal_mut'); if (old) old.remove();
      const st = document.createElement('style'); st.id = '__pal_mut'; st.textContent = ${JSON.stringify(css)};
      document.head.appendChild(st); return true; })()`);
    await sleep(90);
  };
  const clearMut = async () => {
    await cdp.eval("document.getElementById('__pal_mut')?.remove(); true");
    await clearForced();
  };
  const forcedNode = async (sel) => {
    const { root } = await cdp.send("DOM.getDocument", { depth: 0 });
    const r = await cdp.send("DOM.querySelectorAll", { nodeId: root.nodeId, selector: sel }).catch(() => null);
    return (r && r.nodeIds && r.nodeIds[0]) || 0;
  };
  const clearForced = async () => {
    const id = await forcedNode("[data-reaction-chip]");
    if (id) await cdp.send("CSS.forcePseudoState", { nodeId: id, forcedPseudoClasses: [] }).catch(() => {});
  };
  const palRead = (target) => cdp.eval(`window.__pal.measure("[data-reaction-chip]", 0, ${JSON.stringify(target)}, "")`);

  // 变异 ①：胶囊文字改回固定浅色（旧实现里的"跟气泡走"）
  await inject("[data-reaction-chip]{color:#e6e9ef!important}");
  const fixedInk = await palRead("secondary");
  await clearMut();
  check("palette 反例①：胶囊文字注回固定浅色 ⇒ 默认态读数必须翻红",
    !!fixedInk && !fixedInk.miss && fixedInk.ok === false,
    "ok=false", JSON.stringify(fixedInk));

  // 变异 ②：hover 叠成"透明"（透出下面的气泡 ⇒ 等于第二层底/没有底）
  const hoverNode = await forcedNode("[data-reaction-chip]");
  await inject("[data-reaction-chip]:hover{background-color:transparent!important}");
  if (hoverNode) await cdp.send("CSS.forcePseudoState", { nodeId: hoverNode, forcedPseudoClasses: ["hover"] }).catch(() => {});
  await sleep(70);
  const stacked = await palRead("secondary");
  await clearMut();
  check("palette 反例②：胶囊 hover 透出气泡（叠成第二层/没有底）⇒ 读数必须翻红",
    !!stacked && !stacked.miss && stacked.ok === false,
    "ok=false", JSON.stringify(stacked));

  // 变异 ③：同一份证据，把阈值降到 Lc30/W2.0 就该判绿 —— 证"红"是阈值卡出来的，不是读数本身乱红。
  // 用一张**中等对比**的证据（灰字压胶囊浅底：实测 Lc≈55/W≈2.3），而不是 ② 里那种"底都没了"的极端帧：
  // 极端帧在降档阈值下仍然红，那只能证明读数烂，证明不了阈值在起作用。
  await inject("[data-reaction-chip]{color:#8f8f8f!important}");
  const midTone = await palRead("secondary");
  await clearMut();
  const realRed = !!midTone && !midTone.miss && midTone.ok === false && midTone.lc < 70 && midTone.ratio < 4.5;
  const laxGreen = !!midTone && !midTone.miss && midTone.lc >= 30 && midTone.ratio >= 2.0;
  check("palette 反例③：同一格中等对比证据，真阈值必须红、降到 Lc30/W2.0 必须绿（判据确实卡在阈值上）",
    realRed && laxGreen, "真红 + 降档绿", JSON.stringify(midTone));

  // ---- 修前/修后取证帧（只在 --shot= 给路径时写，避免平时多落文件）----
  if (SHOT_PATH) {
    const clipShot = async (tag) => {
      const rect = await cdp.eval(`(() => { const c = document.querySelector("[data-reaction-strip]");
        if (!c) return null; const r = c.getBoundingClientRect();
        return { x: Math.max(0, r.left - 16), y: Math.max(0, r.top - 16), width: r.width + 32, height: r.height + 32, scale: 1 }; })()`);
      if (!rect) return;
      const shot = await cdp.send("Page.captureScreenshot", { format: "png", clip: rect });
      fs.writeFileSync(path.join(shotDir, `palette-pill-${tag}.png`), Buffer.from(shot.data, "base64"));
    };
    for (const tag of ["after-light", "after-dark"]) {
      await cdp.eval(`window.__pal.apply('#2f6bff', ${tag === "after-dark"}, 'var(--gosslan-chat)')`);
      await sleep(150);
      await clipShot(tag);
    }
    // 修前：把旧实现的三种颜色注回去（默认 = `--gosslan-hover` 5% 墨迹 + `--gosslan-text-2` 字，
    // 已选 = `--gosslan-primary-light` 底 + `--gosslan-primary` 字）—— 与用户截图同一个形态
    await cdp.eval("window.__pal.apply('#2f6bff', false, 'var(--gosslan-chat)')");
    await inject(`[data-reaction-chip]{background:var(--gosslan-hover)!important;color:var(--gosslan-text-2)!important;border-color:transparent!important}`);
    await sleep(160);
    await clipShot("before-light");
    await clearMut();
    console.log("  📷 胶囊取证帧 → " + shotDir + "/palette-pill-{before-light,after-light,after-dark}.png");
  }

  await cdp.send("Emulation.clearDeviceMetricsOverride").catch(() => {});
  console.log(`· palette：${PALETTE_PRESETS.length} 内置主色 × 亮/暗 × 11 类场景，共 ${cells} 格读数`);
}

await main();
